RG.HK["07"] = [{"id":"07_wakamatsu_jo","n":"若松城（鶴ヶ城・会津戦争の籠城戦）","yomi":"わかまつじょう（つるがじょう）","cat":"城","rank":"S","y":1868,"era":["azuchi","edo","meiji"],"sh":"国指定史跡","ad":"会津若松市追手町","st":"JR会津若松駅からまちなか周遊バス «ハイカラさん» で約20分、«鶴ヶ城入口» から歩いて約5分","la":37.4875,"lo":139.9297,"hook":"新政府軍の大砲を1か月浴びつづけても落ちなかった城。赤い瓦の天守は、会津の人の «誇り» そのもの。","lead":"会津若松の町のまん中に建つ «鶴ヶ城» は、戦国時代に蒲生氏郷が大きな天守をあげ、江戸時代は会津藩の本拠地でした。1868年の会津戦争では、女性や子どもまで城に入り、約1か月の籠城戦をたたかいました。今の天守は1965年に再建されたもので、2011年に幕末と同じ赤い瓦にもどりました。","story":["この地に最初の館を築いたのは、室町時代の蘆名氏といわれます。当時は «黒川» と呼ばれていました。戦国時代の終わり、豊臣秀吉の命令で会津に入った蒲生氏郷は、町の名を «若松» と改め、七層ともいわれる大きな天守を建てました。城の名 «鶴ヶ城» は、氏郷の幼名 «鶴千代» にちなむという説がありますが、はっきりしません。","江戸時代のはじめ、大地震で天守がいたんだあと、加藤明成が五層の天守に建て直しました。これが幕末まで続いた天守です。やがて将軍家の身内である保科正之が会津藩主となり、その子孫の松平家が明治維新までこの城の主をつとめました。«会津は将軍家を守る藩» ――この考えが、のちの運命を大きく決めることになります。","1868年、戊辰戦争。藩主・松平容保は京都守護職として新選組などを使い京の治安を守った人物で、新政府からは «朝敵» とされていました。旧暦8月23日、新政府軍が城下になだれこむと、鐘が鳴らされ、藩士の家族は城へ走りました。«城へ入れ、遅れるな!» 間に合わなかった家では、女性たちが自ら命を絶った悲劇も起きています。","城に入った人びとは、男も女も、老人も子どもも、それぞれの仕事をしました。山本八重はスペンサー銃を手に夜の出撃に加わったと伝わります。女性たちは飛んでくる砲弾に濡れたふとんをかぶせて火を消し、兵糧のおにぎりを握りました。家老の山川大蔵は、敵に囲まれた城へ入るため、地元の «彼岸獅子» のおはやしを先頭に堂々と行進し、敵を驚かせたうちに入城したといわれます。","しかし、城の南東にある小田山から大砲が撃ちこまれ、天守は穴だらけになりました。食べ物も弾も減り、旧暦9月22日、会津藩はついに降伏します。約1か月の籠城でした。明治になると城は取りこわされ、石垣だけが残りました。1965年、市民の願いで天守が鉄筋コンクリートで再建され、今は郷土博物館として、あの日々の記憶を伝えています。"],"tl":[["1384年","蘆名直盛が東黒川館を築いたと伝わる（城のはじまり）"],["1592年","蒲生氏郷が大改修し、町の名を «若松» と改める"],["1639年","加藤明成が天守を五層に改築"],["1643年","保科正之が会津藩主となる"],["1868年","会津戦争。約1か月の籠城ののち降伏"],["1874年","天守などが取りこわされる"],["1934年","若松城跡として国の史跡に指定"],["1965年","天守を再建"],["2011年","屋根瓦を幕末と同じ赤瓦にふき替え"]],"who":[["蒲生氏郷","城と城下町を整え、«若松» と名づけた戦国大名"],["保科正之","会津松平家の初代藩主。会津の藩風をつくった"],["松平容保","幕末の会津藩主。京都守護職をつとめ、籠城戦を指揮"],["山本八重","砲術家の娘。銃をとって籠城戦に加わった。のちの新島八重"],["山川大蔵（浩）","家老。彼岸獅子を先頭に入城したと伝わる"]],"deep":["赤瓦: 寒さで割れにくいよう釉薬をかけて焼いた瓦で、幕末の天守も赤瓦だったことが古写真や記録からわかり、2011年に再現されました。日本の現存・再建天守で赤瓦はここだけといわれます。","小田山: 城の南東約1.5kmの山で、新政府軍はここに砲台を置き、天守を見下ろして砲撃しました。どの藩のどんな砲が使われたかは諸説あります。","天守台の石垣は、自然の石をあまり加工せずに積んだ «野面積み»。蒲生時代の古い技術を今に伝え、反りのある美しい姿は «忍者落とし» の名でも呼ばれます。","茶室 «麟閣»: 千利休が切腹したあと、氏郷はその子・少庵を会津にかくまったと伝わります。少庵のためにつくったとされる茶室が、明治に城外へ移されたのち、1990年に城内へもどされました。","降伏の式は城下の甲賀町口近くで行われ、敷かれた緋毛氈を藩士たちが切り分けて持ち帰り、くやしさを忘れないようにしたという «泣血氈» の話が伝わります。","土井晩翠の «荒城の月» は、この城や仙台の青葉城をイメージしたといわれ、城内に歌碑があります。"],"look":["赤瓦の天守と最上階からの会津盆地のながめ","天守台の野面積みの石垣","本丸と二の丸をつなぐ廊下橋と、深い堀","茶室 «麟閣»","城の南東に見える小田山（砲撃の地）"],"q":["鶴ヶ城の天守の瓦は何色？","赤色。寒さに強い釉薬をかけた赤瓦で、幕末の姿にあわせて2011年に復元されました。"],"koji":[{"w":"ならぬことはならぬものです","m":"会津藩士の子どもの «什の掟» のしめくくりのことば。だめなことはだめ、という会津の気風を表す"}],"myth":"城名の由来、彼岸獅子の入城、泣血氈の話、八重の活躍の細部は伝承・諸説を含む。","img":["会津戦争","松平容保","新島八重","蒲生氏郷"],"wp":"若松城","rel":{"ev":["boshin"],"grave":[]},"ph":[["c:e/e6/%E8%8B%A5%E6%9D%BE%E5%9F%8E%EF%BC%88%E9%B6%B4%E3%83%B6%E5%9F%8E%EF%BC%8920220917-P1003471.jpg",1600,1200,"若松城"],["c:c/c8/1_%C5%8Ctemachi%2C_Aizuwakamatsu-shi%2C_Fukushima-ken_965-0873%2C_Japan_-_panoramio_%282%29.jpg",3456,5184],["c:2/21/%22Shachihoko%22_roof_ornament_of_The_Aizu-Wakamatsu_Castle.jpg",3264,1992],["c:3/31/AizuCastle.jpg",2818,2032],["c:8/8d/Wakamatsujo_viewofthetop.jpg",1400,2100],["c:8/8d/Fukushima-Sakura_in_Tsuruga_Castle%2C_Aizuwakamatsu_City-m.jpg",1920,1439],["c:f/fb/Aizu_Wakamatsu_Castle_air.jpg",1900,1370],["c:3/3f/Old_Aizu_Castle_in_1874.jpg",500,357]]},{"id":"07_iimoriyama","n":"飯盛山（白虎隊自刃の地）","yomi":"いいもりやま","cat":"幕末","rank":"S","y":1868,"era":["edo"],"sh":"","ad":"会津若松市一箕町八幡","st":"JR会津若松駅からまちなか周遊バスで約5分、«飯盛山下» 下車すぐ（参道は長い石段、動く坂道もある）","la":37.4966,"lo":139.9533,"hook":"16、17歳の少年たちが見下ろした城下の煙。あの日、彼らの目には何が映っていたのか。","lead":"飯盛山は、会津若松の町の東にある小さな山です。1868年の会津戦争で、白虎隊の少年たちがここで自ら命を絶ちました。山には十九士の墓があり、今も花とお線香がたえません。","story":["会津藩は戊辰戦争にそなえ、藩士を年齢で分けて部隊をつくりました。50歳以上は «玄武»、36歳から49歳は «青龍»、18歳から35歳は «朱雀»、そして16、17歳の少年は «白虎»。中国の四神の名前です。白虎隊は本来、城を守る予備の部隊でした。","ところが新政府軍の進み方は予想より速く、少年たちも前線へ出されます。士中二番隊の少年たちは猪苗代湖に近い戸ノ口原へ向かいましたが、激しい戦いにやぶれ、ちりぢりになりました。雨の夜をこえ、彼らは戸ノ口堰の用水が山を抜ける洞穴をくぐって、飯盛山へたどりつきます。","山の中腹から見えたのは、黒い煙に包まれた城下でした。«城が燃えている……» と思ったのか、それとも城がまだ残っていると知ったうえで、敵に捕まるよりは武士として死ぬ道を選んだのか。少年たちは話し合い、ここで自刃しました。«なぜ?» の答えは、今も研究者のあいだで意見が分かれています。","20人のうち、ただ一人、飯沼貞吉だけが通りかかった人に助けられ、命をとりとめました。貞吉はのちに電信技師として明治の日本を支え、長いあいだこの日のことを多く語らなかったといわれます。晩年に残した証言が、白虎隊のできごとを知る大切な手がかりになりました。","少年たちの遺体は、新政府軍の命令でしばらく葬ることを許されなかったと伝わります。やがて墓が建てられ、白虎隊の物語は全国に知られるようになりました。山の上には、遠くイタリアのローマ市やドイツの人から贈られた記念碑まであります。城の方角を向いた少年の像の前に立つと、今も同じ景色が広がっています。"],"tl":[["1868年春","会津藩が年齢別の軍制をしき、白虎隊が生まれる"],["1868年旧暦8月22日","白虎士中二番隊が戸ノ口原へ出陣"],["1868年旧暦8月23日","飯盛山で隊士20人が自刃、飯沼貞吉のみ蘇生"],["1868年旧暦9月22日","会津藩降伏"],["1928年","ローマ市から記念碑が贈られる"],["1931年","飯沼貞吉（貞雄）死去"]],"who":[["飯沼貞吉","ただ一人生き残った隊士。のち電信技師"],["篠田儀三郎","士中二番隊の隊士で、自刃の場をまとめた一人と伝わる"],["日向内記","士中二番隊の隊長。戦いの途中で隊とはぐれた"],["松平容保","会津藩主。白虎隊は藩主の護衛も役目とした"]],"deep":["白虎隊は士中・寄合・足軽など身分ごとの隊に分かれ、全体で三百数十人いたといわれます。飯盛山で自刃したのは «士中二番隊» の一部です。","«城が燃えていると誤解した» という話は広く知られますが、飯沼貞吉の晩年の証言では、城が落ちていないことはわかっていたとも読め、誤解説と覚悟説で議論があります。","戸ノ口堰洞穴は、猪苗代湖の水を会津盆地へ運ぶ用水路が山を抜けるトンネルで、今も水が流れています。隊士がここをくぐったことが、飯盛山にたどりついた理由です。","墓は «十九士» の墓です。自刃は20人で、生き残った飯沼貞吉の墓も、のちに同じ場所の近くに建てられました。","ローマ市の記念碑は、白虎隊の話に感動したとされ1928年に贈られた古代ローマの石柱です。ドイツ人の記念碑は戦後、碑文の一部が削られるなど、時代の影響も受けています。","飯盛山には国重要文化財の «さざえ堂» もあり、白虎隊記念館とあわせて見学できます。"],"look":["白虎隊十九士の墓","城下を見下ろす自刃の地と少年の像","戸ノ口堰洞穴（水の流れるトンネル）","ローマ市寄贈の記念碑","近くのさざえ堂"],"q":["白虎隊の名前はどこから来た？","中国の四神のうち西を守る «白虎» から。会津藩は年齢で玄武・青龍・朱雀・白虎の隊をつくりました。"],"koji":[],"myth":"自刃の理由（城炎上の誤認か覚悟の死か）は諸説。遺体放置の期間や埋葬の経緯にも異説がある。","img":["飯沼貞吉","会津戦争","円通三匝堂"],"wp":"白虎隊","rel":{"ev":[],"grave":[]},"ph":[["c:5/5e/Byakko-tai_statues.JPG",2128,2832,"白虎隊"],["c:8/82/Aidu_Byakkotai_Monument_by_Mussolini.jpg",1024,768],["c:a/a9/NDL-DC_762376_0220_0028crd-Byakkotai_Funbo.jpg",561,391],["c:1/1c/Iinuma_Sadakichi.jpg",780,1037,"飯沼貞吉"],["c:5/50/Battle_of_Aizu_at_Wakamatsu_castle_by_Tsukioka_Yoshitoshi.png",3877,1900,"会津戦争"]]},{"id":"07_shirakawa_seki","n":"白河関跡（みちのくの入口）","yomi":"しらかわのせきあと","cat":"遺跡","rank":"S","y":800,"era":["nara","heian"],"sh":"国指定史跡","ad":"白河市旗宿","st":"JR白河駅から車で約20分（路線バスは本数が少ない）","la":37.0556,"lo":140.2362,"hook":"ここをこえれば «みちのく»。都の歌人たちがあこがれ、芭蕉が旅の決意を新たにした関所。","lead":"白河関は、奈良・平安時代に陸奥国（今の東北地方）の南の入口に置かれた関所です。建物は残っていませんが、発掘で堀や土塁、柵のあとが見つかりました。昔の人にとってここは «遠い国への入口» で、多くの和歌や俳句によまれました。","story":["むかし、都の人から見て東北は «道の奥»、つまり «みちのく» でした。その入口に置かれたのが白河関です。海側の勿来関、日本海側の念珠関とあわせて «奥州三関» と呼ばれます。関所では人や物の出入りを調べ、北からの攻撃にもそなえたと考えられています。","平安時代の中ごろ、歌人の能因法師がこんな歌をよみました。«都をば 霞とともに 立ちしかど 秋風ぞ吹く 白河の関»。春がすみのころ都を出たのに、ここに着いたらもう秋風。旅の長さが一首にこめられています。後の時代には «能因は本当は旅をせず、家で日焼けして旅から帰ったふりをした» という笑い話まで生まれました。","やがて関所としての役目は終わり、場所もわからなくなっていきました。«白河の関はどこだったのか?» それを確かめようとしたのが、江戸時代の白河藩主・松平定信です。定信は古い記録や地形を調べ、ここが関の跡だと考えて «古関蹟» の碑を建てました。","1689年、松尾芭蕉は弟子の曾良と «おくのほそ道» の旅でこの地を通りました。«心もとなき日かず重なるままに、白川の関にかかりて旅心定まりぬ»。不安な日が続いたけれど、白河の関にさしかかって、ようやく旅の覚悟が決まった――芭蕉にとってもここは特別な場所だったのです。","昭和の発掘では、空堀や土塁、柵の穴、住居のあとなどが見つかり、定信の考えを裏づける結果となりました。今は白河神社が建ち、杉の古木に囲まれた静かな森です。石段を上ると、千年前の旅人たちと同じ «みちのくの入口» に立っていることに気づくでしょう。"],"tl":[["5世紀ごろ","このころ関が置かれたとする説もあるが不明"],["835年","朝廷の文書に白河と菊多（勿来）の関の名が見える"],["平安時代中ごろ","能因法師が «秋風ぞ吹く白河の関» とよむ"],["1689年","松尾芭蕉と曾良が訪れる"],["1800年","松平定信がここを関跡と考え «古関蹟» の碑を建てる"],["1959〜1963年","発掘調査で堀・土塁・柵のあとを確認"],["1966年","国の史跡に指定"]],"who":[["能因法師","平安時代の歌人。白河関の歌で有名"],["松尾芭蕉","«おくのほそ道» の旅で訪れた俳人"],["曾良","芭蕉の弟子。旅日記を残した"],["松平定信","白河藩主。関跡の場所を考証し碑を建てた"],["源義経","奥州へ向かう途中に立ち寄ったという伝説がある"]],"deep":["«関» と «剗（せき）»: 古い記録では «白河剗» とも書かれます。軍事的な «関» と区別して、交通を取り締まる場所を «剗» と書いたという説があります。","関がいつ置かれたかははっきりせず、5世紀ごろ説から7〜8世紀説まであります。史料で確かめられるのは平安時代初めの記録からです。","松平定信の考証は «決め手» が史料より地形や伝承に頼っていたため、ほかの候補地（境の明神付近など）を推す声もありましたが、発掘によって古代の遺構が見つかりました。","能因法師の «日焼け» の話は後世の説話で、本当に旅をしたかどうかは確かではありません。","境内には源義経が戦勝を祈って矢を立てたという «矢立の松»、旗を立てたという «旗立の桜» などの伝説の木があります。","関跡のすぐ近くの «白河関の森公園» には、芭蕉と曾良の像もあります。"],"look":["松平定信の «古関蹟» の碑","空堀と土塁のあと","白河神社と杉の古木","矢立の松・旗立の桜（伝説の木）","白河市の «白河関跡» 展示施設（関の森公園）"],"q":["奥州三関とは、白河関とあと二つは？","勿来関（太平洋側）と念珠関（日本海側、山形県）です。"],"koji":[{"w":"都をば霞とともに立ちしかど秋風ぞ吹く白河の関","m":"能因法師の歌。春に都を出て、白河に着いたら秋だった。みちのくの遠さを表す"}],"myth":"関の設置時期、義経の伝説の木、能因の «日焼け» の話は伝承・諸説。","img":["能因","松平定信","おくのほそ道"],"wp":"白河関","rel":{"ev":[],"grave":[]},"ph":[["c:5/52/Shirakawa-no-Seki_monument.jpg",2288,1712,"白河関"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:3/3f/Sugi%2C_Shirakawa_no_Seki.jpg",1712,2288],["c:1/14/Shirakawa_jinja.jpg",2288,1712],["c:9/9f/Shirakawa-no-seki_dry_Moat.jpg",2288,1712],["c:d/d8/Shirakawa-no-seki_Jinja_Sando.jpg",1712,2288],["c:8/83/Shirakawanoseki-kuhi.jpg",1824,1216],["c:d/d9/Hyakuninisshu_069.jpg",325,457,"能因"]]},{"id":"07_nakoso_seki","n":"勿来関跡","yomi":"なこそのせきあと","cat":"遺跡","rank":"S","y":800,"era":["nara","heian"],"sh":"","ad":"いわき市勿来町関田","st":"JR常磐線勿来駅から車で約5分、歩くと約30分","la":36.8665,"lo":140.784,"hook":"名前の意味は «来ること勿れ（来るな）»。それなのに、なぜ多くの歌人がこの関をよんだのか。","lead":"勿来関は、奥州三関の一つで、太平洋側から東北へ入る入口に置かれたと考えられている関所です。古い記録では «菊多剗» とも呼ばれました。正確な場所はわかっていませんが、いわき市の «勿来の関公園» が伝承地として親しまれています。","story":["«なこそ» とは、古いことばで «来るな» という意味です。«勿» は «〜するな»。つまり «勿来» は «来ること勿れ»。関所にぴったりの、少しこわい名前ですね。でも、この関が本当にこう呼ばれていたのか、それとも歌の中で生まれた呼び名なのか、ははっきりしません。","古い記録に出てくるのは «菊多剗» という名前です。菊多は、このあたりの古い郡の名前。平安時代のはじめ、朝廷の文書に白河とならんでその名が見えます。やがて «なこそ» という響きが歌人たちの心をとらえ、和歌の世界で有名な «歌枕» になりました。","いちばん有名なのは、平安時代の武将・源義家の歌です。«吹く風を 勿来の関と 思へども 道もせに散る 山桜かな»。風よ来るなという名の関なのに、道がふさがるほど山桜が散っている――戦の旅の途中、桜吹雪に心を動かされた武士の姿が浮かびます。","«来るな» といわれると、かえって行ってみたくなるのが人の心。江戸時代にはこの伝承地に多くの旅人が訪れ、碑が建てられました。一方で、関の本当の場所については、茨城県側の説や、もう少し内陸だったという説など、いくつもの考えがあります。","今、公園には義家の像や歌碑がならび、春には桜が山をいろどります。近くの «勿来関文学歴史館» では、関の歴史や、この地をよんだ歌や文学を紹介しています。«来るな» の関は、いつのまにか «来てほしい» 名所になったのです。"],"tl":[["835年","朝廷の文書に «菊多剗» の名が白河剗とならんで見える"],["平安時代後期","源義家の «勿来の関» の歌が生まれたとされる"],["1187年ごろ","義家の歌が «千載和歌集» に収められる"],["江戸時代","伝承地に碑が建てられ名所となる"],["現代","伝承地に «いわき市勿来関文学歴史館» が建つ"]],"who":[["源義家","八幡太郎とも。«勿来の関» の歌で知られる武将"],["紀貫之","勿来をよんだ歌があるとされる平安の歌人"],["小野小町","勿来をよんだとされる歌が伝わる歌人"]],"deep":["«勿来» という書き方は «来ること勿れ» の漢文読み。古代の正式名称は «菊多剗» で、«勿来関» の名は和歌の中で広まったと考えられています。","場所は確定しておらず、公園のある伝承地のほか、茨城県北茨城市側、内陸の旧街道ぞいなど複数の説があります。国の史跡には指定されていません。","源義家の歌は «千載和歌集» に入っています。義家が実際にここを通ったのか、どの戦いのときかは不明で、歌の成り立ちにも議論があります。","白河・勿来・念珠の «奥州三関» のうち、白河と念珠関は発掘や史料で位置がかなり確かめられていますが、勿来はもっとも謎の多い関です。","関の近くは海ぞいの断崖で、古くは海岸を通る道が険しかったため、ここが «入口» として意識されたと考えられています。"],"look":["源義家の騎馬像と歌碑","公園内の多くの歌碑（歌枕の道）","勿来関文学歴史館","春の山桜と太平洋のながめ"],"q":["«勿来» はどういう意味？","«来ること勿れ»、つまり «来るな» という意味です。"],"koji":[{"w":"吹く風を勿来の関と思へども道もせに散る山桜かな","m":"源義家の歌。風よ来るなという名の関なのに、桜が道いっぱいに散っている、という意味"}],"myth":"関の正確な位置は不明で諸説。小町・貫之の歌の作者についても伝承を含む。","img":["源義家","奥州三関"],"wp":"勿来関","rel":{"ev":[],"grave":[]},"ph":[["c:d/d7/Minamoto_Yoshiie_at_the_Nakoso_barrier.jpg",1648,3587,"勿来関"],["c:7/77/Monument_of_Nakoso_Jinja_shrine_in_Rifu_01.jpg",3630,2218],["c:2/27/Nakosonoseki.jpg",800,600],["c:9/9b/%E6%BA%90%E7%BE%A9%E5%AE%B6%E7%94%BB%E5%83%8F.jpg",1411,1606,"源義家"]]},{"id":"07_nisshinkan","n":"会津藩校日新館","yomi":"あいづはんこうにっしんかん","cat":"学び","rank":"S","y":1803,"era":["edo"],"sh":"","ad":"会津若松市河東町南高野（復元施設）","st":"JR磐越西線広田駅から車で約5分。会津若松駅からは車で約20分","la":37.5555,"lo":139.9975,"hook":"«ならぬことはならぬものです»。会津の子どもたちが毎日となえた約束が、ここから生まれた。","lead":"日新館は、江戸時代の会津藩が藩士の子どもを教えた学校です。10歳ごろになると入学し、学問や武道、礼儀を学びました。本物は戊辰戦争で焼けてしまい、今の建物は河東町に復元されたものです。","story":["江戸時代の後半、会津藩はききんや財政難に苦しんでいました。家老の田中玄宰は «藩を立て直すには、人を育てるしかない» と考え、大きな学校をつくることを提案します。こうして鶴ヶ城の西どなりに建てられたのが日新館でした。完成したのは1803年ごろのことです。","入学する前、6歳から9歳の子どもたちは近所の同じ年ごろの仲間で «什» というグループをつくりました。毎日集まって、«年長者の言うことにそむいてはなりませぬ»«卑怯なふるまいをしてはなりませぬ» などの約束をとなえ、最後にこう結びます。«ならぬことはならぬものです»。","日新館の中には、儒学を学ぶ部屋のほか、弓・槍・剣術の道場、天文台、そして水練水馬池まであったといいます。水練とは水泳のこと。甲冑をつけたまま泳ぐ練習もしたそうです。«日本で最初のプールでは?» といわれることもあります。","成績のよい生徒は江戸の昌平坂学問所へ進むこともできました。白虎隊の少年たちもここで学んだ生徒たちです。けれど1868年、会津戦争の戦火で日新館は焼け落ちました。今、もとの場所に残るのは、天文台のあとの石垣だけです。","1987年、河東町の丘に日新館が復元されました。大成殿や道場、水練水馬池などが、当時の絵図をもとによみがえっています。弓道の体験や、赤べこの絵付けなどもでき、会津の子どもたちが何を学び、どんな約束を守ろうとしたのかを体で感じられる場所です。"],"tl":[["1664年","保科正之のころ、学問所 «稽古堂» が町に開かれる"],["1799年","家老・田中玄宰の提案で日新館の建設が始まる"],["1803年","日新館が完成したといわれる"],["1868年","会津戦争で焼失"],["1987年","河東町に日新館が復元される"]],"who":[["田中玄宰","会津藩の家老。藩政改革の中で日新館をつくった"],["松平容頌","日新館が建てられたころの会津藩主"],["白虎隊士","日新館で学んだ少年たち"],["山川健次郎","日新館で学び、のちに東京帝国大学総長となった物理学者"]],"deep":["«什の掟» は全7か条といわれますが、地域や家によって文言が少しちがって伝わっています。有名なしめくくりの一文は、今も会津の子どもの教育の合言葉です。","もとの日新館は、東西約120間、南北約60間ともいわれる大きな敷地でした。場所は鶴ヶ城の西側で、今は住宅地になっています。","もとの場所に残る «日新館天文台跡» は、当時の天文台の土台で、日本に残る江戸時代の天文台跡として貴重なものです。","水練水馬池は、泳ぎや、馬に乗ったまま水をわたる訓練に使われたと伝わります。復元施設でその姿を見ることができます。","会津藩は «会津藩家訓»（保科正之が定めた15か条）を大切にしていて、日新館の教育の土台になりました。","復元された日新館は映画やテレビドラマのロケ地としても使われています。"],"look":["大成殿（孔子をまつる建物）","水練水馬池","弓道場と武道場","«什の掟» の展示","会津若松市内のもとの場所にある天文台跡"],"q":["«什の掟» のしめくくりのことばは？","«ならぬことはならぬものです»。だめなことはだめ、という意味です。"],"koji":[{"w":"ならぬことはならぬものです","m":"理屈ではなく、してはいけないことはしてはいけないという教え"}],"myth":"«日本最古のプール» は俗説。什の掟の文言にも異同がある。","img":["白虎隊","会津藩","山川健次郎"],"wp":"日新館","rel":{"ev":[],"grave":[]},"ph":[["c:3/33/Nisshinkan_Samurai_School_exterior_in_2013-10-18.jpg",2000,1500,"日新館"],["c:5/55/First_SwimmingPool_in_Japan%28Nisshinkan%29.jpg",3872,2592],["c:8/85/Nissinkan_astronomical_observatory_remains_in_2014-01-24.jpg",3200,2400],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:e/e9/South_Gate_of_Nisshinkan.jpg",1200,720],["c:5/5e/Byakko-tai_statues.JPG",2128,2832,"白虎隊"],["c:7/72/March_2011_The_Aizu-Wakamatsu_Castle.jpg",640,480,"会津藩"],["c:5/59/Kenjiro_Yamakawa_2.jpg",771,905,"山川健次郎"]]},{"id":"07_komine_jo","n":"白河小峰城（白河口の戦い）","yomi":"しらかわこみねじょう","cat":"城","rank":"S","y":1632,"era":["muromachi","edo"],"sh":"国指定史跡","ad":"白河市郭内","st":"JR白河駅から歩いて約5分（駅の北側すぐ）","la":37.1334,"lo":140.2146,"hook":"戊辰戦争の弾のあとが残る木で建て直された三重櫓。城そのものが «戦いの証人» になっている。","lead":"白河小峰城は、みちのくの入口・白河を守った城です。江戸時代のはじめに丹羽長重が石垣の城に造りかえました。1868年の戊辰戦争では «白河口の戦い» の舞台となり、城は焼けおちましたが、今は三重櫓と前御門が木造で復元されています。","story":["城のはじまりは南北朝時代、白河結城氏の結城親朝が «小峰ヶ岡» に館を築いたことだといわれます。«小峰» という名前はここから来ています。その後、城の主は何度も変わりました。","大きく姿を変えたのは江戸時代のはじめ。1627年に白河へ来た丹羽長重は、何年もかけて城を大改修し、東北ではめずらしい、総石垣の立派な城をつくりました。長重は «築城の名人» ともいわれた人物です。«なぜ白河にこれほどの城を?» それは、白河が東北の大名たちへのにらみをきかせる大事な場所だったからだと考えられています。","江戸時代の中ごろには、寛政の改革で知られる松平定信が白河藩主となりました。ききんのときに領民を一人も飢え死にさせなかったと伝わるほど、藩の政治に力を入れた人です。日本で最も古い公園の一つといわれる «南湖» をつくり、身分に関係なく人びとが楽しめる場所にしました。","1868年、戊辰戦争。白河は «奥州の関門» として激しい取り合いになりました。旧幕府側の会津藩や仙台藩などの同盟軍と、薩摩・長州などの新政府軍が、城の南の稲荷山などで何度もぶつかりました。この戦いで城は焼け、多くの兵士が命を落としました。今も市内には、敵味方それぞれの戦死者の墓や慰霊碑が残っています。","1991年、城の顔である三重櫓が、江戸時代の絵図をもとに木造で復元されました。その材木には、激戦地・稲荷山の杉が使われています。«よく見ると、弾のあとがあるよ»。柱や床板に残る小さな穴は、150年以上前の戦いの証です。2011年の東日本大震災では石垣が大きく崩れましたが、何年もかけて積み直され、城は再びよみがえりました。"],"tl":[["1340年ごろ","結城親朝が小峰ヶ岡に城を築いたと伝わる"],["1627年","丹羽長重が白河藩主となる"],["1632年ごろ","長重による大改修が完成"],["1783年","松平定信が白河藩主となる"],["1868年","戊辰戦争・白河口の戦い。城が焼ける"],["1991年","三重櫓が木造で復元される"],["1994年","前御門が木造で復元される"],["2010年","国の史跡に指定"],["2011年","東日本大震災で石垣が崩れる（のちに修復）"]],"who":[["結城親朝","南北朝時代の武将。城を最初に築いたといわれる"],["丹羽長重","江戸初期の白河藩主。石垣の城に大改修した"],["松平定信","白河藩主。のち老中として寛政の改革を行う"],["伊地知正治","薩摩藩士。白河口の戦いで新政府軍を指揮した"],["西郷頼母","会津藩家老。白河口の戦いで同盟軍の総督をつとめた"]],"deep":["三重櫓は天守の代わりの建物です。江戸時代の «白河城御櫓絵図» などをもとに木造で復元され、城郭の本格的な木造復元の早い例として知られます。","稲荷山の杉: 戊辰戦争の激戦地に育っていた杉を使ったため、材木に弾丸が当たったあとが残っています。場所は館内で案内されています。","丹羽長重は関ヶ原で西軍についていったん領地を失いましたが、のちに大名に復帰し、白河10万石余の城主となりました。","白河口の戦いは1868年旧暦4月から約3か月つづいたといわれ、とくに5月1日の戦いで同盟軍が大きな損害を出しました。","震災で崩れた石垣は、石一つひとつに番号をつけて元の位置に積み直す方法で修復されました。","松平定信が白河に残した南湖公園は、国の史跡・名勝に指定されています。"],"look":["木造復元の三重櫓（稲荷山の杉の弾のあと）","前御門","修復された本丸の石垣","清水門跡など曲輪のあと","近くの稲荷山の戊辰戦争戦死者の碑"],"q":["三重櫓の材木にはどんな «あと» が残っている？","戊辰戦争の弾丸のあと。激戦地・稲荷山の杉を材木に使ったためです。"],"koji":[],"myth":"城の創建年、白河口の戦いの戦死者数は諸説。","img":["丹羽長重","松平定信","白河口の戦い"],"wp":"白河小峰城","rel":{"ev":[],"grave":[]},"ph":[["c:a/ab/Shirakawa_Komine_Castle_20100625-01.jpg",5184,3456,"白河小峰城"],["c:8/89/Shirakawakomine_castle_tensyu2.JPG",4000,3000],["c:9/9a/Shirakawakomine_castle_ishigaki.JPG",4000,3000],["c:0/0d/Shirakawa_Komine_Castle_20100625-02.jpg",5184,3456],["c:2/21/%E7%99%BD%E6%B2%B3%E5%B0%8F%E5%B3%B0%E5%9F%8E_%E7%9F%B3%E5%9E%A3%E5%B4%A9%E5%A3%8A%E3%81%AE%E6%A7%98%E5%AD%90.JPG",3648,2736],["c:d/dc/Sirakawakomine_castle_ninomaru.JPG",3072,2304],["c:1/10/Sirakawakomine_castle_huzimon.JPG",3072,2304],["c:9/9b/Shirakawakomine_castle_takenomaru.JPG",3072,2304]]},{"id":"07_nihonmatsu_jo","n":"二本松城（二本松少年隊）","yomi":"にほんまつじょう","cat":"幕末","rank":"S","y":1868,"era":["muromachi","edo"],"sh":"国指定史跡","ad":"二本松市郭内","st":"JR東北本線二本松駅から歩いて約20分","la":37.601,"lo":140.427,"hook":"12歳から17歳の少年たちが大砲を引いて守った城。石垣の上には «智恵子抄» の空が広がる。","lead":"二本松城は «霞ヶ城» とも呼ばれ、室町時代の畠山氏から江戸時代の丹羽氏までつづいた城です。戊辰戦争では多くの少年たちが戦い、のちに «二本松少年隊» と呼ばれました。今は霞ヶ城公園として、石垣と桜の名所になっています。","story":["室町時代、奥州探題の一族である畠山氏がこの山に城を築いたのが始まりといわれます。戦国時代の終わり、畠山氏は伊達氏とはげしく争いました。1585年、畠山義継が伊達輝宗（伊達政宗の父）を連れ去る事件が起き、義継も輝宗もその場で命を落とします。怒った政宗は二本松城を攻め、畠山氏はここを去りました。","江戸時代、1643年に丹羽光重が二本松藩主となり、以来、明治まで丹羽氏の城となりました。藩の役人への戒めを岩に刻んだ «戒石銘» は、«おまえたちの給料は民の汗と脂からできている。民をしいたげれば天はそれを見ている» という意味の文で、今も城の近くに残っています。","1868年、戊辰戦争。二本松藩は奥羽越列藩同盟に加わりました。大人の兵の多くは白河などの前線に出ていたため、城下を守るため少年たちも戦いに加わります。«自分も戦わせてほしい» と願い出た子もいたといいます。22歳の砲術師範・木村銃太郎が隊長となり、少年たちは大砲を引いて城の南の大壇口に向かいました。","旧暦7月29日、新政府軍が攻めよせます。少年たちは必死に大砲を撃ちましたが、数にまさる相手にかないません。木村隊長は撃たれ、多くの少年も命を落としました。城は炎に包まれ、その日のうちに落城します。«どうしてこんなに幼い子が?» と、敵の兵士たちも驚いたと伝わります。","彼らは当時 «少年隊» と呼ばれていたわけではなく、この呼び名は後の時代につけられました。今、城には少年隊の像が立ち、毎年ふるさとの人びとが慰霊をつづけています。本丸の石垣に上ると、高村光太郎が «智恵子抄» で «あれが阿多多羅山、あの光るのが阿武隈川» とうたった景色が広がります。"],"tl":[["1414年ごろ","畠山満泰が城を築いたとされる（諸説）"],["1585年","畠山義継と伊達輝宗が落命。政宗が二本松を攻める"],["1586年","畠山氏が城を去り伊達氏の城となる"],["1643年","丹羽光重が二本松藩主となる"],["1749年","戒石銘が刻まれる"],["1868年旧暦7月29日","戊辰戦争で落城。少年たちも戦死"],["2007年","二本松城跡が国の史跡に指定"]],"who":[["畠山義継","二本松城主。伊達輝宗を連れ去る事件を起こした"],["伊達政宗","父の死後、二本松城を攻め取った"],["丹羽光重","江戸時代の二本松藩の初代藩主"],["木村銃太郎","少年たちの砲術の師で隊長。大壇口で戦死"],["高村光太郎","妻・智恵子のふるさと二本松の空をうたった詩人"]],"deep":["«二本松少年隊» の数は62人とされることが多いですが、実際に戦った少年の数や年齢には記録によってちがいがあります。","最年少の少年は12歳とも13歳ともいわれます。当時、二本松藩は出陣できる年齢を引き下げていたと伝わります。","戒石銘は国の史跡。1749年、藩主・丹羽高寛が儒学者・岩井田昨非の進言で刻ませたもので、中国の宋の時代の文をもとにしています。","本丸の石垣は、1990年代に修復・復元され、中世の石積みと江戸時代の石積みが重なって見つかったことでも注目されました。","城の中にある «洗心亭» は、江戸時代から残る茶亭と伝わります。","毎年秋の «二本松の菊人形» は、霞ヶ城公園を会場にして長くつづいてきた行事です。"],"look":["本丸の石垣と安達太良山のながめ","二本松少年隊の像","箕輪門（復元）","戒石銘（城の近くの岩）","大壇口の古戦場の碑"],"q":["«二本松少年隊» という名前はいつついた？","戊辰戦争のあと、後の時代になってつけられた呼び名です。"],"koji":[{"w":"爾俸爾禄 民膏民脂","m":"戒石銘の一節。あなたの給料は民の汗と脂から出ている、という役人への戒め"}],"myth":"少年隊の人数・年齢、城の創建年は諸説。","img":["二本松少年隊","丹羽光重","戒石銘"],"wp":"二本松城","rel":{"ev":[],"grave":[]},"ph":[["c:3/34/Nihonmatsu_Castle_Minowa_Gate_20100625-01.jpg",5184,3456,"二本松城"],["c:8/89/Nihonmatsu_Shonentai_Manifestation_Monument_20100625.jpg",5184,3456],["c:9/96/Nihonmatsu_Castle_Keep_Tower_Base_20100625-01.jpg",5184,3456],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:0/06/Niwa_Mitsushige.jpg",210,264,"丹羽光重"]]},{"id":"07_atsukashiyama","n":"阿津賀志山防塁（奥州合戦）","yomi":"あつかしやまぼうるい","cat":"古戦場","rank":"S","y":1189,"era":["heian","kamakura"],"sh":"国指定史跡","ad":"伊達郡国見町大木戸・西大枝ほか","st":"JR東北本線藤田駅から車で約10分。いくつかの地点は歩いて見学できる","la":37.877,"lo":140.539,"hook":"奥州藤原氏が頼朝の大軍をむかえうつため、山から川まで約3kmにわたって掘った «巨大な堀»。","lead":"1189年、源頼朝は平泉の奥州藤原氏を攻めました（奥州合戦）。藤原氏は国見町の阿津賀志山のふもとに二重の堀と土塁を築き、頼朝軍を止めようとしました。その跡が今も畑や林の中に残っています。","story":["源平の戦いが終わったあと、兄・頼朝に追われた源義経は、平泉の藤原秀衡のもとへ逃げこみました。秀衡が亡くなると、あとをついだ泰衡は頼朝の圧力に負け、義経を攻めて死なせてしまいます。ところが頼朝は «義経をかくまっていた罪» を理由に、今度は奥州藤原氏そのものを攻めることにしました。","頼朝の大軍が鎌倉を出たのは1189年の夏。平泉を守るため、泰衡は兄の国衡を大将とする大軍を阿津賀志山に送りました。ここは奥州へ入る道が山と阿武隈川にはさまれて細くなる場所です。«ここで止めるしかない»。藤原方は山の中腹から川の近くまで、長い堀と土塁を築きました。","鎌倉幕府の記録 «吾妻鏡» によれば、頼朝方の畠山重忠は、連れてきた人夫たちに鋤や鍬を持たせ、夜のうちに堀を埋めさせたといいます。戦いは数日つづき、ついに鎌倉方の別動隊が山の後ろへ回りこんで攻めかかり、藤原方はくずれました。","国衡は逃げる途中で討たれ、泰衡は平泉に火を放って北へ逃げました。しかし最後は、家来の裏切りにあって命を落とします。約100年にわたって栄えた奥州藤原氏は、ここで終わりを迎えました。阿津賀志山の戦いは、その運命を決めた最大の戦いだったのです。","防塁は、800年以上たった今も、ところどころで土の盛り上がりやくぼみとしてはっきり見えます。«これを人の手で掘ったの?» と驚くほどの長さです。国見町の «あつかし歴史館» では、防塁の模型や発掘の成果を紹介しています。"],"tl":[["1187年","藤原秀衡が亡くなる"],["1189年閏4月","藤原泰衡が衣川で義経を攻める"],["1189年7月","源頼朝が鎌倉を出陣"],["1189年8月","阿津賀志山の戦い。藤原国衡が敗れる"],["1189年9月","泰衡が討たれ、奥州藤原氏がほろびる"],["1981年","阿津賀志山防塁が国の史跡に指定"]],"who":[["源頼朝","鎌倉幕府を開いた人物。大軍を率いて奥州へ攻めこんだ"],["藤原泰衡","奥州藤原氏の4代目。義経を死なせ、頼朝に攻められた"],["藤原国衡","泰衡の兄。阿津賀志山の藤原軍の大将"],["畠山重忠","鎌倉方の武将。堀を埋めて進んだと «吾妻鏡» に書かれる"],["源義経","この戦いの原因となった人物"]],"deep":["防塁は «二重の堀と、その間と外側の三重の土塁» の構造で、全長は約3.2kmといわれます。山の中腹から阿武隈川の近くまで、道をさえぎるように築かれました。","史料はおもに鎌倉幕府側の «吾妻鏡»。勝った側の記録なので、藤原方の兵の数などは誇張されている可能性も指摘されています。","防塁の工事には、多くの人手と時間が必要だったはずです。藤原氏が頼朝の攻撃をかなり前から予想して準備していたことを示す、と考えられています。","頼朝軍は東海道・北陸道・中央（奥大道）の三方面から攻めこみ、頼朝自身は中央の大手軍を率いて阿津賀志山を攻めました。","国見町には «大木戸» の地名が残り、ここが奥州の入口の «木戸» だったことを思わせます。","防塁の堀の一部は、平成の発掘で断面が確認され、深さ・幅が当時の姿に近い形でわかってきています。"],"look":["下二重堀地区などの、よく残る堀と土塁","防塁ぞいの見学路と案内板","阿津賀志山（厚樫山）のすがた","国見町の «あつかし歴史館»"],"q":["阿津賀志山の戦いで負けた一族は？","平泉の奥州藤原氏。この戦いのあと、約1か月でほろびました。"],"koji":[],"myth":"兵の数や戦いの細部は «吾妻鏡» による記述で、誇張の可能性がある。","img":["奥州合戦","藤原泰衡","畠山重忠"],"wp":"阿津賀志山防塁","rel":{"ev":[],"grave":[]},"ph":[["c:e/e9/Atsukashiyama_ruins.jpg",900,674,"阿津賀志山防塁"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:1/1c/%E5%A5%A5%E5%B7%9E%E9%AB%98%E9%A4%A8%E5%A4%A7%E5%90%88%E6%88%A6.jpg",1925,950,"奥州合戦"],["c:a/a1/Hatakeyama_Shigetada.jpg",886,1326,"畠山重忠"]]},{"id":"07_noguchi","n":"野口英世記念館（生家）","yomi":"のぐちひでよきねんかん","cat":"近代","rank":"S","y":1876,"era":["meiji","taisho","showa"],"sh":"","ad":"耶麻郡猪苗代町三ツ和","st":"JR磐越西線猪苗代駅からバスで約10分、«野口英世記念館» 下車","la":37.5565,"lo":140.1065,"hook":"«志を得ざれば 再び此地を踏まず»。15歳で家を出る日、少年は柱にこう刻んだ。","lead":"野口英世記念館には、千円札の肖像でも知られる細菌学者・野口英世が生まれ育った家が、当時のまま残されています。幼いころの大やけど、苦しい暮らし、そして世界で活躍するまでの歩みを、たくさんの資料で知ることができます。","story":["1876年、猪苗代湖のほとりの小さな農家に、清作という男の子が生まれました。のちの野口英世です。1歳半のころ、囲炉裏に落ちて左手に大やけどを負い、指がくっついて開かなくなってしまいます。母のシカは «わたしが目をはなしたから» と、深く自分を責めたといいます。","手が不自由な清作に、母は «農業はむずかしい、学問で身を立てなさい» と教えました。清作は必死に勉強し、成績優秀で高等小学校に進みます。やがて先生や友だちがお金を集め、若松の医師・渡部鼎のもとで左手の手術を受けることができました。«医学とはこんなに人を救えるのか»。この経験が、清作を医学の道へ向かわせます。","上京の日、清作は生家の床柱に «志を得ざれば 再び此地を踏まず» と刻みました。«目的を果たすまで、ふるさとには帰らない» という決意です。その後、医師の試験に合格し、名前を英世と改め、1900年には海をわたってアメリカへ向かいました。","ニューヨークのロックフェラー医学研究所で、英世は昼も夜もなく研究を続け、梅毒の病原体を患者の脳の中で見つけるなど、世界的な成果をあげます。その間、ふるさとの母は、覚えたてのひらがなで «はやくきてくだされ» と何度も書いた手紙を送りました。英世は1915年、15年ぶりに帰国し、母との再会を果たしました。","1928年、英世は黄熱病の研究のために行ったアフリカのアクラ（今のガーナ）で、自らも黄熱病にかかり、51歳で亡くなりました。生家は記念館として守られ、今も囲炉裏と、あの決意の文字が刻まれた床柱を見ることができます。"],"tl":[["1876年","猪苗代で清作（のちの英世）が生まれる"],["1878年ごろ","囲炉裏に落ち左手に大やけど"],["1892年","会津若松で左手の手術を受ける"],["1896年","上京。床柱に決意の文字を刻む"],["1900年","アメリカにわたる"],["1915年","15年ぶりに帰国し母と再会"],["1928年","アフリカで黄熱病のため死去"],["1939年","記念館が開館"],["2004年","千円札の肖像になる"]],"who":[["野口英世","細菌学者。この家で生まれ育った"],["野口シカ","英世の母。英世を支えつづけた"],["渡部鼎","会津若松の医師。英世の左手を手術した"],["小林栄","高等小学校の先生。英世を励まし支えた"],["血脇守之助","東京で英世の生活や留学を支えた歯科医"]],"deep":["«志を得ざれば再び此地を踏まず» の床柱は生家の中にあり、記念館の見どころの一つです。","母シカの手紙は、ひらがなを独学で覚えて書いたといわれ、記念館に展示されています。«はやくきてくだされ» のくり返しが心を打ちます。","英世の研究のなかには、梅毒スピロヘータの発見のように高く評価されたものがある一方、黄熱病の病原体の研究など、後に誤りとわかったものもあります。","«英世» への改名は、坪内逍遥の小説の登場人物の名前が自分と似ていたことがきっかけだったといわれます。","英世は何度もノーベル賞の候補になったといわれますが、受賞はしていません。","生家は、建てられた江戸時代後期の姿をよく残す農家として、記念館の中で保存されています。"],"look":["生家（英世がやけどをした囲炉裏）","«志を得ざれば…» の床柱の文字","母シカの手紙","英世が使った顕微鏡など研究の資料","近くの猪苗代湖のながめ"],"q":["英世の母・シカが手紙で何度も書いたことばは？","«はやくきてくだされ»。アメリカにいる英世に帰ってきてほしいと願った手紙です。"],"koji":[{"w":"志を得ざれば再び此地を踏まず","m":"目標をなしとげるまでは、ふるさとに帰らないという決意"}],"myth":"改名のきっかけやノーベル賞候補の回数には諸説。","img":["野口英世","野口シカ","猪苗代町"],"wp":"野口英世記念館","rel":{"ev":[],"grave":[]},"ph":[["c:c/c2/Hideyo_Noguchi_Memorial_Hall.JPG",2560,1920,"野口英世記念館"],["c:d/df/Noguchi-Inawashiro.jpg",1200,800],["c:3/3e/Noguchi_Hideyo.jpg",2930,4669,"野口英世"],["c:b/bc/Noguchi_Hideyo.png",422,389,"野口シカ"],["c:5/54/Nagahama_Iwanashiroko.jpg",2592,1944,"猪苗代町"]]},{"id":"07_ouchijuku","n":"大内宿（会津西街道の宿場）","yomi":"おおうちじゅく","cat":"街道","rank":"S","y":1640,"era":["edo"],"sh":"国の重要伝統的建造物群保存地区","ad":"南会津郡下郷町大内","st":"会津鉄道湯野上温泉駅から車で約15分（季節運行のバスあり）","la":37.335,"lo":139.861,"hook":"茅葺き屋根がずらりと並ぶ道。江戸時代の旅人が見た景色が、そのまま目の前にある。","lead":"大内宿は、会津若松と日光・今市を結ぶ «会津西街道（下野街道）» の宿場町です。道の両側に茅葺き屋根の家が並び、江戸時代の宿場の姿をよく残しています。1981年に国の重要伝統的建造物群保存地区に選ばれました。","story":["江戸時代、会津から江戸へ向かう道の一つが会津西街道でした。山あいを通るこの道には、旅人が泊まったり、荷物を運ぶ馬を取りかえたりする «宿場» がいくつも置かれました。大内宿もその一つで、江戸時代のはじめごろに整えられたと考えられています。","会津藩の殿様が江戸へ向かう参勤交代にも、この道が使われた時期がありました。大内宿には、殿様が休む本陣や脇本陣が置かれ、宿場は大いににぎわいました。今は本陣の建物が «町並み展示館» として復元され、当時のくらしの道具を見ることができます。","ところが明治になると、新しい道や鉄道が別の場所に通り、大内宿は «時代に取り残された» 村になりました。«なぜこんなに昔の姿が残ったの?» 答えの一つは、ここにあります。開発の波が来なかったため、茅葺きの家並みがそのまま残ったのです。","昭和のなかごろ、この町並みの価値に気づいた研究者たちが調査をはじめ、村の人たちも «この景色を守ろう» と話し合いました。茅葺き屋根はふき替えに大変な手間がかかりますが、地域で茅を育て、技術を伝えています。1981年、大内宿は国の重要伝統的建造物群保存地区に選ばれました。","今、大内宿には多くの観光客が訪れます。名物は、箸の代わりに長ねぎ1本でそばを食べる «ねぎそば»。宿場のいちばん奥の高台に上ると、茅葺き屋根が一列に並ぶ有名な景色を見わたすことができます。"],"tl":[["江戸時代初期","会津西街道の宿場として整えられる"],["江戸時代","参勤交代や物資の輸送に使われる"],["1868年","戊辰戦争で街道ぞいでも戦いがあった"],["明治以降","主要な交通路から外れ、古い家並みが残る"],["1981年","国の重要伝統的建造物群保存地区に選定"]],"who":[["会津藩主","参勤交代でこの街道を使った時期がある"],["宿場の人びと","旅人の宿や荷物の運送をになった"],["以仁王","平安時代の皇子。この地に逃れてきたという伝説がある"]],"deep":["道の両側には用水路が流れ、家々はその用水を生活に使っていました。家々は道から少し下がって同じ向きに建ち並び、前庭が広くとられているのも特徴です。","大内宿には平安時代末に源頼政とともに兵をあげた以仁王が逃れてきたという伝説があり、高倉神社にまつられています（伝説で史実ではありません）。","ねぎを箸がわりにするそばは «高遠そば» とも呼ばれ、信濃国高遠から会津に移った保科正之にゆかりがあるといわれます。","重要伝統的建造物群保存地区の制度ができたのは1975年。大内宿は比較的早い時期に選ばれた地区の一つです。","茅葺き屋根のふき替えは数十年に一度行われ、村の人たちが協力する «結» のしくみが受けつがれてきました。"],"look":["高台（子安観音の石段の上）から見る茅葺き屋根の並び","大内宿町並み展示館（本陣の復元）","道の両側の用水路","高倉神社"],"q":["大内宿の名物 «ねぎそば» は何で食べる？","長ねぎ1本を箸の代わりに使って食べます。"],"koji":[],"myth":"以仁王の伝説、ねぎそばと保科正之のゆかりは伝承。","img":["会津西街道","重要伝統的建造物群保存地区"],"wp":"大内宿","rel":{"ev":[],"grave":[]},"ph":[["c:6/61/Ja-fukushima-ohuchijuku-4.jpg",800,600,"大内宿"],["c:8/8d/%E5%A4%A7%E5%86%85%E5%AE%BF_-_panoramio_%2812%29.jpg",5472,3648],["c:5/5e/%E5%A4%A7%E5%86%85%E5%AE%BF_-_panoramio_%2810%29.jpg",5472,3648],["c:e/e8/%E5%A4%A7%E5%86%85%E5%B3%A0%E3%81%AE%E8%8C%B6%E5%B1%8B.JPG",2816,2112],["c:0/0e/Washing_place_and_waterway%2COuchi-jyuku%2CShimogo-town%2CJapan.JPG",2896,1944],["c:2/24/Aerial_photo_of_Oouchi-juku_in_2022-09.jpg",2325,2256],["c:a/a2/Yunokamionsen_sta.jpg",1280,960],["c:8/81/OuchiDamM.jpg",1280,960]]},{"id":"07_shiramizu","n":"白水阿弥陀堂","yomi":"しらみずあみだどう","cat":"寺社","rank":"S","y":1160,"era":["heian"],"sh":"国宝","ad":"いわき市内郷白水町広畑","st":"JR常磐線内郷駅から車で約10分、歩くと約30分","la":37.0625,"lo":140.8553,"hook":"池にうかぶお堂は、この世にあらわれた «極楽浄土»。平泉の姫がふるさとをしのんで建てたと伝わる。","lead":"白水阿弥陀堂は、平安時代の終わりに建てられた阿弥陀堂で、福島県でただ一つの国宝の建物です。お堂のまわりを池が囲む «浄土庭園» がつくられ、極楽の世界をこの世に表しています。","story":["平安時代の終わり、人びとのあいだには «末法» という考えが広がっていました。仏の教えがおとろえ、世の中が乱れる時代が来る――そんな不安の中で、せめて死んだあとは阿弥陀如来のいる西方極楽浄土に生まれかわりたいと願う人が増えました。京都の平等院鳳凰堂も、そうした願いから生まれたお堂です。","このお堂を建てたのは、この地の豪族・岩城則道の妻、徳姫（徳尼）と伝わります。徳姫は奥州平泉の藤原氏の娘（藤原秀衡の妹とも、清衡の娘ともいわれます）でした。夫が亡くなったあと、そのとむらいのために1160年にこのお堂を建てたといわれています。","«白水» という地名には、おもしろい話があります。平泉の «泉» という字を上下に分けると «白» と «水»。ふるさと平泉をしのんで、徳姫がそう名づけたといわれるのです。本当かどうかはわかりませんが、遠い平泉とこの地を結ぶ、すてきな言い伝えです。","お堂は «方三間» と呼ばれる正方形に近い形で、屋根は優美な宝形造り。中には阿弥陀如来と両側の観音・勢至菩薩、そして持国天・多聞天がまつられています。池の中の島に建つお堂へは、橋をわたって向かいます。橋をわたることは、この世から極楽へわたることを表しているのです。","長い年月のあいだに庭園は荒れて田んぼになっていましたが、昭和の発掘調査で池のあとが見つかり、平安時代の姿に近い浄土庭園がよみがえりました。夏には池にハスの花が咲き、秋は紅葉がお堂をいろどります。«極楽って、こんな景色かな» と思わず考えてしまう場所です。"],"tl":[["1160年","徳姫が夫・岩城則道のとむらいのために建てたと伝わる"],["1952年","阿弥陀堂が国宝に指定"],["昭和","境内（白水阿弥陀堂境域）が国の史跡に指定"],["昭和後期","発掘調査にもとづき浄土庭園を復元"]],"who":[["徳姫（徳尼）","平泉藤原氏の娘。お堂を建てたと伝わる"],["岩城則道","この地の豪族。徳姫の夫"],["藤原秀衡","平泉の奥州藤原氏3代目。徳姫の兄ともいわれる"],["阿弥陀如来","お堂の本尊。極楽浄土の仏"]],"deep":["お堂は平安時代後期の阿弥陀堂の典型で、同じころの中尊寺金色堂（岩手県）や富貴寺大堂（大分県）などとならび、東北に残る貴重な例です。","本尊の阿弥陀如来坐像と両脇侍、持国天・多聞天の立像は国の重要文化財です。","正式な寺の名前は «願成寺»。阿弥陀堂はその境内にあるお堂です。","徳姫が秀衡の妹か清衡の娘かは史料によって異なり、はっきりしません。建てた年も伝承によるものです。","浄土庭園は、池の南から北のお堂をおがむように配置されています。平等院が東向きなのとは向きがちがい、地形に合わせた工夫と考えられます。","白水の地名の由来（«泉» を分けた）は言い伝えで、確かな史料はありません。"],"look":["池の中島に建つ阿弥陀堂の全景","橋をわたってお堂に向かう参道","堂内の阿弥陀三尊（公開日や時間を確認）","夏のハス、秋の紅葉"],"q":["«白水» の地名は、どの漢字を分けたものと伝わる？","平泉の «泉»。上下に分けると «白» と «水» になります。"],"koji":[],"myth":"徳姫の系譜、建立年、地名の由来は伝承・諸説。","img":["浄土式庭園","奥州藤原氏"],"wp":"白水阿弥陀堂","rel":{"ev":[],"grave":[]},"ph":[["c:c/c1/Shiramizu_amidadou.jpg",500,375,"白水阿弥陀堂"],["c:2/2c/%E7%99%BD%E6%B0%B4%E9%98%BF%E5%BC%A5%E9%99%80%E5%A0%82_-_panoramio_%283%29.jpg",4752,3168],["c:f/fe/Shiramizu_Amida-do_Hall.jpg",1920,1080],["c:8/86/Shiramizu-Amidado-kyoiki.jpg",943,596],["c:4/46/Byodo-in_in_Uji.jpg",4440,2960,"浄土式庭園"]]},{"id":"07_enichiji","n":"慧日寺跡（徳一の寺）","yomi":"えにちじあと","cat":"寺社","rank":"S","y":807,"era":["heian"],"sh":"国指定史跡","ad":"耶麻郡磐梯町磐梯","st":"JR磐越西線磐梯町駅から歩いて約20分","la":37.57,"lo":139.997,"hook":"平安のはじめ、会津の山すそから都の最澄に «論争» をいどんだ僧がいた。その名は徳一。","lead":"慧日寺は、平安時代のはじめに法相宗の僧・徳一が開いたと伝わる寺で、かつて東北の仏教の中心として栄えました。今は寺のあとが国の史跡となり、発掘調査をもとに金堂や中門が復元されています。","story":["平安時代のはじめ、奈良で学んだ僧・徳一が東国へやってきました。徳一は会津の磐梯山のふもとに寺を開きます。これが慧日寺です。«なぜ都から遠いこの地に?» はっきりした理由はわかりませんが、徳一は常陸国（茨城県）などでも寺を開き、東国に仏教を広めた人でした。","ちょうどそのころ、都では最澄が天台宗を、空海が真言宗を開いていました。徳一は最澄と手紙で激しい論争をくり広げます。«すべての人が仏になれるのか、それとも仏になれない人もいるのか»。これは «三一権実論争» と呼ばれる、日本仏教史上有名な論争です。","空海も徳一に手紙を送り、真言宗の経典を写してほしいと頼んでいます。これに対し徳一は、真言宗への疑問をまとめた書を書きました。都の二人の天才と正面から議論した徳一は、いなかの僧どころか、当時を代表する学僧だったのです。","慧日寺はその後、大きな寺として栄え、多くの僧や僧兵をかかえたといわれます。しかし戦国時代の終わり、1589年に伊達政宗が会津の蘆名氏を攻めたとき、寺の建物の多くが焼けてしまったと伝わります。その後は小さな寺として続き、明治のはじめに廃寺となりました（のちに «恵日寺» として再興）。","昭和の終わりから本格的な発掘が行われ、金堂や講堂のあとが見つかりました。2008年には金堂が、当時の建て方にならって復元されています。寺のあとには、徳一の墓と伝わる石の塔 «徳一廟» も残ります。背後にそびえる磐梯山を見上げながら、1200年前の論争に思いをはせてみましょう。"],"tl":[["807年","徳一が慧日寺を開いたと伝わる"],["817年ごろ","最澄との論争が始まる"],["1589年","伊達政宗の会津攻めで多くの建物が焼けたと伝わる"],["明治初め","神仏分離の影響で廃寺となる"],["1970年","慧日寺跡が国の史跡に指定"],["2008年","金堂が復元される"]],"who":[["徳一","法相宗の僧。慧日寺を開き、最澄と論争した"],["最澄","天台宗を開いた僧。徳一の論争相手"],["空海","真言宗を開いた僧。徳一に手紙を送った"],["伊達政宗","会津攻めの際、慧日寺が焼けたとされる"]],"deep":["徳一の生まれや没年ははっきりせず、藤原仲麻呂の子とする説もありますが確かではありません。","三一権実論争: 徳一は «仏になれる素質は人によって違う» という法相宗の立場、最澄は «すべての人が仏になれる» という立場で論争しました。","空海は徳一あての手紙で経典の書写への協力を求めており、この手紙は «高野雑筆集» などに伝わると言われます。","慧日寺の創建を806年の磐梯山の噴火と結びつける話がありますが、この噴火自体が史料で確かめられず、伝承の域を出ません。","復元された金堂は、発掘された礎石の位置や平安時代の建築様式をもとに建てられました。","寺の宝物の一部は、近くの恵日寺（現在の寺）や資料館に伝えられています。"],"look":["復元された金堂と中門","講堂などの礎石","徳一廟（石の塔）","磐梯山慧日寺資料館","背後の磐梯山のながめ"],"q":["徳一が手紙で論争した、天台宗を開いた僧はだれ？","最澄です。«三一権実論争» と呼ばれます。"],"koji":[],"myth":"創建年・磐梯山噴火との関係・政宗による焼失は伝承を含む。","img":["徳一","三一権実諍論","磐梯山"],"wp":"慧日寺","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:6/62/Mt._Bandaisan_0811.JPG",3264,2448,"磐梯山"],["c:7/7f/JR_East_Bandaimachi_Station_building_%28West_Exit%29.jpg",5328,4000,"近く: 磐梯町駅"],["c:2/28/Alts_Bandai_02.jpg",4288,3216,"近く: 磐梯町"],["c:5/52/Bandai%2C_Michi-no-Eki%2C_Fukushima%2C_Japan%2C_April_2020.jpg",4032,3024,"近く: 道の駅ばんだい"],["c:6/64/Ryuuga_Spring.jpg",4000,3000,"近く: 龍ヶ沢湧水"]]},{"id":"07_aizu_otsukayama","n":"会津大塚山古墳","yomi":"あいづおおつかやまこふん","cat":"遺跡","rank":"S","y":350,"era":["kofun"],"sh":"国指定史跡","ad":"会津若松市一箕町八幡","st":"JR会津若松駅から車で約10分","la":37.5045,"lo":139.9495,"hook":"遠い会津の地から、ヤマト王権とつながる «三角縁神獣鏡» が見つかった。","lead":"会津大塚山古墳は、4世紀ごろに造られた長さ約114mの前方後円墳です。東北地方でもとても古い大きな古墳の一つで、発掘では鏡や刀などの豪華な副葬品が見つかりました。","story":["古墳時代、近畿地方のヤマト王権と結びついた各地の有力者は、前方後円墳という «かぎ穴形» の大きなお墓をつくりました。東北地方にも、その波は早くからとどいていました。会津大塚山古墳は、その代表の一つです。","1964年、この古墳で本格的な発掘調査が行われました。後円部の中からは、木の棺をおさめたあとが二つ見つかります。そして研究者たちを驚かせたのが、一面の銅鏡でした。«これは、三角縁神獣鏡だ!» 近畿を中心に見つかるこの鏡が、はるか北の会津から出てきたのです。","ほかにも、柄の頭が輪の形になった «環頭大刀»、矢を入れる «靫»、玉や鉄の道具など、たくさんの品が見つかりました。これらは国の重要文化財に指定されています。«会津の王» は、ヤマト王権とつながりを持つ力のある人物だったのでしょう。","«会津» という地名には、古事記に出てくる話があります。四道将軍として北陸道へ向かった大毘古命と、東海道へ向かったその子・建沼河別命が、この地でばったり «相い津（出会った）» ので «相津» と名づけた、というのです。言い伝えではありますが、古墳が造られたころの、地方と中央との結びつきを思わせる話です。","今、古墳は森におおわれた丘になっていて、上に登ることもできます。近くには飯盛山や、ほかの古墳もあります。会津盆地を見わたしながら、1600年以上前にこの地を治めた «王» のすがたを想像してみましょう。"],"tl":[["4世紀ごろ","会津大塚山古墳が造られる"],["1964年","本格的な発掘調査。三角縁神獣鏡などが出土"],["1977年","国の史跡に指定"],["昭和後期","出土品が国の重要文化財に指定"]],"who":[["会津の首長（王）","古墳に葬られた人物。名前はわからない"],["大毘古命","古事記に登場する四道将軍。会津の地名伝説に出てくる"],["建沼河別命","大毘古命の子。父と会津で出会ったと伝わる"]],"deep":["墳丘の長さは約114m。東北地方の古い前方後円墳の中でも大型で、築造時期は4世紀後半ごろとする説が多いですが、年代には幅があります。","三角縁神獣鏡は、ヤマト王権が各地の有力者に配ったと考える説がある鏡です。会津で見つかったことは、この地域が早くから王権とつながっていた証拠とされます。","後円部には南北二つの棺のあとがあり、副葬品の内容から、それぞれ性格のちがう人物が葬られた可能性も考えられています。","出土品は福島県立博物館で見ることができます（展示状況は要確認）。","環頭大刀は、柄の頭に輪のかざりがついた刀で、身分の高さを示す品と考えられています。","会津の地名伝説は古事記にもとづくもので、史実かどうかは確かめられません。","会津盆地には、このほか亀ヶ森古墳・鎮守森古墳（会津坂下町）など古い前方後円墳がいくつもあり、古墳時代前期の会津が東北の中でも早くから開けた地域だったことがわかります。","古墳は丘の地形を利用して造られていて、墳丘の上からは会津盆地を広く見わたせます。«見せる墓» として、盆地のどこからも見上げられる場所が選ばれたと考えられています。"],"look":["前方後円墳の形がわかる墳丘","後円部の頂上からの会津盆地のながめ","案内板の出土品の説明","福島県立博物館の出土品展示"],"q":["会津大塚山古墳で見つかった、近畿地方とのつながりを示す鏡は？","三角縁神獣鏡です。"],"koji":[],"myth":"«会津» の地名伝説は古事記の伝承。築造年代には幅がある。","img":["三角縁神獣鏡","前方後円墳"],"wp":"会津大塚山古墳","rel":{"ev":[],"grave":[]},"ph":[["c:e/e8/%E4%BC%9A%E6%B4%A5%E5%A4%A7%E5%A1%9A%E5%B1%B1%E5%8F%A4%E5%A2%B3.jpg",2810,1702,"会津大塚山古墳"],["c:d/d6/Aizu-otsukayama-kofun_funcho.JPG",6016,4000],["c:c/c9/Aizu-otsukayama-kofun_2gou-fun.JPG",6016,4000],["j:e/e2/%E4%BC%9A%E6%B4%A5%E5%A4%A7%E5%A1%9A%E5%B1%B1%E5%8F%A4%E5%A2%B3%E5%8D%97%E6%A3%BA%E5%87%BA%E5%9C%9F_%E4%B8%89%E8%A7%92%E7%B8%81%E5%94%90%E8%8D%89%E6%96%87%E5%B8%AF%E4%B8%89%E7%A5%9E%E4%BA%8C%E7%8D%A3%E9%8F%A1.JPG",3478,3162],["j:1/14/%E8%9F%B9%E6%B2%A2%E5%8F%A4%E5%A2%B3%E5%87%BA%E5%9C%9F_%E4%B8%89%E8%A7%92%E7%B8%81%E5%90%8C%E5%90%91%E5%BC%8F%E7%A5%9E%E7%8D%A3%E9%8F%A1.JPG",3559,3359,"三角縁神獣鏡"],["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"]]},{"id":"07_soma_nakamura","n":"相馬中村城（相馬野馬追）","yomi":"そうまなかむらじょう","cat":"城","rank":"S","y":1611,"era":["edo"],"sh":"","ad":"相馬市中村","st":"JR常磐線相馬駅から歩いて約15分","la":37.796,"lo":140.916,"hook":"平将門の子孫を名のる相馬氏が、およそ260年守りつづけた城。甲冑の騎馬武者がかけぬける祭りのふるさと。","lead":"相馬中村城は、江戸時代に相馬中村藩の藩主・相馬氏がくらした城です。天守はありませんが、堀や石垣、大手一ノ門が残ります。城内の相馬中村神社は、相馬野馬追にかかわる神社として知られています。","story":["相馬氏は、平安時代の武将・平将門の子孫だと伝えています。鎌倉時代に下総国（千葉県）から奥州の相馬の地へ移り、この地方をおさめてきました。戦国時代には伊達氏と何度も戦いながら、領地を守りぬきました。","1600年の関ヶ原の戦いのとき、相馬氏ははっきり味方をしなかったため、いったん領地を取り上げられそうになります。しかし交渉のすえ領地は守られ、1611年、相馬利胤は本拠地を小高から中村に移して城を整えました。これが相馬中村城です。«馬陵城» という別名もあります。","城には天守もあったといわれますが、1670年に雷で焼けてしまい、その後は建てられませんでした。それでも、深い堀や土塁、石垣が本丸を囲み、城らしさを今も感じられます。二の丸へ向かう入口の «大手一ノ門» は江戸時代の建物が残り、市の文化財になっています。","相馬の人びとが大切にしてきたのが «相馬野馬追» です。甲冑姿の騎馬武者が、先祖伝来の旗をなびかせて野原をかけぬけ、空から落ちてくる御神旗をうばい合います。将門が野馬を敵に見立てて軍事訓練をしたのが始まり、と伝わっています。«まるで戦国時代にタイムスリップしたみたい!» と見物客が驚く、国の重要無形民俗文化財です。","本丸にある相馬中村神社は、相馬氏の守り神である妙見さまをまつる神社で、野馬追のときには騎馬武者たちがここから出陣します。2011年の東日本大震災で相馬の町も大きな被害を受けましたが、その年も野馬追は規模を小さくして行われ、ふるさとの人びとを励ましました。"],"tl":[["1611年","相馬利胤が小高から中村へ本拠を移す"],["1643年","相馬中村神社の社殿が建てられる"],["1670年","天守が落雷で焼ける"],["1868年","戊辰戦争で相馬中村藩は新政府軍に降伏"],["1871年","廃藩置県で城の役目が終わる"],["2011年","東日本大震災の年も野馬追が行われる"]],"who":[["相馬利胤","相馬中村藩の初代藩主。中村に城を移した"],["平将門","相馬氏の祖先と伝わる武将。野馬追の起源伝説に登場"],["相馬義胤","戦国時代の当主。伊達政宗と争った"],["二宮尊徳","相馬中村藩が «御仕法» を取り入れた農政家"]],"deep":["相馬中村神社の社殿は1643年の建築で、国の重要文化財です。","相馬野馬追は、相馬中村神社・相馬太田神社・相馬小高神社の三つの妙見社のお祭りで、国の重要無形民俗文化財に指定されています。","野馬追の起源を平将門とする話は伝承で、史料で確かめることはできません。","相馬中村藩は江戸時代後期、二宮尊徳の «報徳仕法» を取り入れ、ききんで荒れた村と藩の財政の立て直しに取り組みました。","城の石垣は、本丸・二の丸まわりに部分的に残り、赤い橋（赤橋）など城跡公園として整備されています。","戊辰戦争で相馬中村藩は奥羽越列藩同盟に加わりましたが、のちに新政府軍に降伏しました。"],"look":["大手一ノ門","本丸の相馬中村神社（国重要文化財）","堀と石垣、赤橋","城跡の桜"],"q":["相馬中村神社がまつる、相馬氏の守り神は？","妙見さま（妙見菩薩）。北極星・北斗七星の神とされます。"],"koji":[],"myth":"相馬氏が将門の子孫であること、野馬追の起源は伝承。","img":["相馬野馬追","相馬中村神社","相馬中村藩"],"wp":"相馬中村城","rel":{"ev":[],"grave":[]},"ph":[["c:f/fe/Somanakamura_Castle.jpg",3264,1835,"相馬中村城"],["c:c/c6/Soma_otemon.JPG",3072,2304],["c:5/5f/Nakamura_shrine_002.JPG",3072,2304],["c:6/6d/Moat_of_somanakamura_castle.jpg",1600,1200],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:1/15/The_Soma_Nomaoi_2005-5.jpg",960,1280,"相馬野馬追"],["c:7/77/Somanakamura_shrine.jpg",1600,1600,"相馬中村神社"]]},{"id":"07_asaka_sosui","n":"安積疏水（十六橋水門）","yomi":"あさかそすい（じゅうろっきょうすいもん）","cat":"近代","rank":"S","y":1882,"era":["meiji"],"sh":"","ad":"会津若松市河東町・猪苗代町（十六橋水門）ほか","st":"十六橋水門へはJR猪苗代駅から車で約15分","la":37.518,"lo":140.038,"hook":"猪苗代湖の水を、山をぬいて東へ。荒れ野だった郡山を、日本有数の米どころに変えた大工事。","lead":"安積疏水は、明治時代に国の事業としてつくられた用水路で、猪苗代湖の水を奥羽山脈の向こうの安積原野（郡山）へ運びます。湖の出口には水量を調節する十六橋水門が築かれ、オランダ人技師ファン・ドールンの設計とされています。","story":["明治のはじめ、郡山の西に広がる安積原野は、水が少なく作物の育ちにくい荒れ野でした。一方、山をはさんだ西側には大きな猪苗代湖があります。«あの水を、こちらへ引けないだろうか?» 地元の人たちは古くからそう願っていました。","この願いを国の事業として進めたのが、内務卿の大久保利通でした。明治維新で仕事を失った各地の士族に新しい土地を与え、国の産業をさかんにする――そのために安積原野の開拓が選ばれたのです。久留米や鳥取、岡山など、全国から士族の家族が移り住むことになりました。","1878年、工事の計画が決まりますが、その直後に大久保は東京で暗殺されてしまいます。それでも事業は引きつがれ、1879年に工事が始まりました。オランダから来ていた技師ファン・ドールンは現地を調べ、湖の水位を調節する水門をつくれば、会津側の田んぼに迷惑をかけずに水を東へ送れると考えました。","工事には、のべ85万人ともいわれる多くの人が働き、山にトンネルを掘り、川や谷をこえて水路をのばしました。そして1882年、ついに疏水が完成します。«水が来たぞ!» 荒れ野だった土地に次々と田んぼがつくられ、郡山は大きく発展していきました。","疏水の水はのちに発電にも使われ、その電気が郡山の工場を動かし、町は福島県を代表する都市へ成長しました。十六橋水門は今も猪苗代湖の出口で水を守っています。2016年、安積疏水は «世界かんがい施設遺産» に登録され、日本遺産の物語にもなりました。"],"tl":[["1876年","明治天皇の東北巡幸にあわせ、安積の開拓が注目される"],["1878年","疏水の事業が決まる。大久保利通が暗殺される"],["1879年","工事が始まる"],["1880年ごろ","十六橋水門が完成したとされる"],["1882年","安積疏水が完成"],["1899年","疏水の水を使った沼上発電所が送電を開始"],["2016年","世界かんがい施設遺産に登録"]],"who":[["大久保利通","内務卿。安積開拓と疏水を国の事業として進めた"],["ファン・ドールン","オランダ人技師。疏水の調査・設計にかかわった"],["中條政恒","福島県の役人。安積原野の開拓を進めた"],["全国の士族たち","久留米・鳥取などから移住し、原野を開いた"]],"deep":["十六橋水門は石造りの水門で、湖の出口の日橋川にあります。猪苗代湖の水位を調節し、会津側と郡山側の両方に水を配る役目をもっています。","ファン・ドールンがどこまで設計にかかわったかは研究者の間で議論があり、実際の工事では日本人技術者の役割も大きかったと考えられています。","郡山の «開成山大神宮» や «開成館» は、安積開拓の歴史を伝える場所です。開成館は福島県の重要文化財です。","十六橋の近くのファン・ドールン像は、戦争中に金属供出を逃れるため地元の人が隠して守ったと伝わります。","安積疏水は、那須疏水・琵琶湖疏水とならんで «日本三大疏水» と呼ばれることがあります。","安積疏水と開拓をめぐる物語は、郡山市などの «日本遺産» の構成要素にもなっています。"],"look":["十六橋水門と猪苗代湖の出口","ファン・ドールン像","郡山市の開成館（開拓の資料）","疏水ぞいの取水口や水路"],"q":["安積疏水は、どこの湖の水を郡山へ運んでいる？","猪苗代湖です。十六橋水門で水量を調節しています。"],"koji":[],"myth":"工事の人数、ファン・ドールン像を隠した話、設計の役割分担には諸説。","img":["十六橋水門","ファン・ドールン","大久保利通"],"wp":"安積疏水","rel":{"ev":[],"grave":[]},"ph":[["c:5/5b/AsakaSosuiKansenSuiroB.JPG",3072,2304],["c:f/fc/20090321%E5%A5%A5%E7%BE%BD%E5%B1%B1%E8%84%88Tagged.jpg",2560,1370],["c:a/ae/TakenouchiHatsudensho.jpg",1280,960],["c:c/cd/NumagamiHatsudensho.jpg",1280,960],["c:2/2e/JoukoToushukou.jpg",1280,960],["c:e/e6/FukadaDamMomument.jpg",1280,960],["c:8/88/FukadaDam.jpg",1280,960],["c:0/00/FukadaChouseichi.jpg",1280,960]]},{"id":"07_denshokan","n":"東日本大震災・原子力災害伝承館","yomi":"ひがしにほんだいしんさい・げんしりょくさいがいでんしょうかん","cat":"事件","rank":"S","y":2011,"era":["heisei","reiwa"],"sh":"","ad":"双葉郡双葉町中野","st":"JR常磐線双葉駅から車で約5分（駅から送迎・路線バスの運行日あり、事前に確認）","la":37.4615,"lo":141.023,"hook":"地震、津波、そして原発事故。«ふるさとに帰れない» という災害を、未来へ語りつぐ場所。","lead":"2011年3月11日の東日本大震災と、それに続く東京電力福島第一原子力発電所の事故。その記録と教訓を伝えるため、2020年に双葉町に開館したのがこの伝承館です。当時の資料や証言を通して、何が起き、人びとがどう生きてきたのかを学ぶことができます。","story":["2011年3月11日午後2時46分、三陸沖を震源とするマグニチュード9.0の巨大地震が起きました。福島県の沿岸にも大きな津波がおしよせ、多くの尊い命が失われました。家族や友だち、ふるさとの景色が、一瞬で奪われたのです。","さらに、津波におそわれた東京電力福島第一原子力発電所では、電源が失われて原子炉を冷やせなくなり、水素爆発などが起きました。放射性物質が広い範囲に広がり、周辺の町や村の人びとは避難を強いられました。双葉町は、町の全域から住民が避難することになりました。","«すぐに帰れると思っていた»。多くの人がそう語ります。着のみ着のままで家を出た人たちは、何年も、あるいは今も、ふるさとに帰れない日々を過ごしています。避難のなかで体調をくずして亡くなった人も少なくありません。この災害は、一日で終わる災害ではなかったのです。","伝承館には、地震で止まった時計、避難所で使われた掲示物、子どもたちが残した言葉など、たくさんの実物資料が展示されています。また、当時を経験した «語り部» の人たちが、自分の言葉で体験を伝えています。«なぜこんなことが起きたのか?»«どうすればくり返さずにすむのか?» 展示は訪れる人に問いかけてきます。","双葉町では、2022年に一部の地域で避難指示が解除され、少しずつ人が戻りはじめました。伝承館の近くには、津波の被害を受けた浪江町の請戸小学校が震災遺構として残されています。亡くなった方々への祈りとともに、ここで知ったことを家族や友だちに伝えることが、この場所を訪れる意味なのかもしれません。"],"tl":[["2011年3月11日","東日本大震災が発生。津波が沿岸をおそう"],["2011年3月12日以降","福島第一原発で水素爆発などが起き、避難が広がる"],["2011年","双葉町の全域から住民が避難"],["2020年9月","東日本大震災・原子力災害伝承館が開館"],["2021年","浪江町の請戸小学校が震災遺構として公開"],["2022年8月","双葉町の一部で避難指示が解除される"]],"who":[["双葉町の人びと","町の全域から避難し、長くふるさとを離れた"],["語り部の人たち","自らの体験を来館者に伝えている"],["請戸小学校の児童と先生","津波の前に全員で避難し、無事だった"]],"deep":["伝承館は福島県がつくった施設で、震災と原発事故にかかわる多くの資料を集め、その一部を展示しています。","展示はプロローグのシアターから始まり、震災前の地域のくらし、地震と津波、原発事故と避難、復興への歩みの順に見るつくりになっています。","浪江町の請戸小学校は、津波が2階までおしよせましたが、児童と教職員は近くの大平山へ避難して全員無事でした。建物は福島県で最初の震災遺構として公開されています。","原発事故による避難指示は、放射線量の低下や除染の進み具合に応じて段階的に解除されてきました。今も立ち入りが制限されている区域があります。","原発事故のあと、避難生活のなかで亡くなった «震災関連死» は、福島県で特に多いことが知られています。","伝承館では、語り部による講話が定期的に行われています（日時は要確認）。"],"look":["導入のシアター展示","地震・津波・原発事故・避難の実物資料","語り部の講話","屋上からの沿岸部のながめ","近くの震災遺構・請戸小学校（浪江町）"],"q":["双葉町で避難指示が一部解除されたのは何年？","2022年です。事故から11年以上がたっていました。"],"koji":[],"myth":"","img":["東日本大震災","福島第一原子力発電所事故","双葉町","請戸小学校"],"wp":"東日本大震災・原子力災害伝承館","rel":{"ev":[],"grave":[]},"ph":[["c:6/6a/%E6%9D%B1%E6%97%A5%E6%9C%AC%E5%A4%A7%E9%9C%87%E7%81%BD%E3%83%BB%E5%8E%9F%E5%AD%90%E5%8A%9B%E7%81%BD%E5%AE%B3%E4%BC%9D%E6%89%BF%E9%A4%A8.jpg",4000,2667,"東日本大震災・原子力災害伝承館"],["c:e/e4/Distant_view_of_Rikuzentakata.jpg",3872,2592,"東日本大震災"],["c:6/69/Appearance_of_Fukushima_I_Nuclear_Power_Plant_Unit_3_after_the_explosion_20110315.jpg",1000,750,"福島第一原子力発電所事故"]]},{"id":"07_buke_yashiki","n":"会津武家屋敷（西郷頼母邸）","yomi":"あいづぶけやしき（さいごうたのもてい）","cat":"大名屋敷","rank":"A","y":1868,"era":["edo"],"sh":"","ad":"会津若松市東山町石山院内","st":"JR会津若松駅からまちなか周遊バス «ハイカラさん» で約25分、«会津武家屋敷前» 下車すぐ","la":37.484,"lo":139.9585,"hook":"38の部屋をもつ家老の屋敷。その奥の一室で、戊辰戦争の悲劇が起きた。","lead":"会津武家屋敷は、会津藩の家老・西郷頼母の屋敷を復元した施設です。部屋数が38もある大きな屋敷で、上級武士のくらしがよくわかります。ここでは、会津戦争のときに西郷家の女性たちが自ら命を絶った悲劇も伝えられています。","story":["西郷頼母は、会津藩で代々家老をつとめた家の当主でした。本当の屋敷は鶴ヶ城の北出丸のすぐ前にありましたが、戊辰戦争で焼け、今の建物は記録をもとに東山温泉への道の途中に復元されたものです。","屋敷には、藩主を迎えるための特別な部屋や、身分によって使い分ける玄関、家族の生活の場、使用人の部屋まであります。«家老の家って、こんなに広いの?» と驚くほどです。当時の上級武士が、藩の政治と家のしきたりの両方を背負って生きていたことが伝わってきます。","頼母は、藩主の松平容保が京都守護職を引き受けることに強く反対したといわれます。«会津の力では無理です、藩がほろびます»。その意見はいれられず、頼母は一時、役をしりぞきました。戊辰戦争がはじまると呼びもどされ、白河口の総督として戦いました。","1868年旧暦8月23日、新政府軍が城下に攻めこんだ日。頼母の母や妻の千重子、幼い娘たちなど一族の女性・子ども21人は、城に入らず屋敷で自ら命を絶ちました。«足手まといにならぬように»。そう覚悟していたと伝わります。千重子の辞世の句は «なよ竹の 風にまかする 身ながらも たわまぬ節は ありとこそ聞け»。","頼母はのちに名前を保科近悳と改め、明治の世を生き、日光東照宮の宮司などもつとめました。屋敷には一族の自刃の場面が人形で再現され、訪れる人が静かに手を合わせています。武家屋敷の敷地には、ほかに会津藩の陣屋や、米をつく水車小屋なども移されています。"],"tl":[["江戸時代","西郷家が代々会津藩の家老をつとめる"],["1862年","松平容保が京都守護職に。頼母は反対したといわれる"],["1868年","頼母が白河口総督として戦う"],["1868年旧暦8月23日","西郷家の女性・子ども21人が自刃"],["1903年","頼母（保科近悳）が亡くなる"],["昭和","屋敷が現在地に復元される"]],"who":[["西郷頼母","会津藩家老。京都守護職に反対したと伝わる"],["西郷千重子","頼母の妻。一族とともに自刃した"],["松平容保","会津藩主"],["西郷四郎","頼母の養子。柔道家で «姿三四郎» のモデルといわれる"]],"deep":["屋敷は38部屋、約280坪ともいわれます。来客の身分によって通す玄関や部屋が細かく決まっていました。","自刃した西郷家の女性と子どもは21人と伝わり、中には2歳の子もいたといわれます。中に入った新政府軍の土佐藩士・中島信行が、まだ息のあった娘に頼まれて介錯したという話が伝わっています。","頼母が生きのびたことについて、当時から批判的な見方もあり、会津の中でも評価が分かれた人物です。","西郷四郎は講道館柔道の初期の四天王の一人で、富田常雄の小説 «姿三四郎» のモデルといわれます（小説は創作）。","敷地内の «旧中畑陣屋» は、江戸時代の陣屋建築として移築・保存されている建物です。","鶴ヶ城の北出丸前には、もとの西郷邸の場所を示す碑があります。"],"look":["家老屋敷の表玄関と御成の間","西郷一族自刃の間（人形による再現）","千重子の辞世の歌碑","旧中畑陣屋","水車でまわる精米所"],"q":["西郷頼母は、藩主の何に反対したといわれる？","京都守護職を引き受けること。藩の力では負担が大きすぎると考えたといわれます。"],"koji":[{"w":"なよ竹の風にまかする身ながらもたわまぬ節はありとこそ聞け","m":"西郷千重子の辞世。しなやかな竹のように風にまかせる身でも、曲がらない節（志）がある、という意味"}],"myth":"自刃の場面の細部（介錯の話など）は伝承。頼母の京都守護職反対の言葉も伝承による。","img":["西郷頼母","会津戦争","西郷四郎"],"wp":"会津武家屋敷","rel":{"ev":[],"grave":[]},"ph":[["c:5/53/Aizu_Bukeyashiki_Garden.jpg",4608,3456,"会津武家屋敷"],["c:3/34/Aizu_Bukeyashiki_Garden_03.jpg",4608,3456],["c:e/e6/Fukushima-Aizu_Buke-Yashiki_%28Samurai_Residence%29-m.jpg",1920,1280],["c:c/ce/Saig%C5%8D_Tanomo.jpg",367,565,"西郷頼母"],["c:5/50/Battle_of_Aizu_at_Wakamatsu_castle_by_Tsukioka_Yoshitoshi.png",3877,1900,"会津戦争"],["c:f/f6/Saigo_Shirou.jpg",990,1333,"西郷四郎"]]},{"id":"07_oyakuen","n":"御薬園（会津松平氏庭園）","yomi":"おやくえん","cat":"大名屋敷","rank":"A","y":1696,"era":["muromachi","edo"],"sh":"国指定名勝","ad":"会津若松市花春町","st":"JR会津若松駅からまちなか周遊バス «ハイカラさん» で約15分、«御薬園» 下車すぐ","la":37.4945,"lo":139.945,"hook":"殿さまの庭であり、薬草の畑でもあった。戦火をまぬがれた、会津の «ひみつの庭»。","lead":"御薬園は、会津藩の歴代藩主の別荘として使われた大名庭園です。名前のとおり、薬草を育てる畑があり、藩の人びとのための薬もつくっていました。池を中心とした美しい庭は «会津松平氏庭園» として国の名勝に指定されています。","story":["このあたりには昔から «霊泉» と呼ばれる泉がわいていたといわれます。室町時代、会津を治めていた蘆名氏の当主が、この泉のそばに小さなお堂をつくったのが始まりと伝わります。","江戸時代、会津藩の藩主となった保科正之は、ここに薬草を育てる畑をつくりました。ききんや病気から領民を守るには、薬が欠かせません。«薬をつくる庭» ――これが «御薬園» の名前のもとです。のちの藩主たちは朝鮮人参の栽培にも取り組み、会津の特産品になりました。","3代藩主・松平正容のころ、庭は大きくつくりかえられました。池の中に島をうかべ、そこに茶室 «楽寿亭» を建て、まわりの山を借景にした回遊式の庭園です。«殿さまはどんな気持ちでこの池をながめたのだろう?» 池のまわりを歩くと、景色が少しずつ変わっていきます。","1868年の会津戦争のとき、城下は大きな被害を受けました。けれど御薬園は、新政府軍が負傷者の治療所として使ったため、焼かれずに残ったといわれます。薬の庭が、戦争の中で人の命を救う場所になったのです。","今も薬草園では、400種類ほどの薬草が育てられています。園内のお休み処では、薬草を使ったお茶を味わうこともできます。静かな池と茶室、季節ごとの花や紅葉が、訪れる人の心をいやしてくれます。"],"tl":[["室町時代","蘆名氏がこの地の霊泉のそばにお堂を建てたと伝わる"],["1670年ごろ","保科正之が薬草園をつくる"],["1696年ごろ","松平正容が庭園を大改修し、現在の形に"],["江戸時代後期","朝鮮人参の栽培がさかんになる"],["1868年","会津戦争で新政府軍の治療所となり、焼けずに残る"],["1932年","国の名勝に指定"]],"who":[["保科正之","会津藩初代藩主。薬草園をつくった"],["松平正容","3代藩主。庭園を大改修した"],["目黒浄定","庭の改修にかかわった庭師と伝わる"],["蘆名氏","室町・戦国時代の会津の領主。御薬園のはじまりに関わると伝わる"]],"deep":["庭は池の中央に島を配し、その島に茶室 «楽寿亭» を建てた «心字の池» を中心とする回遊式庭園です。","借景として、東の小田山などの景色が取りこまれています。","会津藩は江戸時代後期に朝鮮人参の栽培を藩の産業として進め、清（中国）への輸出品にもなったといわれます。","庭園の改修には、小堀遠州の流れをくむとされる庭師・目黒浄定がかかわったと伝わります。","戊辰戦争のあと、新政府軍の治療所として使われたことで建物が残ったという話は、会津ではよく知られています。","園内の重陽閣は、昭和のはじめに秩父宮妃勢津子さまが泊まられた建物を移したものです。","勢津子さまは松平容保の孫にあたる方で、1928年に秩父宮と結婚されました。«朝敵» とされた会津の家から皇族妃が出たことは、会津の人びとにとって名誉回復の出来事として大きな喜びだったと伝えられています。"],"look":["心字の池と中島の茶室 «楽寿亭»","薬草園の薬草","重陽閣","池のまわりの回遊路と四季の景色"],"q":["御薬園という名前の由来は？","藩主・保科正之がここに薬草を育てる畑をつくったことから。"],"koji":[],"myth":"蘆名氏の霊泉の話、庭師の名前、戦火をまぬがれた理由には伝承を含む。","img":["保科正之","会津藩"],"wp":"御薬園","rel":{"ev":[],"grave":[]},"ph":[["c:6/6a/Oyakuen%2C_Aizu_1.JPG",3264,2448,"御薬園"],["c:9/9d/Oyakuen%2C_Aizu_3.JPG",2932,2199],["c:0/08/Ch%C5%8Dy%C5%8Dkaku_at_Aizu_Matsudaira%27s_Royal_Garden.JPG",1600,1200],["c:2/2c/Hoshina_Masayuki2.jpg",414,402,"保科正之"],["c:7/72/March_2011_The_Aizu-Wakamatsu_Castle.jpg",640,480,"会津藩"]]},{"id":"07_matsudaira_byo","n":"院内御廟（会津藩主松平家墓所）","yomi":"いんないごびょう","cat":"墓所","rank":"A","y":1681,"era":["edo","meiji"],"sh":"国指定史跡","ad":"会津若松市東山町石山院内","st":"JR会津若松駅からバスで約20分、«奴郎ヶ前» 付近から歩いて約5分（山の斜面の石段が続く）","la":37.483,"lo":139.964,"hook":"大きな亀が墓碑を背負う。森の奥に眠る、会津藩の殿さまたちの «神道式» の墓。","lead":"院内御廟は、会津藩の2代藩主から9代藩主・松平容保までの歴代藩主とその家族が眠る墓所です。多くが神道の形式でつくられた、全国でもめずらしい大名の墓で、国の史跡に指定されています。","story":["鶴ヶ城から東へ、東山温泉へ向かう山の斜面に、うっそうとした杉の森があります。その中に、会津藩主の墓所 «院内御廟» があります。初代藩主・保科正之の墓だけは、猪苗代町の見禰山にありますが、2代正経から9代容保までの藩主たちはここに眠っています。","江戸時代の大名の墓の多くは、仏教の寺の中につくられました。けれど会津松平家の墓の多くは、神道の形式です。これは、神道を深く学んだ初代・保科正之の考えを受けついだためと考えられています。«なぜ仏教ではなく神道なのか?» その答えは、藩のはじまりの人の信念にあるのです。","墓は、石段をのぼった先にならんでいます。八角形の «鎮石» と呼ばれる石を土まんじゅうの上に置き、その前に表石、さらに大きな亀の形の台に乗った墓碑が建っています。亀が石碑を背負う形を «亀趺» といい、長寿や力強さを表しています。","9代藩主の松平容保は、会津戦争のあと、明治の世を東京で生き、1893年に亡くなりました。容保は孝明天皇からいただいた手紙をおさめた竹筒を、生涯肌身はなさず持っていたといわれます。その容保も、ふるさと会津のこの森に葬られました。","墓所は山の斜面にあり、広い範囲に墓が点在しています。森の中の石段は少し大変ですが、静かな空気の中を歩くと、会津藩の260年あまりの歴史と、最後の藩主の思いにふれることができます。見学のときは、墓所であることを忘れずに静かに歩きましょう。"],"tl":[["1672年","初代・保科正之が亡くなる（墓は猪苗代の見禰山）"],["1681年","2代藩主・正経が亡くなる"],["江戸時代","歴代藩主がこの地に葬られる"],["1893年","9代藩主・松平容保が東京で亡くなり、この地に葬られる"],["昭和","会津藩主松平家墓所として国の史跡に指定（猪苗代の正之の墓とあわせて）"]],"who":[["保科正之","初代藩主。神道を重んじ、墓所の形式にも影響をあたえた"],["松平正経","2代藩主。院内御廟に葬られた最初の藩主"],["松平容保","9代藩主。幕末の京都守護職"],["孝明天皇","容保を信頼し、手紙（御宸翰）を与えた天皇"]],"deep":["神道式の墓は、«鎮石»（八角形の石）«表石»（名前を刻んだ石）«碑石»（亀趺の上の石碑）の組み合わせでできていると説明されます。","墓の大きさや形式は藩主によって少しずつちがいがあり、見比べると時代による変化も感じられます（詳しくは現地の案内を確認）。","国の史跡 «会津藩主松平家墓所» は、この院内御廟と、猪苗代町の保科正之の墓（見禰山）の二つをあわせた指定です。","容保が肌身はなさず持っていたとされる孝明天皇の御宸翰は、会津藩が朝敵ではなかったことを示すものとして、明治以後に大きな意味をもちました。","墓所は山の斜面に広がり、藩主のほか夫人や子どもなど一族の墓も含まれます。上下の段に分かれて配置されています。"],"look":["亀趺（亀の台）に乗った大きな墓碑","八角形の鎮石","9代藩主・松平容保の墓","杉の森と石段の参道"],"q":["院内御廟の墓碑を背負っている動物は？","亀です。この形を «亀趺» といいます。"],"koji":[],"myth":"墓の形式の由来（正之の考えを受けついだ）、容保の竹筒の話は伝承を含む。","img":["松平容保","保科正之"],"wp":"会津藩主松平家墓所","rel":{"ev":[],"grave":[]},"ph":[["c:5/5e/AizuMatsudairake_Bosyo.JPG",3001,2441,"会津藩主松平家墓所"],["c:9/90/Matudaira_Katamori.jpg",993,1548,"松平容保"],["c:2/2c/Hoshina_Masayuki2.jpg",414,402,"保科正之"]]},{"id":"07_hanitsu_jinja","n":"土津神社（保科正之）","yomi":"はにつじんじゃ","cat":"寺社","rank":"A","y":1675,"era":["edo"],"sh":"国指定史跡","ad":"耶麻郡猪苗代町見禰山","st":"JR磐越西線猪苗代駅から車で約5分、歩くと約30分","la":37.5775,"lo":140.101,"hook":"将軍の弟でありながら、名もない家で育った殿さま。その人を «神» としてまつる社。","lead":"土津神社は、会津藩の初代藩主・保科正之をまつる神社です。正之は «土津霊神» という神の名でまつられ、神社の奥には正之の墓があります。幕府の政治を支え、会津藩の土台をつくった名君として知られています。","story":["保科正之は、2代将軍・徳川秀忠の子として生まれました。けれど母の身分が低く、正室の目をはばかって、正之の存在はかくされました。正之は信濃国高遠（長野県）の保科家で養子として育てられます。«将軍の子なのに、どうして?» それが江戸時代のしきたりでした。","やがて、異母兄である3代将軍・家光が正之の存在を知り、その人柄と才能を気に入ります。正之は山形をへて、会津23万石の藩主となりました。家光は死の直前、«幼い家綱をたのむ» と正之に言い残したといわれます。","4代将軍・家綱を支えた正之は、江戸の町を大火が焼きつくした明暦の大火のあと、«天守を建て直すより、町の復興が先だ» と主張したといわれます。そのため江戸城の天守は、その後二度と建てられませんでした。家臣の殉死の禁止を進めたのも正之の時代です。","会津では、ききんにそなえて米をたくわえる «社倉» の制度をつくり、藩士の心がまえを15か条の «家訓» にまとめました。第一条には «会津藩は将軍家を守ることに尽くせ» という意味のことが書かれています。この家訓が、幕末の会津藩の運命を決めることになりました。","正之は神道を深く学び、生前、自ら猪苗代の見禰山を墓所に選んだといわれます。正之が亡くなったあと、1675年に神社が建てられました。戊辰戦争で社殿は焼けてしまいましたが、明治になって再建されました。境内には正之の事績を刻んだ大きな石碑が、亀の台に乗って建っています。"],"tl":[["1611年","保科正之が生まれる"],["1643年","会津藩主となる"],["1651年","家光の遺言で4代将軍家綱を補佐する"],["1657年","明暦の大火。天守の再建を見送る"],["1668年","会津藩の «家訓» 15か条を定める"],["1672年","正之が亡くなる"],["1675年","土津神社が建てられる"],["1868年","戊辰戦争で社殿が焼ける"],["明治","社殿が再建される"]],"who":[["保科正之","会津藩初代藩主。土津霊神としてまつられる"],["徳川秀忠","2代将軍。正之の父"],["徳川家光","3代将軍。異母弟の正之を重く用いた"],["徳川家綱","4代将軍。正之が補佐した"],["吉川惟足","神道家。正之に神道を教え、霊号をおくった"]],"deep":["«土津» の名は、正之が神道の師・吉川惟足からさずかった霊号 «土津霊神» による。«土» の字には吉川神道の教えにもとづく意味がこめられていると説明されます。","境内の «土津霊神之碑» は、亀趺の上に建つ非常に大きな石碑で、正之の生涯と業績が刻まれています。","正之の墓は神道式で、八角形の鎮石などがあります。院内御廟とあわせて国の史跡 «会津藩主松平家墓所» に指定されています。","社殿は創建当時、日光東照宮にもくらべられるほど豪華だったと伝わりますが、1868年に焼失しました。会津藩が敵の手に渡るのを避けて自ら焼いたともいわれます。","正之の «家訓» は、藩主の座を継ぐ者は必ずこれを守ることとされ、幕末の容保が京都守護職を受けたのも、この家訓があったからだといわれます。","藩主家の苗字を «保科» から «松平» に改めたのは、正之ではなく3代・正容のときです。"],"look":["朱色の社殿と参道","土津霊神之碑（亀趺の大石碑）","奥の院の保科正之の墓","秋の紅葉"],"q":["保科正之の父はだれ？","2代将軍・徳川秀忠です。"],"koji":[],"myth":"創建時の社殿の豪華さや、戊辰で自ら焼いた話は伝承。天守再建見送りの言葉も伝承による。","img":["保科正之","会津藩家訓","明暦の大火"],"wp":"土津神社","rel":{"ev":[],"grave":[]},"ph":[["c:8/80/Hanitsu_Jinja.jpg",800,600,"土津神社"],["c:2/2c/Hoshina_Masayuki2.jpg",414,402,"保科正之"],["c:2/2c/Meireki_fire.JPG",3375,1340,"明暦の大火"]]},{"id":"07_sazaedo","n":"さざえ堂（円通三匝堂）","yomi":"さざえどう（えんつうさんそうどう）","cat":"寺社","rank":"A","y":1796,"era":["edo"],"sh":"国の重要文化財","ad":"会津若松市一箕町八幡弁天下","st":"JR会津若松駅からまちなか周遊バスで約5分、«飯盛山下» から歩いて約5分","la":37.4968,"lo":139.9538,"hook":"上る人と下りる人が、一度もすれちがわない。江戸時代の «ふしぎ建築»。","lead":"さざえ堂は、飯盛山にある六角形の高さ約16mのお堂です。中はらせん状のスロープになっていて、上りと下りの道が別々。上った人は、来た道とは別の道を通って、反対側の出口から出てきます。この «二重らせん» のつくりは世界でもめずらしく、国の重要文化財です。","story":["江戸時代、各地の観音さまをめぐる «三十三観音めぐり» が人びとのあいだで人気でした。けれど遠くまで旅をするのは大変です。«一つのお堂の中で、三十三の観音さまをおまいりできたら……» そんな願いにこたえてつくられたのが、この円通三匝堂でした。","建てたのは、飯盛山にあった正宗寺の住職・郁堂と伝わります。1796年、お堂が完成しました。ぐるぐると右回りにスロープを上っていくと、そこに観音さまがならび、てっぺんの太鼓橋をわたると、今度は左回りに下りていく。上りの道と下りの道はまったく交わりません。","«三匝» とは «三回まわる» という意味です。お堂をめぐることでおまいりの功徳が得られるという、仏教の «右繞三匝» という礼の作法から来た名前です。見た目がサザエの貝がらに似ているので、人びとは «さざえ堂» と呼ぶようになりました。","明治のはじめ、神仏分離によって観音さまはお堂から移され、今は «皇朝二十四孝» の額がかけられています。それでも建物そのものは、江戸時代の姿のまま残りました。«どうやって、こんな形を思いついたんだろう?» 設計図もなかった時代の大工の知恵に、今の建築家たちも驚きます。","実際に入ってみると、木のスロープは少しすべりやすく、らせんのせいで方向感覚がくるいそうになります。最上部の太鼓橋から見下ろす吹き抜けは圧巻です。すぐ近くには白虎隊の墓もあり、あわせて飯盛山の歴史を感じてみてください。"],"tl":[["1796年","正宗寺の住職・郁堂がさざえ堂を建てたと伝わる"],["明治初め","神仏分離で観音像が移される"],["平成","国の重要文化財に指定"]],"who":[["郁堂","正宗寺の住職。さざえ堂を建てたと伝わる"],["当時の大工たち","二重らせんの構造をつくりあげた"],["参拝した人びと","一つのお堂で三十三観音めぐりをした"]],"deep":["高さは約16.5m、六角形の三層のお堂です。内部は一方通行の二重らせんになっていて、建物の中心に向かってねじれるような造りです。","二重らせんで上りと下りが交わらない木造建築は、世界的にもほかにほとんど例がないといわれます。","江戸時代には東京や群馬などにも «さざえ堂» と呼ばれる建物がありましたが、この会津の円通三匝堂のような二重らせんの構造は独特です。","«右繞三匝» は、仏や塔のまわりを右回りに三回まわって敬意を表す作法です。","内部にかけられた «皇朝二十四孝» の額は、親孝行の話を描いたもので、明治以降に置かれたものです。","入口と出口が建物の反対側にあるため、入った人が別の場所から出てくる様子も見どころ。見学は有料で、内部の撮影や歩き方の注意は現地の案内にしたがいましょう。"],"look":["六角形の外観と、サザエのようなねじれた姿","内部の上りスロープと下りスロープ","最上部の太鼓橋","内部の «皇朝二十四孝» の額"],"q":["さざえ堂の内部で、上りの人と下りの人がすれちがわないのはなぜ？","上りと下りが別々のらせんになっている «二重らせん» 構造だからです。"],"koji":[{"w":"右繞三匝","m":"仏のまわりを右回りに三回まわり、敬意を表す仏教の作法。«三匝堂» の名の由来"}],"myth":"建てた人物や年代は伝承にもとづく部分がある。","img":["飯盛山 (福島県)","栄螺堂"],"wp":"円通三匝堂","rel":{"ev":[],"grave":[]},"ph":[["c:c/c6/Iimoriyama_1.jpg",660,480,"飯盛山 (福島県)"],["c:4/44/100_views_edo_070.jpg",779,1200,"栄螺堂"],["c:3/35/Junior_College_of_Aizu.JPG",3648,2736,"近く: 会津大学短期大学部"],["c:3/38/%E5%8E%B3%E5%B3%B6%E7%A5%9E%E7%A4%BE%EF%BC%88%E4%BC%9A%E6%B4%A5%E8%8B%A5%E6%9D%BE%E5%B8%82%EF%BC%89.jpg",4032,3024,"近く: 厳島神社 (会津若松市)"],["c:5/5e/AizuMatsudairake_Bosyo.JPG",3001,2441,"近く: 会津藩主松平家墓所"],["c:e/e7/KyuTakizawa-honjin.JPG",3264,2448,"近く: 旧滝沢本陣"],["c:6/6a/Oyakuen%2C_Aizu_1.JPG",3264,2448,"近く: 御薬園"]]},{"id":"07_amidaji","n":"阿弥陀寺（斎藤一の墓・戊辰戦死者）","yomi":"あみだじ","cat":"墓所","rank":"A","y":1869,"era":["edo","meiji","taisho"],"sh":"","ad":"会津若松市七日町","st":"JR只見線七日町駅から歩いて約3分","la":37.501,"lo":139.9215,"hook":"新選組・斎藤一が眠る寺。その墓のそばには、戊辰戦争の戦死者たちが静かにねむる。","lead":"阿弥陀寺は、会津若松の七日町にある寺です。会津戦争で亡くなった藩士たちの遺体が葬られた場所で、境内には «東軍殉難者墓» があります。また、新選組の斎藤一の墓があることでも知られています。","story":["1868年、会津戦争が終わったあと、城下や周辺には多くの戦死者の遺体が残されていました。ところが新政府は、はじめのうち、これらの遺体を葬ることを許さなかったと伝わります。«家族を、仲間を、きちんと葬ってやりたい» 会津の人びとの苦しみは、深いものでした。","やがて許しが出て、多くの遺体が阿弥陀寺と長命寺に運ばれ、葬られました。阿弥陀寺の境内には、その人びとをまとめて葬った大きな墓があり、今も花がたえません。何人がここにねむっているのか、正確な数ははっきりしませんが、千人をこえるともいわれます。","境内のもう一つの見どころは、新選組三番隊組長・斎藤一の墓です。京都で新選組として戦った斎藤は、戊辰戦争で会津に来て、新選組が会津をはなれたあとも会津藩とともに戦ったといわれます。«会津を見すてるわけにはいかない» そんな思いがあったのかもしれません。","明治になると斎藤は «藤田五郎» と名前を変え、東京で警察官として働きました。会津藩士の娘・時尾と結婚し、1915年に東京で亡くなります。本人の願いで、墓はこの会津の阿弥陀寺に建てられたといわれます。","寺には、鶴ヶ城の本丸にあった «御三階» という建物も移されています。明治になって城が取りこわされるとき、ここに移されて本堂として使われたと伝わります。戦争の記憶と、城の記憶、そして一人の剣士の人生が、この小さな寺に重なっているのです。"],"tl":[["1868年","会津戦争。多くの戦死者が出る"],["1869年","戦死者の埋葬が許され、阿弥陀寺などに葬られる"],["明治初め","鶴ヶ城の «御三階» が寺に移される"],["1915年","藤田五郎（斎藤一）が東京で亡くなる"],["その後","斎藤一の墓が阿弥陀寺に建てられる"]],"who":[["斎藤一（藤田五郎）","新選組三番隊組長。会津で戦い、この寺に墓がある"],["藤田時尾","斎藤一の妻。会津藩士の娘"],["会津藩の戦死者たち","この寺の東軍殉難者墓に葬られた"],["松平容保","会津藩主。新選組を京都でおさめる立場にあった"]],"deep":["«東軍殉難者墓» にねむる人の数は記録によってちがい、千人をこえるとも、1300人ほどともいわれます。","戦死者の埋葬が禁じられた期間や、その理由については諸説あり、近年の研究では «埋葬が一切禁止されていた» という通説に疑問を出す意見もあります。","斎藤一は明治には警視庁に勤め、西南戦争にも警視隊として加わったといわれます。","斎藤一の妻・時尾は会津藩の高木家の娘で、結婚の際には元会津藩主・松平容保が仲人の一人になったと伝わります。","«御三階» は鶴ヶ城の本丸にあった三階建ての建物で、外からは三階、中は四層の構造だったといわれ、密議の場とも伝わります。","七日町駅のすぐ近くにあり、大正から昭和初期の建物が残る七日町通りの散策とあわせて訪れる人が多い寺です。斎藤一の墓前には、今も新選組ファンが供えた花や酒が見られます。"],"look":["東軍殉難者墓","斎藤一（藤田五郎）の墓","鶴ヶ城から移された «御三階»","七日町通りの古い町並み"],"q":["斎藤一が明治に名のった名前は？","藤田五郎。東京で警察官として働きました。"],"koji":[],"myth":"埋葬禁止の実態、戦死者の数、御三階の用途や移築の年には諸説。斎藤一の会津での行動にも不明な点がある。","img":["斎藤一","新選組","会津戦争"],"wp":"阿弥陀寺 (会津若松市)","rel":{"ev":[],"grave":[]},"ph":[["c:c/c2/Amida-ji_%28Aizuwakamatsu%29.JPG",3648,2736,"阿弥陀寺 (会津若松市)"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:3/34/Goro_Fujita_aka_Hajime_Saito.jpg",680,1006,"斎藤一"],["c:5/50/Battle_of_Aizu_at_Wakamatsu_castle_by_Tsukioka_Yoshitoshi.png",3877,1900,"会津戦争"]]},{"id":"07_kozashi_jo","n":"神指城跡（上杉景勝の幻の城）","yomi":"こうざしじょうあと","cat":"城","rank":"A","y":1600,"era":["azuchi"],"sh":"","ad":"会津若松市神指町","st":"JR会津若松駅から車で約15分（城跡は田園の中に点在）","la":37.518,"lo":139.887,"hook":"鶴ヶ城の約2倍ともいわれる巨大な城。完成する前に、関ヶ原がすべてを変えた。","lead":"神指城は、1600年に上杉景勝が会津に築きはじめた城です。鶴ヶ城よりはるかに大きな城になる予定でしたが、関ヶ原の戦いの前後の情勢の中で工事は止まり、完成しませんでした。今は田んぼの中に、土塁や石垣のあとがわずかに残っています。","story":["1598年、豊臣秀吉の命令で、上杉景勝は越後から会津120万石へ移りました。大きな領地を治めるには、それにふさわしい城が必要です。景勝と家老の直江兼続は、鶴ヶ城の北西、阿賀川のほとりの神指に、新しい城を築くことにしました。","1600年のはじめ、工事が始まります。本丸と二の丸をもつ、四角い大きな城。領内から大勢の人が集められ、急ピッチで工事が進められました。ところが、この動きを見ていたのが、豊臣政権の実力者・徳川家康です。«上杉は戦の準備をしているのではないか?»","家康は景勝に «京都に来て説明せよ» と求めます。これに対し、直江兼続が返したといわれるのが有名な «直江状» です。«田舎の武士が武具を集めるのは、都の人が茶道具を集めるのと同じこと» ――家康を挑発するような内容だったと伝わります。怒った家康は、上杉を討つため兵をあげました。","しかし家康が東へ向かったすきに、西では石田三成らが兵をあげ、家康は引き返して関ヶ原で戦うことになります。上杉家はこの戦いのあと、会津から米沢30万石へと大きく領地を減らされました。神指城の工事はとちゅうで止まり、城は幻となったのです。","今、城跡には本丸の土塁のあとなどが残り、そのそばには大きなケヤキの木が立っています。«ここにどんな城が建つはずだったのだろう?» 田んぼの中に立って、景勝と兼続が夢見た城の姿を想像してみてください。"],"tl":[["1598年","上杉景勝が会津120万石に移る"],["1600年春","神指城の工事が始まる"],["1600年","直江状がやりとりされたといわれる。家康が上杉討伐へ"],["1600年9月","関ヶ原の戦い。工事は中止に"],["1601年","上杉家が米沢30万石に減らされる"]],"who":[["上杉景勝","会津120万石の大名。神指城を築かせた"],["直江兼続","上杉家の家老。築城を指揮し、直江状を書いたといわれる"],["徳川家康","上杉の築城を問題視し、会津攻めを決めた"],["石田三成","家康が会津へ向かったすきに兵をあげた"]],"deep":["計画された城の広さは、本丸が約180m四方、二の丸を含めると鶴ヶ城の約2倍にもなったといわれます。数字には諸説があります。","«直江状» は原本が残っておらず、写しだけが伝わっています。内容が後の時代に書きかえられたのではないかという説もあり、本物かどうか議論があります。","神指城の石垣の石は、のちに鶴ヶ城の修築などに運ばれたと伝わります。","本丸跡近くの «高瀬の大木» と呼ばれるケヤキは、国の天然記念物に指定されている巨木です。","神指城は平城で、川の近くの平地に築かれました。新しい城下町をつくる大きな都市計画の一部だったとも考えられています。","景勝が会津に入ってわずか2年ほどで新城に取りかかったことは、会津の中心を黒川（鶴ヶ城）から移し、上杉家の新しい本拠をつくろうとしたことを示すと考えられています。"],"look":["本丸の土塁のあと","高瀬の大木（ケヤキ）","城跡の案内板と、周囲の田園風景"],"q":["神指城の工事が止まったきっかけとなった戦いは？","1600年の関ヶ原の戦いです。"],"koji":[],"myth":"城の規模の数字、直江状の真偽、石垣の転用は諸説・伝承。","img":["上杉景勝","直江兼続","直江状"],"wp":"神指城","rel":{"ev":[],"grave":[]},"ph":[["c:e/e8/Kouzashi_castle_site.JPG",1152,720,"神指城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:6/61/Uesugi_Kagekatsu_Portrait_Yonezawa_City_Uesugi_Museum.png",705,1708,"上杉景勝"],["c:3/34/Naoe_Kanetsugu02.jpg",800,1159,"直江兼続"]]},{"id":"07_mukaihaguro","n":"向羽黒山城","yomi":"むかいはぐろやまじょう","cat":"城","rank":"A","y":1568,"era":["muromachi","azuchi"],"sh":"国指定史跡","ad":"大沼郡会津美里町本郷","st":"JR只見線会津本郷駅から車で約10分（山頂近くまで車道あり）","la":37.456,"lo":139.87,"hook":"戦国の会津の王・蘆名盛氏が、7年かけて山まるごとを城にした。東北屈指の巨大山城。","lead":"向羽黒山城は、戦国時代に会津を治めた蘆名盛氏が築いた山城です。山全体に曲輪や堀が配置され、東北地方でも最大級の山城として国の史跡に指定されています。山の上からは会津盆地を一望できます。","story":["戦国時代、会津を治めていたのは蘆名氏でした。その全盛期を築いたのが蘆名盛氏です。盛氏は周りの大名と戦ったり手を結んだりしながら領地を広げ、«会津の王» とも呼ばれる力をもちました。","盛氏は、黒川城（今の鶴ヶ城）の南、阿賀川をはさんだ岩崎山に新しい城を築きはじめます。工事は永禄年間に7年ほどかかったといわれます。«なぜ本拠地の黒川城とは別に、山の上に城を?» 隠居したあとの居城にするため、そしていざというときの «つめの城» にするためだったと考えられています。","城は山の頂上から中腹、ふもとまで、たくさんの曲輪（平らな区画）が階段のように並び、堀や土塁で守られていました。山まるごとが城、といってよいほどの広さです。盛氏はこの城で晩年をすごしたと伝わります。","盛氏の死後、蘆名氏はおとろえ、1589年、伊達政宗との摺上原の戦いに敗れてほろびました。その後、会津には蒲生氏郷や上杉景勝が入り、この城も修築されながら使われたと考えられています。やがて江戸時代のはじめに城としての役目を終えました。","今は山に遊歩道が整備され、曲輪や空堀、土塁のあとを歩いて見ることができます。山頂近くの展望地からは、会津盆地と遠くに鶴ヶ城、磐梯山まで見わたせます。«この景色を、盛氏も見ていたんだ» そう思うと、戦国の空気が感じられるはずです。"],"tl":[["1561年","蘆名盛氏が築城を始めたといわれる"],["1568年","城が完成したといわれる"],["1580年","蘆名盛氏が亡くなる"],["1589年","摺上原の戦いで蘆名氏がほろびる"],["1590年代","蒲生氏・上杉氏の時代に修築されたと考えられる"],["2001年","国の史跡に指定"]],"who":[["蘆名盛氏","戦国時代の会津の大名。向羽黒山城を築いた"],["伊達政宗","摺上原の戦いで蘆名氏をほろぼした"],["蒲生氏郷","蘆名氏のあとに会津に入った大名"],["上杉景勝","蒲生氏のあとに会津を治めた大名"]],"deep":["城の範囲は岩崎山全体に広がり、数百メートル四方をこえる広さをもつことから、東北地方で最大級の山城のひとつとされます。","«一曲輪»«二曲輪»«三曲輪» と呼ばれる中心部のほか、ふもとには家臣の屋敷があったと考えられています。","築城は1561年から1568年までかかったとされ、史料や伝承にもとづく年代です。","城の遺構には、蘆名時代だけでなく、蒲生・上杉時代の改修のあとが含まれていると考えられており、どの部分がいつのものかは研究が続いています。","会津美里町では、発掘調査の成果をもとに案内板や遊歩道を整備しています。","«向羽黒山» の名は、黒川城から見て阿賀川の向こう側にある羽黒山（岩崎山）という意味だといわれます。山には羽黒権現がまつられていたと伝わります。","蘆名盛氏は、家督を子の盛興にゆずったのちも実権をにぎり、この城から政治を行ったと考えられています。盛興は若くして亡くなり、蘆名氏の衰えの一因となりました。"],"look":["山頂部の一曲輪と展望","空堀と土塁","曲輪が階段のように並ぶ山の斜面","遠くに見える鶴ヶ城と磐梯山"],"q":["向羽黒山城を築いた戦国大名はだれ？","蘆名盛氏です。"],"koji":[],"myth":"築城期間、廃城の時期、城の規模には諸説。","img":["蘆名盛氏","摺上原の戦い"],"wp":"向羽黒山城","rel":{"ev":[],"grave":[]},"ph":[["c:a/a4/Mukaihaguro-yamasiroato.jpg",2813,1004],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:f/fa/%E8%98%86%E5%90%8D%E7%9B%9B%E6%B0%8F.png",628,810,"蘆名盛氏"]]},{"id":"07_isasumi","n":"伊佐須美神社（会津一之宮）","yomi":"いさすみじんじゃ","cat":"寺社","rank":"A","y":300,"era":["myth","heian"],"sh":"","ad":"大沼郡会津美里町宮林","st":"JR会津若松駅からバスで約30分、«横町» 付近から歩いて約5分","la":37.462,"lo":139.843,"hook":"«会津» の名前が生まれた、その物語につながる神社。","lead":"伊佐須美神社は、会津地方の総鎮守で、岩代国の一之宮とされる古い神社です。古事記に出てくる «会津» の地名の由来の物語と深く関わる神社として知られています。春の薄墨桜や初夏のあやめでも有名です。","story":["古事記には、こんな話があります。崇神天皇の時代、四方の国々を治めるために «四道将軍» が送り出されました。父の大毘古命は北陸道を、その子の建沼河別命は東海道を進みました。そして二人は、ある場所でばったり出会います。«相い津（あいづ）» ――そこが、今の会津だというのです。","伊佐須美神社は、この伝説と結びついた神社です。二人の将軍が、国の神であるイザナギ・イザナミの二神をまつったのが始まりと伝えられています。はじめは御神楽岳という山の上にまつられ、その後いくつかの場所を移って、今の場所に落ち着いたといわれます。","平安時代の «延喜式» という法令集には、伊佐須美神社は «名神大社» として名前が出てきます。名神大社とは、国がとくに重く見た神社のことです。遠い陸奥の国の中でも、会津の人びとにとって大切な神社だったことがわかります。","2008年、伊佐須美神社の社殿は火事で焼けてしまいました。«会津の総鎮守が……» 多くの人が悲しみましたが、再建に向けた取り組みが続けられています。境内の宝物殿には、国の重要文化財の «朱漆金銅装神輿» などが伝わっています。","神社の名物は、境内に咲く «薄墨桜»。咲きはじめは薄い墨色をおびた花が、しだいに色を変えていきます。初夏には外苑のあやめ苑が見ごろを迎え、夏には田植えの様子を再現する «御田植祭» も行われます。長い歴史の中で、人びとは季節ごとにこの神社に集ってきたのです。"],"tl":[["伝説の時代","四道将軍の大毘古命・建沼河別命が会津で出会ったと古事記に書かれる"],["927年","«延喜式» に名神大社として記される"],["江戸時代","会津藩主の崇敬を受ける"],["2008年","火災で社殿が焼失"]],"who":[["大毘古命","四道将軍の一人。北陸道を進んだ"],["建沼河別命","大毘古命の子。東海道を進み会津で父と出会ったと伝わる"],["伊弉諾尊・伊弉冉尊","神社にまつられる国生みの神"],["会津藩主","代々この神社をあつく敬った"]],"deep":["«会津» の地名の由来は古事記の伝承で、史実とは確かめられません。この出会いの話は、おもに古事記に見えるものです。","延喜式神名帳で陸奥国に記された名神大社の一つで、会津地方ではもっとも格の高い神社とされてきました。","重要文化財の «朱漆金銅装神輿» は、鎌倉時代から室町時代ごろの作とされる美しいみこしです（年代は諸説）。","御田植祭は、7月に行われる古い田植えの神事で、日本の三大田植祭の一つに数えられることがあります。","境内の薄墨桜は、花の色の移り変わりで知られる古木で、神社の春の名物です。","伊佐須美神社は «会津総鎮守» と呼ばれ、会津一円から参拝者が集まります。","神社のある会津美里町の旧会津高田町は、門前町として発展した町です。参道ぞいには古い商家も残り、神社とともに町の歴史をつくってきました。"],"look":["楼門・参道（再建の状況は現地で確認）","薄墨桜","あやめ苑","宝物殿（朱漆金銅装神輿など）"],"q":["«会津» の地名は、だれとだれが出会ったことから生まれたと古事記に書かれている？","四道将軍の大毘古命と、その子の建沼河別命です。"],"koji":[],"myth":"創建や地名の由来は古事記などの伝承。神社の移転の経緯、神輿の年代にも諸説。","img":["四道将軍","大毘古命","岩代国"],"wp":"伊佐須美神社","rel":{"ev":[],"grave":[]},"ph":[["c:3/36/Isasumi-jinja_roumon.JPG",6016,4000,"伊佐須美神社"],["c:b/ba/Kamegamori-kofun_zenkei-1.JPG",6016,4000],["c:7/70/Isasumi-jinja_torii.JPG",6016,4000],["c:4/45/Isasumi-jinja_roumon-2.JPG",5986,3954],["c:7/7f/Isasumi-jinja_karishaden.JPG",6016,4000],["c:9/9d/Isasumi-jinja_honden-ato.JPG",6016,4000],["c:8/89/Isasumi-jinja_higashi-shinmon.JPG",5976,3940],["c:4/47/Isasumi-jinja_fuji.JPG",4000,6016]]},{"id":"07_shinguu_kumano","n":"新宮熊野神社長床","yomi":"しんぐうくまのじんじゃながとこ","cat":"寺社","rank":"A","y":1100,"era":["heian","kamakura"],"sh":"国の重要文化財","ad":"喜多方市慶徳町新宮","st":"JR磐越西線 喜多方駅から車で約15分","la":37.6815,"lo":139.8466,"hook":"壁がひとつもない、太い柱だけの大きな建物。44本の柱の森に立つと、平安の風が吹きぬける。","lead":"«長床（ながとこ）» は、熊野神社の本殿の前に建つ横に長い拝殿です。壁や戸がなく、太くて丸い柱がずらりと並んでいるだけの、とても珍しい形をしています。建てられたのは平安時代の終わりから鎌倉時代のはじめごろと考えられ、国の重要文化財になっています。","story":["喜多方の町から北へ少し走ると、田んぼの向こうにこんもりとした森が見えてきます。石段をのぼると、目の前にあらわれるのは、かやぶき屋根の下に太い柱だけが立ち並ぶ不思議な建物。«これ、建てかけなの?» と思わず聞きたくなるかもしれません。でもこれが完成した姿。壁のない «吹き放し» の拝殿、それが長床です。","神社の始まりは、平安時代の後半にさかのぼると伝わります。東北で «前九年の役» という戦いがあったころ、源頼義が紀州（和歌山県）の熊野の神をこの地に迎えたといわれます。熊野は、都の上皇や貴族たちが何度もお参りした、あこがれの聖地。遠い会津の地に «もうひとつの熊野» がつくられたのです。","なぜ壁がないのでしょう。長床は、もともと修験者（山伏）たちが集まり、祈ったり儀式をしたりする場所だったと考えられています。大勢の人が入れて、神様のいる本殿も見通せる。だから壁はいらなかったのかもしれません。柱の間から見える本殿と森が、そのまま建物の «壁» の役目をしているようです。","江戸時代のはじめ、会津を大きな地震がおそい、長床もたおれてしまいました。けれど人々は古い柱や材木を使って建て直し、昔の姿を守りました。昭和には建物をいったんばらばらにする大修理が行われ、平安・鎌倉ごろの古い形がよみがえりました。","秋になると、長床の横に立つ大イチョウが金色に染まります。樹齢は800年をこえるともいわれ、散った葉が地面をじゅうたんのようにおおう光景は、会津の秋の名物。夜のライトアップの日には、柱の列と金色の葉が照らされ、まるで平安の絵巻の中に迷いこんだような気持ちになります。"],"tl":[["11世紀後半","源頼義が熊野の神をむかえたと伝わる（神社の始まり）"],["平安末〜鎌倉初め","長床が建てられたと考えられる"],["1611年","会津地震（慶長の大地震）で長床が倒れる"],["江戸時代","古い材を生かして建て直される"],["昭和","解体修理で古い形に復元"],["現在","秋の大イチョウとライトアップが人気"]],"who":[["源頼義","前九年の役で東北に来た武将。熊野の神をむかえたと伝わる"],["源義家","頼義の子。神社の整備にかかわったとする伝えがある"],["修験者（山伏）","長床で祈りや儀式を行ったと考えられる人々"],["会津の人々","地震で倒れた長床を建て直し、守ってきた"]],"deep":["長床は正面9間・奥行4間ほどの大きな建物で、ならぶ柱は44本。丸い柱の太さがそろっていて、柱の林のような空間になります。寝殿造の雰囲気を残す建物ともいわれます。","«長床» という名前の拝殿は、熊野信仰や修験道とかかわりのある古い神社に見られる形です。山伏たちが長い床に並んで座ったことに由来するという説があります。","建てられた年を示す確かな記録はなく、柱や組物の形などから、平安末から鎌倉初めごろと推定されています。慶長の地震で倒れたあとも古い部材が多く使われ、それが年代を知る手がかりになっています。","新宮熊野神社には本殿が三つ（本宮・新宮・那智）並ぶとされ、紀州熊野三山をまるごとうつしたつくりです。«新宮» という地名そのものが、熊野とのつながりを語っています。","境内の宝物殿には、古い仏像や鏡、神仏習合の時代をしのばせる品々が伝わります。明治の神仏分離より前は、神社とお寺がいっしょになった信仰の場でした。","喜多方といえばラーメンと蔵の町ですが、その北のはずれに平安の建物が残るというギャップも面白いところ。会津は古い仏教文化が花開いた土地で、勝常寺など平安の仏像とあわせてめぐると理解が深まります。"],"look":["44本の柱が並ぶ長床の内側（柱の間から本殿を見通す）","かやぶき屋根の大きさと、壁のない «吹き放し» のつくり","長床の横の大イチョウ（秋の黄葉とライトアップ）","宝物殿の古い文化財"],"q":["長床には、ふつうの建物にある «あるもの» がありません。それは何？","壁と戸。太い柱だけで屋根を支える «吹き放し» のつくりです。"],"koji":[],"myth":"源頼義・義家による創建は神社の伝承。長床の建築年代は推定で、確かな記録はない。","img":["喜多方市","熊野三山"],"wp":"新宮熊野神社 (喜多方市)","rel":{"ev":[],"grave":[]},"ph":[["c:b/b5/Kitakata_ramen_by_macyu_in_Yamagata.jpg",2048,1536,"喜多方市"],["c:7/73/Kita_no_sato%2C_Michi-no-Eki%2C_Yamagata%2C_Japan%2C_November_2019.jpg",4032,3024,"近く: 道の駅喜多の郷"],["c:e/eb/Kitakata_High_School%2C_May_2022.jpg",4608,3456,"近く: 福島県立喜多方高等学校"],["c:6/61/Former_Kitakata_Commercial_High_School.JPG",3648,2736,"近く: 福島県立喜多方商業高等学校"],["c:6/67/Aizu-Muramatsu_Station_20260524_1.jpg",4080,3072,"近く: 会津村松駅"],["c:6/60/Oshikirigawa_Park.jpg",737,997,"近く: 押切川公園スポーツ広場"],["c:7/71/Temple_Ganjoji%28Kitakata-city%29.JPG",3264,2448,"近く: 願成寺 (喜多方市)"]]},{"id":"07_shojoji","n":"勝常寺（薬師三尊像）","yomi":"しょうじょうじ","cat":"寺社","rank":"A","y":807,"era":["heian"],"sh":"国宝","ad":"河沼郡湯川村勝常","st":"JR会津若松駅から車で約20分（公共交通は少なめ）","la":37.569,"lo":139.887,"hook":"田んぼの中の小さな村に、1200年前の仏さまが三人そろって座っている。東北の仏教のはじまりを語る国宝。","lead":"勝常寺は、平安時代のはじめに徳一（とくいつ）というお坊さんが開いたと伝わるお寺です。薬師堂にまつられる «薬師如来» と左右の «日光・月光菩薩» の三体は国宝。ほかにもたくさんの平安時代の仏像が重要文化財になっていて、«会津の仏都» の中心といわれます。","story":["会津盆地のまんなか、湯川村。見わたすかぎり田んぼが広がるのどかな村に、勝常寺はひっそりと建っています。山門をくぐると、どっしりした薬師堂。とびらの向こうには、1200年ほど前に彫られた薬師さまが、今も静かにこちらを見つめています。","このお寺を開いたのは、徳一という奈良から来たお坊さんだと伝わります。徳一は会津の磐梯山のふもとに慧日寺（えにちじ）を開き、東北に仏教を広めた人。都ではあの最澄と «だれでも仏になれるのか?» をめぐって大論争をしたことでも知られています。そんな学問のお坊さんが、なぜ遠い会津に来たのでしょう。はっきりした理由はわかっていません。","薬師三尊像のまんなかの薬師如来は、大きな一本の木から彫り出した坐像です。どっしりした体つき、ふっくらした顔、衣のひだの深い彫り。平安時代はじめの仏像らしい力強さがあふれています。左右に立つ日光菩薩・月光菩薩は、すらりとした姿で薬師さまを支えています。","«こんな立派な仏像を、どうやってこの村で作ったんだろう?» そう思った人も多いはず。当時の会津は、徳一の活動によって仏教の一大拠点になっていました。都の技術を身につけた仏師が来たのか、地元の仏師が育ったのか。専門家の間でも議論が続いています。","平成になって、薬師三尊像は国宝に指定されました。村の人たちはこのお寺と仏さまを何百年も守ってきました。拝観は事前に申しこむのが基本。静かなお堂で仏さまと向き合うと、平安の会津の人々の祈りが、少しだけ聞こえてくる気がします。"],"tl":[["807年（大同2年）","徳一が開いたと伝わる"],["9世紀前半","薬師三尊像など多くの仏像が作られたと考えられる"],["室町時代","現在の薬師堂が建てられる（重要文化財）"],["江戸時代","会津藩のもとで寺が続く"],["1996年","薬師如来坐像と両脇侍立像が国宝に指定"]],"who":[["徳一","奈良から来た法相宗の僧。会津に慧日寺を開き、勝常寺も開いたと伝わる"],["最澄","天台宗を開いた僧。徳一と «三一権実論争» をくり広げた"],["空海","真言宗を開いた僧。徳一に手紙を送り協力を求めたことが知られる"]],"deep":["«三一権実（さんいちごんじつ）論争»: 徳一は «仏になれる人となれない人がいる» という立場、最澄は «だれでも仏になれる» という立場で、何年も文書で論争しました。平安仏教の大テーマのひとつです。","薬師如来坐像はケヤキ材の一木造とされ、平安前期（貞観期ごろ）の特徴を持つとされます。東北地方にある平安前期の彫刻の中でも、特に質の高い作例と評価されています。","勝常寺には国宝の三尊のほかにも、四天王立像、聖観音立像、十一面観音立像など、平安時代の仏像が多数伝わり、その多くが国の重要文化財です。一つの寺にこれだけまとまって残るのは珍しいことです。","薬師堂（中央薬師堂）は室町時代の建物で、国の重要文化財。屋根の大きな寄棟造で、会津の中世寺院建築を知る貴重な例です。","徳一の拠点・慧日寺跡（磐梯町）は国の史跡で、金堂が復元されています。勝常寺、慧日寺、さらに会津坂下町などの古寺をめぐると、«会津仏教» の広がりがつかめます。"],"look":["国宝の薬師三尊像（拝観は予約が基本）","室町時代の薬師堂（重要文化財）","平安時代の仏像が並ぶ収蔵庫","お寺をとりまく会津盆地の田園風景"],"q":["勝常寺を開いたと伝わる徳一が、論争した有名なお坊さんは？","天台宗の最澄。«だれでも仏になれるか» をめぐって論争しました（三一権実論争）。"],"koji":[],"myth":"徳一による開山と807年の年代は寺伝。仏像の作者・制作地は不明で諸説。","img":["徳一","慧日寺","薬師三尊"],"wp":"勝常寺","rel":{"ev":[],"grave":[]},"ph":[["c:e/e2/Shojoji_Yakushi_Hall.jpg",2816,2112,"勝常寺"],["c:7/7a/Statue_of_yakushi_nyorai_of_Shojo-ji%2C_Fukushima.jpg",1482,2152],["c:8/8c/Statues_of_nikko_bosatsu_and_gakko_bosatsu_of_Shojo-ji%2C_Fukushima.jpg",1292,1628],["c:0/01/Statue_of_sho_kannon_of_Shojo-ji%2C_Fukushima.jpg",838,1538],["c:7/74/Statues_of_komokuten_and_tamonten_of_Shojo-ji%2C_Fukushima.jpg",859,1132],["c:3/3b/Triad_of_Yakushi_Nyorai.JPG",970,1232,"薬師三尊"]]},{"id":"07_bonari","n":"母成峠古戦場","yomi":"ぼなりとうげこせんじょう","cat":"幕末","rank":"A","y":1868,"era":["edo","meiji"],"sh":"","ad":"郡山市熱海町石筵〜耶麻郡猪苗代町の境","st":"車でないと行きにくい。磐越自動車道 磐梯熱海ICから車で約30分","la":37.567,"lo":140.215,"hook":"会津へ入る «裏口» は、たった一日で破られた。この峠の敗北が、白虎隊の悲劇と鶴ヶ城の籠城へつながっていく。","lead":"母成峠は、郡山の石筵（いしむしろ）から会津の猪苗代へぬける山の峠です。1868年（慶応4年）、戊辰戦争で新政府軍がここを攻め、守っていた旧幕府軍や会津軍などを破りました。ここを突破されたことで、新政府軍は一気に会津若松へ迫ることになります。","story":["1868年の夏、二本松城を落とした新政府軍は、次の目標・会津をにらんでいました。会津へ入る道はいくつもあります。会津側は、大軍が通りやすい中山峠などの守りを固めていました。«まさか、あの山道からは来ないだろう» ——そう考えた道のひとつが、母成峠でした。","峠を守ったのは、大鳥圭介ひきいる旧幕府の伝習隊、会津藩兵、二本松藩の兵、そして新選組の隊士たち。土を盛った防塁（ぼうるい）を三段に築き、大砲をすえて待ちかまえました。けれど兵の数は新政府軍よりずっと少なく、武器の差もありました。","旧暦8月21日、霧の中で戦いが始まりました。新政府軍は板垣退助や伊地知正治らがひきい、正面だけでなく、山の尾根づたいに回りこんで攻めたと伝わります。守る側は横や後ろからも攻められ、防塁はつぎつぎに破られました。«もはや支えきれぬ!» 兵たちは猪苗代の方へと退いていきました。","母成峠が破られると、新政府軍は猪苗代から十六橋、戸ノ口原へと進み、わずか2日後の8月23日には会津若松の城下へなだれこみます。白虎隊が飯盛山で自刃したのも、この日です。山あいの小さな峠の敗北が、会津の運命を大きく変えたのです。","いま峠には、戦いで亡くなった人々をしのぶ碑が立ち、防塁の跡が森の中に残っています。夏にはミズバショウやレンゲツツジが咲く静かな高原。ここで多くの若者が命を落としたことを思い、手を合わせてから歩きたい場所です。"],"tl":[["1868年7月29日","二本松城が落城（旧暦）"],["1868年8月21日","母成峠の戦い。新政府軍が峠を突破"],["1868年8月22日","十六橋・戸ノ口原で戦い"],["1868年8月23日","新政府軍が若松城下に突入。白虎隊が飯盛山で自刃"],["1868年9月22日","会津藩が降伏"]],"who":[["大鳥圭介","旧幕府の伝習隊をひきいて峠を守った。のちに外交官"],["板垣退助","土佐藩の指揮官として新政府軍をひきいた。のちに自由民権運動"],["伊地知正治","薩摩藩の軍師。母成峠からの攻撃を主張したといわれる"],["土方歳三","新選組の副長。この方面の戦いにかかわった"]],"deep":["なぜ母成峠だったのか: 新政府軍の内部では、会津への進入路をめぐって意見が分かれたといわれます。伊地知正治が手薄な母成峠からの進撃を主張したという話が知られています。","峠の防塁は三段構えだったとされ、第一から第三防塁の跡が今も確認できます。土を盛って胸壁にした野戦陣地で、戊辰戦争の野戦築城を知る遺構として貴重です。","大鳥圭介は戦いの記録を『南柯紀行（なんかきこう）』という回想録に残しています。敗れた側の指揮官が書いた記録として、母成峠の戦いを知る重要な史料です。","戦死者の数ははっきりしませんが、峠には «東軍殉難者埋骨の地» の碑があり、長く放置されていた遺体を地元の人たちが葬ったと伝わります。","母成峠を突破した新政府軍の速さは驚くほどで、会津側は城下の防備を固める時間がありませんでした。このため、老人や女性、少年までが城にこもる総力戦になっていきます。"],"look":["第一〜第三防塁の跡（森の中の土手）","東軍殉難者埋骨の碑と慰霊碑","峠から猪苗代方面への眺め","母成グリーンライン沿いの高原の自然"],"q":["母成峠が破られた2日後に、会津でおきたことは？","新政府軍が若松城下に突入し、白虎隊が飯盛山で自刃しました（旧暦8月23日）。"],"koji":[],"myth":"新政府軍の迂回ルートや作戦決定の経緯には諸説。戦死者数は不明確。","img":["大鳥圭介","会津戦争","伊地知正治"],"wp":"母成峠の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:2/2e/Bonari_pass.jpg",800,600,"母成峠の戦い"],["c:3/37/Itagaki_Taisuke_1870.jpg",1696,2268],["c:c/c1/AizuAoi.png",744,744],["c:4/4c/Otori_Keisuke.jpg",1024,1327,"大鳥圭介"],["c:5/50/Battle_of_Aizu_at_Wakamatsu_castle_by_Tsukioka_Yoshitoshi.png",3877,1900,"会津戦争"],["c:8/82/IJICHI_Masaharu.jpg",1024,1461,"伊地知正治"]]},{"id":"07_tonokuchi","n":"戸ノ口原古戦場（白虎隊の戦場）","yomi":"とのくちはらこせんじょう","cat":"幕末","rank":"A","y":1868,"era":["edo","meiji"],"sh":"","ad":"会津若松市河東町（強清水付近）","st":"JR会津若松駅から車で約20分","la":37.524,"lo":139.995,"hook":"16、17歳の少年たちが、雨の夜に銃を抱えて立った原っぱ。白虎隊の «最初で最後の戦場» がここ。","lead":"戸ノ口原（とのくちはら）は、猪苗代湖の西、会津若松へ向かう道沿いの原野です。1868年8月、会津へ攻めこむ新政府軍を止めようと、会津藩の兵とともに白虎隊の少年たちが戦いました。ここで敗れた少年たちが飯盛山へ退き、自刃したことはよく知られています。","story":["母成峠が破られたという知らせは、会津若松の城にいた藩主・松平容保のもとへすぐに届きました。新政府軍は猪苗代湖のほとりの十六橋を渡り、若松へ迫ってくる。«なんとしても戸ノ口で食い止めよ!» 城にいた兵は少なく、まだ16、17歳の少年でつくる白虎隊にも出陣の命令が下りました。","白虎隊士中二番隊の少年たちは、容保の出陣に従って城を出て、戸ノ口原へ向かいました。雨の降る夜、食べ物も十分にないまま、少年たちは原っぱに身をひそめて敵を待ちます。«腹がへった» と言いあう声もあったでしょう。隊長は食料をさがしに行ったまま戻らなかったと伝わります。","8月23日の朝、戦いが始まりました。新政府軍は最新式の銃と大砲をそろえ、数でもまさっていました。会津の兵たちは必死に撃ち返しますが、じりじりと押されていきます。少年たちもけがをしたり仲間とはぐれたりしながら、ついに退くことになりました。","退いた少年たちは、戸ノ口堰の洞穴（ほらあな）を通って飯盛山へのぼりました。そこから城下を見ると、町は煙に包まれていました。«城が燃えている…» 実際には城は落ちていませんでしたが、少年たち19人はこの山で自刃します。ただ一人、飯沼貞吉だけが助けられ、のちにこの日のことを語り残しました。","戸ノ口原には今、戦いで亡くなった会津藩士の墓や、白虎隊が戦ったことを伝える碑が立っています。車がひっきりなしに通る国道のすぐそば。ここで少年たちが一夜を明かしたことを思い、静かに手を合わせたい場所です。"],"tl":[["1868年3月","会津藩が軍制を改め、年齢別に白虎隊などを編成"],["1868年8月21日","母成峠の戦い（旧暦）"],["1868年8月22日","新政府軍が十六橋を渡る。白虎隊士中二番隊が出陣"],["1868年8月23日","戸ノ口原の戦い。敗れた白虎隊士が飯盛山で自刃"],["1868年9月22日","会津藩降伏"]],"who":[["白虎隊士中二番隊","16〜17歳の藩士の子らの部隊。戸ノ口原で戦った"],["飯沼貞吉","飯盛山で自刃をはかったが助けられた隊士。のちに語り部に"],["日向内記","士中二番隊の隊長。食料を探しに出て隊と離れたと伝わる"],["松平容保","会津藩主。滝沢本陣に出て指揮をとった"]],"deep":["白虎隊は «朱雀・青龍・玄武・白虎» の四神の名で年齢別に分けた部隊のひとつで、16〜17歳が中心。身分によって士中・寄合・足軽の隊に分かれていました。","会津藩は十六橋を壊して新政府軍を止めようとしましたが、壊しきれず、新政府軍はすぐに橋を渡ったといわれます。この橋が、戸ノ口原の戦いの前線を決めました。","戸ノ口堰洞穴は、猪苗代湖の水を会津盆地へ引くために掘られた用水路のトンネルです。江戸時代に作られた疏水の一部で、少年たちはその中を通って飯盛山へ出ました。","飯盛山で自刃した白虎隊士は19人とされ、飯沼貞吉は一命をとりとめ、明治以降は電信技師として生きました。彼の証言が白虎隊の話の大きなよりどころになっています。","«城が燃えていると見て自刃した» という話は広く知られていますが、実際には城下の炎を見ても城が落ちていないことはわかっていたが、敵に捕まるより死を選んだという説もあり、証言をどう読むかで議論があります。"],"look":["戸ノ口原古戦場の碑と会津藩士の墓","白虎隊奮戦の地を伝える碑","近くの十六橋水門（猪苗代湖の出口）","あわせて訪ねたい飯盛山の戸ノ口堰洞穴と白虎隊士の墓"],"q":["白虎隊の少年たちが飯盛山へ出るために通ったのは？","戸ノ口堰の洞穴。猪苗代湖の水を会津へ引く用水路のトンネルです。"],"koji":[{"w":"ならぬことはならぬものです","m":"会津藩の子どもの決まり «什の掟» のしめくくりのことば。だめなことはだめ、という教え"}],"myth":"隊長が離れた経緯や、自刃の理由（城の炎を見誤った説など）には諸説。","img":["白虎隊","飯沼貞吉","飯盛山 (福島県)"],"wp":"戸ノ口原の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:5/5e/Byakko-tai_statues.JPG",2128,2832,"白虎隊"],["c:1/1c/Iinuma_Sadakichi.jpg",780,1037,"飯沼貞吉"],["c:c/c6/Iimoriyama_1.jpg",660,480,"飯盛山 (福島県)"]]},{"id":"07_suriagehara","n":"摺上原古戦場（伊達政宗の会津攻め）","yomi":"すりあげはらこせんじょう","cat":"古戦場","rank":"A","y":1589,"era":["azuchi"],"sh":"","ad":"耶麻郡磐梯町〜猪苗代町（磐梯山の南のふもと）","st":"JR磐越西線 磐梯町駅または猪苗代駅から車で約10分","la":37.575,"lo":140.035,"hook":"23歳の伊達政宗が、南奥州の覇者になった一日。その勝利は、翌年には秀吉に取り上げられる «幻の天下取り» でもあった。","lead":"摺上原（すりあげはら）は、磐梯山の南に広がる原野です。1589年（天正17年）、伊達政宗がここで会津の蘆名（あしな）氏の軍を破りました。この勝利で政宗は会津を手に入れ、東北南部の大部分を支配する大名になります。","story":["会津を400年近く治めてきた蘆名氏。でもこのころの蘆名家は、当主が若くして亡くなることが続き、家臣たちの心もばらばらでした。常陸（茨城県）の佐竹家から養子にむかえた蘆名義広が当主になると、«よそから来た殿様» に不満を持つ家臣も出てきます。その様子を、米沢の伊達政宗はじっと見ていました。","政宗がまず手を回したのは、蘆名の重臣・猪苗代盛国（もりくに）。盛国は伊達側につき、猪苗代城を政宗に明け渡しました。«会津の玄関がひらいた!» 政宗は大軍をひきいて猪苗代へ入り、1589年6月5日、磐梯山のふもとの摺上原で蘆名軍と向き合います。","戦いの始まりは、蘆名軍が優勢だったといわれます。ところが途中で風向きが変わり、砂ぼこりが蘆名軍の顔に吹きつけた——そんな話が伝わっています。やがて蘆名軍はくずれ、日橋川（にっぱしがわ）へ逃げる兵の多くが、橋が落とされていたために川で命を落としたといわれます。","義広は会津の黒川城（のちの鶴ヶ城）へ戻ることもできず、実家の佐竹家へ逃れました。政宗は黒川城に入り、ここを新しい本拠にします。南奥州の多くを手にした政宗は、このとき23歳。«天下も夢ではない» と思ったかもしれません。","けれど天下は、すでに豊臣秀吉のものになりつつありました。秀吉は大名どうしの勝手な戦いを禁じていたので、政宗の会津攻めは «命令違反» とされます。翌1590年、政宗は小田原へ出向いて秀吉に従い、会津は取り上げられました。摺上原は、政宗の栄光と、時代の大きな流れがぶつかった場所なのです。"],"tl":[["1584年","伊達政宗が家督をつぐ"],["1587年","蘆名家に佐竹家から義広が養子に入る"],["1589年6月5日","摺上原の戦い。伊達軍が蘆名軍を破る（旧暦）"],["1589年6月","政宗が黒川城に入る。蘆名氏の会津支配が終わる"],["1590年","政宗が小田原で秀吉に従う。奥州仕置で会津は没収され蒲生氏郷へ"]],"who":[["伊達政宗","伊達家の当主。摺上原で勝ち、会津を手に入れた"],["蘆名義広","佐竹家から蘆名家に入った当主。敗れて常陸へ逃れた"],["猪苗代盛国","蘆名家の重臣。伊達側について猪苗代城を開いた"],["豊臣秀吉","惣無事令を出し、政宗から会津を取り上げた"],["蒲生氏郷","政宗のあとに会津に入り、黒川を «若松» とあらためた"]],"deep":["«惣無事令（そうぶじれい）»: 秀吉が大名たちに私戦を禁じた命令をこう呼びます。ただし一つの法令として出されたかどうかには議論があり、研究者の間でも見方が分かれています。","風向きが変わって伊達軍に有利になったという話は、戦いの様子を語る後世の記録に出てくるもので、どこまで事実かは確かめにくい部分があります。","伊達軍と蘆名軍の兵の数は、記録によってさまざまで、はっきりしません。伊達軍のほうが多かったとみるのが一般的です。","猪苗代盛国の寝返りの背景には、猪苗代家の中での親子の対立もあったとされます。戦国の家は、一族の争いが外の戦いと結びつくことがよくありました。","政宗は会津を失ったあと、さらに葛西・大崎一揆への関与を疑われ、最終的に岩出山、そして仙台へと移ります。摺上原の勝利は、仙台藩誕生への長い道の出発点ともいえます。"],"look":["摺上原古戦場の碑（周辺の原野と磐梯山の眺め）","蘆名軍が逃げた日橋川の流れ","猪苗代城跡（亀ヶ城公園）","会津若松の鶴ヶ城（黒川城）とあわせてめぐる"],"q":["摺上原の戦いのあと、伊達政宗が本拠にした城は？","会津の黒川城（のちの若松城・鶴ヶ城）です。翌年、秀吉に取り上げられました。"],"koji":[],"myth":"風向きの逆転や日橋川の落橋の話は伝承的要素を含む。兵数は諸説。碑の正確な位置は現地で確認を。","img":["伊達政宗","蘆名義広","猪苗代城"],"wp":"摺上原の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:1/19/MASAMUNE777.PNG",533,394,"伊達政宗"],["c:3/33/%E8%98%86%E5%90%8D%E7%BE%A9%E5%BA%83%E3%81%AE%E8%8A%B1%E6%8A%BC.jpg",1993,1536,"蘆名義広"],["c:2/28/%E7%8C%AA%E8%8B%97%E4%BB%A3%E5%9F%8E%E8%B7%A1.jpg",2816,2112,"猪苗代城"]]},{"id":"07_hitotoribashi","n":"人取橋古戦場","yomi":"ひととりばしこせんじょう","cat":"古戦場","rank":"A","y":1585,"era":["azuchi"],"sh":"","ad":"本宮市青田（人取橋付近）","st":"JR東北本線 本宮駅から車で約5分","la":37.533,"lo":140.403,"hook":"数倍の大軍に囲まれた19歳の政宗。老将・鬼庭左月が命をかけた «しんがり» が、伊達家をすくった。","lead":"人取橋（ひととりばし）は、本宮市を流れる小さな川にかかる橋です。1585年（天正13年）、伊達政宗の軍と、佐竹・蘆名などの連合軍がここで激しく戦いました。あまりにも多くの人が討たれたことから «人取橋» の名がついたといわれます。","story":["事件の始まりは、政宗の父・輝宗の死でした。二本松城主の畠山義継が、話し合いの席で輝宗を連れ去ったのです。追いかけた伊達軍が義継を撃ち、輝宗もこのとき命を落としました。«父のかたきを!» 政宗は二本松城を取りかこみます。","ところが、この動きを見た周りの大名たちが立ち上がりました。常陸の佐竹義重を中心に、蘆名・岩城・石川・白河・二階堂など南奥州の大名が手を組み、大軍で政宗に迫ります。連合軍は3万ともいわれ、伊達軍はその数分の一だったと伝わります。","1585年11月、両軍は本宮の人取橋のあたりでぶつかりました。伊達軍は押しまくられ、政宗自身も危ない場面があったといわれます。そのとき、しんがり（退く味方を守る最後尾の役）を引き受けたのが、70歳をこえた老将・鬼庭左月（おににわさげつ）でした。«若殿を無事に逃がせ!» 左月は奮戦して討ち死にします。","その夜、ふしぎなことがおこりました。勝っていたはずの連合軍が、次の日には兵を引き上げてしまったのです。佐竹家の本国が他の大名におびやかされたため、あるいは陣中で重臣が亡くなる事件があったためなど、理由はいくつか伝わっています。政宗はぎりぎりのところで生きのびました。","いま人取橋のあたりには古戦場の碑が立ち、近くには鬼庭左月の墓とされる場所もあります。何気ない田園の小川ですが、ここで多くの人の命がうばわれたこと、そしてこの一戦がなければ «独眼竜» の物語もなかったかもしれないことを思いながら歩いてみてください。"],"tl":[["1584年","伊達政宗が18歳で家督をつぐ"],["1585年10月","畠山義継が伊達輝宗を連れ去り、輝宗・義継ともに死亡（粟之巣の変）"],["1585年11月","人取橋の戦い（旧暦）。連合軍が突然撤退"],["1586年","二本松城が開城し、畠山氏が滅ぶ"],["1589年","摺上原の戦いで政宗が蘆名氏を破る"]],"who":[["伊達政宗","19歳の伊達家当主。大軍に囲まれ苦戦した"],["鬼庭左月（良直）","伊達家の老臣。しんがりをつとめて討ち死に"],["佐竹義重","常陸の大名。連合軍の中心。«鬼義重» とも呼ばれた"],["伊達輝宗","政宗の父。畠山義継に連れ去られ亡くなった"],["畠山義継","二本松城主。輝宗を連れ去った"]],"deep":["«人取橋» の名は、この戦いで多くの人が討たれたことに由来するといわれますが、戦いの前からの名だという説もあります。","連合軍の兵数 «約3万»、伊達軍 «約7千» という数字は軍記物などに見えるもので、正確な数はわかりません。ただ伊達軍が大きく劣勢だったことは確かとみられます。","連合軍が撤退した理由としては、佐竹領に北条氏や江戸氏の動きがあったこと、佐竹方の重臣が陣中で殺されたことなどが挙げられ、複数の要因が重なったとも考えられます。","鬼庭左月の子が鬼庭綱元（のちの茂庭綱元）で、政宗を支えた «伊達三傑» の一人に数えられます。父子二代で伊達家を支えた家柄です。","政宗はのちにこの戦いをふりかえり、生涯でも最も危ない戦いのひとつだったと語ったと伝わります。若き日の政宗の «負けなかった戦い» として知られています。"],"look":["人取橋古戦場の碑","鬼庭左月の墓と伝わる場所","瀬戸川にかかる人取橋と周辺の地形","本宮の町並み（奥州街道の宿場）"],"q":["人取橋の戦いで、政宗を逃がすために最後尾で戦った老将は？","鬼庭左月（良直）。70歳をこえていたといわれ、この戦いで討ち死にしました。"],"koji":[{"w":"殿（しんがり）","m":"軍が退くとき、最後尾で敵を食い止める役。最も危険な役目とされた"}],"myth":"兵数、地名の由来、連合軍撤退の理由は諸説。鬼庭左月の年齢は73歳とする記録が多い。","img":["伊達政宗","鬼庭良直","佐竹義重 (十八代当主)"],"wp":"人取橋の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:4/47/%E4%BA%BA%E5%8F%96%E3%82%8A%E6%A9%8B_%E5%A2%93_%E5%85%A8%E6%99%AF_%E3%83%A1%E3%83%BC%E3%83%AB%E7%94%A8.jpg",1151,863,"人取橋の戦い"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c2/Satake.jpg",710,710],["c:1/16/%E5%8A%9F%E5%A3%AB%E5%A3%87_%E3%83%A1%E3%83%BC%E3%83%AB%E7%94%A8.jpg",679,509],["c:1/19/MASAMUNE777.PNG",533,394,"伊達政宗"],["c:8/89/%E4%BD%90%E7%AB%B9%E7%BE%A9%E9%87%8D%EF%BC%88%E4%BD%90%E7%AB%B9%E6%B0%8F%E7%AC%AC18%E4%BB%A3%EF%BC%89%E3%81%AE%E4%BD%8D%E7%BD%B2%E3%81%A8%E8%8A%B1%E6%8A%BC.jpg",1536,1785,"佐竹義重 (十八代当主)"]]},{"id":"07_shirakawaguchi","n":"稲荷山（白河口の戦いの激戦地）","yomi":"いなりやま","cat":"幕末","rank":"A","y":1868,"era":["edo","meiji"],"sh":"","ad":"白河市稲荷山","st":"JR白河駅から歩いて約20分","la":37.1165,"lo":140.2065,"hook":"«白河以北一山百文»——みちのくの入り口で、100日にわたる攻防がくり広げられた。その中心が、この小さな山。","lead":"白河は昔から «みちのくの玄関» とされてきた場所です。1868年（慶応4年）、戊辰戦争で新政府軍と、会津・仙台など奥羽の藩の軍がこの白河をめぐって戦いました。城の南にある稲荷山は、いちばんの激戦地の一つです。","story":["江戸城が戦わずに明け渡されたあと、新政府の矛先は会津へ向かいました。会津を助けようと、東北や越後の藩は «奥羽越列藩同盟» を結びます。南から攻めてくる新政府軍を止めるには、みちのくの入り口・白河を守らなければならない。こうして白河は、東北の運命をかけた戦場になりました。","旧暦閏4月、同盟軍は白河の小峰城を押さえ、最初の新政府軍の攻撃を退けました。けれど5月1日、薩摩・長州・大垣などの新政府軍が、三方向から攻め寄せます。町の南の稲荷山には会津や仙台の兵が陣をしき、激しい撃ちあいになりました。","新政府軍は数こそ少なかったものの、射程の長い新式の銃と、たくみな作戦がありました。山の上からの攻撃に、同盟軍はつぎつぎに倒れていきます。会津の若き副総督・横山主税（ちから）もこの日に命を落としました。«一日で数百人が…»。白河の戦いの中で最も多くの死者を出したのが、この日だったといわれます。","小峰城は新政府軍の手に落ちました。同盟軍はその後も何度も城を取り返そうとし、戦いは約100日も続きます。しかし白河を取り戻すことはできず、ここが破られたことで、新政府軍は二本松、そして会津へと進んでいきました。","いま稲荷山は住宅地の近くの小さな丘で、戊辰の戦いを伝える碑が立っています。白河の町には、敵味方を問わず戦死者をとむらった墓がいくつも残り、白河の人々が両軍の死者を手厚く葬ったことが語りつがれています。"],"tl":[["1868年閏4月20日","同盟軍が白河小峰城を押さえる（旧暦）"],["1868年閏4月25日","新政府軍の最初の攻撃を同盟軍が退ける"],["1868年5月1日","新政府軍が白河を総攻撃。稲荷山などで激戦、小峰城が落ちる"],["1868年5〜7月","同盟軍が何度も白河奪回をめざして攻撃"],["1868年7月","新政府軍が棚倉・二本松方面へ進む"]],"who":[["西郷頼母","会津藩家老。白河口の総督をつとめた"],["横山主税","会津藩の副総督。稲荷山の戦いで戦死"],["伊地知正治","薩摩藩の軍師。新政府軍の指揮をとった"],["坂本大炊","仙台藩の指揮官。白河で戦死した"]],"deep":["«白河以北一山百文（しらかわいほくひとやまひゃくもん）»: 白河から北は山ひとつが百文の値打ちしかない、という東北をさげすむことばが、戊辰戦争のあとに使われたといわれます。のちに原敬がこれを逆手にとって «一山» という号を名乗った話は有名です。","5月1日の戦いでの同盟軍の戦死者は数百人にのぼったとされますが、記録によって数に幅があります。新政府軍の戦死者はずっと少なかったとされます。","白河市内には、会津藩の戦死者を葬った墓、長州・大垣など新政府軍の墓、仙台藩士の慰霊碑などが点在し、両軍の墓を市民が守ってきたことが知られています。","白河の戦いが長引いたことで、新政府軍は兵力を分けて平潟（茨城県）に上陸させるなど、別のルートからも東北へ攻め入る作戦をとりました。","小峰城は戊辰戦争で大部分が焼け、のちに三重櫓や前御門が木造で復元されています。稲荷山とあわせて歩くと、戦場の距離感がよくわかります。"],"look":["稲荷山の戊辰戦争の碑","横山主税ら会津藩士の慰霊碑・墓","白河小峰城（復元三重櫓）","市内に残る両軍の戦死者墓"],"q":["戊辰戦争の後に使われた «白河以北一山百文» とはどんな意味？","白河から北の東北は、山ひとつ百文の値打ちしかないという、東北をさげすむことばです。"],"koji":[{"w":"白河以北一山百文","m":"東北を低く見たことば。のちに岩手出身の原敬が «一山» と号して反骨を示したと伝わる"}],"myth":"死者数は史料により差がある。稲荷山の碑の配置は現地で確認を。","img":["白河小峰城","西郷頼母","奥羽越列藩同盟"],"wp":"白河口の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:1/1d/Komine_castle.jpg",3068,1793,"白河口の戦い"],["c:5/5b/Komine_castle_simizugomon.JPG",3072,2304],["c:c/c1/AizuAoi.png",744,744],["c:a/ab/Shirakawa_Komine_Castle_20100625-01.jpg",5184,3456,"白河小峰城"],["c:c/ce/Saig%C5%8D_Tanomo.jpg",367,565,"西郷頼母"]]},{"id":"07_nanko","n":"南湖公園（松平定信の «士民共楽»）","yomi":"なんここうえん","cat":"学び","rank":"A","y":1801,"era":["edo"],"sh":"国指定史跡・名勝","ad":"白河市南湖","st":"JR白河駅からバスで約10分、または東北新幹線 新白河駅から車で約10分","la":37.1165,"lo":140.224,"hook":"«武士も町人も、ともに楽しめ»。200年以上前、お殿様がみんなのためにつくった、日本最古といわれる公園。","lead":"南湖公園は、白河藩主の松平定信が1801年（享和元年）につくった池と庭の公園です。身分に関係なくだれもが楽しめるようにという «士民共楽（しみんきょうらく）» の考えで開かれ、«日本で最初の公園» ともいわれます。国の史跡と名勝に指定されています。","story":["松平定信は、8代将軍・徳川吉宗の孫として江戸に生まれました。若くして白河藩の養子になり、藩主になったのは天明の大飢饉のころ。東北では多くの人が飢えて亡くなりましたが、定信は米を集めて領民に配り、白河藩からは一人も飢え死にを出さなかったと伝わります。","その腕を見こまれ、定信は江戸で老中となり、«寛政の改革» を進めました。けれど改革はきびしすぎると反発もあり、数年で老中を退きます。白河に戻った定信が取り組んだことのひとつが、城の南の湿地を、大きな池のある公園に変えることでした。","«ここは殿様だけの庭ではない。武士も町の人も、ともに楽しむ場所にしよう»。定信はこの思いを «士民共楽» ということばに込めました。池をほる工事には、仕事を失った人々に働く場を与える意味もあったといわれます。池の水は田んぼをうるおす用水にもなりました。","池のまわりには松や桜、吉野の桜や嵐山の楓が植えられ、定信は景色の美しい場所を選んで «南湖十七景» と名づけました。«南湖» という名は、中国の詩人・李白の詩にちなむともいわれます。定信自身も和歌を詠み、文化人としても知られた人でした。","いま南湖公園には、定信をまつる南湖神社や、日本庭園の «翠楽苑»、名物の «南湖だんご» の茶屋が並びます。春は桜、秋は紅葉。200年前のお殿様の «みんなで楽しもう» という考えが、今もそのまま生きている場所です。"],"tl":[["1758年","松平定信、田安家に生まれる（吉宗の孫）"],["1783年","白河藩主となる。天明の飢饉への対応で名をあげる"],["1787年","老中首座となり寛政の改革を始める"],["1793年","老中を退く"],["1801年","南湖を開く（享和元年）"],["1922年","定信をまつる南湖神社が創建"],["1924年","南湖公園が国の史跡・名勝に指定"]],"who":[["松平定信","白河藩主・老中。寛政の改革を行い、南湖を開いた。号は楽翁"],["徳川吉宗","8代将軍。定信の祖父"],["白河の人々","池づくりの工事にたずさわり、公園を守ってきた"]],"deep":["«士民共楽»: 身分の区別がきびしかった江戸時代に、武士と庶民が同じ場所で楽しむことを目的にした点が画期的とされ、«日本最古の公園» といわれる理由になっています。","南湖は景観のための池であると同時に、下流の新田をうるおす灌漑用のため池の役割も持っていました。美しさと実用をかねた «定信らしい» 事業です。","«南湖十七景» と «南湖十六勝» は定信が選んだ名所で、それぞれに和歌や漢詩が詠まれ、碑が残るものもあります。","定信は白河藩で子どもの教育にも力を入れ、藩校 «立教館» や、庶民のための学校 «敷教舎» をつくりました。南湖とあわせて «教育と楽しみの殿様» といえます。","寛政の改革をからかった狂歌 «白河の清きに魚もすみかねて もとの濁りの田沼こひしき» は有名。きびしすぎる政治への庶民の本音が伝わってきます。"],"look":["大池の周りの散策路と «南湖十七景»","南湖神社（松平定信をまつる）","日本庭園 «翠楽苑»","名物の南湖だんご","共楽亭（定信ゆかりの茶室）"],"q":["南湖公園の «士民共楽» とはどういう意味？","武士も庶民も、身分に関係なくともに楽しむという意味。定信が公園に込めた考えです。"],"koji":[{"w":"白河の清きに魚もすみかねて もとの濁りの田沼こひしき","m":"定信の政治がきびしすぎて、以前の田沼意次の時代がなつかしいという庶民の皮肉の歌"}],"myth":"«日本最古の公園» は通説的な表現。名前の由来（李白の詩）や救済事業の性格は諸説あり。","img":["松平定信","寛政の改革","南湖神社"],"wp":"南湖公園","rel":{"ev":[],"grave":[]},"ph":[["c:a/a2/Shirakawa_nanko.jpg",2014,1343,"南湖公園"],["c:9/9b/ShirakawaCity.jpg",2816,2112],["c:b/b9/1975%E5%8D%97%E6%B9%96%28%E7%99%BD%E6%B2%B3%E5%B8%82%29.jpg",1280,960],["c:5/5e/Matsudaira_Sadanobu.jpg",800,800,"松平定信"],["c:1/18/Nanko_shrine.JPG",1920,1080,"南湖神社"]]},{"id":"07_tanagura_jo","n":"棚倉城","yomi":"たなぐらじょう","cat":"城","rank":"A","y":1625,"era":["edo"],"sh":"","ad":"東白川郡棚倉町棚倉（亀ヶ城公園）","st":"JR水郡線 磐城棚倉駅から歩いて約10分","la":37.029,"lo":140.379,"hook":"神社を引っ越させて建てた城。水をたたえた堀と土塁が、今も «東北の南の守り» の形を残している。","lead":"棚倉城は、江戸時代のはじめに丹羽長重（にわながしげ）が築いた城です。関東と東北の境を守る大事な城とされ、何度も藩主が入れかわりました。戊辰戦争で焼け落ちましたが、今も広い堀と土塁が残り、«亀ヶ城公園» として親しまれています。","story":["関ヶ原の戦いで西軍についた丹羽長重は、一度は領地をすべて失いました。けれど築城の名人として知られ、やがて許されて棚倉の大名になります。ここで城を築く場所に選ばれたのが、なんと «近津明神» という古い神社の森でした。神社はよそへ移され、そのあとに城が建てられたと伝わります。","«なぜ、わざわざ神社の場所に?» ——棚倉は常陸（茨城県）から東北へ入る道の途中にあり、南からの敵にそなえる要の地でした。台地の上にあるこの場所は、城を築くのにぴったりだったのでしょう。堀に水を満たし、高い土塁をめぐらせた、どっしりとした平城が生まれました。","ところが長重は、城ができて間もなく白河へ移り、今度は白河小峰城を築きます。そのあと棚倉には、内藤氏、太田氏、松平氏、小笠原氏、井上氏など多くの大名が入れかわりました。«棚倉に移されるのは左遷» とささやかれることもあったといわれます。","幕末、最後の藩主となった阿部氏のとき、戊辰戦争がおこります。白河を落とした新政府軍は棚倉へ進み、1868年6月、城は炎に包まれて落ちました。藩士たちの多くは城を捨てて退き、戦いを続けたといわれます。","いま城跡には建物はありませんが、大きな堀と土塁がほぼぐるりと残っています。春は桜、夏は堀に映る緑。本丸跡の大ケヤキは、城ができる前の神社の時代からあったともいわれ、この場所の長い歴史を見守ってきたかのようです。"],"tl":[["1622年","丹羽長重が棚倉に入る"],["1625年ごろ","近津明神を移して棚倉城の築城が始まる"],["1627年","丹羽長重が白河へ移る"],["江戸時代","内藤・太田・松平・小笠原・井上など藩主が次々に交代"],["1866年","阿部氏が白河から棚倉へ移る"],["1868年6月","戊辰戦争で棚倉城が落城（旧暦）"]],"who":[["丹羽長重","丹羽長秀の子。築城の名手。棚倉城と白河小峰城を築いた"],["阿部正静","棚倉藩最後の藩主。戊辰戦争で城を失った"],["近津明神（都々古別神社）","もとは城の場所にあった神社。馬場へ移された"]],"deep":["棚倉城は台地を利用した輪郭式の平城で、本丸を二の丸・三の丸が囲むつくり。現在も本丸をめぐる堀と土塁がよく残り、城の形をたどることができます。","近津明神（のちの馬場都々古別神社）を移して城を築いたという話は、神社側の由緒にも伝わります。城と神社の歴史がつながっている珍しい例です。","棚倉藩は江戸時代に藩主家が何度も交代したことで知られ、老中を出した家もあれば、失敗の罰として移された家もあったといわれます。","戊辰戦争での棚倉落城は、白河口の戦いの続きとして起きました。新政府軍が白河から東へ兵を向けたことで、同盟軍の南の守りが崩れていきます。","丹羽長重は小峰城の石垣づくりでも名を残し、棚倉と白河の二つの城は、同じ人物が築いた «兄弟城» ともいえます。"],"look":["本丸をかこむ水堀と高い土塁","本丸跡の大ケヤキ","城跡の石碑と説明板","春の桜と堀の景色"],"q":["棚倉城を築いた丹羽長重が、次に築いた城は？","白河小峰城。棚倉からすぐに白河へ移りました。"],"koji":[],"myth":"築城開始の年は1625年とされることが多いが、史料により前後する。大ケヤキの樹齢も伝承的。","img":["丹羽長重","棚倉藩","白河小峰城"],"wp":"棚倉城","rel":{"ev":[],"grave":[]},"ph":[["c:5/59/Tanakura_Castle_hori.JPG",6016,4000,"棚倉城"],["c:6/6c/Tanakura_Castle_keyaki.JPG",6016,4000],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c3/TanakuraJo.jpg",1280,960],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:5/57/Niwa_Nagashige.jpg",573,1179,"丹羽長重"],["c:a/ab/Shirakawa_Komine_Castle_20100625-01.jpg",5184,3456,"白河小峰城"]]},{"id":"07_babatsutsuko","n":"馬場都々古別神社（陸奥一之宮）","yomi":"ばばつつこわけじんじゃ","cat":"寺社","rank":"A","y":1625,"era":["heian","azuchi","edo"],"sh":"国の重要文化財","ad":"東白川郡棚倉町棚倉字馬場","st":"JR水郡線 磐城棚倉駅から歩いて約20分","la":37.039,"lo":140.381,"hook":"«ここが陸奥国の一宮»——同じ名前の神社が二つ、どちらも一宮を名のる。そのなぞの一方がここ。","lead":"都々古別（つつこわけ）神社は、古くから陸奥国（東北地方の太平洋側）の «一宮» とされる格式の高い神社です。棚倉町には «馬場» と «八槻（やつき）» の二つの都々古別神社があり、馬場の神社は、もともと棚倉城のある場所にあったと伝わります。","story":["都々古別神社の名は、平安時代の法令集 «延喜式» にも出てきます。陸奥国の神社の中でも特に重要な «名神大社» に数えられた、由緒ある神社です。まつられているのは、国づくりの神の一人 «味耜高彦根命（あじすきたかひこねのみこと）» と、東国を平定したと伝わる日本武尊（やまとたけるのみこと）です。","この神社には、大きなお引っ越しの歴史があります。江戸時代のはじめ、棚倉城を築くことになった丹羽長重は、城の場所にあった神社を別の場所へ移しました。«神様を追い出して城を建てるなんて!» と思うかもしれませんが、こうして神社は、今の馬場の地に鎮まることになったと伝わります。","境内の奥に建つ本殿は、華やかな彫刻と色をもつ建物で、安土桃山時代の気風を残すつくりとされます。戦国から江戸へと移る時代の、力強い美しさを感じさせます。国の重要文化財に指定されており、陸奥一宮にふさわしい堂々とした姿を今に伝えています。","ところで、近くの八槻にも同じ名前の都々古別神社があり、こちらも «陸奥一宮» を名のっています。どちらが本来の神社なのか。古くは一つだった神社が分かれたのか、それとも別々だったのか——。«一宮はふたつ?» という不思議は、歴史好きの心をくすぐるなぞのひとつです。","杉の大木に囲まれた参道を歩くと、町のすぐそばとは思えない静けさに包まれます。城と神社の引っ越しの物語を知ってから、棚倉城跡と馬場の神社をあわせてめぐると、この町の成り立ちがぐっと身近に感じられるはずです。"],"tl":[["927年","延喜式神名帳に «都都古和気神社» が名神大社として記される"],["平安〜中世","陸奥国一宮として崇敬される"],["1625年ごろ","棚倉城築城のため、城地から馬場へ移されたと伝わる"],["明治時代","近代社格で国幣中社となる"],["現在","本殿が国の重要文化財。陸奥一宮として参拝者を集める"]],"who":[["味耜高彦根命","まつられている神。大国主命の子とされる"],["日本武尊","東征の伝説の英雄。あわせてまつられる"],["丹羽長重","棚倉城を築くため神社を移した大名"],["佐竹氏","戦国時代にこの地を支配した常陸の大名"]],"deep":["«一宮» とは、その国でいちばん格の高い神社のこと。陸奥国の一宮は都々古別神社とされますが、馬場・八槻のほか、石川町の石都々古和気神社も一宮を名のっていて、どの神社が本来の一宮かは諸説あります。","延喜式神名帳の «都都古和気神社» がどの神社にあたるのかについても、研究者の間で議論があります。棚倉周辺に古くから有力な神社があったことはまちがいありません。","本殿は三間社流造で、桃山時代の気風を残す装飾が見どころ。国の重要文化財に指定されています。造営の年代や施主については資料で確かめたい点が残ります。","社宝には平安時代の仏像や太刀なども伝わり、神と仏をいっしょにまつった神仏習合の時代の名残を感じさせます。","棚倉は常陸と陸奥を結ぶ道の途中にあり、古代には都から東北へ向かう人々が通った地域です。一宮がこの南の入り口に置かれたことにも意味があると考える説があります。"],"look":["重要文化財の本殿（江戸時代はじめの装飾）","杉並木の参道と静かな境内","近くの棚倉城跡（神社がもとあった場所）","八槻都々古別神社との見くらべ"],"q":["馬場都々古別神社が、もともとあったと伝わる場所は？","今の棚倉城跡。城を築くために馬場の地へ移されたと伝わります。"],"koji":[],"myth":"一宮の本来の所在や延喜式の比定には諸説。本殿の造営年・施主は未確認。","img":["八槻都都古別神社","陸奥国","一宮"],"wp":"馬場都都古別神社","rel":{"ev":[],"grave":[]},"ph":[["c:a/a0/Tsutsukowake-jinja_%28Baba%29_shaden-1.JPG",5936,3878,"馬場都都古別神社"],["c:a/a6/Tsutsukowake-jinja_%28Yatsuki%29_zuishinmon-2.JPG",6016,4000],["c:e/e4/Tsutsukowake-jinja_%28Yatsuki%29_zuishinmon-1.JPG",5996,3970],["c:2/2a/Tsutsukowake-jinja_%28Yatsuki%29_torii.JPG",6016,4000],["c:a/a7/Tsutsukowake-jinja_%28Yatsuki%29_shaden.JPG",6016,4000],["c:b/b1/Tsutsukowake-jinja_%28Yatsuki%29_keidaisha.JPG",6016,4000],["c:f/fb/Tsutsukowake-jinja_%28Yatsuki%29_honden.JPG",6016,4000],["c:2/20/Tsutsukowake-jinja_%28Yatsuki%29_haiden.JPG",6012,3996]]},{"id":"07_yatsuki","n":"八槻都々古別神社","yomi":"やつきつつこわけじんじゃ","cat":"寺社","rank":"B","y":1000,"era":["heian","muromachi","edo"],"sh":"","ad":"東白川郡棚倉町八槻字大宮","st":"JR水郡線 近津駅から歩いて約10分","la":37.0075,"lo":140.3975,"hook":"日本武尊が放った «八本目の矢» が落ちた場所——そんな伝説から名づけられた、もうひとつの陸奥一宮。","lead":"八槻（やつき）都々古別神社は、棚倉町の南にある古い神社です。近くの馬場の都々古別神社と同じ名前で、こちらも «陸奥国一宮» を名のっています。田植えのようすを演じる古い祭りが伝わり、地域の人々に大切に守られてきました。","story":["むかし、東の国々を平定するためにやってきた日本武尊。この地で矢を放つと、八本目の矢がここに突き立ったといいます。«矢が着いた» から «矢着（やつき）»、それが «八槻» になった——。地名にまで伝説がしみこんだ、ふしぎな土地です。","神社の森に入ると、大きな杉やケヤキがそびえ、空気がひんやりと変わります。まつられているのは味耜高彦根命と日本武尊。馬場の神社と同じ神様です。«どうして同じ名前の神社が二つあるの?» この問いには、はっきりした答えはありません。","中世には、八槻の神社には修験（山伏）の人々がかかわり、神社を支える別当の家が大きな力を持っていたといわれます。その家に伝わった古い文書は、戦国時代の南奥州の様子を知る手がかりとして研究されています。神社は、祈りの場であると同時に、情報や人が集まる地域の中心でもあったのです。","この神社で知られるのが、年のはじめに行われる «御田植（おたうえ）» の祭りです。田をたがやし、苗を植え、稲を刈る——一年の米づくりのようすを、人々がことばと動きで演じ、豊作を祈ります。昔の農村の暮らしと祈りを、今に伝える貴重な行事です。","にぎやかな観光地ではありませんが、それだけに、古い神社の静けさがそのまま残っています。馬場の都々古別神社、棚倉城跡とあわせて歩けば、«一宮はどこか» というなぞを自分の目で考える小さな旅になるでしょう。"],"tl":[["伝説の時代","日本武尊の矢が落ちた地と伝わる"],["927年","延喜式神名帳に «都都古和気神社» が名神大社として記される"],["中世","別当の家を中心に修験とかかわりを深める"],["戦国時代","別当家に伝わる文書に、佐竹氏・白河氏などとのかかわりが記される"],["現在","年のはじめに御田植の祭りが行われる"]],"who":[["日本武尊","東征伝説の英雄。矢の伝説で地名の由来に登場する。祭神"],["味耜高彦根命","まつられている神"],["別当（八槻家）","中世以来、神社を支えた家。古文書を伝えた"],["地域の人々","御田植の祭りを受けついできた"]],"deep":["陸奥国一宮を名のる神社は、八槻・馬場の二つの都々古別神社と、石川町の石都々古和気神社があります。延喜式の «都都古和気神社» がどれにあたるかは、昔から諸説あります。","八槻の地名が «矢着» に由来するという話は、神社に伝わる伝説で、歴史的に確かめられるものではありません。地名の由来として楽しむのがよいでしょう。","別当家に伝わった古文書（八槻文書と呼ばれることがある）は、中世の白河結城氏や佐竹氏などの動きを知る史料として、研究に使われています。","年のはじめの御田植は、ことばと所作で一年の稲作を模擬的に演じる «予祝（よしゅく）» の行事です。国の重要無形民俗文化財とされる «都々古別神社の御田植» として知られます。","八槻と馬場は数キロしか離れておらず、どちらも久慈川流域の、常陸から陸奥へ入る道の近くにあります。古代の交通路と一宮の関係を考える手がかりになります。"],"look":["杉やケヤキの大木に囲まれた境内","社殿と参道の静けさ","年のはじめの御田植の祭り（日程は事前に確認）","馬場都々古別神社との見くらべ"],"q":["«八槻» という地名の由来として伝わる伝説は？","日本武尊が放った八本目の矢がこの地に突き立った（矢着）という伝説です。"],"koji":[],"myth":"地名の由来は伝説。一宮の所在は諸説。御田植の文化財指定の範囲は資料で確認を。","img":["馬場都都古別神社","日本武尊","一宮"],"wp":"八槻都都古別神社","rel":{"ev":[],"grave":[]},"ph":[["c:a/a0/Tsutsukowake-jinja_%28Baba%29_shaden-1.JPG",5936,3878,"八槻都都古別神社"],["c:a/a6/Tsutsukowake-jinja_%28Yatsuki%29_zuishinmon-2.JPG",6016,4000],["c:e/e4/Tsutsukowake-jinja_%28Yatsuki%29_zuishinmon-1.JPG",5996,3970],["c:2/2a/Tsutsukowake-jinja_%28Yatsuki%29_torii.JPG",6016,4000],["c:a/a7/Tsutsukowake-jinja_%28Yatsuki%29_shaden.JPG",6016,4000],["c:b/b1/Tsutsukowake-jinja_%28Yatsuki%29_keidaisha.JPG",6016,4000],["c:f/fb/Tsutsukowake-jinja_%28Yatsuki%29_honden.JPG",6016,4000],["c:2/20/Tsutsukowake-jinja_%28Yatsuki%29_haiden.JPG",6012,3996]]},{"id":"07_iwaki_taira","n":"磐城平城","yomi":"いわきたいらじょう","cat":"城","rank":"A","y":1603,"era":["edo","meiji"],"sh":"","ad":"いわき市平字旧城跡","st":"JR常磐線 いわき駅から歩いて約5分","la":37.0615,"lo":140.888,"hook":"駅を出てすぐの丘が、かつての «龍ヶ城»。老中を生んだ城は、戊辰戦争の炎の中に消えた。","lead":"磐城平城は、江戸時代のはじめに鳥居忠政が築いた城で、«龍ヶ城（たつがじょう）» とも呼ばれました。いわき駅のすぐ北の丘にあり、幕末には老中・安藤信正の城でした。1868年の戊辰戦争で焼け落ち、今は堀の跡や石垣の一部などが残っています。","story":["関ヶ原の戦いのあと、徳川家康の信頼があつい鳥居忠政が、磐城の地に入りました。忠政の父・元忠は、関ヶ原の前に伏見城を守って討ち死にした忠義の武将。その息子にまかされたのが、太平洋側の要地・磐城でした。忠政は丘の上に新しい城を築き始め、完成までに十年以上かかったといわれます。","城は丘の地形をいかし、深い沢を堀に使った守りの固いつくりでした。今の «丹後沢» の池も、そのなごりとされます。三階の櫓がそびえるその姿から、城は «龍ヶ城» と呼ばれたと伝わります。","江戸時代の間に、城の主は鳥居氏から内藤氏、井上氏、そして安藤氏へと変わりました。幕末の藩主・安藤信正は老中として、将軍の妹・和宮を天皇家から迎える «公武合体» を進めた人物です。ところが1862年、江戸城の坂下門の外で水戸の浪士らにおそわれ、けがを負いました。«坂下門外の変» です。","1868年、戊辰戦争。平潟に上陸した新政府軍が北へ進み、磐城平城に迫りました。平藩は奥羽越列藩同盟の一員として戦いましたが、7月13日、城は炎に包まれて落ちました。藩士たちは北へ退き、戦いを続けたといわれます。","いま城跡には建物は残っていませんが、丹後沢の池、石垣の一部、城の坂道が、昔の姿を伝えています。駅前のにぎやかな町からほんの数分。«ここに龍ヶ城が立っていた» と想像しながら、丘の上を歩いてみてください。"],"tl":[["1602年","鳥居忠政が磐城平に入る"],["1603年ごろ","築城が始まる。完成まで十年以上かかったといわれる"],["1622年","鳥居氏が山形へ移り、内藤氏が入る"],["1747年","内藤氏が日向延岡へ移り、井上氏が入る"],["1756年","安藤氏が入り、幕末まで治める"],["1862年","藩主・安藤信正が坂下門外の変で負傷"],["1868年7月13日","戊辰戦争で落城（旧暦）"]],"who":[["鳥居忠政","城を築いた大名。伏見城で討ち死にした鳥居元忠の子"],["安藤信正","幕末の藩主・老中。和宮降嫁を進め、坂下門外の変でおそわれた"],["内藤氏","江戸時代前半の藩主家。俳諧など文化を好んだ藩主も出た"]],"deep":["«龍ヶ城» の呼び名は、城のある丘の形や櫓の姿にちなむといわれますが、由来ははっきりしません。","鳥居忠政の父・元忠が守って討ち死にした伏見城の床板は、のちに «血天井» として京都の寺々に移されたと伝わります。磐城平城を築いた一族の «忠義» の物語として語られてきました。","城跡の中心部は長く民有地となっていたため、自由に入れない部分がありました。近年は市による整備が進められています。訪れる前に最新の見学情報を確認しましょう。","安藤信正は坂下門外の変のあと老中を退きますが、戊辰戦争では隠居の身ながら藩を指導し、同盟側として戦いました。戦後は処罰を受けています。","内藤家の時代、藩主の内藤義概（風虎）は俳諧を愛し、多くの俳人と交流したことで知られます。平の町が文化の町として育った背景のひとつです。"],"look":["丹後沢公園（堀として使われた沢の池）","残る石垣と城坂の道","本丸跡周辺の丘（見学できる範囲を確認）","いわき駅北口からの城跡の丘の眺め"],"q":["磐城平城の藩主で、坂下門外の変でおそわれた老中は？","安藤信正。和宮降嫁など公武合体を進めた人物です。"],"koji":[],"myth":"«龍ヶ城» の名の由来は諸説。完成年は史料で幅がある。城跡中心部の公開状況は変化している。","img":["安藤信正","鳥居忠政","坂下門外の変"],"wp":"磐城平城","rel":{"ev":[],"grave":[]},"ph":[["c:c/cf/Tangosawa_Park.JPG",3648,2736,"磐城平城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:4/43/Ando_Nobumasa.jpg",192,285,"安藤信正"],["c:d/d9/Torii_Tadamasa.jpg",1676,3223,"鳥居忠政"],["c:9/9b/Sakashita-Mon%2CHasuike_tatsumi_Mie_tower.jpg",1024,589,"坂下門外の変"]]},{"id":"07_miharu_jo","n":"三春城（舞鶴城）","yomi":"みはるじょう","cat":"城","rank":"A","y":1504,"era":["muromachi","azuchi","edo"],"sh":"","ad":"田村郡三春町大町（城山公園）","st":"JR磐越東線 三春駅から歩いて約25分","la":37.441,"lo":140.493,"hook":"伊達政宗の妻 «愛姫（めごひめ）» が生まれた城。山の上から、梅・桃・桜が一度に咲く «三春» の町を見下ろす。","lead":"三春城は、戦国時代に田村氏が築いた山城で、«舞鶴城» とも呼ばれます。田村清顕の娘・愛姫は伊達政宗の正室になりました。江戸時代には秋田氏の城となり、幕末まで三春藩の中心でした。今は城山公園として整備され、石垣の一部などが残っています。","story":["三春の町は、山と谷がいりくんだ土地にあります。その中心の山の上に、戦国時代の初め、田村義顕が城を築きました。«三春» という名は、春に梅・桃・桜が一度に咲くからとも伝わります。山の上からは、城下の町並みがひと目で見わたせます。","田村氏は、伊達・蘆名・佐竹といった強い大名にはさまれた小さな大名でした。生きのびるためには、どこかと手を結ばなければならない。田村清顕が選んだのは伊達家でした。一人娘の愛姫を、数え12歳で、13歳の伊達政宗のもとへ嫁がせたのです。«どうか伊達とともに、田村を守ってくれ»——そんな願いが込められていたのでしょう。","けれど清顕の死後、跡つぎをめぐって田村家の中は割れ、豊臣秀吉の奥州仕置で田村氏は領地を失います。その後、三春は何人かの大名の手を渡り、江戸時代の半ばからは常陸から移った秋田氏が治めました。秋田氏は明治まで約220年、三春の殿様をつとめます。","幕末の戊辰戦争で、三春藩ははじめ奥羽越列藩同盟に加わりました。しかし新政府軍が迫ると、戦わずに新政府側についたのです。周りの藩からは «裏切り» と非難されましたが、城と町は戦火をまぬがれました。«戦わない» という選択の是非は、今も語られるテーマです。","明治になると城の建物は取りこわされ、今は城山公園として石垣や曲輪の跡が残っています。山頂からは三春の町並みが一望でき、春には桜の名所になります。有名な «三春滝桜» とあわせて訪ねる人も多い町です。"],"tl":[["1504年","田村義顕が三春城を築いたと伝わる（永正元年）"],["1579年","田村清顕の娘・愛姫が伊達政宗に嫁ぐ"],["1590年","奥州仕置で田村氏が領地を失う"],["1645年","秋田俊季が三春に入る"],["1868年","戊辰戦争で三春藩が新政府側につき、城下は戦火をまぬがれる"],["明治初め","城の建物が取りこわされる"]],"who":[["田村義顕","三春城を築いたと伝わる田村氏の当主"],["田村清顕","義顕の孫。娘を伊達政宗に嫁がせた"],["愛姫（陽徳院）","清顕の娘で伊達政宗の正室。三春城で生まれた"],["伊達政宗","愛姫の夫。田村家と深く結びついた"],["秋田俊季","江戸時代に三春に入った秋田氏の初代藩主"]],"deep":["«舞鶴城» の呼び名は、山の形が鶴が舞う姿に似ていることからといわれます。同じ呼び名の城は全国にいくつもあります。","愛姫は政宗との間に、のちの仙台藩2代藩主・伊達忠宗を産みました。仙台藩の血筋に、三春の田村家の血が流れていることになります。","政宗は田村家の家名を残すことにこだわり、のちに孫の代に «田村家» を再興させました。この一関藩田村家の屋敷で、浅野内匠頭が切腹したことはよく知られています。","三春藩の戊辰戦争での行動は «三春狐» などと周囲から悪く言われたと伝わりますが、藩内には早くから新政府との交渉を進める動きがあったとされ、評価は分かれます。","三春は自由民権運動の指導者・河野広中の出身地でもあります。城下の町からは明治の政治を動かす人物も育ちました。"],"look":["城山公園の山頂（本丸跡）からの町並みの眺め","残る石垣と曲輪の跡","城下町の寺町と古い町並み","あわせて訪ねたい三春滝桜"],"q":["三春城で生まれ、伊達政宗の妻になった女性は？","愛姫（めごひめ）。田村清顕の娘で、12歳で政宗に嫁ぎました。"],"koji":[],"myth":"築城年（1504年）と «三春» の名の由来は伝承を含む。«三春狐» の評価は諸説。","img":["愛姫","三春藩","三春滝桜"],"wp":"三春城","rel":{"ev":[],"grave":[]},"ph":[["c:d/d9/%E4%B8%89%E6%98%A5%E5%9F%8E%E8%B7%A1_%E7%9F%B3%E5%9E%A3.jpg",3264,2448,"三春城"],["c:0/00/%E8%97%A9%E6%A0%A1%E6%98%8E%E5%BE%B3%E5%A0%82%E8%A1%A8%E9%96%80.JPG",3888,2592],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:8/86/Yotoku-in_Tamaya_2015a.jpg",2000,1500,"愛姫"],["c:8/8f/Miharu_Miharu-Takizakura_Front_1.jpg",3515,2636,"三春滝桜"]]},{"id":"07_ryozen","n":"霊山城（北畠顕家）","yomi":"りょうぜんじょう","cat":"城","rank":"A","y":1337,"era":["kamakura","muromachi"],"sh":"国指定史跡・名勝","ad":"伊達市霊山町（霊山）","st":"JR福島駅からバスで約1時間の «霊山» 付近の登山口から、歩いて約1時間","la":37.776,"lo":140.681,"hook":"岩山の上に «東北の都» が置かれた。10代の若き公家将軍・北畠顕家が、南朝の夢をかけた山城。","lead":"霊山（りょうぜん）は、ごつごつした岩がそびえる標高800mほどの山です。南北朝時代、南朝の北畠顕家（あきいえ）が、多賀城にあった陸奥の国府をここに移し、城を構えました。山全体が国の史跡・名勝で、今は紅葉の名所として知られます。","story":["鎌倉幕府がほろびたあと、後醍醐天皇は東北を治めるため、公家の北畠顕家を陸奥守として送りこみました。このとき顕家はまだ16歳ほど。幼い義良親王（のちの後村上天皇）を奉じて多賀城に入り、«陸奥将軍府» を開きます。都の公家が東北の武士たちをまとめる、前例のない試みでした。","やがて足利尊氏が後醍醐天皇にそむき、天下は二つに割れます。顕家は東北の兵をひきいて京へ攻め上り、尊氏を九州へ追いやるという大活躍を見せました。けれど東北に戻ると、多賀城のまわりは足利方の勢力に囲まれていました。«多賀城では守れない»。顕家が選んだのが、けわしい岩山・霊山でした。","1337年、顕家は国府を霊山に移します。切り立った岩壁、見通しのよい山頂。«ここなら敵も簡単には攻め上がれない»。山にはもともと、平安時代に開かれたと伝わる霊山寺があり、多くの僧坊が立ち並んでいたといわれます。その建物や地形が、城として使われたのでしょう。","しかし同じ年、顕家は再び京へ向けて出陣します。そして翌1338年、和泉国の石津（大阪府堺市）で戦死しました。まだ21歳でした。出陣前に後醍醐天皇へ書き送った意見書には、政治の改めるべき点がまっすぐに書かれていて、若き将軍の強い思いが伝わってきます。","顕家のあとも弟の顕信らが霊山を守りましたが、1347年ごろに落城したといわれます。いま山には岩場をめぐる登山道があり、国司館跡などとされる場所や、奇岩の絶景が楽しめます。ふもとには、北畠親房・顕家らをまつる霊山神社が建っています。"],"tl":[["859年","円仁が霊山寺を開いたと伝わる"],["1333年","北畠顕家が義良親王を奉じて多賀城に入る"],["1336年","顕家が京へ攻め上り、足利尊氏を破る"],["1337年","顕家が国府を霊山へ移す"],["1338年","顕家が和泉の石津で戦死（21歳）"],["1347年ごろ","霊山城が落城したといわれる"],["1881年","ふもとに霊山神社が創建される"]],"who":[["北畠顕家","南朝の公家・武将。陸奥守として東北を治め、霊山に国府を移した"],["北畠親房","顕家の父。『神皇正統記』を書いた南朝の重臣"],["義良親王（後村上天皇）","顕家に奉じられて陸奥に下った皇子"],["足利尊氏","室町幕府を開いた武将。顕家と戦った"],["円仁","霊山寺を開いたと伝わる天台宗の僧"]],"deep":["«顕家諫奏（かんそう）»: 顕家が戦死の直前に後醍醐天皇に出した意見書で、地方に有力者を置くこと、税を軽くすること、恩賞を公平にすることなどを求めています。若い顕家の政治観を示す史料として有名です。","霊山城は、岩山の地形そのものを守りに使った山城で、石垣を積んだ近世の城とはまったく違います。山上の平らな場所が、国司館や寺院の跡と考えられています。","霊山寺は平安時代に開かれたと伝わり、最盛期には多くの僧坊があったといわれますが、落城とともに焼けたとされます。寺の歴史には伝承の部分も多く残ります。","霊山は1930年代に国の史跡・名勝に指定され、歴史と景観の両方から価値が認められています。奇岩が連なる姿は «みちのくの耶馬渓» とたとえられることもあります。","霊山神社は明治時代に創建され、北畠親房・顕家・顕信・守親の4人をまつります。南朝の忠臣をたたえる明治の風潮の中で建てられた神社です。"],"look":["山頂付近の奇岩と絶景（護摩壇・天狗の相撲場など）","国司館跡とされる平場","ふもとの霊山神社","秋の紅葉（登山は足ごしらえをしっかり）"],"q":["霊山に国府を移した北畠顕家は、何歳で戦死した？","21歳。1338年、和泉国石津の戦いで亡くなりました。"],"koji":[],"myth":"霊山寺の開山（円仁・859年）は伝承。落城年は1347年とする説が多いが幅がある。遺構の性格は推定を含む。","img":["霊山","北畠顕家","霊山神社","陸奥将軍府"],"wp":"霊山城","rel":{"ev":[],"grave":[]},"ph":[["c:4/4a/Ryozen-Fukushima1.jpg",366,247,"霊山城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:8/8a/%E5%8C%97%E7%95%A0%E9%A1%95%E5%AE%B6.png",368,462,"北畠顕家"],["c:c/c4/%E9%9C%8A%E5%B1%B1%E7%A5%9E%E7%A4%BE.jpg",1024,768,"霊山神社"]]},{"id":"07_koori_nishiyama","n":"桑折西山城（伊達氏の本拠）","yomi":"こおりにしやまじょう","cat":"城","rank":"A","y":1532,"era":["muromachi"],"sh":"国指定史跡","ad":"伊達郡桑折町万正寺","st":"JR東北本線 桑折駅から歩いて約30分","la":37.854,"lo":140.504,"hook":"伊達家の親子げんかが、奥州じゅうを巻きこんだ。その舞台になった、政宗のひいおじいさんの城。","lead":"桑折西山城は、戦国時代に伊達稙宗（たねむね）が本拠にした山城です。稙宗はここで分国法 «塵芥集（じんかいしゅう）» を定めました。やがて息子の晴宗と争う «天文の乱» がおこり、戦いが終わると伊達家は米沢へ移りました。城跡は国の史跡です。","story":["伊達家のふるさとは、ここ伊達郡です。鎌倉時代、源頼朝の奥州合戦で手柄を立てた先祖がこの地を与えられ、«伊達» を名のったのが始まりといわれます。そして戦国時代、伊達稙宗が本拠を移したのが、桑折の西山にある山城でした。","稙宗は、とても野心的な殿様でした。子どもたちを周りの大名家へつぎつぎに養子や嫁に出し、奥州の大名たちと血のつながりをつくりました。さらに1536年、伊達家の領国を治めるための法律 «塵芥集» をつくります。170条をこえる、戦国大名の法の中でも特に大きなものです。","ところが、息子の晴宗が父のやり方に反対しました。稙宗が三男を越後の上杉家へ養子に出そうとしたことなどをきっかけに、晴宗は父を西山城に閉じこめてしまいます。«父上、もう好きにはさせません!» 稙宗は家臣に助け出され、親子の争いが始まりました。","これが «天文の乱» です。稙宗と晴宗、それぞれに周りの大名や家臣がついて、南奥州全体を巻きこむ大きな戦いになりました。争いは6年ほど続き、最後は将軍の仲立ちもあって晴宗が勝ちます。晴宗は本拠を米沢に移し、西山城はその役目を終えました。","いま城跡は、ふもとから歩いて登れる山になっていて、本丸や二の丸の跡、堀や土塁が残っています。山頂からは福島盆地が一望。«この景色を見ながら、稙宗は奥州を動かそうとしたのか» と思うと、ちょっとわくわくしてきます。この争いが終わってから約20年後に生まれる晴宗の孫こそ、あの伊達政宗です。"],"tl":[["1189年","奥州合戦のあと、伊達氏の先祖が伊達郡を与えられたと伝わる"],["1532年ごろ","伊達稙宗が本拠を桑折西山城へ移す"],["1536年","稙宗が «塵芥集» を定める"],["1542年","晴宗が稙宗を西山城に幽閉。天文の乱が始まる"],["1548年","天文の乱が終わり、晴宗が米沢へ本拠を移す"],["1567年","晴宗の孫・伊達政宗が生まれる"]],"who":[["伊達稙宗","西山城を本拠にした伊達家の当主。塵芥集を定めた"],["伊達晴宗","稙宗の長男。父と天文の乱で争い、米沢へ移った"],["伊達政宗","晴宗の孫。稙宗のひ孫にあたる"],["伊達朝宗","伊達氏の祖とされる人物。奥州合戦の功で伊達郡を得たと伝わる"]],"deep":["«塵芥集»: 伊達家の分国法で、170条あまりからなるとされます。刑事や土地、主従関係などを細かく定め、今川氏の «今川仮名目録» などとならぶ代表的な戦国大名の法です。","天文の乱の原因には、稙宗の婚姻・養子政策への家中の反発、越後上杉家への三男・実元の養子問題などがあったとされ、複数の要因が重なったとみられています。","城跡の発掘調査では、本丸・二の丸・中館などの曲輪、空堀や土塁が確認されています。山の尾根を利用した大規模な山城で、伊達家の力の大きさを物語ります。","伊達氏の名字の地・伊達郡には、奥州合戦の古戦場 «阿津賀志山防塁»（国史跡）も残ります。伊達家誕生のきっかけとなった戦いの跡とあわせて訪ねると、伊達家の «はじまり» がわかります。","桑折は江戸時代に奥州道中と羽州街道が分かれる宿場町として栄え、旧伊達郡役所（国の重要文化財）も残ります。戦国と近代の歴史を同じ町で見られます。"],"look":["本丸跡からの福島盆地の眺め","空堀と土塁の跡","城跡の説明板と遊歩道","ふもとの桑折の町（旧伊達郡役所など）"],"q":["伊達稙宗が桑折西山城で定めた法律の名前は？","«塵芥集（じんかいしゅう）»。戦国大名の分国法の代表例です。"],"koji":[],"myth":"本拠を移した年、塵芥集の条数、天文の乱の原因には諸説。伊達氏の起源は伝承を含む。","img":["伊達稙宗","伊達晴宗","塵芥集","天文の乱"],"wp":"桑折西山城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:4/43/Date_Tanemune.JPG",1810,1849,"伊達稙宗"],["c:5/58/Date_Harumune.jpg",1707,1522,"伊達晴宗"]]},{"id":"07_handa_ginzan","n":"半田銀山","yomi":"はんだぎんざん","cat":"産業","rank":"A","y":1874,"era":["edo","meiji"],"sh":"","ad":"伊達郡桑折町（半田山のふもと）","st":"JR東北本線 桑折駅から車で約10分","la":37.87,"lo":140.52,"hook":"佐渡・生野とならび称された «みちのくの銀の山»。明治には、あの五代友厚が近代鉱山に生まれ変わらせた。","lead":"半田銀山は、桑折町の半田山で掘られていた銀山です。江戸時代には幕府が直接おさめる大切な鉱山となり、明治になると実業家の五代友厚が西洋の技術を取り入れて大きく発展させました。今は鉱山の跡をしのぶ史跡公園などが整えられています。","story":["半田山のふもとを歩くと、ところどころに古い坑口や石垣のあとが見つかります。«ここに本当に銀が眠っていたの?» ——そう思うほど静かな山ですが、かつてここは、日本でも指折りの銀山でした。見つかったのは平安時代のはじめ、大同年間のことと伝わります。","江戸時代、銀は国のお金をつくる大事な金属でした。半田銀山は幕府が直接おさめる鉱山となり、たくさんの鉱夫が山に入って銀をほり出しました。周りの村には鉱山で働く人やその家族が集まり、にぎやかな鉱山町ができていたといわれます。","しかし掘り進むうちに、坑道には地下水がたまり、銀も取りにくくなっていきました。幕末には、山はすっかり衰えていたといわれます。そこに目をつけたのが、大阪で商売を広げていた薩摩出身の実業家・五代友厚でした。«西洋の技術を入れれば、この山はよみがえる!»","明治のはじめ、五代は半田銀山の経営にのり出し、水を抜く機械や新しい精錬の方法を取り入れました。銀の産出は大きくのび、半田銀山は日本の近代鉱山の先がけの一つになります。明治天皇が東北をめぐった際に、この銀山を視察したことも伝えられています。","やがて銀の量は減り、昭和になって鉱山の歴史は幕を閉じました。いまは史跡公園として整備され、坑口の跡や説明板で、銀山の時代をしのぶことができます。静かな山を見上げながら、地下にのびていた長い坑道と、そこで働いた人々に思いをはせてみてください。"],"tl":[["大同年間（9世紀初め）","銀が見つかったと伝わる"],["江戸時代","幕府が直接おさめる銀山として栄える"],["幕末","坑道の水や資源の減少で衰える"],["1874年","五代友厚が経営にのり出し、近代化を進める"],["明治時代","新しい技術で産出が増え、近代鉱山の先がけとなる"],["昭和","鉱山の歴史が終わる"]],"who":[["五代友厚","薩摩出身の実業家。大阪商法会議所をつくった。半田銀山を近代化した"],["明治天皇","東北巡幸の際に銀山を視察したと伝わる"],["鉱夫たち","坑道で銀をほり出した人々"]],"deep":["半田銀山は佐渡金山・但馬の生野銀山とならべて «日本三大鉱山» と呼ばれることがありますが、この呼び方にはほかの組み合わせもあり、地元での言い方として受けとめるのがよいでしょう。","五代友厚は、明治初めの大阪経済を立て直した人物として知られ、大阪証券取引所の前身や大阪商法会議所の設立にかかわりました。その資金のもとの一つが鉱山経営だったといわれます。","江戸時代の鉱山経営で最大の敵は «水» でした。坑道にたまる地下水をくみ出すため、人力の水かえに多くの人手がかかりました。明治に機械を入れたことが、復活の大きな鍵になったといわれます。","銀山のまわりには鉱山で亡くなった人々の供養碑などもあり、山の暮らしのきびしさを伝えています。","半田山のふもとには半田沼があり、鉱山とのかかわりを語る話も伝わります。桑折町は伊達氏の桑折西山城跡もある町で、戦国と近代の両方の歴史をめぐることができます。"],"look":["半田銀山史跡公園の坑口跡と説明板","鉱山に関わる石垣や供養碑","半田山と半田沼の風景","桑折の町（旧伊達郡役所など）とあわせてめぐる"],"q":["明治時代に半田銀山を近代化した実業家は？","五代友厚。西洋の技術を取り入れて銀の産出をのばしました。"],"koji":[],"myth":"発見の年代（大同年間）は伝承。幕府直轄となった年、明治天皇の視察、閉山年は資料で確認を。","img":["五代友厚","桑折町"],"wp":"半田銀山","rel":{"ev":[],"grave":[]},"ph":[["c:6/61/Shoin_Godai_Tomoatsu.jpg",1007,1325,"五代友厚"],["c:a/a2/KyuDateGunyakusho2006-12.jpg",1128,852,"桑折町"],["c:6/65/Kunimi_IC.jpg",1600,1200,"近く: 国見インターチェンジ"],["c:3/34/Fujita_Station_20190416.jpg",4032,2267,"近く: 藤田駅"],["c:4/42/JR_T%C5%8Dhoku_Line_Koori_Station_building.jpg",4161,2949,"近く: 桑折駅"],["c:e/e9/Atsukashiyama_ruins.jpg",900,674,"近く: 国見町"]]},{"id":"07_tenkyokaku","n":"天鏡閣（有栖川宮の別邸）","yomi":"てんきょうかく","cat":"近代","rank":"A","y":1908,"era":["meiji","taisho"],"sh":"国の重要文化財","ad":"耶麻郡猪苗代町翁島","st":"JR磐越西線 猪苗代駅からバスで約10分","la":37.548,"lo":140.06,"hook":"湖を «天の鏡» にたとえた洋館。皇太子が名づけた、明治の皇族の夏の別荘。","lead":"天鏡閣は、明治時代に有栖川宮威仁（たけひと）親王が猪苗代湖のほとりに建てた洋風の別邸です。完成した翌年に泊まった皇太子（のちの大正天皇）が、中国の詩人・李白の詩から «天鏡閣» と名づけました。国の重要文化財で、中を見学できます。","story":["猪苗代湖の北岸、松林に囲まれた丘の上に、白い壁と赤い屋根の洋館が建っています。門をくぐると、まるで明治の外国映画のセットに迷いこんだよう。ここは、有栖川宮威仁親王が夏を過ごすために建てた別荘です。","威仁親王は、若いころにイギリスで海軍を学んだ皇族でした。明治の終わりごろ、東北を旅してこの湖の景色にほれこみ、別邸を建てることにしたといわれます。できあがったのは、ルネサンス風の木造2階建ての洋館。暖炉やシャンデリア、洋風の家具がそろった、当時としてはとてもモダンな建物でした。","完成の翌年、皇太子の嘉仁親王がここに泊まりました。のちの大正天皇です。窓から見える猪苗代湖は、空をそのまま映して、まるで大きな鏡のよう。皇太子は李白の詩の一節 «明湖落天鏡（明るい湖は天から落ちた鏡のようだ）» から、この館を «天鏡閣» と名づけたと伝わります。«なんて美しい名前だろう»。","威仁親王が亡くなると、有栖川宮家のまつりは高松宮家に受けつがれ、天鏡閣も高松宮家のものになりました。第二次世界大戦のあと、天鏡閣は福島県にゆずられ、修理を受けて一般に公開されるようになります。","いま館内では、当時の家具や調度品、皇族の暮らしをしのばせる部屋を見ることができます。明治の衣装を着て記念写真をとれる体験も人気です。すぐ近くには高松宮家の別邸だった和風の建物もあり、洋と和の二つの «皇族の別荘» を見くらべるのも楽しいでしょう。"],"tl":[["1907年","有栖川宮威仁親王の別邸として建てられる"],["1908年","皇太子嘉仁親王が滞在し、«天鏡閣» と名づける"],["1913年","威仁親王が亡くなり、のちに高松宮家が引きつぐ"],["1952年","福島県にゆずられる"],["1979年","国の重要文化財に指定される"],["現在","一般公開され、明治の洋館として人気"]],"who":[["有栖川宮威仁親王","天鏡閣を建てた皇族。海軍軍人"],["嘉仁親王（大正天皇）","皇太子のときに滞在し、館を名づけた"],["高松宮宣仁親王","有栖川宮家のまつりを受けつぎ、天鏡閣を所有した"],["李白","唐の詩人。«天鏡» の出どころの詩を書いた"]],"deep":["«明湖落天鏡» は李白の詩の一節として知られ、もとは中国の湖の景色をうたったものです。それを猪苗代湖に重ねたところに、明治の皇族の漢詩の教養がうかがえます。","建物は木造2階建てで、塔屋や八角形の部屋などを持つ洋風建築です。外観はルネサンス風とされ、明治の皇族が好んだ洋館の典型例とされます。","近くの «旧高松宮翁島別邸» は、高松宮家が建てた和風の別邸で、こちらも国の重要文化財。現在は福島県の迎賓館として使われ、ふだんは公開されていません。","有栖川宮家は威仁親王の死で直系がとだえ、祭祀は大正天皇の皇子・宣仁親王（高松宮）が受けつぎました。高松宮の宮号自体が、有栖川宮家の古い称号にちなむものです。","猪苗代は野口英世のふるさとでもあり、天鏡閣から野口英世記念館までは車ですぐ。明治という時代の «皇族の暮らし» と «苦学の偉人» を同じ日に見くらべることができます。"],"look":["館の外観（塔屋と赤い屋根）","暖炉や当時の家具が残る各部屋","2階の窓から見る猪苗代湖","明治の衣装体験","近くの旧高松宮翁島別邸の外観（内部は通常非公開）"],"q":["«天鏡閣» という名前は、何から取られた？","唐の詩人・李白の詩 «明湖落天鏡»。皇太子嘉仁親王（大正天皇）が名づけました。"],"koji":[{"w":"明湖落天鏡","m":"明るい湖は、天から落ちてきた鏡のようだ、という意味の李白の詩の一節"}],"myth":"命名のいきさつは伝承的要素を含む。重要文化財の指定範囲・年は資料で確認を。","img":["有栖川宮威仁親王","猪苗代湖","旧高松宮翁島別邸"],"wp":"天鏡閣","rel":{"ev":[],"grave":[]},"ph":[["c:e/ea/Tenkyokaku.jpg",1053,700,"天鏡閣"],["c:b/b6/Tenkyokaku2008.jpg",1053,700],["c:d/d8/Tenkyokaku1908.jpg",1130,650],["c:c/c1/Arisugawa_Takehito.jpg",709,1024,"有栖川宮威仁親王"],["c:4/48/Lake_Inawashiro_view_from_Mt.Bandai.jpg",1024,768,"猪苗代湖"]]},{"id":"07_asaka_rekishi","n":"安積歴史博物館（旧福島県尋常中学校本館）","yomi":"あさかれきしはくぶつかん","cat":"学び","rank":"A","y":1889,"era":["meiji"],"sh":"国の重要文化財","ad":"郡山市開成5丁目","st":"JR郡山駅からバスで約15分","la":37.393,"lo":140.36,"hook":"明治の中学生が学んだ洋風校舎。ここから、アメリカの名門大学の教授になった少年が巣立った。","lead":"安積（あさか）歴史博物館は、1889年（明治22年）に建てられた «旧福島県尋常中学校» の本館を使った博物館です。今の福島県立安積高校のはじまりの校舎で、国の重要文化財に指定されています。明治の学校のようすや、ここで学んだ人々のことを知ることができます。","story":["郡山の開成山のあたりは、明治のはじめまで水の少ない原野でした。そこへ士族たちが移り住み、猪苗代湖から水を引く «安積疏水» がつくられて、少しずつ町が育っていきます。«新しい町には、新しい学校を»——そんな思いの中で建てられたのが、この洋風の中学校でした。","白い壁に、縦に長い窓がずらりと並ぶ木造2階建ての建物。2階には広い講堂があり、生徒たちはここで式典や演説会にのぞみました。明治の人々にとって、洋風の校舎は «新しい時代そのもの» だったにちがいありません。","この学校で学んだ一人に、二本松出身の朝河貫一がいます。貫一は英語がとても得意で、卒業式では英語でスピーチをしたと伝わります。やがてアメリカにわたり、イェール大学の教授になりました。日米が戦争へ向かう時代、貫一は «日本の進む道はあやうい» と、母国に警告を送りつづけました。","作家の久米正雄もこの学校（旧制安積中学）で学びました。のちに芥川龍之介や菊池寛らとともに活躍した作家です。«この廊下を、あの人たちも歩いたのか» と思うと、古い床のきしむ音さえ特別に聞こえてきます。","校舎は長い間学校として使われたあと、博物館として公開されるようになりました。東日本大震災では被害を受け、修理が行われています。明治の教室、講堂、そして卒業生たちの資料。明治の «学び» の熱気を、いまも感じられる建物です。"],"tl":[["1882年","安積疏水が完成し、開拓が進む"],["1889年","福島県尋常中学校の本館が完成（明治22年）"],["1892年ごろ","朝河貫一が卒業"],["明治後期","安積中学校となる（旧制）"],["1977年","本館が国の重要文化財に指定される"],["2011年","東日本大震災で被害を受け、のちに修理"]],"who":[["朝河貫一","卒業生。イェール大学教授となり、日本に国際的な警告を送りつづけた歴史学者"],["久米正雄","卒業生。大正・昭和の作家・劇作家"],["安積開拓の人々","この地を開いた士族や農民たち。学校が生まれる土台をつくった"]],"deep":["朝河貫一は1909年に英文の著作をもとにした『日本の禍機（かき）』を出し、日露戦争後の日本の大陸政策に警告を発しました。太平洋戦争の直前には、天皇へ親書を送るよう米大統領に働きかけたことでも知られます。","本館は洋風の外観ですが、日本の大工が西洋の建物をまねて建てた要素もあり、明治中期の学校建築のうつりかわりを知る貴重な例とされます。","2階の講堂は天井が高く、明治の学校に欠かせない «式典の場» でした。当時の学校は、儀式や演説を通じて国の教育方針を伝える場でもありました。","開成山一帯には、明治初めの開拓の拠点 «開成館»（福島県史跡）も残ります。安積開拓・安積疏水と中学校の誕生は、ひとつながりの物語です。","安積疏水は、那須疏水・琵琶湖疏水とならび日本三大疏水の一つとされます。国の事業として進められた、明治の大規模な開拓の象徴です。"],"look":["木造2階建ての洋風の外観と縦長の窓","2階の講堂","明治の教室の再現展示","朝河貫一ら卒業生の資料","近くの開成館（安積開拓の資料館）"],"q":["この学校で学び、アメリカのイェール大学の教授になった人物は？","朝河貫一。日本に国際的な警告を送りつづけた歴史学者です。"],"koji":[],"myth":"朝河貫一の卒業年、講堂での英語スピーチの逸話は資料で確認を。震災後の開館状況は最新情報を確認。","img":["朝河貫一","久米正雄","安積疏水"],"wp":"福島県立安積高等学校","rel":{"ev":[],"grave":[]},"ph":[["c:7/7b/%E5%AE%89%E7%A9%8D%E6%AD%B4%E5%8F%B2%E5%8D%9A%E7%89%A9%E9%A4%A8%28%E5%86%AC%29.JPG",466,350,"福島県立安積高等学校"],["c:a/a5/Kwan-Ichi_Asakawa.jpg",168,228,"朝河貫一"],["c:7/70/Kume_Masao.jpg",468,600,"久米正雄"]]},{"id":"07_joban_tanden","n":"いわき市石炭・化石館（常磐炭田）","yomi":"いわきしせきたんかせきかん","cat":"産業","rank":"A","y":1855,"era":["edo","meiji","showa"],"sh":"","ad":"いわき市常磐湯本町向田","st":"JR常磐線 湯本駅から歩いて約10分","la":37.008,"lo":140.844,"hook":"東京にいちばん近い炭田。地下深くでわき出るお湯と戦った坑夫たちの町は、やがて «フラガール» の町になった。","lead":"常磐炭田は、福島県のいわき市から茨城県の北部に広がっていた炭田です。江戸時代の終わりに石炭が見つかり、明治から昭和にかけて首都圏へ石炭を送りつづけました。«いわき市石炭・化石館 ほるる» では、実物大の模擬坑道で当時の炭鉱のようすを体験できます。","story":["1855年、いわきの白水（しらみず）村の山で、一人の商人が黒く光る石を見つけました。片寄平蔵（かたよせへいぞう）です。«これは燃える石だ!» 平蔵は石炭の値打ちを見ぬき、掘り出しを始めました。ちょうど黒船が来て、蒸気船の燃料として石炭が求められはじめた時代でした。","明治になると、渋沢栄一や浅野総一郎らがかかわって大きな炭鉱会社ができ、東京へ石炭を運ぶための鉄道も通りました。今の常磐線です。«石炭を運ぶために線路が敷かれた»——常磐線は、まさに炭田から生まれた鉄道でした。いわきの町には、全国から多くの人が働きに集まりました。","常磐の炭鉱には、ほかの炭鉱にはない大きな悩みがありました。地下を掘ると、熱い温泉がどっとわき出てくるのです。坑道の中は蒸し風呂のような暑さ。お湯をくみ出しながらの石炭掘りは、とてもきびしい仕事でした。落盤やガス爆発の事故で命を落とした人も少なくありません。","昭和の半ば、石油の時代がやってくると、炭鉱はつぎつぎに閉じていきました。«働く場がなくなってしまう!» そのとき炭鉱会社は、じゃまものだった温泉を逆に生かし、常夏のレジャー施設 «常磐ハワイアンセンター» をつくります。炭鉱の娘たちがフラダンスをおどって町を支えた話は、のちに映画にもなりました。","«ほるる» では、実物大の模擬坑道を歩き、人形や機械で再現された炭鉱の仕事を見ることができます。そしてもうひとつの主役が、いわきで見つかった首長竜 «フタバスズキリュウ» の化石。地下にねむる石炭と化石、どちらも大昔の地球からの贈りものです。"],"tl":[["1855年","片寄平蔵が白水で石炭を見つける（安政2年）"],["1884年ごろ","磐城炭礦社が設立され、本格的な採掘が進む"],["1897年","日本鉄道の路線（のちの常磐線）が平まで開通"],["1944年","炭鉱会社が合併し常磐炭礦となる"],["1966年","常磐ハワイアンセンターが開業"],["1968年","高校生の鈴木直さんがフタバスズキリュウの化石を発見"],["1976年","常磐炭礦の閉山で大規模な採掘が終わる"]],"who":[["片寄平蔵","常磐の石炭を見つけ、採掘を始めた商人"],["渋沢栄一","磐城炭礦社の設立にかかわった実業家"],["浅野総一郎","炭鉱経営やセメント業で知られる実業家"],["鈴木直","フタバスズキリュウの化石を発見した高校生"]],"deep":["常磐炭田は首都圏に近いという強みがあり、明治以降の東京の工業や鉄道を支えました。一方で石炭の質はほかの炭田より低いとされ、それが閉山を早めた一因ともいわれます。","坑内にわき出る温泉水の量は非常に多く、石炭を掘るよりも水をくみ出す手間のほうが大きいといわれるほどでした。その温泉がのちの観光に生かされたのは歴史の皮肉です。","«常磐ハワイアンセンター»（現在のスパリゾートハワイアンズ）の誕生と、炭鉱の娘たちのフラダンスの物語は、2006年の映画『フラガール』で描かれました。映画には脚色（創作）も含まれます。","フタバスズキリュウは約8500万年前の首長竜で、2006年に新属新種 «フタバサウルス・スズキイ» として学名がつきました。発見から学名まで38年かかったことになります。","«ほるる» の模擬坑道では、手掘りの時代から機械化までの採炭のうつりかわりを見られます。炭鉱住宅や人々の暮らしの展示もあり、«ヤマの暮らし» を知ることができます。"],"look":["実物大の模擬坑道（エレベーターで «地下» へ）","フタバスズキリュウの全身骨格の復元","炭鉱の暮らしの展示","近くのいわき湯本温泉の町並み"],"q":["常磐炭田の炭鉱で、坑夫たちを悩ませた «地下からわき出るもの» は？","温泉。のちにこのお湯を生かして常磐ハワイアンセンターがつくられました。"],"koji":[{"w":"一山一家（いちざんいっか）","m":"炭鉱で働く人は、ひとつの山の家族のように助けあうという、炭鉱の町でよく使われたことば"}],"myth":"映画『フラガール』は実話をもとにした創作を含む。会社設立年などは資料で確認を。","img":["フタバスズキリュウ","スパリゾートハワイアンズ","片寄平蔵"],"wp":"常磐炭田","rel":{"ev":[],"grave":[]},"ph":[["c:2/28/Coal_mines_1955_in_Japan_Tohoku.webp",1683,2362,"常磐炭田"],["c:0/0d/%E5%B8%B8%E7%A3%90%E7%82%AD%E9%89%B1%E4%B8%AD%E9%83%B7%E9%89%B1%E8%B7%A1.jpg",4320,3240],["c:3/3d/Futabasaurus.jpg",1200,800,"フタバスズキリュウ"],["c:f/f3/Spa_Resort_Hawaiians_Water_Park._A.JPG",4000,3000,"スパリゾートハワイアンズ"]]},{"id":"07_fusen_bakudan","n":"風船爆弾放球地跡（勿来）","yomi":"ふうせんばくだんほうきゅうちあと","cat":"昭和","rank":"A","y":1944,"era":["showa"],"sh":"","ad":"いわき市勿来町関田（放球地跡の碑）","st":"JR常磐線 勿来駅から歩いて約20分","la":36.87,"lo":140.79,"hook":"紙とこんにゃくのりでつくった気球が、太平洋をこえてアメリカへ。少女たちが作り、ここから飛ばされた «秘密兵器» の跡。","lead":"風船爆弾は、第二次世界大戦の終わりごろ、日本の陸軍がアメリカ本土をねらって飛ばした爆弾つきの気球です。和紙をこんにゃくのりではり合わせてつくられ、高い空をふく偏西風にのせて太平洋をわたらせました。勿来はその放球基地の一つで、跡地には碑が立っています。","story":["1944年、戦争はすでに日本にとって苦しい状況でした。«アメリカ本土を直接攻撃できないか»——陸軍が考えたのが、気球に爆弾をつけて飛ばすという作戦でした。日本の上空には、冬に西から東へとても速い風がふいています。この風にのれば、気球は数日で太平洋をこえられる。","気球は直径10mほど。材料は和紙で、それをこんにゃくのりで何枚もはり合わせました。作ったのは、学校から動員された女学生たちでした。劇場や大きなホールが工場になり、少女たちは何が作られているのかを知らされないまま、手を真っ赤にして紙をはりつづけたといいます。","放球基地は、太平洋に面した茨城県の大津、千葉県の一宮、そしてここ福島県の勿来などに置かれました。1944年の秋の終わりから翌年の春まで、何千もの気球が、夜明けの空へ向けて放たれていきました。«ほんとうにアメリカまで届くのか»。放った兵士たちにも、結果はわからなかったといいます。","実際に、一部の気球はアメリカやカナダにたどり着きました。1945年5月、アメリカ・オレゴン州の森で、ピクニックに来ていた女性と子どもたちが落ちていた気球にふれ、6人が亡くなりました。アメリカ本土で、戦争の攻撃によって民間人が亡くなった数少ない出来事とされています。","戦後、この悲しい出来事をきっかけに、日本とオレゴンの人々の間で交流が生まれ、風船爆弾を作った女性たちが謝罪と追悼の思いを込めた千羽鶴を送ったことも知られています。勿来の放球地跡の碑の前では、戦争の «見えない加害と被害» について、静かに考えたいものです。"],"tl":[["1944年","陸軍が風船爆弾の本格的な製造と放球の準備を進める"],["1944年11月","太平洋岸の基地から放球が始まる"],["1945年3〜4月","放球が終わる"],["1945年5月5日","アメリカ・オレゴン州で気球の爆発により6人が亡くなる"],["1945年8月","終戦"],["戦後","放球地跡に碑が建てられ、日米の交流も生まれる"]],"who":[["動員された女学生たち","和紙をはり合わせて気球をつくった"],["陸軍の兵士たち","基地で気球を放った"],["オレゴン州の犠牲者","ピクニック中に気球にふれて亡くなった女性と子どもたち"]],"deep":["日本上空の強い西風（のちにジェット気流と呼ばれる）は、大正から昭和の初めに気象学者の大石和三郎が観測していたことで知られます。風船爆弾はその知識を戦争に使ったものともいえます。","放たれた気球はおよそ9000個以上とされ、北米で見つかったものは数百とされます。どれだけが実際に届いたかは推定にとどまります。","アメリカ政府は、日本に効果を知らせないため、風船爆弾について報道を控えるよう求めたといわれます。そのため日本側は成果をほとんどつかめませんでした。","気球の高度を保つため、気圧を感じて砂袋を落とす自動の装置が工夫されていました。紙の気球に高度な仕組みを組み合わせた、ふしぎな兵器でした。","風船爆弾には、生物兵器を積む計画もあったといわれますが、実際には使われなかったとされます。戦争末期の兵器開発の危うさを物語る話として語られています。"],"look":["放球地跡の碑（周辺は住宅地や私有地もあるので配慮して見学）","近くの勿来の関跡（古代の関所の伝承地）","太平洋に面した勿来の地形（西風と海の近さ）"],"q":["風船爆弾の気球は、何でできていた？","和紙を、こんにゃくのりで何枚もはり合わせてつくられていました。"],"koji":[],"myth":"放球数・到達数は推定。碑の正確な位置・見学方法は現地で確認を。生物兵器計画の話は諸説。","img":["勿来の関","ジェット気流"],"wp":"風船爆弾","rel":{"ev":[],"grave":[]},"ph":[["c:5/52/Japanese_fire_balloon_Moffett.jpg",1377,1800,"風船爆弾"],["c:a/a1/Mitchell_Monument%3B_August_12%2C_2013.jpg",4368,2859],["c:9/9c/342-FH-3B23423_%2817973857089%29.jpg",2638,2160],["c:e/e5/%22Washi%22_%28Paper%29_of_Fire_ballon.jpg",998,1286],["c:d/d7/Minamoto_Yoshiie_at_the_Nakoso_barrier.jpg",1648,3587,"勿来の関"],["c:6/6b/Jetstreamconfig.jpg",336,193,"ジェット気流"]]},{"id":"07_bandaisan","n":"磐梯山（明治21年の大噴火）","yomi":"ばんだいさん","cat":"事件","rank":"A","y":1888,"era":["meiji"],"sh":"","ad":"耶麻郡北塩原村桧原（裏磐梯・磐梯山噴火記念館付近）","st":"JR磐越西線 猪苗代駅からバスで約30分（裏磐梯方面）","la":37.649,"lo":140.083,"hook":"ある夏の朝、山の一部がまるごと消えた。村をのみこんだ大災害は、美しい湖と沼を生み出した。","lead":"1888年（明治21年）7月15日の朝、磐梯山が大噴火し、北側の «小磐梯（こばんだい）» という峰がくずれ落ちました。大量の土砂が村々をうめ、477人が亡くなったとされます。このとき川がせき止められてできたのが、檜原湖や五色沼など «裏磐梯» の湖沼です。","story":["その日は、よく晴れた夏の朝だったといわれます。7時半を過ぎたころ、山が大きくゆれ、はげしい音とともに爆発がくり返されました。«山が…山がくずれてくる!» 北側の峰・小磐梯が吹き飛ばされるようにくずれ、岩や土砂が雪崩のようにふもとへかけ下りました。","くずれた土砂は、北のふもとにあった集落をのみこみ、多くの人の命をうばいました。畑で働いていた人、温泉に来ていた人、家にいた子どもたち。わずかな時間の出来事でした。噴火で亡くなった人は477人とされ、明治時代の日本で最大級の火山災害になりました。","このとき、日本赤十字社が医師や看護婦を送りこみ、けが人の手当てにあたりました。戦争のためにつくられた赤十字が、初めて行った大きな «災害救護» といわれます。また、学者たちが現地を調べ、写真や報告書を残しました。日本の近代的な火山研究のはじまりの一つでもあります。","土砂は川をせき止め、水がたまって大小たくさんの湖や沼ができました。檜原湖、小野川湖、秋元湖、そして青や緑に光る五色沼。«悲しい災害が、こんなに美しい景色を生んだの?» ——自然は、こわさと美しさの両方を持っています。噴火で荒れた土地には、のちに植林が進められ、今の豊かな森になりました。","いま裏磐梯の «磐梯山噴火記念館» では、噴火のしくみや当時の記録を学ぶことができます。北側から見ると、磐梯山には大きくえぐれた «馬てい形» のくぼみがはっきり見えます。美しい景色を楽しむときには、その下に今も眠る村々と人々のことも、少しだけ思い出してください。"],"tl":[["1888年7月15日","磐梯山が噴火し、小磐梯がくずれる。477人が亡くなったとされる"],["1888年","日本赤十字社が初めての災害救護活動を行う"],["1888年以降","学者による現地調査と報告が行われる"],["明治〜昭和","荒れ地への植林が進み、裏磐梯の森が育つ"],["1950年","磐梯朝日国立公園に指定"],["現在","磐梯山ジオパークとして学びの場に"]],"who":[["関谷清景","地震学者。噴火の調査にあたった"],["日本赤十字社の救護員","初の災害救護で被災者の手当てをした"],["遠藤十次郎（現夢）","裏磐梯の荒れ地に植林を進めた人物"],["被災した村人たち","噴火で命を落とし、また生き残って村を再建した人々"]],"deep":["磐梯山の噴火は、マグマそのものが噴き出したのではなく、地下の水が熱せられて爆発した «水蒸気爆発（水蒸気噴火）» だったと考えられています。山体の一部が崩れる «山体崩壊» の代表例として世界の教科書にも取り上げられます。","崩れた土砂が高速で流れ下る現象は «岩屑なだれ（がんせつなだれ）» と呼ばれます。磐梯山の噴火は、その研究でたびたび引かれる例です。","477人という死者数は広く使われる数字ですが、史料によって数え方に差があるともされます。","噴火のあと、報道や写真、版画などで災害のようすが全国に伝えられ、全国から義援金が集まりました。近代日本のメディアと災害報道のはじまりの一つともいえます。","遠藤十次郎（号・現夢）は、荒れ地となった裏磐梯に私財を投じて植林を行ったと伝わり、その緑が今の観光地・裏磐梯の土台になりました。"],"look":["磐梯山噴火記念館の展示","北側から見た磐梯山の «馬てい形» の崩れ跡","五色沼自然探勝路の沼めぐり","檜原湖に沈んだ集落の話を伝える場所（湖畔の案内など）"],"q":["磐梯山の噴火で、日本赤十字社が初めて行ったことは？","災害救護活動。けが人の手当てのために医師や看護婦を送りました。"],"koji":[],"myth":"死者数は史料により差があるとされる。植林の経緯は伝承的要素を含む。","img":["五色沼 (福島県)","檜原湖","裏磐梯"],"wp":"磐梯山","rel":{"ev":[],"grave":[]},"ph":[["c:6/62/Mt._Bandaisan_0811.JPG",3264,2448,"磐梯山"],["c:7/7b/%E7%A3%90%E6%A2%AF%E5%B1%B1%E3%81%8B%E3%82%89%E8%A3%8F%E7%A3%90%E6%A2%AF%E3%82%92%E6%9C%9B%E3%82%80.jpg",4608,3456],["c:6/6c/Nekoma_volcano_from_Mount_Bandai_2010.05.02.jpg",3456,2592],["c:8/84/Mount_Bandai2010.05.02.JPG",3456,2592],["c:9/9b/%E7%A3%90%E6%A2%AF%E5%B1%B1%E3%81%8B%E3%82%89%E7%8C%AA%E8%8B%97%E4%BB%A3%E6%B9%96%E3%82%92%E6%9C%9B%E3%82%80.jpg",3463,2309],["c:c/c0/Mount_Bandai_in_Autumn.jpg",2592,1944],["c:1/15/Bandaisan_funka_shinzu_by_Yamamoto_H%C5%8Dsui.jpg",1280,945],["c:1/19/Tankei_-_Eruption_of_Mount_Bandai.jpg",1000,504]]},{"id":"07_otaiyaba","n":"大安場古墳","yomi":"おおやすばこふん","cat":"遺跡","rank":"A","y":380,"era":["kofun"],"sh":"国指定史跡","ad":"郡山市田村町大善寺","st":"JR郡山駅から車で約20分","la":37.353,"lo":140.427,"hook":"«前も後ろも四角い» 大きなお墓。東北でいちばん大きな前方後方墳が、郡山の丘に眠っている。","lead":"大安場（おおやすば）古墳は、古墳時代の前期、4世紀後半ごろにつくられたと考えられる大きなお墓です。前も後ろも四角い «前方後方墳» という形で、長さは約83m。東北地方でいちばん大きな前方後方墳として、国の史跡に指定されています。","story":["郡山市の東、阿武隈川を見下ろす丘の上。ここに、長さ約83mもある大きな古墳があります。ふつう古墳といえば «前方後円墳»、前が四角で後ろが丸い形を思いうかべますよね。でも大安場古墳は、前も後ろも四角い «前方後方墳»。«どうして丸じゃないの?» それが、この古墳を知る手がかりになります。","前方後方墳は、古墳時代の始まりのころ、東日本に多くつくられた形です。前方後円墳がヤマト王権の中心の人々のお墓の形だとすると、前方後方墳は、それとは少しちがう系統の人々とかかわりがあったのではないか、という考えもあります。形のちがいは、つながりのちがいなのかもしれません。","発掘調査では、後方部の上から、木の棺をおさめた跡が見つかりました。そこからは鉄の剣や、石でつくった腕輪の形の品などが出てきました。«この地域の王は、遠くの権力者ともつながっていたのだろう»——出てきた品々が、そう語りかけてきます。","このお墓にほうむられたのは、阿武隈川流域を治めた有力な首長だったと考えられます。ただ、名前や生涯を伝える記録はありません。4世紀の東北に、これほど大きな墓をつくらせるほどの力を持った人がいた。そのこと自体が、古代の東北の姿を考えるうえで大切な発見なのです。","いま古墳は «大安場史跡公園» として整えられ、墳丘にのぼって形を確かめることができます。ガイダンス施設では出土品のレプリカや説明が見られ、古民家も移築されています。丘の上から阿武隈川の流れを見わたし、1600年前の王の気持ちになってみましょう。"],"tl":[["4世紀後半ごろ","大安場古墳がつくられたと考えられる"],["1990年代","調査で東北最大級の前方後方墳であることが確かめられる"],["発掘調査","後方部から木棺の跡、鉄剣や腕輪形の石製品などが出土"],["2000年ごろ","国の史跡に指定"],["現在","大安場史跡公園として整備・公開"]],"who":[["阿武隈川流域の首長","この古墳にほうむられたと考えられる地域の有力者。名前は不明"],["ヤマト王権","近畿を中心とした政治勢力。副葬品を通じたつながりが考えられる"],["調査にあたった研究者","発掘で古墳の形と年代を明らかにした"]],"deep":["«前方後方墳» は、弥生時代の終わりから古墳時代前期にかけて、東海地方や東日本に多く見られます。その広がりから、東海地方とのつながりを指摘する研究者もいます。","全長約83mという規模は東北の前方後方墳で最大とされ、同じ時代の東北の古墳の中でも有数の大きさです。","出土した腕輪形の石製品は、近畿地方で作られたと考えられる品で、ヤマト王権から地方の首長へ配られたものとみる説があります。東北でこうした品が出るのは貴重です。","古墳は丘陵の先端を利用してつくられ、阿武隈川の流れと周辺の平野を見わたせる位置にあります。«見せる墓» として、ながめのよい場所が選ばれたと考えられます。","郡山周辺には、同じころの古墳がほかにも点在し、阿武隈川流域が古墳時代の東北の重要な地域だったことがわかってきています。"],"look":["墳丘の上から見る «前も後ろも四角» の形","阿武隈川方面の眺め","ガイダンス施設の出土品レプリカと解説","公園内の移築古民家"],"q":["大安場古墳のような、前も後ろも四角い古墳を何という？","前方後方墳。大安場古墳は東北最大の前方後方墳です。"],"koji":[],"myth":"被葬者は不明。前方後方墳の系統や副葬品の配布の意味は諸説。史跡指定年は資料で確認を。","img":["前方後方墳","郡山市","古墳時代"],"wp":"大安場古墳","rel":{"ev":[],"grave":[]},"ph":[["c:9/96/Oyasuba_Kofun_Group-1%2C_funkyu.jpg",5568,3712,"大安場古墳"],["c:2/2a/Oyasuba_Kofun_Group-2%2C_funkyu.jpg",5568,3712],["c:0/0b/Shimosamuraizuka_Kofun_2.jpg",4608,3456,"前方後方墳"],["c:4/42/Koriyama_Montage.jpg",1024,1407,"郡山市"]]},{"id":"07_kiyotosaku","n":"清戸迫横穴（装飾横穴）","yomi":"きよとさくよこあな","cat":"遺跡","rank":"A","y":650,"era":["kofun","asuka"],"sh":"国指定史跡","ad":"双葉郡双葉町新山","st":"JR常磐線 双葉駅から歩いて約15分（横穴の内部は非公開）","la":37.448,"lo":141.008,"hook":"岩のかべに赤い渦巻きと人と馬。1300年以上前の «えがかれた墓» が、双葉の丘に眠る。","lead":"清戸迫（きよとさく）横穴は、7世紀ごろに丘の斜面をほってつくられたお墓の集まりです。その中の一つに、赤い顔料で大きな渦巻きや人物、馬などがえがかれた «装飾横穴» があり、国の史跡に指定されています。壁画を守るため、内部はふだん公開されていません。","story":["1967年、双葉町の丘で工事をしていたとき、斜面にぽっかりと穴があいているのが見つかりました。中をのぞいた人たちは息をのみました。奥のかべに、赤い色で大きな渦巻きがえがかれていたのです。«これは、ただの穴じゃない!»","調べてみると、そこは7世紀ごろのお墓でした。古墳時代の終わりから飛鳥時代にかけて、東北南部の太平洋側では、丘の斜面に横穴をほってお墓にすることがよく行われました。清戸迫には、そうした横穴がたくさん集まっていて、そのうちの一つに絵がえがかれていたのです。","えがかれているのは、大きな渦巻きの模様、両手を広げたような人物、馬に乗った人、動物など。«この渦巻きは太陽? それとも魂?» ——意味ははっきりわかっていません。死んだ人の魂が安らかに旅立てるように、あるいは生きていたころの狩りや暮らしをえがいたのか。見る人の想像をかきたてる絵です。","装飾のある墓は、九州北部に多く見られ、東日本では福島県や茨城県の太平洋側に集中しています。«なぜ遠く離れた九州と、この地域に?» 人の移動や文化の伝わり方を考えるうえで、清戸迫横穴はとても大切な手がかりです。","2011年の東京電力福島第一原子力発電所の事故で、双葉町は長く人が住めない町になりました。清戸迫横穴も、しばらく人の立ち入りが難しい場所にありました。いまは町に人が戻りはじめ、文化財を守り伝える取り組みも続いています。1300年前の人々の祈りを、未来へつなぐために。"],"tl":[["7世紀ごろ","横穴墓がつくられ、一つに壁画がえがかれる"],["1967年","工事中に装飾のある横穴が見つかる"],["1968年","国の史跡に指定"],["2011年","原発事故により双葉町の全域が避難区域となる"],["2022年","双葉町の一部で避難指示が解除され、住民の帰還が始まる"]],"who":[["横穴に葬られた人々","7世紀ごろのこの地域の有力者やその一族と考えられる"],["壁画をえがいた人","赤い顔料で渦巻きや人物をえがいた。名前は不明"],["双葉町の人々","発見から今まで、横穴を守り伝えてきた"]],"deep":["壁画は、ベンガラ（酸化鉄）などの赤い顔料でえがかれたと考えられています。大きな渦巻き文は、横穴の奥壁の中心に大きくえがかれているのが特徴です。","福島県内には、中通りの泉崎村にある «泉崎横穴»（国史跡）など、ほかにも装飾横穴があります。同じ時期・同じ地域の横穴をくらべることで、地域のつながりが見えてきます。","装飾横穴の壁画は、空気や湿度、光の変化にとても弱く、見つかったあとに色が薄れてしまう例もあります。そのため、多くは保存施設で管理され、一般公開はかぎられています。","«渦巻き» の意味については、太陽、魂、再生、水など、さまざまな説があり、決め手はありません。人物や馬の絵は、狩りや儀式の場面とみる考えもあります。","原発事故のあと、双葉町では文化財の状態確認や保全が課題になりました。被災地の文化財を守る活動は、ふるさとの記憶を守る活動でもあります。"],"look":["横穴群がある丘の地形（外から見学できる範囲を確認）","双葉町の案内板や展示で紹介される壁画の写真・複製","あわせて訪ねたい東日本大震災・原子力災害伝承館"],"q":["清戸迫横穴の壁画で、奥のかべの中心に大きくえがかれている模様は？","赤い渦巻きの模様。意味には太陽、魂など諸説があります。"],"koji":[],"myth":"壁画の意味は諸説。見学方法・公開状況は双葉町に確認を。","img":["装飾古墳","双葉町","横穴墓"],"wp":"清戸迫横穴","rel":{"ev":[],"grave":[]},"ph":[["c:3/34/Kiyotosaku_aero_1975.jpg",1089,1121,"清戸迫横穴"],["j:7/72/%E7%8E%8B%E5%A1%9A%E5%8F%A4%E5%A2%B3_%28%E6%A1%82%E5%B7%9D%E7%94%BA%29_%E7%9F%B3%E5%AE%A4%E3%83%AC%E3%83%97%E3%83%AA%E3%82%AB.JPG",5502,3665,"装飾古墳"],["c:6/6a/%E6%9D%B1%E6%97%A5%E6%9C%AC%E5%A4%A7%E9%9C%87%E7%81%BD%E3%83%BB%E5%8E%9F%E5%AD%90%E5%8A%9B%E7%81%BD%E5%AE%B3%E4%BC%9D%E6%89%BF%E9%A4%A8.jpg",4000,2667,"双葉町"],["j:1/18/Yoshimi_Yoshimi-hyakuana_2.JPG",3264,2448,"横穴墓"]]},{"id":"07_miyahata","n":"宮畑遺跡（じょーもぴあ宮畑）","yomi":"みやはたいせき","cat":"遺跡","rank":"A","y":-2500,"era":["jomon"],"sh":"国指定史跡","ad":"福島市岡島","st":"JR福島駅から車で約15分","la":37.779,"lo":140.5,"hook":"縄文の人は、なぜ自分たちの家に火をつけたのか。燃えた家と巨大な柱のあとが語る、4000年前のなぞ。","lead":"宮畑遺跡は、縄文時代の中ごろから終わりごろにかけて人々が暮らした村の跡です。わざと燃やしたと考えられる家の跡がたくさん見つかり、また、とても太い柱を立てた大きな建物の跡もあります。国の史跡で、今は «じょーもぴあ宮畑» として公開されています。","story":["福島市の東の田園地帯。ここに、縄文の人々の村がありました。発掘してみると、家の跡の床から、焼けた柱や屋根の材料が次々に見つかりました。«火事があったのかな?» と思いますよね。ところが、あまりにも多くの家が燃えていて、しかもその燃え方にふしぎなところがあったのです。","研究者たちは考えました。«これは、たまたまの火事ではなく、人がわざと家を燃やしたのではないか»。家に住んでいた人が亡くなったとき、あるいは村をうつすときに、家を燃やして送る儀式があったのかもしれません。実際に復元した家を燃やしてみる実験も行われ、燃え方がくらべられました。","さらに縄文時代の終わりごろの地層からは、直径1mちかい巨大な柱の穴が見つかりました。太い柱を何本も立てた、大きな掘立柱の建物があったと考えられます。«そんな大きな建物を、何のために?» 集会所か、祭りの場か。青森の三内丸山遺跡の大型建物とくらべられることもあります。","村の人々は、土器や石器を作り、木の実を集め、動物をとって暮らしていました。土偶などの祈りの道具も見つかっていて、自然とともに生き、命や死にていねいに向き合っていた人々のすがたが浮かんできます。","いま遺跡は «じょーもぴあ宮畑» として整えられ、復元された家や柱、出土品の展示を見ることができます。土器づくりなどの体験もできます。燃やされた家の跡の前に立って、«私たちは、何を送り、何を残すのだろう» と考えてみるのも、縄文の村の楽しみ方です。"],"tl":[["約4500年前（縄文時代中期）","村がつくられ、多くの家が燃やされる"],["約3000年前（縄文時代晩期）","巨大な柱を持つ掘立柱建物がつくられる"],["1990年代","発掘調査で遺跡の重要性が明らかになる"],["2003年","国の史跡に指定"],["2015年","史跡公園 «じょーもぴあ宮畑» が開園"]],"who":[["縄文時代の村人","この村で暮らし、家を燃やす儀式を行ったと考えられる人々"],["福島市の調査員・研究者","発掘や家を燃やす実験で、遺跡のなぞにいどんだ"],["地域の人々","遺跡公園の運営や体験活動を支える"]],"deep":["«焼失住居» の多くが、意図的に燃やされたと考えられている点が宮畑遺跡の大きな特徴です。家の上に土をかけてから燃やしたとみられる例もあり、儀礼説が有力ですが、決め手はありません。","復元住居を実際に燃やす «焼失実験» が行われ、炭化材の残り方や床の焼け方が発掘の結果とくらべられました。実験考古学の取り組みとして注目されました。","縄文晩期の掘立柱建物の柱穴は非常に大きく、柱の直径は1mちかいと推定されます。東北の縄文時代の大型建物の例として重要です。","縄文時代中期と晩期の二つの時期に、ちがう性格の遺構が見つかっている点も興味深く、同じ場所が長い時間をかけて使われつづけたことがわかります。","福島盆地には、ほかにも縄文時代の遺跡が多く、阿武隈川の水と山の恵みが人々の暮らしを支えていたと考えられます。"],"look":["復元された縄文の家と、燃やされた家の跡の展示","巨大な柱の復元","体験学習館の出土品展示","土器づくりなどの体験（予約制の場合あり）"],"q":["宮畑遺跡でたくさん見つかった、ふしぎな家の跡とは？","わざと燃やしたと考えられる «焼失住居»。儀式のためという説があります。"],"koji":[],"myth":"家を燃やした理由は諸説。年代は推定。","img":["縄文時代","竪穴建物","掘立柱建物"],"wp":"宮畑遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:0/0b/Miyahata_Site.jpg",1600,1200,"宮畑遺跡"],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:5/5a/Yoshinogari-iseki_tateanashiki-juukyo.JPG",6016,4000,"竪穴建物"],["c:b/b4/%E4%B8%89%E5%86%85%E4%B8%B8%E5%B1%B1%E9%81%BA%E8%B7%A1%E6%8E%98%E7%AB%8B%E6%9F%B1%E5%BB%BA%E7%89%A9.JPG",3888,2592,"掘立柱建物"]]},{"id":"07_izumi_kanga","n":"泉官衙遺跡（行方郡家）","yomi":"いずみかんがいせき","cat":"遺跡","rank":"A","y":700,"era":["asuka","nara","heian"],"sh":"国指定史跡","ad":"南相馬市原町区泉","st":"JR常磐線 原ノ町駅から車で約10分","la":37.656,"lo":140.98,"hook":"都から遠く離れた海辺の町に、古代の «市役所» と «米の倉庫群» があった。奈良時代の役人たちの仕事場。","lead":"泉官衙（かんが）遺跡は、奈良時代を中心に、陸奥国の «行方（なめかた）郡» を治める役所「郡家（ぐうけ）」があった場所です。役人が仕事をした建物や、税として集めた米をしまう倉庫が並んでいました。7世紀後半から10世紀前半ごろまで使われたと考えられ、国の史跡に指定されています。","story":["飛鳥時代の終わりから奈良時代にかけて、日本は «律令» という決まりにもとづいて国を治める仕組みをつくりました。全国を国・郡・里（郷）に分け、それぞれに役所を置いたのです。陸奥国の南の太平洋側、今の南相馬のあたりは «行方郡» と呼ばれ、その役所がここ泉に置かれました。","発掘された跡から、役所の中心の «郡庁»、たくさんの倉が並ぶ «正倉»、役人やお客が泊まる建物などの配置がわかってきました。正倉には、人々が税として納めた稲がぎっしりしまわれていました。倉の跡からは、焼けて黒くなった米の粒が見つかることもあります。«火事で燃えてしまったのかな?»","この郡家は、川の近くにありました。米や品物を船で運ぶのに便利だったからだと考えられます。近くには、同じころの鉄をつくった跡も見つかっていて、この地域が鉄の生産でも大切な場所だったことがわかってきました。古代の東北の開発と、そこで働いた人々のすがたが見えてきます。","この遺跡からは古い瓦も出ていて、かつては «お寺の跡» と考えられ、«泉廃寺跡» と呼ばれていました。調べが進むにつれ、じつは郡の役所だったとわかってきたのです。都から来た役人と、地元の有力者が力をあわせて郡を治めていたのでしょう。«遠い都の決まりを、この海辺の町でどうやって守らせたのか»。そんな疑問をいだきながら遺跡を歩くと、古代の役所の苦労が想像できます。","遺跡はいま、建物の跡が平面表示されるなどして整備が進み、古代の役所の広がりを体で感じることができます。東日本大震災と原発事故をこえて、南相馬の人々が守り伝える古代の記憶です。"],"tl":[["7世紀後半","郡の役所がつくられ始める"],["8世紀（奈良時代）","行方郡家として整えられ、郡庁や正倉が並ぶ"],["9世紀","役所の建物がつくりかえられながら使われる"],["10世紀前半ごろ","役所としての役目を終える"],["2010年","国の史跡に指定"]],"who":[["行方郡の郡司","郡を治めた地元の有力者。役所の長として税や人々の管理を行った"],["国司","陸奥国の国府（多賀城）から派遣された役人"],["郡の人々","税として稲を納め、役所や倉を支えた"]],"deep":["郡家は «郡衙（ぐんが）» とも呼ばれ、郡庁院・正倉院・館（たち）などからなるのが基本の形です。泉官衙遺跡ではそれらの区画がそろって見つかっており、東北の郡家の姿を知る代表例とされます。","正倉からは炭化米が出ることがあり、倉が火災にあったことを示しています。古代の史料には «神火» と呼ばれる倉の火災の記事があり、各地の郡家で倉が焼けた事件が知られています。","近くには、古代の製鉄遺跡がまとまって見つかっており、行方郡が鉄の生産地として重要だったことがわかります。東北での戦いや開発を支えた鉄との関係も考えられています。","«行方» の郡名は、のちの相馬地方の歴史にも受けつがれました。中世の相馬氏も、この行方郡を本拠の一つにしています。","郡家が川の近くに置かれたのは、船で税の稲などを運ぶためとみられ、水運と役所の結びつきを示す例として注目されています。"],"look":["郡庁や正倉の跡の平面表示","遺跡から見る新田川方面の地形","瓦が出たことから «寺の跡» と考えられた時代の説明板","南相馬市博物館の展示（出土品と解説）"],"q":["泉官衙遺跡にあった «郡家（ぐうけ）» とは何？","奈良時代などに郡を治めた役所。役人の建物や税の稲をしまう倉が並んでいました。"],"koji":[],"myth":"役所の始まりと終わりの年代は推定。炭化米の出土状況や瓦葺き建物の性格は資料で確認を。","img":["郡衙","律令制","陸奥国"],"wp":"泉官衙遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:5/50/JR_J%C5%8Dban_Line_Haranomachi_Station_building.jpg",4161,2949,"近く: 原ノ町駅"],["c:c/c7/The_Soma_Nomaoi_2005-6.jpg",1280,960,"近く: 原町市"],["c:a/a0/Minamisoma_Police_station.jpg",1920,1080,"近く: 南相馬警察署"],["c:d/d5/Michinoekiminamisoma.JPG",1280,719,"近く: 道の駅南相馬"],["c:f/fa/Minamisoma_Civic_Hall.jpg",1600,899,"近く: 南相馬市民文化会館"]]},{"id":"07_iouji","n":"医王寺（佐藤継信・忠信の墓）","yomi":"いおうじ","cat":"墓所","rank":"A","y":1189,"era":["heian","kamakura","edo"],"sh":"","ad":"福島市飯坂町平野字寺前","st":"福島交通飯坂線・医王寺前駅から歩いて約15分","la":37.8226,"lo":140.4411,"hook":"源義経のために命をささげた佐藤兄弟。そのふるさとの寺には、帰らぬ息子を待つ母の涙が «咲かない椿» になって残るという。","lead":"医王寺は、平安時代の終わりに信夫（しのぶ）地方をおさめた佐藤氏の菩提寺です。境内には、源義経の家来として戦い、若くして亡くなった佐藤継信・忠信兄弟の墓と伝わる古い石碑があります。松尾芭蕉も «奥の細道» の旅でここに立ち寄りました。","story":["平安時代の終わり、奥州（東北地方）は平泉の藤原秀衡がおさめていました。いまの福島市のあたり «信夫の荘» をまかされていたのが佐藤基治（もとはる）です。飯坂の丘の上に館をかまえ、藤原氏とも親せき関係で結ばれた有力な武士でした。その基治の息子が、兄の継信（つぐのぶ）と弟の忠信（ただのぶ）です。","1180年、兄・頼朝の挙兵を知った源義経は、平泉から駆けつけようとします。そのとき秀衡がつけた家来が佐藤兄弟でした。«義経どのを守り抜け» ――父や母はそう言って送り出したと伝わります。二人はそのまま、平家との長い戦いに身を投じることになりました。","1185年、四国の屋島の戦い。『平家物語』によると、平家一の弓の名手・平教経が義経をねらって矢を放ったとき、継信が主君の前に立ちはだかり、身代わりに射抜かれました。義経は «だれか僧を呼べ» と、自分の名馬を寺に与えて弔わせたといいます。弟の忠信も、のちに頼朝と対立した義経を逃がすために奮戦し、京都で命を落としました。","ふるさとで兄弟の帰りを待っていたのが、母の乙和（おとわ）御前です。息子二人を失った悲しみで、すっかり弱ってしまいました。そこで兄弟の妻、若桜（わかざくら）と楓（かえで）が、夫のよろいを身につけて «ただいま帰りました» と母の前に立ち、なぐさめたと伝わります。本堂にはその二人の姿の人形がまつられています。","薬師堂の裏には «乙和の椿» と呼ばれる椿があります。母の悲しみが乗りうつったのか、つぼみのまま花を開かずに落ちてしまう――そんな言い伝えがあります。なぜ人びとはこんな話を語りついだのでしょう? 勝った頼朝ではなく、負けた義経と、その義経に尽くした家来たちに心を寄せる «判官びいき» の気持ちが、この寺には色濃く流れているのです。","1689年、松尾芭蕉と弟子の曾良がこの寺を訪れました。寺で義経の太刀や弁慶の笈（おい・旅の道具箱）を見た芭蕉は、«笈も太刀も五月にかざれ紙幟» と詠みました。端午の節句の季節、兄弟の忠義をしのぶ一句です。"],"tl":[["826年","空海が開いたと寺の縁起は伝える"],["1180年","佐藤継信・忠信が義経にしたがい平泉を出る"],["1185年","屋島の戦いで継信が義経の身代わりとなって討死（『平家物語』）"],["1186年","忠信が京都で追っ手に囲まれ自害（『吾妻鏡』）"],["1189年","奥州合戦。佐藤基治が石那坂で頼朝軍と戦う"],["1689年","松尾芭蕉と曾良が訪れる（『奥の細道』）"]],"who":[["佐藤基治","信夫の荘をおさめた武士。この寺を菩提寺とした"],["佐藤継信","兄。屋島の戦いで義経の身代わりに討死"],["佐藤忠信","弟。義経の逃避行を助け、京都で最期をとげた"],["乙和御前","兄弟の母。悲しみの伝説が «乙和の椿» に残る"],["源義経","兄弟が命をかけて仕えた主君"],["松尾芭蕉","『奥の細道』の旅で立ち寄り、句を詠んだ"]],"deep":["兄弟の墓とされるのは、平たい石に文字や梵字を刻んだ «板碑（いたび）» です。板碑は鎌倉時代以降に広まったもので、兄弟の没年と同じころに作られたかどうかは確かめられていません。境内には鎌倉期の板碑がほかにも残ります。","宝物殿 «瑠璃光殿» には、弁慶が寄進したと伝わる笈が展示され、福島県の文化財になっています。芭蕉が見たという «義経の太刀» の話とあわせて、実物と伝承の距離を考えるのも面白い点です。","基治は1189年の奥州合戦で、石那坂（いしなざか）で頼朝軍を迎え撃ちました。『吾妻鏡』には敗れたことが記されますが、その後の基治の運命は «処刑された»«許されて帰った» など諸説あります。","よろい姿で母をなぐさめる二人の嫁の話は、宮城県白石市の田村神社（甲冑堂）にも伝わり、そこには二人の像がまつられています。同じ物語が県境をこえて語られているのです。","芭蕉は『奥の細道』で、佐藤庄司の旧跡や丸山（大鳥城跡）もたずねたことを記しています。医王寺と大鳥城跡は近く、あわせて歩くと佐藤氏の本拠地の広がりがよくわかります。"],"look":["参道の奥、杉木立の中にたたずむ佐藤一族の墓（板碑）","宝物殿 «瑠璃光殿» の弁慶の笈と、兄弟ゆかりの品","本堂の、よろい姿の二人の嫁の人形","薬師堂裏の «乙和の椿»","芭蕉の句碑"],"q":["佐藤兄弟の母をなぐさめるため、兄弟の妻たちはどんなことをしたと伝わる?","夫のよろいを着て、兄弟が帰ってきたように見せたと伝わります。"],"koji":[{"w":"判官びいき","m":"弱い立場の人や、負けた側に同情し、応援したくなる気持ち。九郎判官と呼ばれた源義経から生まれたことば"}],"myth":"空海の開山、兄弟の墓、弁慶の笈、乙和の椿、嫁のよろい姿の話は伝承。基治の最期は諸説。","img":["佐藤継信","佐藤忠信","源義経","奥の細道"],"wp":"医王寺 (福島市)","rel":{"ev":[],"grave":[]},"ph":[["c:2/27/Yakushidou_Iouji_%28Fukushima%29.JPG",3523,2730,"医王寺 (福島市)"],["c:4/41/Sato_Tsuginobu.jpg",282,283,"佐藤継信"],["c:9/94/Satou_Tadanobu.jpg",1194,1146,"佐藤忠信"],["c:7/7d/Minamoto_no_Yoshitsune.jpg",1440,1724,"源義経"]]},{"id":"07_kurozuka","n":"安達ヶ原の黒塚（鬼婆伝説）","yomi":"あだちがはらのくろづか","cat":"伝承","rank":"A","y":726,"era":["nara","heian","edo"],"sh":"","ad":"二本松市安達ケ原","st":"JR東北本線・二本松駅から車で約10分","la":37.5943,"lo":140.462,"hook":"«安達ヶ原の鬼婆» ――旅人を泊めては食らったという恐ろしい老婆。その墓と伝わる塚が、阿武隈川のほとりに今もある。","lead":"黒塚は、昔話や能で有名な «安達ヶ原の鬼婆» が葬られたと伝わる塚です。近くの観世寺（かんぜじ）には、鬼婆が住んだという岩屋や大きな岩が残ります。平安時代の和歌にもよまれ、松尾芭蕉も見物に来た、東北きっての伝説の地です。","story":["むかし、京の都のある屋敷に «岩手» という乳母がいました。お世話をしていた姫が、生まれつき口がきけない病でした。占い師は言います。«妊婦のおなかの子の生き肝を飲ませれば治るでしょう»。岩手は、小さな娘を都に残して生き肝を探す旅に出て、はるばるみちのくの安達ヶ原までたどり着きました。","何年も岩屋で待ち続けたある晩、若い夫婦が宿を求めてきました。妻は身ごもっていて、急に産気づきます。夫が薬を買いに出たすきに、岩手は包丁をふるいました。ところが、女が身につけていたお守りを見て、岩手はこおりつきます。それは、都に残してきた自分の娘に持たせたものでした。――あまりのことに岩手は心をこわし、その後、旅人をおそう鬼婆になったと伝わります。","時がたち、紀州・熊野から来た僧の東光坊祐慶（ゆうけい）が、この岩屋に一夜の宿をとりました。«奥の部屋だけは、決してのぞかないでくだされ»。そう言われると、見たくなるのが人の心です。祐慶がそっとのぞくと、そこには人の骨が山のように積まれていました。","逃げる祐慶、追う鬼婆。追いつかれそうになったとき、祐慶が背負っていた如意輪観音の像を取り出して祈ると、観音は空にのぼり、白い真弓（まゆみ）の矢で鬼婆を射たといいます。祐慶は鬼婆を阿武隈川のほとりに葬りました。それが «黒塚» だと伝えられています。観世寺の山号 «白真弓山» は、この話から来ているといわれます。","なぜ、この話はこれほど広まったのでしょう? 平安時代、平兼盛が «みちのくの安達の原の黒塚に鬼こもれりと言ふはまことか» とよみました。本来は、ここに住んでいた女性たちを冗談まじりに «鬼» にたとえた歌だったとされますが、やがて本物の鬼の話と結びついていきます。能 «安達原»（観世流では «黒塚»）でも演じられ、日本中に知られる物語になりました。"],"tl":[["平安時代中ごろ","平兼盛が «安達の原の黒塚» の歌をよむ（『拾遺和歌集』などに収録）"],["726年","東光坊祐慶が鬼婆を退治したと伝わる年"],["室町時代","能 «安達原（黒塚）» が成立したとされる"],["1689年","松尾芭蕉が黒塚の岩屋を見物する（『奥の細道』）"],["現在","観世寺の境内で岩屋や笠石を見学でき、近くに «安達ヶ原ふるさと村» がある"]],"who":[["岩手（鬼婆）","京から来た乳母が、悲劇の末に鬼婆になったと伝わる"],["東光坊祐慶","熊野の僧。鬼婆を退治したと伝わる"],["平兼盛","平安時代の歌人。黒塚の鬼を歌によんだ"],["松尾芭蕉","『奥の細道』の旅で岩屋を見物した"]],"deep":["平兼盛の歌は『大和物語』にも出てきます。そこでは、黒塚に住んでいた源重之の妹たちに向けた、からかい半分の歌として語られます。«鬼» が «美しい女性を隠している家» のたとえだったのに、のちに人食い鬼の話へ変わっていったという見方があります。","『奥の細道』には «二本松より右に切れて、黒塚の岩屋一見し、福島に宿る» とあり、芭蕉は寄り道して立ち寄ったことがわかります。短い一文ですが、江戸時代にはすでに見物の名所だったことを示しています。","観世寺の境内には «笠石» «出刃洗いの池» «鬼婆の岩屋» など、伝説にちなむ岩や池がならびます。大きな岩が重なる地形そのものが、物語のイメージをふくらませたのかもしれません。","能では観世流だけが曲名を «黒塚» とし、ほかの流派は «安達原» と呼びます。歌舞伎や日本画の題材にもなりました。","鬼婆退治を726年（神亀3年）とするのは寺の縁起の伝承です。一方、祐慶（宥慶）は平安時代後期の実在の僧とされ、1163年に亡くなったと伝わるため、年代が合いません。«京の乳母» の話も、まだ平安京がない時代の設定で、後からつくられた由来話とみられています。","正岡子規もこの寺を訪れ、«涼しさや聞けばむかしは鬼の塚» とよみました。芭蕉から約200年後も、黒塚は旅人の心をひきつける場所だったのです。"],"look":["観世寺境内の «鬼婆の岩屋» と巨岩 «笠石»","阿武隈川近くの «黒塚»（鬼婆の墓と伝わる塚）と、その脇の杉","平兼盛の歌碑や芭蕉ゆかりの碑","近くの «安達ヶ原ふるさと村»（観光施設）"],"q":["鬼婆を退治した僧・祐慶が祈った仏さまは?","如意輪観音。空にのぼって白真弓の矢で鬼婆を射たと伝わります。"],"koji":[{"w":"みちのくの安達の原の黒塚に鬼こもれりと言ふはまことか","m":"平兼盛の歌。«安達ヶ原の黒塚に鬼がこもっているというのは本当か» という意味"}],"myth":"鬼婆の物語、726年の退治、岩屋・塚が鬼婆の住まいや墓であることはすべて伝承。","img":["安達原","観世寺","平兼盛","二本松市"],"wp":"黒塚","rel":{"ev":[],"grave":[]},"ph":[["c:0/08/SekienKurozuka.jpg",384,493,"黒塚"],["c:3/3a/Kuroduka.jpg",2448,3264],["c:7/7c/Adachigahara_%E5%AE%89%E9%81%94%E5%8E%9F_-_N%C5%8Dgaku_hyakuban_%E8%83%BD%E6%A8%82%E7%99%BE%E7%95%AA_-_Tsukioka_K%C5%8Dgyo_%E6%9C%88%E5%B2%A1%E8%80%95%E6%BC%81_%28Art_Institute_of_Chicago%29.jpg",2042,3000,"安達原"],["c:d/d6/Sanj%C5%ABrokkasen-gaku_-_24_-_Kan%C5%8D_Naonobu_-_Taira_no_Kanemori.jpg",450,640,"平兼盛"],["c:3/34/Nihonmatsu_Castle_Minowa_Gate_20100625-01.jpg",5184,3456,"二本松市"]]},{"id":"07_sukagawa_jo","n":"須賀川城跡（二階堂氏の滅亡）","yomi":"すかがわじょうあと","cat":"城","rank":"A","y":1589,"era":["muromachi","azuchi"],"sh":"","ad":"須賀川市諏訪町（二階堂神社付近）","st":"JR東北本線・須賀川駅から歩いて約25分、またはバス","la":37.2896,"lo":140.3744,"hook":"甥の伊達政宗に «降参せよ» と迫られた城の女主人。彼女は首を横に振り、名門二階堂氏は炎の中に消えた。","lead":"須賀川城は、鎌倉幕府の重臣の家から始まった名門・二階堂氏が、室町時代から戦国時代までおさめた城です。1589年、伊達政宗に攻められて落城し、二階堂氏はほろびました。今は町なかに二階堂神社などが残るだけですが、秋の火祭り «松明あかし» にその記憶が受けつがれています。","story":["二階堂氏は、鎌倉幕府で政所（まんどころ）という役所の役人をつとめた家がらです。その一族が陸奥国の岩瀬郡をまかされ、室町時代にこの須賀川に城をかまえました。軍記物によれば、最初の築城は1399年、のちに文安年間（1440年代）に二階堂為氏が城主になったといいます。まわりには伊達・蘆名・佐竹・田村といった強い大名がひしめいていて、二階堂氏は親せき関係を結びながら、なんとか生きのびていました。","城主の二階堂盛義は、伊達晴宗の娘・阿南（おなみ）姫を妻にむかえました。阿南姫は、伊達政宗から見ると叔母にあたります。ところが盛義が亡くなり、あとをついだ息子も若くして亡くなってしまいます。城に残ったのは、夫と子を失った阿南姫。出家して «大乗院» と名のり、城主となりました。実務は城代の須田盛秀が支えましたが、家臣たちは «佐竹と組むべきだ» という須田派と、«伊達と手を結ぶべきだ» という保土原（ほどはら）行藤の派に割れていきます。","1589年、摺上原の戦いで蘆名氏を破った政宗は、勢いに乗って南へ進みます。«叔母上、城を明け渡してください»。政宗は降伏をすすめたと伝わります。しかし大乗院は応じませんでした。«二階堂の家を、甥にゆずりわたすわけにはいかない»――そんな気持ちだったのでしょうか。","1589年10月26日、伊達軍が須賀川城に攻めかかりました。伊達方に通じた保土原派が道案内をし、釈迦堂川の南岸で激しい戦いになります。二階堂氏の菩提寺・長禄寺に火が放たれ、その火は本丸にまで燃え広がったといいます。こうして須賀川の二階堂氏はほろびました。大乗院は、妹が嫁いでいた佐竹家のもとへ落ちのびたと伝わります。","須賀川では毎年11月、«松明あかし» という火祭りが行われます。高さ10mもの大たいまつに次々と火がともり、夜空をこがします。この祭りは、落城のときに亡くなった人びとを弔うために始まったと伝えられています。炎を見上げながら、400年以上前の秋の夜を想像してみてください。"],"tl":[["1399年","二階堂行続が須賀川城を築いたと軍記物（『藤葉栄衰記』）は伝える"],["1440年代","二階堂為氏が城主となり、岩瀬郡を支配"],["1581年","城主・二階堂盛義が亡くなる"],["1584年ごろ","跡つぎの行親が若くして亡くなり、大乗院（阿南姫）が城をまとめる"],["1589年6月","摺上原の戦い。伊達政宗が蘆名氏を破る"],["1589年10月26日","伊達軍の攻撃で須賀川城が落城。二階堂氏ほろぶ"],["1627年ごろ","会津藩主が加藤嘉明に代わったあと廃城"],["現在","毎年11月に «松明あかし» が行われる"]],"who":[["大乗院（阿南姫）","伊達晴宗の娘で、政宗の叔母。夫と子の死後、城を守った"],["二階堂盛義","須賀川城主。大乗院の夫"],["伊達政宗","甥でありながら城を攻め落とした"],["蘆名盛隆","盛義の子。人質として会津へ行き、のちに蘆名家の当主になった"]],"deep":["盛義の子・盛隆は、人質として会津の蘆名氏に送られましたが、のちに蘆名家をつぐ当主になりました。二階堂家の子が大名蘆名家の主になるという、戦国らしい意外なつながりです。","落城のとき城を守っていたのは、須田氏や援軍の佐竹勢など約600人だったといわれます。落城後、政宗は一族の石川昭光に城を与えましたが、翌年の豊臣秀吉の奥州仕置で須賀川は蒲生氏郷の領地となりました。","城は平らな町のなかにあったため、町づくりが進んだ今は遺構がほとんど残っていません。«跡» として神社や地名に面影を探す楽しみ方になります。","天正年間の様子を描いたとされる絵図では、本丸を中心に二の丸・三の丸が水堀に囲まれ、西に長禄寺や諏訪明神などの寺社、北に職人の町が配置されていました。城は釈迦堂川を見下ろす高さ約20mの台地の上にありました。","«松明あかし» は、日本三大火祭りの一つと紹介されることもあります。起源を落城の供養とする説は地元の伝承として大切に語りつがれています。"],"look":["城の本丸があったとされる場所にたつ二階堂神社","二階堂氏の菩提寺・長禄寺","須賀川の町に残る城下町の道すじ","11月の «松明あかし» の会場・五老山"],"q":["須賀川城を守った大乗院（阿南姫）と伊達政宗の関係は?","叔母とおい。大乗院は政宗の父・輝宗の妹にあたります。"],"koji":[],"myth":"築城年は軍記物による。大乗院が落ちのびた先の話、松明あかしの起源は伝承。","img":["二階堂氏","阿南姫","伊達政宗","松明あかし"],"wp":"須賀川城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:1/19/MASAMUNE777.PNG",533,394,"伊達政宗"],["c:6/67/Kuriyasawa%2C_Sukagawa%2C_Fukushima_Prefecture_962-0866%2C_Japan_-_panoramio.jpg",5202,3465,"松明あかし"]]},{"id":"07_inawashiro_jo","n":"猪苗代城（亀ヶ城）","yomi":"いなわしろじょう（かめがじょう）","cat":"城","rank":"A","y":1589,"era":["kamakura","azuchi","edo"],"sh":"県指定史跡","ad":"耶麻郡猪苗代町古城町","st":"JR磐越西線・猪苗代駅から歩いて約25分","la":37.562,"lo":140.1039,"hook":"城主のたった一度の «寝返り» が、会津の名門・蘆名氏をほろぼした。磐梯山を見上げる丘の城には、会津の運命を変えた物語がある。","lead":"猪苗代城は «亀ヶ城» とも呼ばれ、鎌倉時代に猪苗代氏が築いたと伝わる城です。戦国時代の終わり、城主が伊達政宗に味方したことで蘆名氏はほろびました。江戸時代には会津藩の «もう一つの城» として守られ、戊辰戦争で焼かれました。今は石垣や土塁の残る公園になっています。","story":["猪苗代湖の北、磐梯山のふもと。小高い丘の上に猪苗代城はあります。城を築いたのは、鎌倉時代に会津に入った三浦一族の流れをくむ猪苗代氏と伝わります。猪苗代氏は会津の大名・蘆名氏と同じ一族でしたが、ときに蘆名氏とぶつかる、なかなか気の強い家でした。","1589年。伊達政宗は会津をねらっていました。そのとき政宗の誘いにこたえたのが、猪苗代城主の猪苗代盛国です。«蘆名につくか、伊達につくか»。家の中でも意見が割れていたといいますが、盛国は伊達方に城を開きました。会津の入口にあたる猪苗代が伊達のものになったのです。","6月5日、猪苗代城を足場にした伊達軍と、蘆名義広の軍が磐梯山のふもとの摺上原でぶつかりました。風向きが変わると形勢は一気に伊達へ。蘆名軍は崩れ、日橋川で多くの兵がおぼれたと伝わります。敗れた義広は常陸（茨城県）へ逃れ、会津を400年近くおさめてきた蘆名氏はここで終わりをむかえました。","江戸時代、幕府は «一つの国には城は一つ» という決まりを出しました。ところが会津では、若松城（鶴ヶ城）のほかに、猪苗代城も «城» として残されました。なぜでしょう? 会津の東の守りの要だったからです。保科正之が藩主になったあとは城代がおかれ、正之が亡くなって城の北の土津（はにつ）神社に葬られると、その墓所を守るという大切な役目も加わりました。","1868年、戊辰戦争。新政府軍が母成峠をやぶって会津に攻めこむと、猪苗代城を守っていた会津藩士たちは、城を敵に使わせないよう自ら火を放ち、若松へ引きあげました。いま残る石垣は、その炎をくぐりぬけてきたものです。明治の終わりに町の人たちが桜やツツジを植え、公園になりました。少年時代の野口英世も、この城跡でよく友だちと遊んだといいます。"],"tl":[["1191年","佐原経連が城を築いたと江戸時代の地誌は伝える（宝治合戦以後とみる説も）"],["1589年","城主・猪苗代盛国が伊達政宗に味方する"],["1589年6月5日","摺上原の戦い。蘆名氏が敗れる"],["1675年","保科正之をまつる土津神社が近くに創建される"],["江戸時代","一国一城令の例外として存続し、城代がおかれる"],["1868年","戊辰戦争。城代・高橋権大夫が城を焼いて若松へ退く"],["2001年","«猪苗代城跡 附鶴峰城跡» として県の史跡に"]],"who":[["猪苗代盛国","城主。伊達政宗に味方し、蘆名氏滅亡のきっかけをつくった"],["伊達政宗","猪苗代を足場に摺上原で蘆名氏を破った"],["蘆名義広","会津の大名。摺上原で敗れ、常陸へ逃れた"],["保科正之","会津藩の藩祖。近くの土津神社にまつられる"]],"deep":["築城の年には諸説があります。江戸時代の地誌は1191年に佐原経連が築いたとしますが、『猪苗代町史』は1247年の宝治合戦以後とみるべきだとしています。","会津藩で若松城と猪苗代城の «二つの城» が認められたことは、一国一城令の例外として知られます。江戸時代の猪苗代城には城代がおかれました。","猪苗代盛国の寝返りの背景には、猪苗代家の中の親子の対立があったと伝わります。軍記物では、息子の盛胤が蘆名方に残ったとも語られます。","東側の大手口には、石垣で囲んだ大きな枡形（ますがた）の出入口が残ります。石の積み方が «穴太積（あのうづみ）» とみられることから、蒲生氏の時代に整えられたと考えられています。北西の丘には、猪苗代氏の隠居の城とみられる «鶴峰城» の土塁や空堀も残ります。","城跡から北へ行くと土津神社があり、保科正之の墓所（奥の院）もあります。会津藩の出発点と、会津の城の終わりが、同じ町に並んでいます。"],"look":["本丸まわりに残る石垣","城跡から見る磐梯山","土塁や空堀のあと","近くの土津神社（保科正之をまつる）"],"q":["猪苗代城の城主が伊達政宗に味方したあとに起きた大きな戦いは?","摺上原の戦い（1589年）。この戦いで蘆名氏は会津を失いました。"],"koji":[],"myth":"築城年代は諸説。盛国の寝返りの細かな事情は軍記物による。","img":["摺上原の戦い","蘆名氏","土津神社","伊達政宗"],"wp":"猪苗代城","rel":{"ev":[],"grave":[]},"ph":[["c:2/28/%E7%8C%AA%E8%8B%97%E4%BB%A3%E5%9F%8E%E8%B7%A1.jpg",2816,2112,"猪苗代城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:8/80/Hanitsu_Jinja.jpg",800,600,"土津神社"],["c:1/19/MASAMUNE777.PNG",533,394,"伊達政宗"]]},{"id":"07_kyu_date_gunyakusho","n":"旧伊達郡役所","yomi":"きゅうだてぐんやくしょ","cat":"近代","rank":"A","y":1883,"era":["meiji"],"sh":"国の重要文化財","ad":"伊達郡桑折町字陣屋","st":"JR東北本線・桑折駅から歩いて約15分","la":37.8434,"lo":140.5188,"hook":"屋根の上に塔がのった、白くて洋風の役所。明治の人びとは «文明開化» を、この建物を見上げて感じた。","lead":"旧伊達郡役所は、明治時代に建てられた郡役所（いまの県と町村のあいだにあった役所）の建物です。西洋の建物をまねて日本の大工がつくった «擬洋風建築» で、屋根の上の塔が目じるしです。国の重要文化財に指定されています。","story":["明治時代になると、国は «郡» という単位ごとに役所をおき、税や学校、道路のことをまとめるようにしました。伊達郡の役所がおかれたのが、奥州街道と羽州街道が分かれる宿場町・桑折です。江戸時代には幕府の代官所（陣屋）があった場所で、昔から «役所の町» でした。","1883年、ここに新しい郡役所が完成しました。白いかべ、縦長の窓、ベランダ、そして屋根の上にちょこんとのった塔。町の人びとはびっくりしたことでしょう。«これが西洋風というものか»。まだ洋風の建物を見たことのない人が、ほとんどだった時代です。","じつは、この場所に郡役所が来たのは町の人たちの努力のおかげでした。伊達郡の役所は、はじめ1879年に保原町におかれましたが、桑折の有志が «ぜひ桑折へ» と誘致運動をして、1883年4月に移ってきたのです。設計と工事をしたのは、地元の大工・山内幸之助と銀作。西洋で建築を学んだ人ではありません。見よう見まねで西洋の建物をつくったので、あちこちに日本の技が顔を出します。こうした建物を «擬洋風建築» と呼びます。«西洋にあこがれた日本人の手作り洋館» なのです。","大正時代の終わりに郡役所の制度がなくなったあとも、建物は県の出先機関として1974年まで使われました。1977年に国の重要文化財に指定。東日本大震災やその後の地震でも傷つきましたが、そのたびに修理されて、いまも町の人たちに守られています。","桑折の町は、江戸時代には «半田銀山» の銀でも知られ、伊達氏の古い城・桑折西山城もあります。中世の伊達氏、江戸の宿場と銀山、そして明治の郡役所。小さな町に、それぞれの時代の «中心地» の顔が重なっています。建物の前に立って、町の歴史の層を感じてみてください。"],"tl":[["江戸時代","桑折に幕府の代官所がおかれ、奥州街道・羽州街道の分かれ道の宿場として栄える"],["1879年","伊達郡の郡役所が保原町におかれる"],["1883年4月","桑折町に移り、新しい庁舎が完成"],["1887年","揺れのため塔屋を撤去"],["1926年","郡役所が廃止される"],["1974年","県の出先機関としての使用を終える"],["1977年","国の重要文化財に指定される"],["1979年","塔屋を当初の形に復元"],["2014年","震災の修復を終えて再オープン"]],"who":[["山内幸之助・銀作","地元の大工。庁舎の設計と工事を手がけた"],["桑折町の有志","郡役所を保原から桑折へ誘致した"],["伊達郡の人びと","郡役所で税や地域の仕事を担った"],["伊達氏","中世に桑折西山城を本拠とした大名。郡の名前の由来の地の領主"]],"deep":["明治の擬洋風建築では、屋根の塔が «文明開化» のシンボルとしてよく使われました。旧伊達郡役所は木造2階建て、建築面積は約376㎡です。","擬洋風建築の見どころは «和と洋のまざり方»。柱のかたち、窓の飾り、天井の作りなどに、日本の大工の工夫が見つかります。","見た目の洋風は、ベランダのはり出し、ペンキ塗りの下見板の壁、ガラス入りの上げ下げ窓、軒の丸い飾りなどでつくられています。北海道や東北の明治の官庁建築と共通する特徴です。","桑折町は、奥州街道と羽州街道の分岐点（追分）がある町で、今も追分の碑が残ります。役所がおかれた理由の一つが、この交通の便のよさでした。","屋根の塔屋は、揺れのため1887年にいったん取りはずされ、1979年の工事で元の形にもどされました。いま見ている塔は «復元» なのです。","残っている郡役所の建物の中では最大の規模とされ、あとからの改造が少ないことも評価されています。阿武隈急行の保原駅は、この建物をまねたデザインになっています。"],"look":["屋根の上の塔屋","正面のベランダと縦長の窓","室内の天井や階段の意匠（和と洋のまざり）","近くの奥州・羽州街道の追分の碑"],"q":["西洋の建物をまねて、日本の大工がつくった建物を何という?","«擬洋風建築» です。旧伊達郡役所はその代表例の一つです。"],"koji":[{"w":"文明開化","m":"明治のはじめ、西洋の文化や技術がどっと入ってきて、世の中の暮らしが大きく変わったこと"}],"myth":"","img":["桑折町","擬洋風建築","桑折西山城","半田銀山"],"wp":"旧伊達郡役所","rel":{"ev":[],"grave":[]},"ph":[["c:e/eb/Former_Date_County_Office_20250301_02.jpg",4391,3297,"旧伊達郡役所"],["c:a/a2/KyuDateGunyakusho2006-12.jpg",1128,852,"桑折町"],["c:8/88/Former_Kaichi_School03_1024.jpg",1536,2048,"擬洋風建築"]]},{"id":"07_hachijuri","n":"八十里越（河井継之助の敗走路）","yomi":"はちじゅうりごえ","cat":"街道","rank":"A","y":1868,"era":["edo","meiji"],"sh":"","ad":"南会津郡只見町叶津（新潟県三条市へ通じる峠道）","st":"JR只見線・只見駅から車で約10分で福島側の入口（叶津）。峠そのものは本格的な登山装備が必要","la":37.36,"lo":139.29,"hook":"«八十里 こしぬけ武士の 越す峠»――深手を負った長岡藩の家老は、担がれながら自分を笑う句をよんだ。","lead":"八十里越は、新潟県の三条市から福島県の只見町へ、越後山脈を越える昔の街道です。本当の距離は約8里（約31km）なのに、けわしくて «1里が10里に感じる» ことから、この名がついたといわれます。戊辰戦争で傷ついた長岡藩の河井継之助が、最後に越えた峠として知られています。","story":["越後（新潟県）と会津を結ぶ山道。北には中ノ又山、南には浅草岳。そのあいだの鞍掛峠（標高965m）と木の根峠（標高845m）を越えていきます。雪深く、道は急。それでも明治時代の終わりまで、新潟からは塩や魚、鉄の道具が、南会津からは布の原料や山の産物が、人の背に負われて運ばれていました。","1868年、戊辰戦争。越後の長岡藩は、家老・河井継之助の指揮で新政府軍と激しく戦いました。いったん奪われた長岡城を、7月25日（旧暦）、夜の沼地をわたる奇襲で取りもどします。しかしその戦いのさなか、継之助は左のひざに弾を受け、大けがをしてしまいました。4日後、長岡城は再び落ちます。","歩けない継之助は戸板にのせられ、会津をめざしました。8月4日、一行は越後側のふもと・吉ケ平から八十里越の山道へ。山の中で一夜を明かし、只見へたどり着きます。峠を越えるとき、継之助は «八十里 こしぬけ武士の 越す峠» とよみました。«腰抜け» と «越後を抜ける» をかけた、自分をあざ笑う句です。藩を守りきれなかった悔しさがにじんでいるようです。","只見に着いたころ、傷は破傷風で悪くなっていました。一行は若松をめざして東へ進みますが、8月16日（旧暦）、継之助は塩沢村の医師の家で息を引き取りました。42歳でした。«なぜ、そこまでして戦ったのか?»――新政府にも旧幕府にもつかない «武装中立» をめざした継之助の考えは、今も多くの人の議論の的です。","明治の終わりに鉄道が通ると、人も物も八十里越を使わなくなり、道は荒れていきました。1970年には新潟側最後の集落・吉ケ平の人びとが村を離れています。いま、国道289号の «通れない区間» を解消するための新しい道路づくりが進められています。昔の峠道は、ブナの森の中にひっそりと残っています。"],"tl":[["江戸時代","越後と南会津を結ぶ物資の道として使われる"],["1868年5月19日","北越戦争で長岡城が新政府軍に落とされる（旧暦）"],["1868年7月25日","長岡藩が城を奪い返すが、河井継之助が左ひざに重傷（旧暦）"],["1868年8月4日","継之助が戸板で担がれ八十里越を越える（旧暦）"],["1868年8月16日","継之助が只見・塩沢で亡くなる（旧暦）"],["1914年","岩越線（いまの磐越西線）が全通。峠道は使われなくなっていく"],["1970年","国道289号に指定。同じ年、新潟側の吉ケ平集落が集団で村を離れる"]],"who":[["河井継之助","長岡藩家老。北越戦争で負傷し、この峠を越えて会津へ逃れ、只見で亡くなった"],["長岡藩の兵たち","継之助を戸板で担ぎ、峠を越えた"],["塩沢の医師","継之助が最期をむかえた家の主"]],"deep":["«八十里» の名の由来は、«8里なのに80里に感じる» という説が有名ですが、ほかの説もあり、はっきりしません。","継之助一行が峠を越えるとき切り開いた近道は «河井新道» と呼び伝えられています。","継之助が亡くなった塩沢の家のあった場所は、1961年、只見川の電源開発（ダム）で水の底になりました。亡くなった部屋は近くの «河井継之助記念館» に移されて保存されています。","戊辰戦争のあと、長岡では継之助を «戦争を招いた人» として恨む声もあったといわれます。英雄として評価されるようになったのは後のことで、小説『峠』（司馬遼太郎）の影響も大きいとされます。","南西に約15km離れた «六十里越» は、1970年代前半に国道252号とJR只見線が開通して通りやすくなりました。«八十» と «六十»、対照的な二つの峠の運命です。","新しい国道の工事区間は、新潟側の三条市から只見町叶津まで総延長約20.8kmと計画されています。"],"look":["只見町塩沢の «河井継之助記念館»（終焉の間を移築）","福島側の入口にあたる叶津の集落と番所跡","ブナの森に残る旧峠道（登山は装備と情報収集が必須）","只見町内の継之助の墓（遺骨の一部を葬ったと伝わる）"],"q":["河井継之助が八十里越でよんだ句 «八十里 こしぬけ武士の 越す峠»。«こしぬけ» には何がかけてある?","«腰抜け（いくじなし）» と «越（越後）を抜ける»。自分を笑う句です。"],"koji":[{"w":"八十里 こしぬけ武士の 越す峠","m":"河井継之助の句。負けて越後を抜け出す自分を «腰抜け» と自嘲した"}],"myth":"«八十里» の名の由来は諸説。只見町の墓に遺骨の一部を葬ったという話は伝承（遺骨は長岡にも葬られた）。","img":["河井継之助","北越戦争","長岡藩","只見町"],"wp":"八十里越","rel":{"ev":[],"grave":[]},"ph":[["c:2/2e/OSM_Hachijurigoe.png",460,460,"八十里越"],["c:8/8a/Kawai_Tugunosuke.jpg",472,659,"河井継之助"],["c:8/84/Echigo_no_kuni_Uesugi_Kagekatsu_katoku_arasoi_kassen.jpg",2176,1040,"北越戦争"],["c:6/66/Lake_Tagokura-2.JPG",3072,2304,"只見町"]]},{"id":"07_shirakawa_jo","n":"白川城（搦目城）","yomi":"しらかわじょう（からめじょう）","cat":"城","rank":"A","y":1289,"era":["kamakura","muromachi"],"sh":"国指定史跡","ad":"白河市藤沢山","st":"JR東北本線・白河駅から車で約10分","la":37.1151,"lo":140.2341,"hook":"南朝に命をささげた «奥州の鬼» 結城宗広。その一族が300年近く拠点にした山城が、白河の丘に眠っている。","lead":"白川城は «搦目（からめ）城» とも呼ばれ、中世に白河地方をおさめた白河結城氏が拠点にした山城です。いまの小峰城（白河城）より古く、鎌倉時代の終わりごろから使われました。2016年に国の史跡になりました。","story":["1189年、源頼朝が奥州藤原氏をほろぼした奥州合戦。その手がらで、下総（千葉県・茨城県）の結城朝光が白河の地をもらいました。やがて朝光の孫・結城祐広が、1289年ごろに白河へ移り住みます。祐広が拠点にしたのが、この白川城だと江戸時代の地誌は伝えています。","祐広の子・結城宗広の時代、世の中は大きくゆれました。後醍醐天皇が鎌倉幕府を倒そうと立ち上がると、宗広は天皇方につきます。1333年、新田義貞が鎌倉を攻め落としたとき、宗広もその戦いに加わったとされます。その後、北畠顕家とともに奥州から大軍で京へ攻め上り、足利尊氏をいったん九州まで追いやります。宗広は «南朝の柱» のような武将になりました。","しかし戦いは長引きます。1338年、宗広は奥州へもどる船に乗りますが、嵐にあい、伊勢（三重県）で病にたおれました。『太平記』は、宗広が死ぬ前に «わしの供養には、お経より朝敵の首を供えよ» と言い残したと描いています。なんとも荒々しい最期の言葉ですね。","ところが、宗広の子・親朝は、やがて北朝（足利方）につきます。父は南朝、子は北朝。なぜでしょう? 戦いに疲れた奥州の武士たちの多くが北朝に流れ、一族と領地を守るには、それしか道がなかったとも考えられます。親朝はのちに小峰城を築いたと伝わり、結城氏の拠点は少しずつそちらへ移っていきました。","戦国時代、白河結城氏は一族の争いで弱まり、1590年、豊臣秀吉の奥州仕置で領地を取り上げられました。約400年にわたる南奥州の支配はここで終わり、白川城も廃城になりました。いま山の上には曲輪（くるわ）や土塁、堀のあとが残り、«史蹟 白川城址» の碑が立っています。"],"tl":[["1189年","奥州合戦の手がらで、結城朝光が白河の地を与えられる"],["1289年ごろ","結城祐広が白河に移り、白川城を拠点にしたとされる"],["1333年","結城宗広が新田義貞の鎌倉攻めに加わる"],["1338年","宗広が伊勢で亡くなる"],["1510年","永正の変。一族の小峰氏が惣領を追い出し、このころ拠点が小峰城へ移ったとされる"],["1590年","奥州仕置で白河結城氏が改易される"],["2016年","«白川城跡» として国の史跡に指定"]],"who":[["結城祐広","白河に移り住み、白川城を拠点にしたとされる"],["結城宗広","祐広の子。後醍醐天皇に味方した南朝の重臣"],["結城親朝","宗広の子。のちに北朝方へ移り、家を守った"],["北畠顕家","宗広とともに奥州軍を率いて京へ攻め上った公家の武将"],["結城義親","戦国末期の当主。奥州仕置で領地を失った"]],"deep":["«搦目城» の «搦目（搦手）» は城の裏口という意味で、表にあたる小峰城に対する呼び名と考える説もあります。名前の由来は諸説です。","正確な築城年も廃城年もわかっていません。2010〜2015年の白河市の発掘調査で、14〜16世紀の遺構や遺物が見つかり、長く使われたことが確かめられました。","見つかった遺構には、曲輪・土塁・堀のほか、柱の列や竪穴の建物跡もあります。山全体を使った大きな中世の城で、南奥州の武士の本拠のようすを伝える貴重な例です。","『太平記』は宗広を、殺生を好む荒々しい人物として描きます。これは物語としての誇張もふくむと考えられ、白河では南朝の忠臣として顕彰されてきました。","白河は «白河の関» のある奥州の入口。結城氏が京と奥州を結ぶ要の地をおさえていたことが、南北朝の争いで重く見られた理由の一つです。"],"look":["山頂部の «史蹟 白川城址» の碑","曲輪を区切る土塁と堀のあと","城跡から見下ろす白河の町と阿武隈川","市内の小峰城とあわせて、結城氏の拠点の移り変わりをたどる"],"q":["『太平記』で結城宗広が «供養にはお経より○○を» と言い残したとされるのは何?","«朝敵の首»。荒々しい武将として描かれています（物語の中の話です）。"],"koji":[],"myth":"宗広の遺言は『太平記』の記述。築城年・搦目の由来は諸説。","img":["結城宗広","白河結城氏","小峰城","結城親朝"],"wp":"白川城","rel":{"ev":[],"grave":[]},"ph":[["c:2/24/Y%C5%ABki-Shirakawa_Castle.jpg",1435,1994,"白川城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:0/07/%E7%B5%90%E5%9F%8E%E5%AE%97%E5%BA%83.jpg",1215,1819,"結城宗広"]]},{"id":"07_kotemori","n":"小手森城（政宗の «撫で斬り»）","yomi":"おでもりじょう","cat":"古戦場","rank":"A","y":1585,"era":["azuchi"],"sh":"","ad":"二本松市針道（旧東和町）","st":"JR東北本線・二本松駅から車で約30分。城跡は山道を歩いて登る","la":37.5917,"lo":140.5834,"hook":"«犬まで撫で斬りにした»――19歳の伊達政宗が、伯父への手紙にそう書いた城。その戦いは、奥州にふるえを走らせた。","lead":"小手森城は、いまの二本松市東和地区にあった戦国時代の山城です。1585年、若い伊達政宗がこの城を攻め落とし、城にいた人びとを女性や子どもまで殺したと伝わります。«撫で斬り» と呼ばれるこの事件は、政宗のこわさを周りに見せつけることになりました。今は本丸跡に愛宕神社がまつられ、石垣などが残ります。","story":["阿武隈川の東、山と谷がつづくこのあたりは «塩松（しおのまつ）» と呼ばれ、小浜城の大内定綱がおさめていました。小手森城はその守りの城のひとつで、菊池顕綱という武将が守っていました。定綱は、伊達家にしたがったり、はなれたり。18歳で家をついだばかりの政宗にとって、見すごせない相手でした。","1585年の旧暦8月、政宗は定綱を討つため、川俣の方から塩松へ攻めこみ、小手森城を囲みました。27日、総攻撃。政宗は自ら最前線に立ち、鉄砲をはげしく撃ちかけさせたといいます。城はその日のうちに落ちました。","そのあとに起きたことが、今も語りつがれています。政宗は、城主や兵だけでなく、城の中にいた女性や子どもまで命を奪ったといわれます。その日のうちに政宗は、伯父の最上義光に手紙を書きました。そこには «人はもちろん、犬に至るまで撫で斬りにした» という意味のことが記されていたといいます。","なぜ、そこまでしたのでしょうか? «伊達にさからえばこうなる»――まわりの城主たちをおそれさせ、戦わずに降参させるためだった、と考える人がいます。一方で、手紙の数字は自分の強さを大きく見せるための誇張だったのでは、という見方もあります。実際、このあと小浜城の定綱は逃げ出し、塩松は政宗のものになりました。","けれど、恐怖は新しい争いも生みました。この年の秋、政宗にしたがおうとした二本松城主・畠山義継が、政宗の父・輝宗を連れ去る事件が起き、輝宗は命を落とします。つづく人取橋の戦いでは、政宗は大軍に囲まれて危うい目にあいました。静かな山の上の城跡は、戦国のきびしさと、そこで亡くなった多くの人びとの記憶を伝えています。"],"tl":[["16世紀後半","塩松の領主・大内定綱の支城として菊池氏が守る"],["1585年8月27日（旧暦）","伊達政宗が小手森城を攻め落とし、«撫で斬り» を行ったと伝わる"],["1585年","小浜城も落ち、塩松が伊達領になる"],["1585年10月","畠山義継が伊達輝宗を連れ去り、輝宗が亡くなる"],["1588年","伊達方の石川弾正が相馬方につき小手森城にこもるが、政宗に攻め落とされる"],["1588年以後","史料に現れなくなり、廃城になったとみられる"]],"who":[["伊達政宗","城を攻め落とし、«撫で斬り» を命じたと伝わる"],["大内定綱","塩松の小浜城主。のちに許されて伊達の家臣になった"],["菊池顕綱","小手森城を守っていた城主"],["最上義光","政宗の伯父。撫で斬りを伝える手紙の受け取り手"],["石川弾正","1588年に政宗にそむき、この城にこもった"]],"deep":["撫で斬りを伝える最上義光あての書状には、城主や大内の親類など500人を討ち取り、ほかに城内の者を犬まで撫で斬りにした、という内容が記されるとされます。全体の数は «800人» と語られることが多いですが、数字には誇張の可能性が指摘されています。","1987年のNHK大河ドラマ『独眼竜政宗』では «八百人斬り» という回でこの事件が描かれ、広く知られるようになりました（ドラマの描写は創作をふくみます）。","1588年、石川弾正が立てこもったときも政宗は城を攻め落とし、約500人を討ち取ったと伝わります。この時の伊達軍には、かつての敵・大内定綱も加わっていました。","本丸跡には愛宕神社がまつられ、城跡の各所に石垣や曲輪が残っています。県などの史跡には指定されていません。","小手森城の戦いから、畠山義継による輝宗連れ去り事件、人取橋の戦いまでは、わずか数か月の間のできごとです。政宗の南奥州制覇は、この年の激動から始まりました。"],"look":["本丸跡の愛宕神社","山の斜面に残る石垣","曲輪の平らな地形","亡くなった人びとへの供養の気持ちをもって歩きたい"],"q":["政宗が撫で斬りのことを知らせた手紙を送った相手はだれ?","伯父の最上義光（山形城主）。母・義姫の兄です。"],"koji":[{"w":"撫で斬り","m":"刀でなでるように、かたっぱしから斬りすてること。皆殺しを意味することば"}],"myth":"撫で斬りの人数は書状によるが誇張説あり。ドラマの描写は創作をふくむ。","img":["伊達政宗","大内定綱","人取橋の戦い","最上義光"],"wp":"小手森城","rel":{"ev":[],"grave":[]},"ph":[["c:e/ec/%E5%B0%8F%E6%89%8B%E6%A3%AE%E5%9F%8E.jpg",1600,1200,"小手森城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:1/19/MASAMUNE777.PNG",533,394,"伊達政宗"],["c:4/47/%E4%BA%BA%E5%8F%96%E3%82%8A%E6%A9%8B_%E5%A2%93_%E5%85%A8%E6%99%AF_%E3%83%A1%E3%83%BC%E3%83%AB%E7%94%A8.jpg",1151,863,"人取橋の戦い"],["c:d/dc/Mogami7.jpg",440,300,"最上義光"]]},{"id":"07_iino_hachimangu","n":"飯野八幡宮","yomi":"いいのはちまんぐう","cat":"寺社","rank":"A","y":1186,"era":["heian","kamakura","edo"],"sh":"国の重要文化財（本殿・楼門など）","ad":"いわき市平字八幡小路","st":"JR常磐線・いわき駅から歩いて約10分","la":37.0604,"lo":140.8821,"hook":"城をつくるために «引っこし» させられた八幡さま。その境内には、江戸時代はじめの社殿と、1,683通もの古文書が守られてきた。","lead":"飯野八幡宮は、いわき市の中心にある、浜通り南部でも最大級の神社です。源頼朝の命で京都の石清水八幡宮から神さまを迎えたと伝わり、本殿や楼門など江戸時代はじめの建物が国の重要文化財になっています。神社に伝わる «飯野家文書» も、中世のいわきを知る宝物です。","story":["社伝によると、はじまりは1063年。前九年合戦に勝った源頼義が、京都の石清水八幡宮の神さまをまつったといいます。そして1186年、源頼朝の命令で、石清水から神さまのご神体を迎え、この地域の荘園 «好嶋荘（よしまのしょう）» の総社としてまつりました。場所は、いまのいわき駅の北側の高台だったと伝わります。","神社を代々守ってきたのは飯野（いいの）氏という一族です。鎌倉幕府の有力な家・伊賀氏の分家で、神主として、また地域の武士として、長い年月を生きぬいてきました。いわきの領主・岩城氏も、この八幡さまを大切にしました。","ところが1600年の関ヶ原の戦いのあと、岩城氏は領地を取り上げられてしまいます。かわって徳川家の家臣・鳥居忠政がやってきました。忠政が新しい城をつくる場所に選んだのが、なんと八幡さまのあった高台。«神さまに、お引っこしいただこう»。1602年、神社はいまの八幡小路へ移され、跡地に磐城平城が築かれました。","新しい土地で、社殿は次々と建てられました。1616年に本殿、1623年に神楽殿、1658年に楼門。どれも江戸時代はじめの姿をよく残し、国の重要文化財に指定されています。楼門をくぐると、400年前の職人たちの仕事がそのまま目の前に広がります。","毎年9月の例祭には、古式大祭や流鏑馬（やぶさめ）が行われます。«鎌倉の武士のころから続く祭りを、自分たちの手で守りたい»――そんな地元の人びとの思いが、社殿とともに受けつがれているのです。"],"tl":[["1063年","源頼義が石清水八幡宮の神をまつったと社伝は伝える"],["1186年","源頼朝の命で好嶋荘の総社としてまつられたと伝わる"],["1602年","磐城平城を築くため、いまの八幡小路に移される"],["1616年","本殿が建てられる（上棟）"],["1658年","楼門が建てられる"],["1703年ごろ","唐門が建てられ、本殿の屋根が入母屋造に改められる"]],"who":[["源頼義","社伝で最初に八幡神をまつったとされる武将"],["源頼朝","好嶋荘の総社としてまつることを命じたと伝わる"],["飯野氏","伊賀氏の分家。代々この神社を守ってきた社家"],["鳥居忠政","磐城平藩主。城を築くため神社を移した"]],"deep":["飯野家に伝わる «飯野家文書» は1,683通にのぼり、国の重要文化財です。鎌倉時代からの土地の争いや、武士のくらしがわかる、中世の東北を知るうえでの一級史料です。","本殿は1616年に建てられたときは流造（ながれづくり）でしたが、1674年と1703年の修理で入母屋造に変わりました。建物にも «歴史の書きかえ» のあとがあります。","重要文化財の建物は、本殿・楼門・唐門・神楽殿・仮殿・若宮八幡社本殿・宝蔵の7棟。江戸時代初期の神社がこれだけまとまって残るのは貴重です。","宝物の大薙刀には «備州長船住盛景 貞治六年» の銘があり、1367年に備前長船の刀工・盛景が作ったものです。これも国の重要文化財です。","創建を1063年とする説と1186年とする説があり、どちらも社伝によります。末社の «白旗社» には源頼朝がまつられています。"],"look":["江戸時代はじめの楼門（1658年）","入母屋造・こけら葺きの本殿","神楽殿や唐門など、江戸時代初期の社殿群","9月の例祭の流鏑馬"],"q":["飯野八幡宮が1602年にいまの場所へ移されたのはなぜ?","もとの場所に磐城平城を築くことになったからです。"],"koji":[],"myth":"1063年・1186年の創建はどちらも社伝による。","img":["磐城平城","好嶋荘","鳥居忠政","石清水八幡宮"],"wp":"飯野八幡宮","rel":{"ev":[],"grave":[]},"ph":[["c:e/ef/Iino_Hachimangu_1.JPG",3648,2736,"飯野八幡宮"],["c:5/5d/Iino_Hachimangu_2.JPG",3636,2720],["c:c/cf/Tangosawa_Park.JPG",3648,2736,"磐城平城"],["c:d/d9/Torii_Tadamasa.jpg",1676,3223,"鳥居忠政"],["c:d/d5/Iwashimizu_hachimangu07s3200.jpg",3200,2142,"石清水八幡宮"]]},{"id":"07_yanagawa_jo","n":"梁川城","yomi":"やながわじょう","cat":"城","rank":"B","y":1426,"era":["kamakura","muromachi","azuchi"],"sh":"国指定史跡（伊達氏梁川遺跡群）","ad":"伊達市梁川町鶴ヶ岡","st":"阿武隈急行・梁川駅から歩いて約15分","la":37.8552,"lo":140.6113,"hook":"独眼竜が生まれるずっと前、伊達氏は300年近くこの城から奥州をながめていた。校庭の下には、中世の庭園が眠っていた。","lead":"梁川城は、鎌倉時代から戦国時代まで伊達氏が本拠にした城です。伊達氏は1532年に桑折西山城へ移るまで、300年近くここを拠点にしたと考えられています。本丸跡の小学校の校庭からは中世の庭園が見つかり、«心字の池» として復元されました。国の史跡です。","story":["1189年、源頼朝の奥州合戦で手がらを立てた関東の武士が、伊達郡をもらって移り住み、«伊達氏» を名のりました。これが、のちに独眼竜・政宗を生む伊達家のはじまりです。梁川城がいつ築かれたか、はっきりした記録はありません。でも発掘された古い道具から、鎌倉時代の中ごろには城があったと考えられています。","伊達氏は代々梁川城を本拠にしながら、力をたくわえていきました。室町時代には鎌倉公方とも張り合うほどの勢いになります。1532年、伊達稙宗は本拠を桑折西山城へ移しますが、そのあとも梁川城は伊達の大切な城として、一族や重臣が守りました。","政宗の若いころにも、梁川城は何度も登場します。政宗の初陣は、相馬氏との戦い。その拠点になったのが梁川城で、政宗は梁川八幡宮で戦勝を祈ったといわれます。また、三春の田村家から愛姫（めごひめ）がお嫁に来たとき、花嫁を受けわたした場所も梁川でした。«ここから伊達の未来が始まる» ――そんな場所だったのです。","1590年、秀吉の奥州仕置で伊達氏は伊達郡を離れます。城は蒲生氏、そして上杉氏のものになりました。1600年、関ヶ原の戦いのころ、政宗は上杉方の梁川城を攻めますが、守りはかたく、攻撃をやめて引きあげました。かつての自分の家の城に、はね返されたのです。","1664年、上杉家の領地が減らされたとき、梁川城は廃城になりました。その後、本丸跡には小学校が建ち、1978年からの発掘調査で、校庭の下から中世の庭園が見つかりました。子どもたちの声がひびいた校庭の一角で、伊達氏の庭の池がよみがえったのです。"],"tl":[["1189年","奥州合戦ののち、伊達氏が伊達郡に入る"],["1426年","記録の上で梁川城の存在がはっきりする"],["1532年","伊達稙宗が桑折西山城へ本拠を移す"],["1590年","奥州仕置で伊達氏が去り、蒲生氏の領地に"],["1600年","関ヶ原の戦いのころ、政宗が上杉方の梁川城を攻めるが引きあげる"],["1664年","上杉家の減封にともない廃城"],["1978〜1981年","本丸跡の発掘調査で中世庭園が見つかる"]],"who":[["伊達稙宗","14代当主。梁川城から桑折西山城へ本拠を移した"],["伊達政宗","初陣のとき梁川城を拠点にしたといわれる"],["愛姫","政宗の正室。梁川で花嫁の受けわたしが行われた"],["須田長義","上杉家の家臣。梁川城主として城を改修した"]],"deep":["城は茶臼山から張り出した高台にあり、南は広瀬川の断崖、西は段丘の急な斜面、東は金沢堀と茶臼山という、自然の地形を生かした守りの城でした。","いま見える石垣や土塁は、蒲生氏か上杉氏の時代に整えられたものと考えられています。本丸の物見櫓跡の石垣は «穴太積» とされます。","国の史跡としての名前は «伊達氏梁川遺跡群»。城跡だけでなく、伊達氏にゆかりの寺院跡などとあわせて指定されています。","江戸時代の梁川は、幕府の直轄地になったり、松前藩の領地になったりと、めまぐるしく持ち主が変わりました。蝦夷地の松前氏が一時この地に移されたこともあります。","城下には «見附»«元陣内»«右城町（うしろまち）» など、城下町の名残の地名がたくさん残っています。"],"look":["本丸跡に復元された中世庭園 «心字の池»","本丸の物見櫓跡の石垣","二の丸まわりの土塁や堀のあと","城下町の名残のクランク型の道や地名"],"q":["梁川城の本丸跡の校庭から見つかり、復元されたものは何?","中世の庭園 «心字の池»。伊達氏の時代の庭と考えられています。"],"koji":[],"myth":"築城年は不明（1189年説あり）。政宗の戦勝祈願の話は伝承。","img":["伊達氏","桑折西山城","伊達稙宗","愛姫"],"wp":"梁川城","rel":{"ev":[],"grave":[]},"ph":[["c:f/f9/Yanagawa_shinji_1.JPG",800,600,"梁川城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:3/33/Yanagawa_shinji_2.JPG",800,600],["c:4/43/Date_Tanemune.JPG",1810,1849,"伊達稙宗"],["c:8/86/Yotoku-in_Tamaya_2015a.jpg",2000,1500,"愛姫"]]},{"id":"07_kowatari","n":"石都々古和気神社（石川の一之宮）","yomi":"いわつつこわけじんじゃ","cat":"寺社","rank":"B","y":1063,"era":["heian","kamakura","muromachi"],"sh":"","ad":"石川郡石川町下泉","st":"JR水郡線・磐城石川駅から歩いて約10分。鳥居から本殿までさらに山道を約10分","la":37.145,"lo":140.4509,"hook":"参道のわきに、苔むした巨石がごろごろと並ぶ。古代の人びとが神さまを感じた «磐境（いわさか）» の山に、石川の一之宮はある。","lead":"石都々古和気神社は、石川町の八幡山の頂上にある古い神社です。平安時代の『延喜式』にのる神社の候補とされ、«陸奥国一宮» を名のっています。山には神さまをまつった大きな岩がいくつもあり、中世にはこの地をおさめた石川氏の城 «三芦城» もありました。","story":["石川町の町なかに、こんもりとした小さな山があります。八幡山です。鳥居をくぐって石段と坂道を登っていくと、道のわきに大きな岩が次々とあらわれます。«なぜ、こんなところに大岩が?»――古代の人びとは、こうした岩に神さまが宿ると考え、祈りの場所にしました。これを «磐境（いわさか）» と呼びます。この神社は、そうした自然への祈りから始まったと考えられています。","平安時代の初め、国が大切な神社を書き出した『延喜式』の «神名帳» に、«陸奥国白河郡 石都都古和気神社» という名前がのっています。これがこの神社のことだとされ、書物にあらわれる最初の記録です。むずかしい名前ですが、«いわつつこわけ» と読みます。","1051年、源有光という武士が、源頼義・義家の安倍氏との戦い（前九年合戦）に加わって手がらを立て、この地をもらいました。有光は1063年に移り住んで «石川» を名のり、神社の東どなりに城を築きます。これが三芦（みよし）城、別名・石川城です。1066年には、源氏の守り神・石清水八幡宮の神さまも迎えて、いっしょにまつりました。«八幡山» という山の名前はここから来ています。","石川氏はこの城を拠点に、25代・528年もこの地をおさめたと伝わります。でも戦国時代の終わり、豊臣秀吉の奥州仕置で領地を取り上げられてしまいました。最後の当主・石川昭光は伊達政宗の叔父にあたり、その後は伊達家の重臣として生きていきました。山の上には、今も三芦城の土塁が残っています。","境内には、ほかでは見られない狛犬がいます。1930年に石工の小林和平がつくった «飛翔獅子»。今にも飛びかかりそうな、力強い姿です。古代の岩の祈り、中世の武士の城、近代の職人の技――山を一つ登るだけで、いくつもの時代に出会える神社です。"],"tl":[["平安時代初め","『延喜式』神名帳に «石都都古和気神社» の名がのる"],["1051年","源有光が前九年合戦の手がらで石川の地を得る"],["1063年","有光が移り住み、石川氏を名のって三芦城を築く"],["1066年","石清水八幡宮の神を迎えてあわせまつる"],["1423年","石川持光が銅製の鰐口を奉納（県の文化財）"],["1590年","奥州仕置で石川氏が領地を失う"],["1930年","石工・小林和平が狛犬 «飛翔獅子» をつくる"]],"who":[["石川有光","石川氏の祖。三芦城を築き、八幡神をあわせまつった"],["石川持光","室町時代の当主。鰐口を奉納した"],["石川昭光","最後の当主。伊達晴宗の子で、政宗の叔父"],["小林和平","狛犬 «飛翔獅子» をつくった石工"]],"deep":["«陸奥国一宮» を名のる神社は福島県内にいくつかあり、棚倉町の都都古別神社（2社）などもそうです。石都々古和気神社のもとの祭神・味耜高彦根命（あじすきたかひこねのみこと）は都都古別神社と同じで、そこから分かれたとする説もありますが、はっきりした裏づけはありません。","『延喜式』にのる «石都都古和気神社» がこの神社だとは断定されておらず、«論社（候補の一つ）» とされます。","1423年に石川持光が奉納した銅の鰐口は、福島県の文化財です。室町時代の石川氏の信仰を示す実物資料です。","祭りは、かつて旧暦9月19日に行われ、神輿が山を下りて麓の御仮屋に7日間とどまり、流鏑馬なども行われたといいます。いまは9月第2土曜日が例祭です。","最後の当主・昭光は伊達晴宗の子で、石川家に養子に入った人物です。須賀川城が落ちたあと、政宗から須賀川城を与えられたのも昭光でした。"],"look":["参道ぞいに点々とある巨石（磐境）","石門のように立つ岩","本殿の東に残る三芦城の土塁","狛犬 «飛翔獅子»"],"q":["山の岩に神が宿ると考えて祈った場所を何という?","«磐境（いわさか）»。参道にたくさんの巨石が残っています。"],"koji":[],"myth":"『延喜式』の神社と同一かは論社（諸説）。石川氏25代528年は伝承による数字。","img":["三芦城","石川町","石川昭光","延喜式神名帳"],"wp":"石都々古和気神社","rel":{"ev":[],"grave":[]},"ph":[["c:8/80/Iwatsutsukowake_Shrine.jpeg",2048,1536,"石都々古和気神社"],["c:f/f3/Iwatsutsu_Kowake-jinja_Komainu_ac.jpg",3872,2581],["c:f/fd/Iwatsutsukowake_Shrine_honden.jpeg",1984,1450],["c:0/0e/%E7%9F%B3%E9%83%BD%E3%80%85%E5%8F%A4%E5%92%8C%E6%B0%97%E7%A5%9E%E7%A4%BE%E5%8F%82%E9%81%93%E3%81%AE%E7%A3%90%E5%BA%A7_DQlVGUrVoAAb2nW.jpg",1024,576],["c:d/d7/%E7%9F%B3%E9%83%BD%E3%80%85%E5%8F%A4%E5%92%8C%E6%B0%97%E7%A5%9E%E7%A4%BEi%E7%9F%B3%E9%96%80_DQlVK6oVAAAL_0P.jpg",1024,576],["c:5/51/Bobataonsen%2C_motoyu_and_hachimanya.JPG",2048,1536,"石川町"],["c:a/a7/Ishikawa_Akimitsu.jpg",937,2084,"石川昭光"],["c:c/c8/Engishiki_Jingi_cropped_Engishiki_Vol_2_Flame_37.jpg",2523,3524,"延喜式神名帳"]]},{"id":"07_utsumine","n":"宇津峰（南朝方の最後の砦）","yomi":"うつみね","cat":"城","rank":"B","y":1353,"era":["muromachi"],"sh":"国指定史跡","ad":"須賀川市・郡山市の境（宇津峰山）","st":"登山口まで車が便利（JR須賀川駅から車で約30分）。山頂まで山道を歩く","la":37.297,"lo":140.4692,"hook":"後醍醐天皇の孫を守り、最後まで旗をかかげた山。ここが落ちたとき、奥州の南北朝の戦いはほぼ終わった。","lead":"宇津峰は、須賀川市と郡山市の境にある宇津峰山（標高677m）の山全体を使った中世の城です。南北朝時代、南朝方の北畠顕信らが後醍醐天皇の孫・守永王をいただいて立てこもり、奥州での南朝の最後の拠点となりました。国の史跡です。","story":["14世紀、日本は二つの朝廷に分かれて争っていました。吉野の南朝と、京都の北朝です。奥州でも戦いは続き、南朝方の中心だった北畠顕家や結城宗広が次々に亡くなると、形勢は北朝にかたむいていきました。そんな中で南朝を支えたのが、宇津峰のふもとをおさめる田村庄司（しょうじ）の一族です。","1346年、北朝方は霊山城など南朝方の城をいっせいに攻め、宇津峰もいったん落ちました。ところが、北朝の足利家で兄弟げんか（観応の擾乱）が起きると、奥州の南朝方は息を吹き返します。1351年の冬には、なんと奥州の政治の中心・多賀国府を取りもどしました。","しかし喜びは長く続きません。翌1352年のはじめ、国府は再び北朝に奪われます。北畠顕信は、後醍醐天皇の孫・守永王（宇津峰宮）をお守りして、この宇津峰山に立てこもりました。«ここを最後の砦とする»。山はけわしく、田村庄司の一族も必死に戦い、北朝軍はなかなか近づけませんでした。","1353年4月、北朝の吉良貞家らが総攻撃をかけます。そして5月4日、宇津峰はついに落ちました。守永王と顕信は出羽（山形県・秋田県）、さらに北へと逃れていきます。«なぜ最後まで戦ったのか?»――天皇への忠義か、一族の誇りか。この戦いで、奥州の南北朝の争いは事実上終わりをむかえ、田村庄司の一族も力を失っていきました。","山には今も «千人溜（せんにんだまり）» «長子城» といった地名が残ります。千人溜は土塁に囲まれた四角い広場で、中には石の祠があります。山頂には «雲水峰城址» の碑。天気がよければ、阿武隈の山なみと郡山・須賀川の町が見わたせます。"],"tl":[["1338年","南朝方の北畠顕家が戦死、結城宗広が病死する"],["1346年","北朝方の攻撃で宇津峰が落ちる"],["1351年冬","南朝方が多賀国府を取りもどす"],["1352年","国府を再び失い、北畠顕信が守永王をいただいて宇津峰にこもる"],["1353年5月4日","吉良貞家らの攻撃で宇津峰が落城"],["1931年","国の史跡に指定"]],"who":[["北畠顕信","顕家の弟。奥州の南朝方を率いて宇津峰にこもった"],["守永王（宇津峰宮）","後醍醐天皇の孫。宇津峰でかつがれた皇族"],["田村宗季（田村庄司）","ふもとの守山城主。南朝方の有力武将"],["吉良貞家","北朝方の奥州管領。宇津峰を攻め落とした"]],"deep":["«千人溜» は高さ1.8mほどの土塁で囲まれた18〜20m四方の曲輪で、中に石の祠があります。その東の «長子城» には空堀のあとや、斜面を階段状に削った平場が確認されています。","宇津峰には «星が城» «雲水峯» という別名もあります。","戦国時代に三春城を本拠とした田村氏（伊達政宗の正室・愛姫の実家）は、南北朝の田村庄司家とは別の一族とされます。同じ «田村» でも混同に注意。","1931年に国の史跡に指定されており、福島県内でも早い時期の指定です。","南朝方の拠点としては、伊達郡の霊山（りょうぜん）も有名です。霊山と宇津峰は、奥州南朝の二大拠点として語られます。"],"look":["土塁に囲まれた «千人溜» と石の祠","«長子城» の空堀のあと","山頂の «雲水峰城址» の碑","山頂からの阿武隈の山なみ"],"q":["宇津峰にこもった後醍醐天皇の孫はだれ?","守永王。«宇津峰宮» とも呼ばれます。"],"koji":[],"myth":"守永王の出自や後の足取りには諸説ある。","img":["宇津峰山","北畠顕信","南北朝時代 (日本)","霊山 (福島県)"],"wp":"宇津峰","rel":{"ev":[],"grave":[]},"ph":[["c:2/26/%E5%AE%87%E6%B4%A5%E5%B3%B0_%E5%85%A5%E5%8F%A3.jpg",2448,3264,"宇津峰"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:1/16/%E5%8C%97%E7%95%A0%E9%A1%95%E4%BF%A1%E3%81%AE%E8%8A%B1%E6%8A%BC.jpg",1536,1872,"北畠顕信"],["c:d/d4/%E7%99%BB%E5%B1%B1%E5%8F%A3%E3%81%8B%E3%82%89%E3%81%AE%E9%9C%8A%E5%B1%B1%EF%BC%92.jpg",5184,3456,"霊山 (福島県)"]]},{"id":"07_azukojima","n":"安子島城","yomi":"あこがしまじょう","cat":"城","rank":"B","y":1589,"era":["kamakura","muromachi","azuchi"],"sh":"","ad":"郡山市熱海町安子島字南町","st":"JR磐越西線・安子ケ島駅から歩いてすぐ（線路の北側の道路ぞいに碑）","la":37.4736,"lo":140.3061,"hook":"まわりの城がみな伊達になびく中、ただひとり «義» をつらぬいた城主がいた。","lead":"安子島城は、郡山市熱海町にあった中世の城です。鎌倉時代から戦国時代まで、安積（あさか）伊東氏の一族・安子島氏の城でした。1589年、伊達政宗の大軍を前に、城兵の命と引きかえに城を明け渡しました。今は建物も堀もほとんど残らず、駅の近くに碑が立っています。","story":["安積郡（いまの郡山市のあたり）は、鎌倉時代に伊東氏という武士がおさめるようになりました。静岡の伊豆から来た一族です。その一族の分かれが «安子島氏» で、この城を代々守ってきました。","室町時代、奥州は鎌倉公方と京都の幕府のあいだで引っぱり合いになりました。安子島氏は、鎌倉公方が送りこんだ «篠川御所» 足利満直にしたがい、幕府方の伊達氏とにらみ合いました。小さな領主たちは、大きな力のどちらにつくかで生き残りを決めなければならなかったのです。","戦国時代、安子島氏は二本松の畠山氏（二本松氏）にしたがっていました。ところが1585年、二本松の畠山義継が伊達政宗の父・輝宗を連れ去る事件を起こし、ともに命を落とします。後ろだてを失った安子島氏は、会津の蘆名義広にたよりました。","1589年、政宗が会津の蘆名氏を倒そうと動き出すと、安積郡の領主たちは次々と伊達方へ寝返りました。そんな中、城主の安子島祐高だけは蘆名方にとどまったと伝わります。«恩を受けた家を裏切るわけにはいかぬ»。しかし、伊達の大軍の前に勝ち目はありません。祐高は、城兵の命を助けることを条件に、戦わずに城を明け渡しました。","まもなく摺上原の戦いで蘆名氏はほろびます。安子島城は一度は捨てられましたが、のちに会津に入った上杉景勝が、家臣の安田能元をおいた «浅香城» がこの城のことだとする説があります。関ヶ原の戦いのあった1600年ごろ、城としての役目を終えました。"],"tl":[["鎌倉時代","安積伊東氏の一族・安子島氏が城を築いたとされる"],["室町時代","安子島祐義が篠川御所・足利満直にしたがう"],["1585年","二本松の畠山義継が亡くなり、安子島氏は蘆名氏にしたがう"],["1589年","伊達政宗の攻勢を前に、城兵の命と引きかえに開城"],["1598年","上杉景勝が会津に入り、«浅香城» に安田能元をおく（安子島城と同じとみる説）"],["1600年","このころ廃城"],["1992〜1993年","発掘調査で堀や建物のあとが見つかる"]],"who":[["安子島祐高","最後の城主。ただひとり蘆名方にとどまったと伝わる"],["安子島祐義","室町時代の城主。鎌倉府方として伊達氏と対立"],["伊達政宗","安積郡を制圧し、蘆名氏を追いつめた"],["安田能元","上杉家の家臣。浅香城主"]],"deep":["1589年、政宗は会津へ向かう途中、安子島城のほかに近くの高玉城も攻めています。高玉城は激しく戦って落城したと伝わり、戦わずに開城した安子島城とは対照的です。","城は平山城で、本丸と東出丸、空堀などがあったとされます。現在は堀も埋まり、地形にわずかな痕跡が残るだけです。","1992〜93年の発掘調査では、堀や建物のあと、中世の遺物が見つかりました。記録として城のすがたが残されています。","上杉時代の «浅香城» を安子島城と同じ城とみる説が有力ですが、確定ではありません。","史跡には指定されておらず、現地は民有地や道路になっています。見学は碑のまわりから、周囲の地形をながめるのがよいでしょう。"],"look":["安子ケ島駅近く、線路北側の道路わきに立つ城跡の碑","周囲に残る、わずかな段差や地形","近くの磐梯熱海温泉とあわせてめぐる"],"q":["1589年、安子島城の城主はどんな条件で城を明け渡した?","城兵の命を助けることと引きかえに、戦わずに開城したと伝わります。"],"koji":[{"w":"衆寡敵せず","m":"少ない人数では、多い相手にはかなわないということ"}],"myth":"祐高が «ただひとり» 蘆名方にとどまった話は伝承。浅香城との同一説は確定していない。","img":["安積郡","伊達政宗","摺上原の戦い","蘆名氏"],"wp":"安子島城","rel":{"ev":[],"grave":[]},"ph":[["c:1/12/%E5%AE%89%E5%AD%90%E5%B3%B6%E5%9F%8E%E5%9D%80.jpg",3264,2448,"安子島城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:4/42/Fukushima_Asaka-gun.png",340,220,"安積郡"],["c:1/19/MASAMUNE777.PNG",533,394,"伊達政宗"]]},{"id":"07_hisakawa","n":"久川城（伊南の籠城戦）","yomi":"ひさかわじょう","cat":"城","rank":"B","y":1589,"era":["azuchi","edo"],"sh":"県指定史跡","ad":"南会津郡南会津町（旧伊南村）","st":"車が便利。会津鉄道・会津高原尾瀬口駅から車で約40分","la":37.1872,"lo":139.5234,"hook":"会津を手に入れた伊達政宗に、山奥の小さな領主が «否» と答えた。急ごしらえの城は、伊達の兵を追い返した。","lead":"久川城は、南会津の伊南（いな）地方にある山城です。1589年、伊達政宗にしたがうことをこばんだ河原田盛次が築き、伊達の軍勢を追い返したと伝わります。曲輪や土塁、空堀がよく残り、福島県の史跡になっています。","story":["南会津の奥深く、伊南川が流れる山あいの里。ここは鎌倉時代の1189年、奥州合戦の手がらで下野（栃木県）の河原田盛光がもらった土地です。それから400年、河原田氏はこの伊南郷をおさめてきました。戦国時代には会津の蘆名氏にしたがうようになります。","1589年、摺上原の戦いで蘆名氏がほろび、伊達政宗が黒川城（のちの会津若松城）に入りました。会津の領主たちは次々と政宗に頭を下げます。けれど河原田盛次はちがいました。«伊達にはしたがわぬ»。盛次は戦にそなえ、伊南川の西の丘に新しい城を築きました。それが久川城です。","政宗は家臣の柴田但馬や、降参したばかりの鴫山城主・長沼盛秀らを伊南に送りこみました。雪深い山の中、城は九十九折りの山道の上。攻めあぐねた伊達勢は、とうとう城を落とせずに引きあげたと伝わります。«小さな城が伊達を追い返した»――伊南の人びとが誇りをもって語りつぐ話です。","ところが歴史は皮肉です。翌1590年、盛次は豊臣秀吉の小田原攻めに参加しなかったため、奥州仕置で領地を取り上げられてしまいました。伊達に勝っても、天下の流れには逆らえなかったのです。一族は蘆名義広について常陸へ行った者、村に残って農民になった者と、それぞれの道を歩みました。","その後、会津には蒲生氏、上杉氏、そして再び蒲生氏が入り、再蒲生時代に久川城はいまの形に改築されました。そして1611年に廃城。山の上には、今も土塁と空堀に囲まれた本丸が、戦国の城のすがたを伝えています。"],"tl":[["1189年","奥州合戦の手がらで河原田盛光が伊南郷を得る"],["1543年ごろ","蘆名盛氏に攻められ、河原田氏は蘆名氏にしたがう"],["1589年","蘆名氏滅亡。河原田盛次が政宗にしたがわず久川城を築き、伊達勢を退ける"],["1590年","小田原攻めに参加せず、奥州仕置で領地を失う"],["蒲生氏の時代","城が改築され、いまの縄張りになる"],["1611年","廃城"]],"who":[["河原田盛次","伊南の領主。久川城を築き伊達勢を退けた"],["伊達政宗","会津を手に入れ、伊南を攻めさせた"],["長沼盛秀","鴫山城主。伊達方として伊南を攻めた"],["蘆名義広","会津の大名。敗れて常陸へ。河原田一族の一部がしたがった"]],"deep":["久川城の戦いの様子は『伊南合戦記』『泉州記』など後の時代の軍記物に詳しく書かれていますが、どこまでが事実かはわかりません。","このとき政宗は、上杉景勝を後ろだてにする伊北郷（只見方面）の山内氏勝の攻撃に力を入れていたとみられ、伊南への攻撃は大規模ではなかった可能性もあります。","城は伊南川の西の南北にのびる丘の上にあり、ふもとからの高さ約70m、東西110m・南北430mの規模。本丸は南北110m・東西65mで、土塁と空堀に囲まれています。","城の北と南のふもとに枡形の出入口があり、本丸の南西すみの稲荷神社のあたりに櫓台があったと考えられています。","常陸へ移った河原田氏は、のちに蘆名義広の領地となった秋田の角館に住みました。角館の武家屋敷 «河原田家» はその子孫の屋敷です。"],"look":["土塁と空堀に囲まれた本丸","連なる曲輪を区切る堀切","ふもとの枡形虎口のあと","本丸南西の稲荷神社（櫓台跡とみられる）"],"q":["伊達勢を追い返した河原田盛次が、翌年に領地を失った理由は?","豊臣秀吉の小田原攻めに参加しなかったからです。"],"koji":[],"myth":"合戦の経過は後世の軍記物による。","img":["伊南村","南会津町","伊達政宗","蘆名義広"],"wp":"久川城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:b/b5/Aizu-tajima_Gionsai%2C_Nanahokai.JPG",4742,3557,"南会津町"],["c:1/19/MASAMUNE777.PNG",533,394,"伊達政宗"],["c:3/33/%E8%98%86%E5%90%8D%E7%BE%A9%E5%BA%83%E3%81%AE%E8%8A%B1%E6%8A%BC.jpg",1993,1536,"蘆名義広"]]},{"id":"07_hacchome","n":"八丁目城","yomi":"はっちょうめじょう","cat":"城","rank":"B","y":1574,"era":["muromachi","azuchi","edo"],"sh":"","ad":"福島市松川町","st":"JR東北本線・松川駅から歩いて約15分","la":37.6608,"lo":140.4569,"hook":"«八丁目» という変わった名前は、国ざかいの川からの距離。伊達と二本松がうばい合った «境目の城» である。","lead":"八丁目城は、福島市松川町にあった戦国時代の山城です。伊達氏と二本松の畠山氏の領地の境目にあり、何度も持ち主が変わりました。ふもとの集落はのちに奥州街道の «八丁目宿» になりました。山頂には愛宕神社と八幡神社がまつられ、土塁のあとがよく残っています。","story":["なぜ «八丁目» なのでしょう? 答えは、南にある境川。安達郡と信夫郡の境になっている川で、そこから «八町（約870m）» の距離にあることから名づけられたといいます。境川は、江戸時代には二本松藩と福島藩の境、そして今も二本松市と福島市の境です。ここは昔から «境目» の土地でした。","城をだれが、いつ築いたかははっきりしません。伊達稙宗が大森城の支城としておいたともいわれ、天文の乱（伊達家の親子げんか）のころには堀越能登守の城でした。稙宗自身も、一時この城にいたといいます。","1570年、城主の堀越宗範が南の二本松城主・畠山氏に寝返りました。八丁目城は二本松のものに。しかし1574年、大森城主の伊達実元（政宗の大叔父で、成実の父）が城を取りもどします。ここから八丁目城は、二本松ににらみをきかせる伊達の «押さえの城» となりました。","城を築くとき、南にあった集落が城のふもとに移されたといわれます。この町が、のちの八丁目宿です。奥州街道が通り、米沢街道・相馬街道とも交わる宿場として、江戸時代にはにぎわいました。城の役目が終わっても、町は街道とともに生きつづけたのです。","山の中腹からは、旧八丁目宿の町並みと、東の土合山が見わたせます。土合山には支城の «土合館» があり、今はあじさいの名所の公園です。なお、城跡の近くは、1949年に列車が脱線転覆し乗務員が亡くなった «松川事件» の現場にも近く、町には昭和の記憶も刻まれています。"],"tl":[["16世紀前半","伊達稙宗が大森城の支城としておいたとされる"],["天文の乱のころ","堀越能登守の居城。稙宗が一時在城"],["1570年","城主・堀越宗範が二本松の畠山氏に寝返る"],["1574年","伊達実元が奪い返し、再び伊達領に"],["1590年ごろ","廃城"],["江戸時代","ふもとの八丁目宿が奥州街道の宿場としてにぎわう"]],"who":[["伊達稙宗","城を築いたともいわれる伊達家14代当主"],["堀越宗範","城主。二本松の畠山氏に寝返った"],["伊達実元","大森城主。城を奪い返した。伊達成実の父"],["畠山氏（二本松氏）","南の二本松城主。伊達と境を争った"]],"deep":["城全体の規模は東西約400m・南北約450m。山頂の本丸は東西40m・南北50mほどで、南に細長い曲輪、その下に帯曲輪がめぐります。","城の南には安達峠まで約1kmの平地が広がり、南から来る敵を見張るのに絶好の位置でした。","ふもとの八丁目宿は、奥州街道に米沢街道（土湯街道）と相馬街道が合流する交通の要で、二本松と福島の城下のちょうど中間にありました。","支城の土合館は、街道をはさんで東へ約800mの土合山にありました。二つの城で街道をはさみこむ形です。","松川事件（1949年）は、のちに被告全員の無罪が確定した事件として知られます。現場付近には記念の塔が立っています。"],"look":["山頂の愛宕神社・八幡神社","残りのよい土塁のあと","中腹から見る旧八丁目宿の町並み","東の土合舘公園（あじさいの名所）"],"q":["«八丁目城» の名前の由来は?","郡境の境川から «八町» の距離にあることからといわれます。"],"koji":[],"myth":"築城者・築城年は不明（伊達稙宗説など）。","img":["伊達実元","伊達稙宗","松川事件","奥州街道"],"wp":"八丁目城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:4/43/Date_Tanemune.JPG",1810,1849,"伊達稙宗"],["c:a/aa/Matsukawa_Incident.JPG",526,316,"松川事件"]]},{"id":"07_otori_jo","n":"大鳥城（信夫佐藤氏）","yomi":"おおとりじょう","cat":"城","rank":"B","y":1189,"era":["heian","kamakura"],"sh":"","ad":"福島市飯坂町字舘ノ山（舘ノ山公園）","st":"福島交通飯坂線・飯坂温泉駅から歩いて約15分","la":37.8319,"lo":140.4372,"hook":"山のてっぺんに一羽の鶴を埋め、«大鳥に変じて敵をはばめ» と祈った――温泉街を見下ろす丘は、義経の忠臣・佐藤兄弟の父の城だった。","lead":"大鳥城は、飯坂温泉の町の西にある舘ノ山にあった城です。平安時代の終わり、源義経に仕えた佐藤継信・忠信兄弟の父、佐藤基治の城だったと伝わります。今は «舘ノ山公園» として整備され、アジサイの名所になっています。","story":["飯坂温泉の町を歩くと、西にこんもりした山が見えます。舘ノ山です。平安時代の終わり、ここに城をかまえたのが、信夫（しのぶ）の荘をまかされていた佐藤基治でした。«湯の庄司» とも呼ばれたといいます。平泉の藤原秀衡の命で、白河や会津までの代官になり、この城を築いたと地元の記録は伝えています。","基治の息子の継信・忠信兄弟は、源義経に仕え、平家との戦いで命を落としました。その義経を、兄の頼朝は許しませんでした。義経が平泉で亡くなったあと、1189年、頼朝は大軍をひきいて奥州に攻めこみます。奥州合戦です。","佐藤基治は石那坂（いしなざか）で陣をしき、頼朝の軍を迎え撃ちました。『吾妻鏡』によれば、堀をほって川の水を引きこみ、守りをかためたといいます。伝説では、基治は山の上の本陣に一羽の鶴を埋め、«鶴の魂よ、羽を広げて大鳥となり、敵をはばめ» と祈ったとされます。«大鳥城» の名はここから来たといわれています。","しかし戦いは敗れ、城も落ちたと伝わります。その後、基治ら佐藤一族は許され、しばらく城にもどったとも考えられています。のちに一族の一部は伊勢へ移り、一部は郷士として飯坂に残ったといいます。全国に多い «佐藤» という名字のルーツの一つともいわれます。","1689年、松尾芭蕉は『奥の細道』の旅で、«丸山と云に尋あたる。是庄司が旧館也» と書き、この城跡をたずねたことを記しました。今は遊歩道がめぐり、6月にはアジサイが咲きほこります。山頂から見下ろす温泉街の景色の中に、800年前の攻防を想像してみてください。"],"tl":[["1157年","佐藤基治が藤原秀衡の命で城を築いたと地元の記録は伝える"],["1185年","基治の子・継信が屋島の戦いで討死"],["1189年8月8日","石那坂の戦い。基治らが頼朝軍と戦い敗れる（『吾妻鏡』）"],["1689年","松尾芭蕉が «丸山» をたずねる（『奥の細道』）"],["1880年","城跡が公園として使われはじめる"],["1995年","山頂部の発掘調査"]],"who":[["佐藤基治","信夫の荘をおさめた武士。この城の主"],["佐藤継信・忠信","基治の子。源義経に仕えて命を落とした"],["源頼朝","奥州合戦で奥州藤原氏と佐藤氏をやぶった"],["松尾芭蕉","『奥の細道』で城跡をおとずれた"]],"deep":["大鳥城は «鵬（おおとり）城» «丸山» とも呼ばれます。南に小川、北に赤川、東に摺上川が流れ、三つの川が天然の堀の役目をしていました。","『吾妻鏡』の «石那坂の戦い» の場所はどこか。福島市南部とする説のほかに、この大鳥城こそが戦いの舞台だったとする説も出されており、議論が続いています（«石那坂» は飯坂の古い名とみる考え）。","1995年の発掘調査で、山頂部から14世紀の輸入陶磁器などが見つかっており、基治の時代よりあとにも城として使われていたことがわかります。","基治の館は、いまの大鳥中学校や飯坂球場のある東のふもと（«赤舘» という地名が残る）にあったと推定され、さらに東の «大門» の地名は大手門のなごりとみられています。","城を築いた年を1157年とするのは、江戸時代の地誌『信達一統志』にのる伝承です。"],"look":["山頂の主郭と «大鳥城跡» の碑","主郭の西の «櫓跡» と呼ばれる曲輪","遊歩道ぞいのアジサイ（6〜7月）","近くの医王寺（佐藤一族の菩提寺）とあわせてめぐる"],"q":["«大鳥城» の名前の由来として伝わる話は?","基治が山頂に鶴を埋め、«大鳥となって敵をはばめ» と祈ったという伝説です。"],"koji":[],"myth":"築城年、鶴の伝説、石那坂の場所は伝承・諸説。","img":["佐藤基治","医王寺 (福島市)","飯坂温泉","奥州合戦"],"wp":"大鳥城","rel":{"ev":[],"grave":[]},"ph":[["c:5/5e/%E8%88%98%E3%81%AE%E5%B1%B1%E5%85%AC%E5%9C%92%E5%B1%B1%E9%A0%82.jpg",3840,2160,"大鳥城"],["c:1/11/%E9%A3%AF%E5%9D%82%EF%BC%88%E8%88%98%E3%81%AE%E5%B1%B1%E5%85%AC%E5%9C%92%EF%BC%89.JPG",4608,3456],["c:2/27/Yakushidou_Iouji_%28Fukushima%29.JPG",3523,2730,"医王寺 (福島市)"],["c:0/0e/Iizaka_Onsen_26-Aug-2018.jpg",6016,4016,"飯坂温泉"],["c:1/1c/%E5%A5%A5%E5%B7%9E%E9%AB%98%E9%A4%A8%E5%A4%A7%E5%90%88%E6%88%A6.jpg",1925,950,"奥州合戦"]]},{"id":"07_odaka_jo","n":"小高城（相馬氏の最初の城）","yomi":"おだかじょう","cat":"城","rank":"A","y":1336,"era":["kamakura","muromachi","azuchi"],"sh":"県指定史跡","ad":"南相馬市小高区小高（相馬小高神社）","st":"JR常磐線・小高駅から歩いて約15分","la":37.5683,"lo":140.9906,"hook":"水と湿地に三方を囲まれ、まるで浮かぶ船のよう――«浮船城» と呼ばれた城から、奥州の相馬氏の長い歴史が始まった。","lead":"小高城は、南相馬市小高区にあった相馬氏の最初の本拠地です。南北朝時代から、中村城へ移るまで約260年間、相馬氏の城でした。別名 «紅梅山浮船城»。いま本丸跡には相馬小高神社がまつられ、相馬野馬追の «野馬懸（のまかけ）» が行われる場所として知られています。","story":["相馬氏のふるさとは、下総国（千葉県・茨城県）の相馬郡です。一族は鎌倉時代に陸奥国の行方郡（なめかたぐん）の土地も得ていて、鎌倉時代の終わりごろ、相馬重胤が一族をひきいて移ってきたと伝わります。相馬氏は、平将門の流れをくむ家と伝え、将門ゆかりの妙見菩薩を守り神にしていました。","南北朝時代、相馬氏は足利尊氏の北朝方につきました。1336年、南朝方の北畠顕家の軍勢に攻められ、小高城は一度落ちます。このとき城を守っていた一族の多くが命を落としたと伝わります。けれど翌1337年、相馬氏は城を取りもどしました。ここから、この城は約260年にわたって相馬氏の拠点になります。","城のまわりは、南を小高川、西から北を水田（かつての堀とみられる）に囲まれていました。三方が水と湿地で、まるで水に浮かぶ船。«浮船城» の名はそこから来たといいます。とはいえ城は小さく、守りにはあまり強くありませんでした。そこで近くの丘にいくつもの出城をおいて守ったといわれます。","戦国時代、相馬氏は北の伊達氏と激しく争いました。小高から北の中村に城代をおき、伊達をにらむ形です。1600年の関ヶ原の戦いでは佐竹氏と歩調を合わせたため、戦後いったん領地を取り上げられてしまいます。ところが意外にも、長年の宿敵・伊達政宗のとりなしもあって旧領にもどることができ、1611年、本拠は中村城に移されました。","城のあとには、相馬氏の守り神・妙見をまつる相馬小高神社が建っています。毎年の相馬野馬追では、白装束の男たちが裸馬を素手で取り押さえて神に納める «野馬懸» がここで行われます。2011年の原発事故で小高の人びとは長く避難を強いられましたが、野馬懸は守りつがれてきました。"],"tl":[["鎌倉時代末","相馬重胤が下総から行方郡へ移ったと伝わる"],["1336年","北畠顕家の南朝軍に攻められ落城"],["1337年","相馬氏が城を奪い返す"],["戦国時代","伊達氏との抗争が激しくなり、中村に城代をおく"],["1600年","関ヶ原の戦いのあと、相馬氏はいったん改易される"],["1611年","本拠を中村城へ移す"],["1958年","福島県の史跡に指定"]],"who":[["相馬重胤","下総から奥州へ移ってきたと伝わる相馬氏の当主"],["北畠顕家","南朝方の武将。1336年に小高城を攻めた"],["相馬義胤","16代当主。本拠を小高から移した"],["伊達政宗","宿敵だったが、関ヶ原後の相馬氏の復帰をとりなしたといわれる"]],"deep":["本丸を丘の付け根の堀切で切り、南の小高川を外堀にした城です。城の東に «弁天池» と呼ばれる堀のあとが残ります。","大手（正面の入口）は東側でした。いまの南側の参道は後の時代のもので、城の遺構とは関係ありません。土塁は神社の裏（北面）がよく残っています。","相馬氏が小高を本拠にしたのは、南の岩城氏をけん制するためだったと考えられています。北の伊達氏との争いが激しくなると、北の中村の重要性が高まりました。","相馬氏は途中、牛越城に本拠を移した時期もあり、その後小高にもどって、最後に中村へ移りました。","«野馬懸» は、国の重要無形民俗文化財 «相馬野馬追» の神事のひとつです。"],"look":["本丸跡の相馬小高神社","神社の裏に残る土塁","城の東の «弁天池»（堀のあと）","野馬追の時期の «野馬懸»"],"q":["小高城が «浮船城» と呼ばれたのはなぜ?","三方を川や水田・湿地に囲まれ、水に浮かぶ船のように見えたからといわれます。"],"koji":[],"myth":"重胤の移住年、1336年の落城のくわしい経過、伊達政宗のとりなしは諸説・伝承をふくむ。","img":["相馬氏","相馬小高神社","相馬野馬追","中村藩"],"wp":"小高城","rel":{"ev":[],"grave":[]},"ph":[["c:e/e4/Odaka_Castle.jpg",1600,1200,"小高城"],["c:d/d7/%E5%B0%8F%E9%AB%98%E7%A5%9E%E7%A4%BE%E6%8B%9D%E6%AE%BF.JPG",5184,3456],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:1/15/The_Soma_Nomaoi_2005-5.jpg",960,1280,"相馬野馬追"]]},{"id":"07_soma_jinja","n":"相馬中村神社（野馬追の出陣地）","yomi":"そうまなかむらじんじゃ","cat":"寺社","rank":"B","y":1643,"era":["edo"],"sh":"国の重要文化財（本殿・幣殿・拝殿）","ad":"相馬市中村字北町","st":"JR常磐線・相馬駅から歩いて約15分","la":37.7971,"lo":140.9135,"hook":"ほら貝が鳴り、甲冑の騎馬武者がずらりと並ぶ。相馬野馬追の «出陣» は、江戸時代の社殿の前から始まる。","lead":"相馬中村神社は、相馬中村藩の城・中村城の中にまつられた相馬氏の守り神の神社です。1643年に建てられた本殿・幣殿・拝殿は国の重要文化財。相馬野馬追の出陣式がここで行われることで知られています。","story":["相馬氏は、平安時代の武将・平将門の流れをくむ家と伝えます。将門は妙見菩薩を信じ、下総国に妙見社を建てたといわれます。相馬氏はその信仰を受けつぎ、奥州に移ってからも妙見を一族の守り神としてまつってきました。","1600年の関ヶ原の戦いのあと、相馬氏はいったん領地を取り上げられましたが、なんとか旧領にもどることができました。1611年、初代藩主の相馬利胤は、本拠を中村城に移し、城の南西に妙見社を建てました。これが相馬中村神社のはじまりです。«家をつぶさずにすんだのは、妙見さまのおかげ»――そんな感謝の気持ちもあったのかもしれません。","いまの社殿は1643年、2代藩主の相馬義胤が建てたものです。本殿・幣殿・拝殿が一つにつながった形で、江戸時代はじめの華やかな技が見られます。国の重要文化財に指定されています。","明治時代になると、神と仏を分ける政策（神仏分離）によって、本尊の妙見菩薩はまつられなくなり、名前も «相馬中村神社» に改められました。«妙見さま» から «神社» へ。名前が変わっても、町の人びとは今も親しみをこめて «妙見さま» と呼ぶことがあります。","相馬野馬追の日、この神社には甲冑を身につけた騎馬武者が集まり、出陣式が行われます。«いざ、出陣!»。ほら貝の音とともに、武者たちは雲雀ヶ原の祭場地をめざして町をねり歩きます。平将門が野に放った馬を敵に見立てて訓練したのが始まり――そんな伝説をもつ祭りの、スタートの場所なのです。"],"tl":[["承平年間（931〜937年）","平将門が下総国に妙見社を建てたと伝わる"],["1611年","相馬利胤が中村城に本拠を移し、城内に妙見社を建てる"],["1643年","2代藩主・相馬義胤がいまの社殿を建てる"],["明治時代はじめ","神仏分離で妙見菩薩の本尊が廃され、相馬中村神社と改称"],["1880年","中村城本丸跡に別に相馬神社が建てられる"],["2021年・2022年","福島県沖地震で大鳥居などが被害を受ける"]],"who":[["相馬利胤","中村藩初代藩主。神社を創建した"],["相馬義胤（2代藩主）","いまの社殿を建てた"],["平将門","相馬氏の祖と伝わる。妙見信仰と野馬追の伝説の人物"],["田代家","代々の宮司をつとめる家"]],"deep":["重要文化財の指定は «本殿・幣殿・拝殿（1棟）» と、付属する «宮殿（くうでん）1基»。三つの建物が一棟につながった構成です。","中村城の本丸跡には、明治になって建てられた «相馬神社» もあります。名前が似ているので、中村神社（妙見）と相馬神社（相馬氏の祖先をまつる）を区別しましょう。","宮司は初代・田代信盛から田代家が代々つとめ、29代を数えると伝わります。","かつて境内には厩舎があり、引退した競走馬が飼われていました。2019年ごろ厩舎は解体されています。","1928年に建てられたコンクリートの大鳥居は2021年の地震で傷み、その後ステンレス製の大鳥居が寄進されることになりました。"],"look":["1643年の本殿・幣殿・拝殿","中村城（馬陵城）の堀や大手門跡","神社入口の馬の像","野馬追の出陣式"],"q":["相馬中村神社の神さま（祭神）はもとは何としてまつられていた?","妙見菩薩。明治の神仏分離で天之御中主神をまつる神社になりました。"],"koji":[],"myth":"平将門を祖とする家伝、妙見社創建、野馬追の起源は伝承。","img":["相馬野馬追","中村藩","相馬利胤","妙見信仰"],"wp":"相馬中村神社","rel":{"ev":[],"grave":[]},"ph":[["c:7/77/Somanakamura_shrine.jpg",1600,1600,"相馬中村神社"],["c:c/c6/Soma_otemon.JPG",3072,2304],["c:e/e2/Nakamura_shrine_003.JPG",3072,2304],["c:1/15/The_Soma_Nomaoi_2005-5.jpg",960,1280,"相馬野馬追"],["c:0/08/Souma_Toshitane.jpg",989,990,"相馬利胤"],["c:7/71/%E5%A6%99%E8%A6%8B%E8%8F%A9%E8%96%A9_-_My%C5%8Dken_Bosatsu_%2801%29.jpg",800,607,"妙見信仰"]]},{"id":"07_kameyamori","n":"亀ヶ森古墳","yomi":"かめがもりこふん","cat":"遺跡","rank":"B","y":370,"era":["kofun"],"sh":"国指定史跡（亀ヶ森・鎮守森古墳）","ad":"河沼郡会津坂下町青津","st":"JR只見線・会津坂下駅から車で約10分","la":37.593,"lo":139.8291,"hook":"長さ約130m。会津の田んぼの中に、東北で2番目に大きな古墳が «亀» のように横たわっている。","lead":"亀ヶ森古墳は、会津坂下町にある古墳時代前期の前方後円墳です。長さは約129m。福島県でいちばん、東北地方では2番目に大きい古墳です。すぐ南には前方後方墳の鎮守森古墳があり、2つあわせて国の史跡になっています。","story":["会津盆地の西、田んぼが広がる中に、木々におおわれた細長い丘があります。それが亀ヶ森古墳です。近づくと、丘の上には稲荷神社や観音堂があって、ふつうの神社の森のようにも見えます。でもこれは、1600年以上前に人の手で土を盛ってつくった、王のお墓なのです。","つくられたのは4世紀の後半ごろ。まだ文字の記録もほとんどない時代に、会津にはこれほど大きな古墳をきずける力をもった人がいました。近畿地方の «ヤマト» の勢力とも結びついていたと考えられています。«どうして会津に、こんなに大きなお墓が?»――会津盆地は、東北の中でも早くから開けた土地だったのです。","«亀» という名前には、意外な理由があります。1611年、会津で大地震が起き、川がせき止められて «山崎新湖» という湖ができました。古墳のまわりも水につかり、水面から古墳の頭だけが出ているすがたが、亀のように見えたのだといわれます。江戸時代の『新編会津風土記』では «大亀甲舘» と呼ばれています。","長いあいだ、この古墳は大きな円墳だと思われていました。1957年の測量で前方後円墳だとわかり、その後の発掘調査で、表面を川原石でおおった «葺石» や、壺の形の埴輪などが見つかりました。まわりには馬のひづめの形の堀がめぐっていたこともわかっています。","すぐ南の鎮守森古墳は、長さ約55mの前方後方墳。前が四角、後ろも四角という形です。二つの古墳は向きをそろえて並び、ほぼ同じころにつくられました。会津の首長たちが、どんな形のお墓を選んだのか。その違いにも、古墳時代の人びとの考えがかくれています。"],"tl":[["4世紀後半","亀ヶ森古墳・鎮守森古墳がつくられる"],["1611年","会津地震で山崎新湖ができ、古墳のまわりが水没"],["1809年","『新編会津風土記』に «大亀甲舘» として記される"],["1957年","測量調査で前方後円墳と確認される"],["1969年","福島県の史跡に指定"],["1976年","鎮守森古墳とあわせて国の史跡に指定"],["1992年以降","数次にわたる発掘調査"]],"who":[["古墳にねむる会津の首長","名前はわかっていない。会津盆地をおさめた有力者"],["山口弥一郎","1957年に測量調査を行い、前方後円墳と報告した研究者"],["会津坂下町の人びと","古墳を守り、調査を続けてきた"]],"deep":["墳丘長は129.4m。後円部は直径約74mで3段に築かれ、前方部は長さ約55m・幅約56m。東北では宮城県名取市の雷神山古墳に次ぐ大きさです。","墳丘には中世に城館が築かれたことがあり、後円部に稲荷神社と観音堂（会津三十三観音の三十二番札所）、前方部は墓地として使われたため、形がかなり変わっています。","墳丘の下からは、わき水から墳丘を守る、あるいは補強するための «礫敷（れきじき）» が見つかっています。湿った低地に大古墳をきずくための工夫です。","鎮守森古墳は墳丘長55.2mの前方後方墳で、後方部の上に八幡神社がまつられています。葺石は見つかっていません。","会津若松市の会津大塚山古墳とならび、会津盆地の古墳時代を考えるうえで欠かせない古墳です。"],"look":["後円部の上の稲荷神社と観音堂","田んぼの中から見る墳丘の長いシルエット","南どなりの鎮守森古墳（前方後方墳）","周囲の地形に残る周堀のなごり"],"q":["亀ヶ森古墳の «亀» の名は何に由来するといわれる?","1611年の地震でできた湖に囲まれ、亀の甲羅のように見えたことからといわれます。"],"koji":[],"myth":"«亀» の名の由来は伝承。埋葬者は不明。","img":["会津坂下町","前方後円墳","会津大塚山古墳","雷神山古墳"],"wp":"亀ヶ森古墳","rel":{"ev":[],"grave":[]},"ph":[["c:e/e5/Kamegamori-kofun_and_Chinjumori-kofun.JPG",6016,4000,"亀ヶ森古墳"],["c:b/ba/Kamegamori-kofun_zenkei-1.JPG",6016,4000],["c:d/d0/Kamegamori-kofun_kouenbu.jpg",6000,3976],["c:f/fa/Kamegamori-kofun_funchou-3.jpg",6010,3990],["c:c/c0/Kamegamori-kofun_funchou-1.JPG",6016,4000],["c:b/be/Chinjumori-kofun_zenkei.JPG",6016,4000],["c:b/b3/Chinjumori-kofun_funchou.JPG",6016,4000],["c:c/ce/%E6%81%B5%E9%9A%86%E5%AF%BA%E8%A6%B3%E9%9F%B3%E5%A0%82_%28Eryuji_Kannondo%29.jpg",2816,2112,"会津坂下町"]]},{"id":"07_nakata_yokoana","n":"中田横穴（装飾横穴）","yomi":"なかだよこあな","cat":"遺跡","rank":"B","y":575,"era":["kofun"],"sh":"国指定史跡","ad":"いわき市平沼ノ内","st":"JR常磐線・いわき駅から車で約20分。内部は非公開（震災後、公開停止）","la":37.0058,"lo":140.9668,"hook":"丘の斜面にあいた小さな穴の奥で、赤と白の三角形が壁一面をうめつくしていた。床まで真っ赤にぬられた、1400年前の «赤い部屋»。","lead":"中田横穴は、いわき市の海に近い丘にある古墳時代の横穴墓（おう穴をほったお墓）です。1969年の道路工事で見つかり、1号横穴の奥の部屋には、赤と白の三角形の模様がびっしりと描かれていました。国の史跡です。","story":["1969年、いわき市沼ノ内で道路工事をしていたときのことです。丘の斜面から、ぽっかりと穴があらわれました。のぞいてみると、中はきちんとした部屋になっていて、壁には色あざやかな模様。工事の人たちは、どんなにおどろいたことでしょう。","見つかった横穴は5つ。斜面に三段に並んでいました。いちばん下の1号横穴は、入口の通路から部屋が二つつづく «複室» のつくりで、全長は6.67m。通路には水をぬく溝まであり、入口をふさぐ工夫も残っていました。","奥の部屋に入ると、三方の壁に、一辺40cmほどの赤と白の三角形が三段にならんでいます。上の段は逆さの三角、下の二段は上向きの三角。多くは細い線で輪郭を下書きしてから色をぬっていました。さらにめずらしいのは、床一面が赤くぬられていたことです。«なぜ、三角形なのか?»――魔よけ、または死者の世界を守るしるしだったという考えもありますが、答えはまだわかっていません。","部屋からは、たくさんの品が出てきました。玉、直刀、よろいのかけら、金の耳輪、金銅の馬具、大きな金銅の鈴、鏡、須恵器……。この地域の有力者がほうむられたのでしょう。調べると、ほうむられたのは一人で、何年かたってから副葬品をいったん取り出し、墓の前でまつりをしたらしいこともわかりました。","横穴は6世紀後半につくられたと考えられます。見つかったあと、保存のための建物がつくられ、見学できる日もありましたが、東日本大震災で施設が被害を受け、公開は止まっています。壁画は光や空気にとても弱く、守りながら伝えていく努力が続いています。"],"tl":[["6世紀後半","中田横穴がつくられる"],["1969年","道路工事中に発見される"],["1970年5月11日","国の史跡に指定"],["2011年","東日本大震災で保存施設が被害を受け、公開停止"]],"who":[["ほうむられた地域の有力者","名前はわからない。豊かな副葬品とともにほうむられた"],["道路工事の人びと","横穴を発見した"],["いわき市の研究者","発掘と保存に取り組んだ"]],"deep":["装飾は後室の三方の壁に、赤と白の三角連続文（一辺約40cm）を三段に配したもの。赤い三角形の中には、白い顔料を下地にぬってから描いた部分もあります。","後室の前の壁（入口の上）には、赤一色で、2本の弧の間にギザギザの «鋸歯文（きょしもん）» が描かれています。","床一面の赤い彩色は、装飾横穴の中でもとくにめずらしい例として注目されています。","副葬品には挂甲（小札をつないだよろい）の破片、金銅製の雲珠や馬鈴、鈴杏葉、珠文鏡、銅製容器のふたなどがあり、地方の有力者の豊かさを示しています。","三角文の装飾横穴や装飾古墳は九州に多く、福島県の浜通り・中通りにも点在します。遠くはなれた地域が、同じような模様を使っている理由は研究の課題です。"],"look":["丘の斜面に三段に並ぶ横穴の位置（外から）","史跡の案内板","いわき市内の資料館などでの展示・写真（見学前に確認を）"],"q":["中田横穴1号の壁に描かれていた模様の基本の形は?","赤と白の三角形（三角連続文）です。床も赤くぬられていました。"],"koji":[],"myth":"三角文の意味は諸説。","img":["装飾古墳","横穴墓","いわき市","羽山横穴"],"wp":"中田横穴","rel":{"ev":[],"grave":[]},"ph":[["j:7/72/%E7%8E%8B%E5%A1%9A%E5%8F%A4%E5%A2%B3_%28%E6%A1%82%E5%B7%9D%E7%94%BA%29_%E7%9F%B3%E5%AE%A4%E3%83%AC%E3%83%97%E3%83%AA%E3%82%AB.JPG",5502,3665,"装飾古墳"],["j:1/18/Yoshimi_Yoshimi-hyakuana_2.JPG",3264,2448,"横穴墓"],["c:6/68/Iwaki_Montage_2.jpg",1024,1014,"いわき市"]]},{"id":"07_hayama_yokoana","n":"羽山横穴","yomi":"はやまよこあな","cat":"遺跡","rank":"B","y":610,"era":["kofun","asuka"],"sh":"国指定史跡","ad":"南相馬市原町区中太田","st":"JR常磐線・原ノ町駅から車で約15分。内部は一般公開停止中（レプリカは南相馬市博物館）","la":37.6144,"lo":140.9574,"hook":"白い鹿、赤い点々、渦まき、そして馬に乗る人。宅地造成の土の中から、1400年前の «絵本» のような壁画があらわれた。","lead":"羽山横穴は、南相馬市原町区の丘の斜面にほられた古墳時代の終わりごろのお墓（横穴墓）です。1973年に宅地の工事中に見つかり、奥の壁に人や馬、白い鹿、渦まき模様などがいきいきと描かれていました。国の史跡で、原寸大のレプリカが南相馬市博物館で見られます。","story":["1973年、南相馬市（当時は原町市）の太田川の北の丘で、宅地をつくる工事が進んでいました。そのとき、斜面から横穴があらわれます。このあたりには数十の横穴が集まっていて、そのうちの一つでした。中をのぞいた人たちは、息をのみました。奥の壁一面に、赤と白の絵が描かれていたのです。","横穴は全長8.32m。前庭、通路（羨道）、そして四角い部屋（玄室）がつづきます。奥の壁には、酸化鉄の赤で描いた人物や馬、ギザギザの模様。さらに、白い粘土をぬった上に赤い斑点をちりばめた «白い鹿»、5本の赤と白の線でつながった渦まき模様、赤い鹿も描かれていました。","天井と奥の壁には、赤と白の丸い点が250以上もちりばめられています。まるで夜空の星のようです。«この人は、死んだあと、どんな世界へ旅立つと考えられていたのだろう?»――馬に乗る人の姿は、あの世への旅を表しているのでは、という見方もあります。","部屋からは、金銅でかざった大刀、小刀、青銅の腕輪、ガラスの小玉、馬具、須恵器などが出てきました。これらから、7世紀のはじめごろにつくられたと考えられています。馬具がそろっていることから、馬を大切にした地域の有力者のお墓だったのでしょう。この地方が、のちに «野馬追» で知られる馬の里になることを思うと、不思議なつながりを感じます。","かつては春と秋に年4回、数時間ずつ一般公開されていましたが、東日本大震災のあと、一般公開は止まっています。壁画はとてもこわれやすく、湿度や温度の変化にも弱いからです。そのかわり、南相馬市博物館では原寸大のレプリカと出土品を見ることができます。"],"tl":[["7世紀初め","羽山横穴がつくられる"],["1973年","宅地造成中に偶然発見される"],["1974年12月23日","国の史跡に指定"],["2011年","東日本大震災のあと、一般公開が中止される"]],"who":[["ほうむられた地域の有力者","名前は不明。馬具や飾り大刀とともにほうむられた"],["南相馬市博物館","原寸大レプリカと出土品を展示している"],["発見・調査にかかわった人びと","工事中の発見を記録し、保存につなげた"]],"deep":["壁画の顔料は、赤が酸化鉄（ベンガラ）、白が白色粘土。白い鹿は、白い下地の上に赤い斑点をのせて、鹿の子模様を表しています。","渦まき模様を5本の紅白の線でつないだ図柄は、ほかにあまり例がなく、意味は諸説あります。","玄室の奥壁の幅は2.79m、側壁の長さは2.9m前後。人が立って入れるほどの広さの部屋に、壁画がびっしり描かれていました。","出土品の金銅装の大刀、轡（くつわ）、辻金具などの馬具は、ほうむられた人が地域の有力者だったことを示します。","福島県の浜通りには、双葉町の清戸迫横穴、いわき市の中田横穴など、彩色壁画をもつ横穴墓がいくつもあり、東北の装飾古墳の集中地域になっています。"],"look":["南相馬市博物館の原寸大レプリカ","出土した大刀・馬具などの展示","現地の案内板と横穴群のある丘（内部は非公開）"],"q":["羽山横穴の壁画に描かれた、赤い斑点のある動物は何?","白い鹿です。白い下地の上に赤い点をちりばめて描かれています。"],"koji":[],"myth":"壁画の意味（あの世への旅など）は推測・諸説。","img":["装飾古墳","横穴墓","南相馬市","中田横穴"],"wp":"羽山横穴","rel":{"ev":[],"grave":[]},"ph":[["j:7/72/%E7%8E%8B%E5%A1%9A%E5%8F%A4%E5%A2%B3_%28%E6%A1%82%E5%B7%9D%E7%94%BA%29_%E7%9F%B3%E5%AE%A4%E3%83%AC%E3%83%97%E3%83%AA%E3%82%AB.JPG",5502,3665,"装飾古墳"],["j:1/18/Yoshimi_Yoshimi-hyakuana_2.JPG",3264,2448,"横穴墓"],["c:c/c7/The_Soma_Nomaoi_2005-6.jpg",1280,960,"南相馬市"]]},{"id":"07_wadai","n":"和台遺跡（人体文土器）","yomi":"わだいいせき","cat":"遺跡","rank":"B","y":-2500,"era":["jomon"],"sh":"国指定史跡","ad":"福島市飯野町明治字南和台","st":"車が便利（福島市中心部から車で約40分）","la":37.6506,"lo":140.5292,"hook":"土器の胴から、身長20cmの «人» がこちらを見つめている。全国でもほとんど例のない土器が、橋の工事現場から出てきた。","lead":"和台遺跡は、福島市飯野町にある縄文時代中期の大きなムラの跡です。家々がドーナツのように輪になってならぶ «環状集落» で、約230軒の竪穴建物が見つかりました。人の姿をかたどった «人体文土器» など、めずらしい土器も出土しています。国の史跡です。","story":["阿武隈川が «レ» の字のように大きく曲がるところ。その上の、標高約195mの台地の先に、和台遺跡はあります。1996年、新しい橋（新飯野橋）への道をつくるために台地をけずったところ、縄文時代のムラが見つかりました。橋の工事のパンフレットには «みちから見つかったロマン» と紹介されたそうです。","調べてみると、ここには約230軒の竪穴建物がありました。まん中に広場があり、そのまわりに柱で建てた建物、さらに外側に竪穴建物が輪になってならぶ、ドーナツのような形のムラです。広場のまわりにはお墓らしい穴もあり、«ご先祖さまをまつる広場» だったのかもしれません。","いちばん注目されたのが «人体文土器» です。ある竪穴建物の床のまん中に、すっぽり埋められていました。高さ32cmの土器の胴に、身長20cmほどの人の姿。顔のつくりはとてもていねいで、芸術品のようです。«なぜ、人の姿を?» 祭りや儀式に使われ、そのあと炉として使われたのではないかと考えられています。","«狩猟文土器» も見つかりました。木や動物、わな、落とし穴などが描かれた土器で、それまで青森県や岩手県など北東北でしか見つかっていませんでした。南東北ではじめての発見で、«縄文人の交流はもっと広かった» ことを示しています。ヒスイや黒曜石、海の魚の骨も出てきました。","ムラは約200年つづいたあと、急におとろえ、すてられました。その理由はまだわかりません。遺跡を守るため、橋への道は遺跡の下をトンネルでくぐる計画に変えられました。2006年、国の史跡に指定されています。"],"tl":[["約4500年前ごろ","縄文時代中期末、ムラが最も栄える（大木10式期）"],["1996年","新飯野橋への道路工事で発見される"],["2000年","遺跡を守るためトンネル方式に変えた新飯野橋が完成"],["2006年7月28日","国の史跡に指定"],["2008年","飯野町が福島市と合併。«和台・宮畑遺跡縄文まつり» が開かれる"]],"who":[["和台のムラの縄文人","約200年にわたって台地に暮らした人びと"],["福島県教育委員会","発掘調査を行った"],["工事の関係者","道路計画を変えて遺跡を残した"]],"deep":["見つかった遺構は、竪穴建物約230軒のほか、掘立柱建物、土器を埋めた «埋甕（うめがめ）»、たくさんの土坑（貯蔵穴やお墓とみられる穴）です。","竪穴建物の多くには «複式炉» がついています。石組みの炉と土器を埋めた部分を組み合わせた炉で、縄文時代中期後半の南東北に特徴的なものです。","人骨は1体だけ見つかっていて、焼かれていたために残ったものです。当時は土葬がふつうだったのに、なぜこの1体だけが焼かれたのかは謎です。","遺跡の広さは約5万㎡と推定され、南東北で最大級の縄文集落です。大量の土器をつくったはずなのに、粘土をとった跡が見つかっていないことも謎の一つです。","人体文土器と狩猟文土器は福島県の重要文化財に指定されています。"],"look":["阿武隈川の曲がりを見下ろす台地の地形","史跡の案内板と、遺跡の下をくぐるトンネル","人体文土器・狩猟文土器の展示（展示場所は事前に確認を）"],"q":["和台遺跡のように、家が輪のように並ぶ縄文のムラを何という?","«環状集落»。まん中に広場があります。"],"koji":[],"myth":"人体文土器の使い方、ムラが消えた理由は推測・諸説。","img":["縄文土器","環状集落","飯野町 (福島県)","宮畑遺跡"],"wp":"和台遺跡","rel":{"ev":[],"grave":[]},"ph":[["j:9/94/%E5%92%8C%E5%8F%B0%E9%81%BA%E8%B7%A1_%E5%BC%93%E7%9F%A2%E3%81%8C%E6%8F%8F%E3%81%8B%E3%82%8C%E3%81%9F%E7%8B%A9%E7%8C%9F%E6%96%87%E5%9C%9F%E5%99%A8.JPG",4691,3515],["j:3/30/%E5%92%8C%E5%8F%B0%E9%81%BA%E8%B7%A1_%E4%BA%BA%E4%BD%93%E6%96%87%E4%BB%98%E3%81%8D%E5%9C%9F%E5%99%A8.JPG",3354,3360],["j:6/63/%E7%AC%B9%E5%B1%B1%E9%81%BA%E8%B7%A1%E5%87%BA%E5%9C%9F_%E7%81%AB%E7%84%94%E5%9E%8B%E5%9C%9F%E5%99%A8_%28%E6%B7%B1%E9%89%A2%E5%BD%A2%29_%28%E5%9B%BD%E5%AE%9D%E6%8C%87%E5%AE%9A%E7%95%AA%E5%8F%B71%29.JPG",3413,3386,"縄文土器"],["c:5/54/Fujimi_Mizukokaiduka_Park_3.JPG",3264,2448,"環状集落"],["c:b/b3/UFO_fureaikan.jpg",1024,768,"飯野町 (福島県)"],["c:0/0b/Miyahata_Site.jpg",1600,1200,"宮畑遺跡"]]},{"id":"07_hoshojiri","n":"法正尻遺跡","yomi":"ほうしょうじりいせき","cat":"遺跡","rank":"B","y":-3000,"era":["jomon"],"sh":"","ad":"耶麻郡磐梯町更科（猪苗代町にかけて）","st":"車が便利。遺跡の多くは磐越自動車道の工事で記録保存され、現地で見られる遺構はほとんどない","la":37.545,"lo":140.01,"hook":"磐梯山のふもと、高速道路の下になった土地から、26万点の遺物があらわれた。そこは «縄文の十字路» だった。","lead":"法正尻遺跡は、磐梯町から猪苗代町にかけての丘にあった、縄文時代中期を中心とする大きなムラの跡です。磐越自動車道の建設にともなう発掘で、100軒をこえる竪穴住居と、たくさんの土器や石器が見つかりました。出土品の一部は国の重要文化財に指定されています。","story":["磐梯山のふもと、猪苗代湖の北西。標高560mほどの丘には、大昔の磐梯山の山くずれでできた小さな丘 «流れ山» がいくつも連なっています。丘と丘のあいだのくぼ地には、わき水がたっぷり。«ここなら水にも困らない»――縄文人がムラをつくるのにぴったりの場所でした。","1980年代の終わり、磐越自動車道をつくるために、この場所が発掘されました。見つかったのは、竪穴住居が120軒以上、貯蔵穴やお墓、落とし穴などの穴が759基、土器を埋めた «埋甕» が26基。遺物は26万点にものぼりました。縄文時代中期のおよそ1000年にわたって、人びとがくらしつづけたムラだったのです。","出てきた土器を見ると、とても不思議なことがわかりました。東北南部の «大木式» の土器を中心に、関東の土器、新潟の «火焔型» の仲間の土器など、あちこちの地方の特徴をもつ土器がまじっていたのです。新潟でとれるヒスイの大きな玉や、各地の黒曜石も見つかりました。«ここは、人と物が行きかう交差点だった»。","住居には、石組みの炉と土器を埋めた部分を組み合わせた «複式炉» がついていました。複式炉は福島県を中心とする南東北の縄文時代中期に特徴的な炉です。一辺11mをこえる大きな長方形の住居も見つかり、ムラのみんなが集まる建物だったのではないかと考えられています。","高速道路ができたいま、遺跡の多くは記録として残され、現地で昔のすがたを見ることはほとんどできません。けれど出土品は大切に保管され、2009年には国の重要文化財になりました。福島県文化財センター白河館 «まほろん» などで、磐梯山ふもとの縄文人のくらしに出会えます。"],"tl":[["約5000〜4000年前","縄文時代中期を中心にムラが栄える"],["1988〜1990年ごろ","磐越自動車道の建設にともない発掘調査"],["2009年7月10日","«福島県法正尻遺跡出土品» が国の重要文化財に指定"],["2020年代","«まほろん» や福島県立博物館で法正尻遺跡の特別展が開かれる"]],"who":[["法正尻のムラの縄文人","磐梯山のふもとで長くくらした人びと"],["福島県の発掘調査員","高速道路建設前に大規模な発掘を行った"],["まほろん（福島県文化財センター白河館）","出土品を保管・展示している"]],"deep":["出土品のうち重要文化財になったのは、土器・土製品・石器・石製品など約800点。文化庁の記録では土器184点、土製品80点、石器・石製品523点です（数え方の違いで855点とする紹介もあります）。","竪穴住居の数は、資料によって120軒、129軒などと紹介されます。前期末から中期末にかけてのものが中心です。","遺跡は縄文時代早期から後期、さらに平安時代の集落もふくむ複合遺跡です。","ヒスイは新潟県糸魚川周辺でとれる石で、各地の黒曜石とあわせて、遠くの地域との交流を物語ります。","磐梯山の山体崩壊でできた «流れ山» 地形の上にある遺跡で、磐梯山ジオパークのジオサイトの一つにもなっています。"],"look":["まほろん（白河市）での出土品展示","磐梯山ジオパークの «流れ山» 地形","猪苗代湖北西岸の丘陵の景色（遺跡そのものの見学は難しい）"],"q":["法正尻遺跡の住居に多い、石組みと土器を組み合わせた炉を何という?","«複式炉»。南東北の縄文時代中期に特徴的な炉です。"],"koji":[],"myth":"住居数・発掘年・出土品数は資料により差がある。","img":["磐梯町","縄文土器","複式炉","磐越自動車道"],"wp":"法正尻遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:2/28/Alts_Bandai_02.jpg",4288,3216,"磐梯町"],["j:6/63/%E7%AC%B9%E5%B1%B1%E9%81%BA%E8%B7%A1%E5%87%BA%E5%9C%9F_%E7%81%AB%E7%84%94%E5%9E%8B%E5%9C%9F%E5%99%A8_%28%E6%B7%B1%E9%89%A2%E5%BD%A2%29_%28%E5%9B%BD%E5%AE%9D%E6%8C%87%E5%AE%9A%E7%95%AA%E5%8F%B71%29.JPG",3413,3386,"縄文土器"],["c:1/1a/Sarashina-Shingojo1.JPG",2000,1502,"近く: 更科信号場"],["c:8/8b/JR_East_Okinashima_Station_building.jpg",5328,4000,"近く: 翁島駅"],["c:7/7f/JR_East_Bandaimachi_Station_building_%28West_Exit%29.jpg",5328,4000,"近く: 磐梯町駅"],["c:0/0d/Bandaisan_Service_Area.jpg",2592,1944,"近く: 磐梯山サービスエリア"]]},{"id":"07_ohata_kaizuka","n":"大畑貝塚","yomi":"おおはたかいづか","cat":"遺跡","rank":"B","y":-2500,"era":["jomon"],"sh":"","ad":"いわき市泉町下川字大畑","st":"JR常磐線・泉駅から車で約10分。現地に目立つ遺構はほとんどない","la":36.937,"lo":140.913,"hook":"鹿の角をけずり、いくつかの部品を組み合わせて作った «組み合わせ釣り針»。縄文の漁師たちの知恵が、小名浜の海辺の丘に眠っていた。","lead":"大畑貝塚は、いわき市泉町の、小名浜の海を見下ろす丘にある縄文時代中期から後期の貝塚です。1970〜72年の発掘で、百本をこえる釣り針や銛など、たくさんの漁の道具が見つかり、«縄文の漁村» のくらしを伝える遺跡として知られています。","story":["いわきの海は、北からの親潮と南からの黒潮がぶつかる、魚の豊かな海です。小名浜の海を見下ろす岬のような丘に、縄文時代の人びとはムラをつくりました。食べた貝のからや魚の骨、動物の骨をすてた場所が積み重なって «貝塚» になったのです。","1970年から72年にかけて、この貝塚が発掘されました。出てきたのは、土器や石器、そしておびただしい数の骨や角でつくった道具です。とくに釣り針は百本あまり。日本の縄文遺跡の中でも、もっとも多いほどの数でした。","中でも注目されたのが «組み合わせ釣り針» です。鹿の角をけずって、軸と針先など別々の部品をつくり、しばり合わせて一本の大きな釣り針にしたもの。«大きな魚をつり上げるには、どうしたら折れない針ができるか?» ――縄文の漁師たちが考えぬいた工夫です。このタイプの釣り針は、いわき地方で特徴的に見つかっています。","漁の道具は、狩りの道具のおよそ2倍も出てきました。ここのムラの人びとは、山より海で生きる «海の民» だったのです。直径30cmもあるアワビの貝がらもたくさん見つかり、海にもぐって大きなアワビをとっていたこともわかります。","貝塚からは、ていねいにほうむられた人の骨や、犬の骨も見つかりました。縄文人にとって犬は、狩りの相棒であり、家族のような存在だったのでしょう。今は現地に目立つものは残っていませんが、出土品はいわき市の考古資料館などで紹介されています。"],"tl":[["約5000〜4000年前","縄文時代中期から後期にかけてムラと貝塚がいとなまれる"],["1970〜1972年","発掘調査が行われ、大量の漁労具が見つかる"],["現在","出土品がいわき市の考古資料館などで紹介されている"]],"who":[["大畑の縄文人","小名浜の海で漁をしてくらした人びと"],["発掘調査の研究者","1970〜72年に貝塚を調査した"],["いわき市考古資料館","いわきの考古資料を展示する施設"]],"deep":["出土した土器は «大木8a式・8b式» と呼ばれる縄文時代中期の型式がほとんどで、角押文・渦巻文・貼付文などが特徴です。","鹿角製の組み合わせ釣り針は、いわき地方の遺跡で特に見つかっている道具で、地域の漁の文化を示す «顔» のような遺物です。","漁労具が狩猟具（石鏃・石槍など）の約2倍という比率は、ムラの生業が海にかたよっていたことを示します。","埋葬された人骨の中には、特色ある葬り方をされた壮年男性の墓があったと報告されています。","石棒（男性のしるしをかたどったとされる石の道具）も出土しており、祈りや祭りのようすを考える手がかりになっています。"],"look":["小名浜の海を見下ろす丘の地形","いわき市考古資料館などの展示（見学前に確認を）","近くの小名浜港から見る海"],"q":["大畑貝塚で注目された、鹿の角の部品を組み合わせて作った道具は?","«組み合わせ釣り針»。いわき地方に特徴的な漁の道具です。"],"koji":[],"myth":"史跡指定の有無は未確認。組み合わせ釣り針の «いわき地方のみ» という評価は資料による。","img":["貝塚","縄文時代","いわき市","小名浜"],"wp":"大畑貝塚","rel":{"ev":[],"grave":[]},"ph":[["c:8/83/Conchero_Arguin.jpg",2048,1536,"貝塚"],["c:6/68/Iwaki_Montage_2.jpg",1024,1014,"いわき市"],["c:d/d4/Aquamarine_Fukushima_20100124.JPG",4000,2672,"近く: アクアマリンふくしま"],["c:d/df/Onahama_high_school.JPG",3648,2736,"近く: 福島県立小名浜高等学校"],["c:b/b7/Iwaki_Kaisei_High_School.JPG",3648,2736,"近く: 福島県立いわき海星高等学校"],["c:2/2c/Iwaki_Lalamew_1.JPG",2800,2100,"近く: いわき・ら・ら・ミュウ"],["c:2/23/%E3%81%84%E3%82%8F%E3%81%8D%E3%83%9E%E3%83%AA%E3%83%B3%E3%82%BF%E3%83%AF%E3%83%BC.jpg",768,1024,"近く: いわきマリンタワー"],["c:b/b3/%E3%81%84%E3%82%8F%E3%81%8D%E5%B8%82%E4%B8%89%E5%B4%8E%E5%85%AC%E5%9C%92.jpg",1024,768,"近く: 三崎公園 (福島県)"]]},{"id":"07_urajiri","n":"浦尻貝塚","yomi":"うらじりかいづか","cat":"遺跡","rank":"B","y":-2500,"era":["jomon","kofun","heian"],"sh":"国指定史跡","ad":"南相馬市小高区浦尻","st":"JR常磐線・小高駅から車で約10分","la":37.5211,"lo":141.0231,"hook":"厚さ1.8mの貝の層。2700年ものあいだ、縄文人は同じ台地で海の恵みを食べつづけた。","lead":"浦尻貝塚は、南相馬市小高区にある、縄文時代前期から晩期（約5700〜3000年前）まで続いたムラと貝塚の跡です。広さは約7ha。アサリやスズキ、シカなど、当時の食べ物がそのまま積み重なっています。2006年に国の史跡になりました。","story":["太平洋に近い、小高の台地。南北にのびる舌のような形の段丘の上に、縄文時代の人びとは住みつきました。それも、ちょっとやそっとの期間ではありません。約5700年前から3000年前まで、なんと2700年近く。«大規模な貝塚をもつ、地域の中心的なムラ» と評価されています。","貝塚は4か所で見つかっていて、大きいものは東西15〜20m、南北30〜40m、厚さは最大で1.8mをこえます。すてた貝がらが、大人の背たけほども積み重なっているのです。«いったい何世代の人が、ここで貝を食べたのだろう?»","貝層をていねいに調べると、何を食べていたかがわかります。いちばん多いのはアサリ。魚ではスズキ、ウナギ、ハゼ、イワシ。陸の動物ではシカやイノシシ、鳥ではカモ。海と川と森、すべての恵みをうまく使っていたのです。","時代が下って縄文時代の晩期になると、ヤマトシジミやフナが増えます。海水と真水がまじる場所や、淡水の場所を使うようになったのです。一方で、大きなサメやマダイ、骨や角でつくった漁の道具も増え、外洋にこぎ出す漁もさかんになったと考えられます。貝塚は、海辺の環境と人のくらしの変化を記録した «年表» でもあるのです。","ムラのまん中は、直径約60mにわたって土をけずって平らにならされていました。みんなで広場をつくった、縄文人の共同作業のあとです。浦尻は、縄文のあとも古墳時代の古墳、平安時代のムラ、中世の豪族の館と、さまざまな時代の人びとがくらした場所でした。"],"tl":[["約5700年前","縄文時代前期、ムラがいとなまれはじめる"],["約3000年前","縄文時代晩期まで貝塚が形成される"],["古墳時代後期","古墳群がつくられる"],["平安時代","集落がいとなまれる"],["2006年12月6日","国の史跡に指定"]],"who":[["浦尻の縄文人","2700年近くこの台地でくらした人びと"],["旧小高町教育委員会","発掘調査を行い、報告書をまとめた"],["南相馬市","史跡の保存と活用に取り組む"]],"deep":["段丘の南側の貝層は縄文時代晩期前半のもので、時代ごとに別の貝塚があるため、食べ物のとり方や海の移り変わりを時代順に追うことができます。","竪穴建物のある中央部は直径約60mにわたって掘りこまれ、平らな場所がつくり出されていました。計画的なムラづくりを示す例です。","台地の上には竪穴建物、柱穴、貯蔵穴、お墓の穴（土坑墓）があり、貝塚と住まいがセットで残る点が重要です。","晩期にヤマトシジミ・フナが増え、大型のサメ類やマダイ、骨角製の漁具も増えることから、汽水・淡水域と外洋の両方の利用が広がったとみられています。","浦尻貝塚は縄文だけでなく、古墳時代後期の古墳群、平安時代の集落、中世の豪族の館と推定される場所をふくむ複合遺跡です。"],"look":["南北にのびる舌状の段丘の地形","史跡の案内板","海に近い立地（縄文時代の海岸線を想像する）"],"q":["浦尻貝塚の貝層でいちばん多く見つかった貝は?","アサリです。晩期にはヤマトシジミも増えました。"],"koji":[],"myth":"","img":["貝塚","縄文時代","南相馬市","小高町"],"wp":"浦尻貝塚","rel":{"ev":[],"grave":[]},"ph":[["c:8/83/Conchero_Arguin.jpg",2048,1536,"貝塚"],["c:c/c7/The_Soma_Nomaoi_2005-6.jpg",1280,960,"南相馬市"],["c:8/8b/Daihizan_Sekibutsu.jpg",1800,1377,"小高町"]]},{"id":"07_negishi","n":"根岸官衙遺跡群（磐城郡家）","yomi":"ねぎしかんがいせきぐん","cat":"遺跡","y":700,"era":["asuka","nara","heian"],"sh":"国指定史跡","rank":"B","ad":"いわき市平下大越","st":"JR常磐線いわき駅から車で約15分（バスの本数は少ない）","la":37.08,"lo":140.927,"hook":"夏井川を見下ろす丘の上に、1300年前の «磐城郡の役所» があった。稲をしまう倉がずらりと並んだ、古代いわきの «県庁» のような場所。","lead":"根岸官衙遺跡群は、奈良時代を中心に «磐城郡（いわきぐん）» を治めた役所（郡家・ぐうけ）の跡です。役所の中心の建物、税の稲をしまう倉庫の列、そしてすぐ近くのお寺（夏井廃寺）がセットで見つかりました。今は建物は残っていませんが、古代の «地方の役所» の姿がよくわかる遺跡です。","story":["いわきの町を流れる夏井川。その河口に近い小高い丘に、今から1300年ほど前、大勢の役人が行き来する役所がありました。丘の上からは川と海の近くの低地が見わたせます。«なぜこの丘に?» ――川を使って物や人を運びやすく、見晴らしがよく、しかも洪水の心配が少ない。役所を置くにはぴったりの場所だったのです。","7世紀の後半、国の仕組みが整えられていくなかで、各地に «評（こおり）»、のちの «郡» が置かれました。ここは磐城郡の中心。村々から集められた税の稲は、丘の一画にずらりと並んだ倉にしまわれました。発掘では、その倉の柱の穴が何十も規則正しく並んで見つかっています。«これだけの倉が満杯になったら、どれほどの稲だったろう»――想像するだけで、当時の郡の力が伝わってきます。","役所の中心は «郡庁（ぐんちょう）»。広場を囲むように建物が建ち、ここで郡の長官である郡司が仕事をし、儀式を行いました。郡司は都から来た役人ではなく、その土地の有力な一族がつとめるのがふつうでした。磐城郡でも、地元の豪族が郡司となって、都の命令と地域の暮らしをつなぐ役目を果たしていたと考えられます。","役所のすぐそばには、瓦ぶきの立派なお寺・夏井廃寺も建てられました。役所とお寺が並ぶのは、この時代の地方の «セット»。郡司の一族が、自分たちの力と信仰を示すためにお寺を建てたと考えられています。丘の上の役所と、川沿いにそびえる塔。古代の旅人の目には、ここが «磐城の都» のように映ったかもしれません。","やがて平安時代が進むと、郡の役所の仕組みはしだいにくずれ、この場所も使われなくなっていきました。建物は失われ、丘は畑や林にもどりました。長い眠りからさめたのは、発掘調査が行われた昭和から平成にかけてのこと。柱の穴一つひとつが、いわきの古代の歴史を語る «文字のない記録» になったのです。"],"tl":[["7世紀後半","この地に磐城評（のちの磐城郡）の役所が置かれたと考えられる"],["701年","大宝律令。«評» が «郡» と呼ばれるようになる"],["718年","陸奥国から «石城国（いわきのくに）» が分けられる（数年でもとにもどる）"],["8世紀","郡庁・倉庫群が整い、役所として最も栄える"],["9〜10世紀ごろ","しだいに役所の役目を終え、使われなくなる"],["昭和〜平成","発掘調査で郡庁や倉の跡が次々に見つかる"],["2011年","夏井廃寺跡とあわせ «根岸官衙遺跡群» として国史跡に"]],"who":[["磐城郡の郡司","地元の有力豪族。この役所で郡を治めた"],["丈部（はせつかべ）氏","磐城郡の豪族。のちに «磐城臣» の姓をもらったと記録される一族"],["律令政府の役人","都から来る国司らが、郡の役所を通して税を集めた"]],"deep":["«官衙（かんが）» とは古代の役所のこと。郡の役所は «郡家（ぐうけ）» または «郡衙（ぐんが）» と呼ばれ、郡庁・正倉（税の倉）・館（宿泊施設）・厨（台所）などで一つのまとまりをつくっていた。","根岸遺跡では、倉庫とみられる建物跡が区画の中に整然と並んで見つかった。税の稲をしまった «正倉» で、倉の数は郡の豊かさを表すものさしにもなる。","『続日本紀』には、奈良時代の後半に陸奥の豪族たちがまとめて新しい姓をもらった記事があり、磐城郡の丈部氏が «磐城臣» を名のることを許されたとされる。郡司一族の姿を知る貴重な手がかりである。","718年、陸奥国の南部を分けて «石城国» がつくられた。石城・標葉・行方・宇太・亘理の郡に、常陸国の菊多郡を加えた国とされるが、わずか数年で陸奥国にもどされた。その理由は、蝦夷との戦いに備えて陸奥をまとめ直すためなど諸説ある。","役所とお寺（夏井廃寺）がすぐ近くに並ぶ形は、全国の郡家に共通して見られる。役所とお寺をセットで国史跡にしたことで、«古代の郡の中心地» を丸ごと守る形になった。","遺跡のある丘は夏井川の下流にあり、川と海につながる場所。税を船で運ぶ «水運» との関わりが指摘されている。"],"look":["丘の上から見下ろす夏井川と低地（古代の役所が見た景色）","すぐ近くの夏井廃寺跡とセットで歩く","いわき市考古資料館などで出土品を見ると、遺跡のイメージがふくらむ","説明板の復元図と、現地の地形を見くらべる"],"q":["古代の郡の役所で、税の稲をしまった倉を何という？","«正倉（しょうそう）»。根岸遺跡でも、その跡がずらりと並んで見つかりました。"],"koji":[],"myth":"郡家の成立年や役目を終えた時期は、発掘成果による推定で幅がある。","img":["夏井廃寺跡","磐城郡","石城国","郡衙"],"wp":"根岸官衙遺跡群","rel":{"ev":[],"grave":[]},"ph":[["c:b/b4/Fukushima_Iwaki-gun1.png",340,220,"磐城郡"],["c:c/cb/Shohei_Junior%26Senior_Highschool.jpg",2048,1536,"近く: 東日本国際大学附属昌平中学・高等学校"],["c:1/1c/JR_J%C5%8Dban_Line_Kusano_Station_building.jpg",4168,2949,"近く: 草野駅 (福島県)"],["c:8/86/Sensyou-ji_Temple_Iwaki_Fukushima.jpg",1500,1000,"近く: 専称寺 (いわき市)"],["c:6/68/Okunitama_Jinja_Iwaki_Haiden.jpg",4608,2592,"近く: 大國魂神社 (いわき市)"],["c:1/15/2013SHK.jpg",1389,683,"近く: 東日本国際大学"],["c:0/0e/Iwaki_Junior_College.jpg",2048,1536,"近く: いわき短期大学"]]},{"id":"07_natsui","n":"夏井廃寺跡","yomi":"なついはいじあと","cat":"遺跡","y":690,"era":["asuka","nara","heian"],"sh":"国指定史跡","rank":"B","ad":"いわき市平下大越","st":"JR常磐線いわき駅から車で約15分","la":37.077,"lo":140.92,"hook":"田んぼの広がる夏井川のほとりに、かつて塔がそびえていた。磐城の豪族が建てた、福島でも指折りに古いお寺の跡。","lead":"夏井廃寺跡は、飛鳥時代の終わりごろから平安時代まで続いた古代のお寺の跡です。塔・金堂・講堂などの建物があったことが、発掘でわかりました。すぐ近くの磐城郡の役所（根岸遺跡）とセットで、今は «根岸官衙遺跡群» として国の史跡になっています。","story":["«廃寺» とは、今はもうなくなってしまったお寺のこと。夏井廃寺も、名前も記録もほとんど残っていません。それでも土の中には、瓦のかけらや、建物の土台をつくった跡がしっかり残っていました。«名前も分からないお寺のことが、どうして分かるの?»――それを教えてくれるのが考古学です。","発掘の結果、このお寺には塔、仏さまをまつる金堂、お坊さんが学ぶ講堂があったことがわかりました。建物の並び方は、九州・太宰府の観世音寺と同じ形とされる «観世音寺式» といわれます。塔と金堂が向かい合うように建つこの配置は、東北地方の古代寺院に多く見られ、都や九州との思わぬつながりを感じさせます。","お寺を建てたのは、すぐそばの役所で郡を治めていた地元の豪族だと考えられています。«仏教を信じ、立派なお寺を建てること» は、当時の豪族にとって、自分たちが新しい文化を取り入れた力ある一族だと示すことでもありました。瓦を焼き、木を組み、塔を立てる。たくさんの職人が集められたはずです。","塔が建ち上がった日を想像してみてください。平らな低地に、瓦ぶきの高い塔が一本。川を行く舟からも、遠くの村からも見えたでしょう。人々は «あそこに仏さまがいる» と手を合わせ、同時に «あそこに郡のまつりごとがある» と感じたはずです。","しかし、郡の役所が役目を終えるころ、お寺もしだいにさびれていきました。いつ、なぜ消えたのかははっきりしません。今は草地に説明板が立つだけですが、足元の土の中には、1300年前の人々の祈りの跡が眠っています。"],"tl":[["7世紀後半","創建されたと考えられる（瓦などから推定）"],["8世紀","塔・金堂・講堂がそろい、郡の中心寺院として栄える"],["9〜10世紀ごろ","しだいに衰え、廃絶したとみられる"],["昭和〜平成","発掘調査で伽藍の配置が明らかになる"],["2011年","根岸遺跡とあわせて «根岸官衙遺跡群» として国史跡に"]],"who":[["磐城郡の郡司一族","お寺を建てた中心と考えられる地元豪族"],["瓦職人・工人たち","瓦を焼き、塔や堂を建てた名もない技術者"],["僧侶","郡の人々のために祈り、仏教を広めた"]],"deep":["«観世音寺式伽藍配置»：東に塔、西に金堂を向かい合わせに置き、その北に講堂を置く形。陸奥国府の多賀城廃寺と同じ形とされ、東北の古代寺院に目立つ。","このお寺は «郡寺（ぐんじ）» とも呼ばれるタイプ。郡の役所のそばに郡司一族が建てたお寺で、全国の郡家の近くにしばしば見られる。","出土した瓦の文様から創建時期が推定されている。瓦は時代や工房で文様が変わるため、«瓦の文様は古代寺院の名刺» ともいえる。","塔の心柱を立てた礎石（心礎）など、建物の中心がどこにあったかを示す手がかりが調査で確認されている。","寺の本当の名前は伝わっていない。そのため地名をとって «夏井廃寺» と呼ばれる。記録に名前がない古代寺院は全国にとても多い。"],"look":["塔・金堂・講堂の位置を示す説明板","低地に立って、塔がそびえていた高さを想像する","丘の上の根岸遺跡（役所跡）とあわせて歩く","いわき市考古資料館などの出土瓦"],"q":["塔と金堂が向かい合う、夏井廃寺の建物の並べ方を何という？","«観世音寺式»。九州・太宰府の観世音寺と同じ形とされ、多賀城廃寺にも見られます。"],"koji":[],"myth":"創建・廃絶の年は出土品からの推定。建てた人物の名前は分からない。","img":["根岸官衙遺跡群","多賀城廃寺","観世音寺","伽藍配置"],"wp":"夏井廃寺跡","rel":{"ev":[],"grave":[]},"ph":[["c:e/e4/Kanzeonji_%28Dazaifu%29_hondou.JPG",4276,2827,"観世音寺"],["c:e/e7/Horyu-ji10s3200.jpg",4500,3000,"伽藍配置"],["c:c/cb/Shohei_Junior%26Senior_Highschool.jpg",2048,1536,"近く: 東日本国際大学附属昌平中学・高等学校"],["c:1/1c/JR_J%C5%8Dban_Line_Kusano_Station_building.jpg",4168,2949,"近く: 草野駅 (福島県)"],["c:8/86/Sensyou-ji_Temple_Iwaki_Fukushima.jpg",1500,1000,"近く: 専称寺 (いわき市)"],["c:1/15/2013SHK.jpg",1389,683,"近く: 東日本国際大学"],["c:0/0e/Iwaki_Junior_College.jpg",2048,1536,"近く: いわき短期大学"],["c:2/26/Taira_commercial_high_school.jpg",2048,1536,"近く: 福島県立平商業高等学校"]]},{"id":"07_karijuku","n":"借宿廃寺跡","yomi":"かりやどはいじあと","cat":"遺跡","y":700,"era":["asuka","nara","heian"],"sh":"国指定史跡","rank":"B","ad":"白河市借宿","st":"JR東北本線白河駅から車で約15分","la":37.118,"lo":140.261,"hook":"手のひらほどの焼き物の仏さま «塼仏（せんぶつ）» が土の中から。みちのくの入口に、都と同じ祈りの形が届いていた。","lead":"借宿廃寺跡は、白河郡の役所（関和久官衙遺跡）と阿武隈川をはさんで向かい合う、古代のお寺の跡です。粘土でつくった小さな仏さまのレリーフ «塼仏» が見つかったことで知られます。役所とお寺をあわせて «白河官衙遺跡群» として国の史跡になっています。","story":["白河は «みちのくの入口»。白河の関をこえると、そこは陸奥国でした。古代、この白河郡は陸奥の中でも大きな郡のひとつで、南から来る人や物が最初に通る大事な場所でした。その郡の中心近く、阿武隈川のほとりに建てられたのが、今は «借宿廃寺» と呼ばれるお寺です。","発掘で特に人々をおどろかせたのが、«塼仏» です。粘土を型に押して仏さまの姿を浮き上がらせ、焼いてつくった小さな板。お堂の壁にずらりとはりつけて、仏さまの世界をあらわしたと考えられています。«どうしてこんな遠くに、都の寺と同じものが?»――それは、このお寺が中央の文化と強く結ばれていたことを物語っています。","お寺を建てたのは、白河郡を治めた郡司の一族と考えられます。川の向こう岸には郡の役所と倉が並び、こちら岸には瓦ぶきの堂や塔。人々は川をはさんで、«まつりごと» と «祈り» の中心を同時に見上げたことでしょう。","みちのくの入口にあるということは、北へ向かう役人や兵士、東北から都へ向かう人々が行き来するということでもあります。旅人たちはこのお寺に立ち寄り、道中の無事を祈ったかもしれません。«ここから先は陸奥だ»――そんな思いで塔を見上げた人もいたはずです。","やがてお寺は姿を消し、名前も伝わらなくなりました。«借宿（かりやど）» という地名から «借宿廃寺» と呼ばれています。旅の宿を思わせるこの地名も、街道の入口という土地柄を感じさせます。"],"tl":[["7世紀後半","創建されたと考えられる（出土品から推定）"],["8世紀","白河郡の中心寺院として栄える"],["9〜10世紀ごろ","しだいに衰え、廃絶したとみられる"],["昭和〜平成","発掘調査で塼仏などが出土"],["平成時代","関和久官衙遺跡とあわせ «白河官衙遺跡群» として国史跡に"]],"who":[["白河郡の郡司一族","お寺を建てた中心と考えられる地元豪族"],["工人たち","塼仏や瓦をつくり、堂塔を建てた技術者"],["みちのくへ向かう旅人","白河を通る役人・兵士・商人たち"]],"deep":["塼仏は飛鳥〜奈良時代に、奈良や畿内の寺院でよく使われた。東北地方での出土例はめずらしく、借宿廃寺の格の高さと中央とのつながりを示す資料とされる。","阿武隈川をはさんで、北岸に郡の役所（関和久）、南岸にお寺（借宿）という配置。役所とお寺が川で分かれる例として興味深い。","白河郡は古代陸奥国の中でも大きな郡とされ、陸奥の南の入口として軍事・交通の上でも重要だった。","伽藍配置は発掘成果から検討されているが、細かな点は研究が続いている。","«借宿» の地名は、中世以降の街道や宿との関わりを想像させるが、古代のお寺との関係ははっきりしない。"],"look":["お寺の範囲や建物位置を示す説明板","阿武隈川の向こう岸（関和久官衙遺跡の方向）をながめる","白河市内の資料館（白河市歴史民俗資料館など）で塼仏や瓦を見る","白河の関跡とあわせて «みちのくの入口» を感じる"],"q":["粘土を型に押して焼いた、小さな板の仏さまを何という？","«塼仏（せんぶつ）»。借宿廃寺から見つかり、都とのつながりを示す資料として注目されました。"],"koji":[],"myth":"創建時期や伽藍配置の細部は研究途上。地名と寺の関係は不明。","img":["関和久官衙遺跡","白河郡","塼仏","白河関"],"wp":"借宿廃寺跡","rel":{"ev":[],"grave":[]},"ph":[["c:5/5e/Kariyado_Haiji%2C_gaikan.jpg",5568,3712,"借宿廃寺跡"],["c:a/a3/Kariyado_Haiji%2C_tou.jpg",5568,3712],["c:a/ac/Kariyado_Haiji%2C_koudou.jpg",5568,3712],["c:2/29/Kariyado_Haiji%2C_kondou.jpg",5568,3712],["j:b/b4/%E5%80%9F%E5%AE%BF%E5%BB%83%E5%AF%BA%E8%B7%A1_%E5%87%BA%E5%9C%9F%E5%93%81.JPG",5179,3363],["j:a/a4/%E5%80%9F%E5%AE%BF%E5%BB%83%E5%AF%BA%E8%B7%A1%E5%87%BA%E5%9C%9F_%E8%A4%87%E5%BC%81%E5%85%AD%E8%91%89%E8%93%AE%E8%8F%AF%E6%96%87%E8%BB%92%E4%B8%B8%E7%93%A6.JPG",3176,3176],["j:5/54/%E5%80%9F%E5%AE%BF%E5%BB%83%E5%AF%BA%E8%B7%A1%E5%87%BA%E5%9C%9F_%E7%93%A6%E5%A1%94.JPG",4288,2929],["j:3/35/%E5%80%9F%E5%AE%BF%E5%BB%83%E5%AF%BA_%E7%8B%AC%E5%B0%8A%E5%83%8F%E5%A1%BC%E4%BB%8F_%28J-34796%29.JPG",2929,2935]]},{"id":"07_sekiwaku","n":"関和久官衙遺跡","yomi":"せきわぐかんがいせき","cat":"遺跡","y":720,"era":["asuka","nara","heian"],"sh":"国指定史跡","rank":"B","ad":"西白河郡泉崎村関和久","st":"JR東北本線泉崎駅から車で約10分","la":37.133,"lo":140.266,"hook":"土の中から出てきたのは、黒く焦げた米粒。1200年以上前の倉が燃えた跡が、白河郡の役所の姿を教えてくれた。","lead":"関和久官衙遺跡は、古代の陸奥国白河郡の役所（郡家）の跡です。税の稲をしまった大きな倉の跡や、焼けて炭になった米が見つかりました。阿武隈川の向こう岸の借宿廃寺跡とあわせて «白河官衙遺跡群» として国の史跡になっています。","story":["阿武隈川がゆったりと流れる泉崎村の関和久。ここはのどかな田園ですが、1200年以上前には、白河郡を治めた役所がありました。郡の役人たちが集まり、税を集め、村々に命令を伝える。いわば古代の «白河の役場» です。","発掘でまず見つかったのは、たくさんの倉の跡でした。税として集めた稲をしまう «正倉» です。そして、その中から黒く焼けた米がどっさりと出てきました。«どうして米が焦げているの?»――倉が火事で燃えたからです。火事の原因ははっきりしませんが、落雷や放火、戦乱などさまざまな可能性が考えられます。","古代の東北では、倉が焼ける事件がたびたび記録に残っています。«神火（しんか）» と呼ばれ、神さまのたたりのようにいわれることもありました。でも実は、税の不正をかくすために役人が火をつけたのではないか、という見方もあります。焦げた米粒は、そんな古代のミステリーも語りかけてくるのです。","白河郡は陸奥の南の入口にある大きな郡でした。ここに多くの稲が集められたのは、北の蝦夷との戦いに向かう兵士たちの食料を支える意味もあったと考えられます。«みちのくの台所» の一つだったのかもしれません。","役所の建物はとうに姿を消し、今は田畑の広がる風景です。それでも、発掘された柱の穴や焦げた米は、ここがかつて地域のまつりごとの中心だったことを確かに伝えています。川向こうのお寺の跡とあわせて歩くと、古代の郡の姿が見えてきます。"],"tl":[["7世紀後半","白河評（のちの白河郡）の役所が置かれたと考えられる"],["8世紀","正倉が並び、郡の役所として整う"],["8〜9世紀","倉の一部が焼け、炭になった米が残る（時期は推定）"],["10世紀ごろ","役所としての役目を終えたとみられる"],["昭和後期","発掘調査が進み、郡家跡と確かめられる"],["平成時代","借宿廃寺跡とあわせ «白河官衙遺跡群» として国史跡に"]],"who":[["白河郡の郡司","役所で郡を治めた地元の有力者"],["郡の役人・農民","税の稲を運び込み、倉を管理した人々"],["陸奥の国司","多賀城から郡の役所を通じて国を治めた"]],"deep":["«炭化米»：焼けて炭になった米は腐らずに残るため、遺跡から出ると倉の存在を示す強い証拠になる。関和久の炭化米は、正倉の火災を物語る資料として知られる。","«神火»：奈良〜平安時代、東国などで正倉が焼ける事件が多く、神のしわざとされることがあった。一方で、役人の不正のもみ消しや郡司の地位争いが原因とみる説もある。","関和久は阿武隈川の北岸、借宿廃寺は南岸にあたる。川を利用して物資を運びやすい場所が選ばれたと考えられる。","郡家には郡庁・正倉・館・厨などの施設があり、関和久でも役所の区画を示す溝などが確認されている。","«関和久» という地名の由来ははっきりしないが、白河の関との関わりを想像する人もいる（確かな根拠はない）。"],"look":["遺跡の範囲を示す説明板と、田園に広がる地形","阿武隈川の対岸にある借宿廃寺跡とのセット見学","資料館で見られる炭化米や瓦など出土品","周辺の段丘の高さに注目（洪水をさけた立地）"],"q":["関和久官衙遺跡から見つかった、倉が燃えた証拠となるものは？","焼けて炭になった米（炭化米）。税の稲をしまう正倉が火事にあったことを示します。"],"koji":[],"myth":"倉が燃えた原因・時期は不明で、«神火» との関係も推測の域を出ない。地名の由来も諸説。","img":["借宿廃寺跡","白河郡","郡衙","正倉"],"wp":"関和久官衙遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:9/9a/Sekiwaku_Kanga_Site%2C_gaikan.jpg",5554,3692,"関和久官衙遺跡"],["j:c/c3/%E9%96%A2%E5%92%8C%E4%B9%85%E5%AE%98%E8%A1%99%E9%81%BA%E8%B7%A1_%E5%87%BA%E5%9C%9F%E5%93%81.JPG",5237,2872],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:5/5e/Kariyado_Haiji%2C_gaikan.jpg",5568,3712,"借宿廃寺跡"],["c:e/e5/Fukushima_NishiShirakawa-gun.png",340,220,"白河郡"],["c:3/32/Pic_azekura.jpg",556,418,"正倉"]]},{"id":"07_shirasaka","n":"白坂宿（奥州街道・下野国境）","yomi":"しらさかしゅく","cat":"街道","y":1650,"era":["edo","meiji"],"sh":"","rank":"B","ad":"白河市白坂","st":"JR東北本線白坂駅から歩いて約20分","la":37.079,"lo":140.176,"hook":"峠をこえたら、そこは陸奥。江戸から北へ向かう旅人が、みちのくで最初に草鞋をぬいだ宿場町。","lead":"白坂宿は、江戸と東北を結ぶ奥州街道の宿場町です。下野国（栃木県）との国境の峠をこえて、陸奥国に入って最初の宿場でした。今は静かな集落ですが、街道筋の家並みに宿場の面影が残ります。","story":["江戸の日本橋を出て北へ。宇都宮で日光街道と分かれ、那須の野をこえると、ゆるやかな坂道になります。坂を登りきったところが下野と陸奥の国境、«境の明神»。そこを下るとすぐに、白坂宿の家並みが見えてきました。«ようやくみちのくだ»――旅人はそう思ってひと息ついたことでしょう。","白坂宿は、国境の宿という大事な役目を持っていました。宿場には、公用の荷物や人を次の宿まで運ぶための人足や馬が用意され、大名行列や役人が通るときには宿場じゅうが大忙し。東北の大名たちが参勤交代で江戸へ向かうときも、この宿場を通りました。","«なぜ白坂は大きな宿場にならなかったの?»――すぐ北に、城下町の白河宿があったからです。多くの旅人は白河まで足をのばして泊まりました。白坂は、峠をこえてつかれた人や、天気の悪いときの人を受けとめる、小さいけれど大切な宿場でした。","幕末の1868年、戊辰戦争で白河は激しい戦いの場になりました。白河の城を取り合う戦いの中で、南から攻め上がる新政府軍が通った道の一つが、この白坂を通る奥州街道でした。静かな宿場も、戦の緊張に包まれたのです。","明治になり、東北本線の鉄道が開通すると、街道を歩く旅人は減っていきました。それでも白坂の家並みを歩くと、ゆるやかにカーブする道筋や、宿場らしい間口の家々に、江戸の旅の記憶を感じることができます。"],"tl":[["江戸時代初め","奥州街道が整えられ、白坂が宿場となる"],["江戸時代","東北諸藩の参勤交代や旅人が行き来する"],["1689年","松尾芭蕉が『おくのほそ道』の旅で白河周辺を通る"],["1868年","戊辰戦争・白河口の戦い。白坂付近も戦いの舞台に"],["1887年","東北本線（当時は日本鉄道）が白河方面まで通じる"],["明治以降","鉄道の開通で街道の旅が減り、静かな集落に"]],"who":[["宿場の問屋・本陣","人馬の手配や大名の宿泊を引き受けた宿場の要"],["参勤交代の大名たち","東北の諸藩が江戸との往復に通った"],["松尾芭蕉","『おくのほそ道』の旅で白河の関を目指した俳人"],["新政府軍・奥羽越列藩同盟軍","戊辰戦争で白河周辺を争った"]],"deep":["奥州街道は、江戸幕府が整えた «五街道» の一つ。正式には日本橋から白河までを «奥州道中» と呼んだとされ、白坂はその終点近くの宿場にあたる。","白坂宿の南には下野国最後の宿場・芦野宿（栃木県那須町）があり、国境の峠をはさんで宿場が向かい合っていた。","宿場には «本陣»（大名の宿）や «問屋場»（人馬の継ぎ立て所）が置かれた。白坂は小規模な宿場だったが、国境の宿として一定の役割を担った。","戊辰戦争の白河口の戦いは、1868年の春から夏にかけて何度も行われた。白河周辺では両軍に多くの戦死者が出て、市内各地に慰霊碑や墓がある。","芭蕉は白河に入る際、境の明神付近から旗宿方面の古い関跡へ向かったとされる。芭蕉の足取りの細部は研究者の間で議論がある。"],"look":["街道沿いの家並みと、ゆるやかに曲がる道筋","宿場の案内板や石碑","南の峠にある境の明神までの坂道（歩くと国境越えの感覚がわかる）","白河市街の戊辰戦争ゆかりの地とあわせて巡る"],"q":["白坂宿は、何という国と陸奥国の境に近い宿場だった？","下野国（今の栃木県）。峠の境の明神をこえると陸奥で、白坂がその最初の宿場でした。"],"koji":[],"myth":"宿場の成立年や芭蕉の詳しい道筋は諸説ある。","img":["境の明神","白河口の戦い","芦野宿"],"wp":"奥州街道","rel":{"ev":[],"grave":[]},"ph":[["c:1/1d/Komine_castle.jpg",3068,1793,"白河口の戦い"],["c:8/8e/Shin-Shirakawa_Station.jpg",4656,3496,"近く: 新白河駅"],["c:1/1b/JR_Tohoku_Line_Shirasaka_Station_building.jpg",4161,2949,"近く: 白坂駅"],["c:7/75/Toyohara_Station%2C_ekisha.jpg",5562,3702,"近く: 豊原駅"],["c:9/96/Shirakawa_IC.JPG",3648,2736,"近く: 白河インターチェンジ"],["c:0/00/JRBK-ShirakawaBranchOffice01.jpg",1080,720,"近く: ジェイアールバス関東白河支店"]]},{"id":"07_sakai_myojin","n":"境の明神（奥州街道の国境）","yomi":"さかいのみょうじん","cat":"街道","y":1650,"era":["heian","edo"],"sh":"","rank":"B","ad":"白河市白坂明神","st":"JR東北本線白坂駅から歩いて約40分、または車で約10分","la":37.052,"lo":140.167,"hook":"峠の上に、国境をはさんで二つの社が背中合わせに立つ。ここから北は陸奥、南は下野。","lead":"境の明神は、奥州街道の下野国（栃木県）と陸奥国（福島県）の国境の峠にある神社です。国境をはさんで二つの社がならび、«二所の明神» とも呼ばれました。旅人はここで旅の無事を祈り、国をこえていきました。","story":["奥州街道を北へ、那須の芦野宿から坂を登っていくと、杉木立の中に小さな社が現れます。そこが国境の峠、境の明神。«ここから先が陸奥国»――江戸時代の旅人にとって、それは «みちのく» への入口をくぐる瞬間でした。","おもしろいのは、社が一つではないことです。国境をはさんで、陸奥側に «玉津島明神»、下野側に «住吉明神» がまつられています。«どうして二つあるの?»――それぞれの国が、自分の側で国境を守る神さまをまつったからだと考えられています。玉津島は女神、住吉は男神とされ、国の内側に女神、外側に男神をまつって守ったという言い伝えもあります。","国境は、ただの線ではありませんでした。病や災いが外から入ってくるのをふせぐ «境» でもあったのです。人々は峠で手を合わせ、「悪いものを入れないでください」「無事に国をこえられますように」と祈りました。峠の神は、村と旅人の両方を守る存在でした。","江戸時代、この峠を東北の大名行列が何度も越えていきました。参勤交代で江戸へ向かう一行は、ここで国元の陸奥に別れを告げ、帰りにはここでふるさとに帰ってきたことを実感したでしょう。俳諧の旅人たちもこの峠を通り、白河の関へ思いをはせました。","今は車も通る道になり、峠の風景はずいぶん変わりました。それでも、社の前に立つと、足元に二つの国の境があることが不思議に感じられます。福島と栃木の県境は、今もこの峠にあります。"],"tl":[["平安時代","この峠付近が陸奥と下野の境として意識されていたと考えられる"],["江戸時代初め","奥州街道が整い、国境の峠として人の往来が増える"],["江戸時代","玉津島明神・住吉明神がならび «二所の明神» と呼ばれる"],["1689年","松尾芭蕉と曾良が白河へ向かう旅でこの付近を通ったとされる"],["1868年","戊辰戦争で白河周辺が戦場となる"],["明治以降","県境として今も福島県と栃木県を分ける"]],"who":[["玉津島明神","陸奥側にまつられた女神。和歌の神としても知られる"],["住吉明神","下野側にまつられた男神。海や旅の守り神"],["参勤交代の大名","東北の大名が江戸への往復で越えた"],["松尾芭蕉","『おくのほそ道』で白河の関を目指した"]],"deep":["国境の神を «内側に女神・外側に男神» とする言い伝えは各地にあり、ここでも双方の国がそれぞれの側を内として神をまつったと説明されることがある。","白河には、奈良・平安時代の «白河の関» があったとされる。関の場所は旗宿の «白河関跡» が有力とされ、江戸時代の奥州街道とは道筋が異なる。","江戸の旅人の間では、境の明神を越えることは «白河の関を越える» のと同じ気持ちで受けとめられていたともいわれる。","«玉津島» は和歌山の玉津島神社の神で、和歌の神として知られる。国境の峠にその名があることから、歌枕・白河との結びつきを考える人もいる（確かな根拠は乏しい）。","峠は県境で、陸奥側の社は白河市、下野側の社は那須町にある。一つの場所で二つの自治体の社を見られる、めずらしいポイント。"],"look":["国境をはさんで並ぶ二つの社","県境を示す標識（片足ずつ福島と栃木）","峠へ登る奥州街道の坂道","南の芦野宿、北の白坂宿とあわせた街道歩き"],"q":["境の明神で、陸奥側にまつられている神さまは？","«玉津島明神»。下野側には «住吉明神» がまつられ、二つあわせて «二所の明神» と呼ばれました。"],"koji":[],"myth":"女神・男神の配置の由来、芭蕉の具体的な通過ルートは伝承・諸説。","img":["奥州街道","白坂宿","白河関","玉津島神社"],"wp":"境の明神","rel":{"ev":[],"grave":[]},"ph":[["c:5/52/Shirakawa-no-Seki_monument.jpg",2288,1712,"白河関"],["c:f/f4/Tamatsushima-shrine.jpg",576,460,"玉津島神社"],["c:7/75/Toyohara_Station%2C_ekisha.jpg",5562,3702,"近く: 豊原駅"],["c:1/1b/JR_Tohoku_Line_Shirasaka_Station_building.jpg",4161,2949,"近く: 白坂駅"]]},{"id":"07_sukagawa_ichirizuka","n":"須賀川一里塚","yomi":"すかがわいちりづか","cat":"街道","y":1604,"era":["edo"],"sh":"国指定史跡","rank":"B","ad":"須賀川市高久田境","st":"JR東北本線須賀川駅から車で約10分","la":37.269,"lo":140.37,"hook":"400年前の «道のりの目印» が、道の両側にそろって残る。旅人はこの塚を数えながら北へ歩いた。","lead":"一里塚は、江戸時代に街道の約4kmごとにつくられた土盛りの目印です。須賀川一里塚は、奥州街道の道の両側に塚が二つとも残っている、全国でもめずらしい例として国の史跡になっています。","story":["時計も地図アプリもない江戸時代。旅人は、どうやって «あとどれくらい歩けばいいか» を知ったのでしょう。その答えが一里塚です。江戸の日本橋から一里（約4km）ごとに、道の両側に土を盛り、上に木を植えました。«塚が見えたら一里進んだ»――旅人は塚を数えながら歩いたのです。","一里塚づくりを命じたのは、江戸幕府を開いた徳川家康だといわれます。1604年、家康は息子の秀忠に命じて、主な街道に一里塚を整えさせたと伝わります。道を整えることは、国をまとめる政治の一部でもありました。","塚の上の木は、夏には日かげをつくり、旅人のひと休みの場所にもなりました。駕籠かきや馬子にとっては、運賃を計算する目安でもあったといいます。«次の塚まで、あと少しだ»――そんな声が聞こえてきそうです。","明治以降、道路が広げられたり、鉄道ができたりして、全国の一里塚の多くはこわされてしまいました。片方だけ残っているものはあっても、両側がそろって残るのはわずか。須賀川一里塚は、その貴重な生き残りです。","今、塚の間を通る道に立ってみると、道幅が江戸時代の街道の広さを想像させてくれます。二つの塚の間を、大名行列も、商人も、お伊勢参りの人々も通っていきました。小さな土の山ですが、何百年分の足音を聞いてきた塚なのです。"],"tl":[["1604年","徳川家康の命で主要街道に一里塚を整えることが始まったと伝わる"],["江戸時代","奥州街道の旅人や参勤交代の行列が塚の間を通る"],["1689年","松尾芭蕉が須賀川に長く滞在（『おくのほそ道』）"],["明治以降","道路改修などで全国の一里塚の多くが失われる"],["昭和","両側の塚がそろって残る貴重な例として国史跡に"]],"who":[["徳川家康","街道の整備と一里塚づくりを命じたと伝わる"],["徳川秀忠","父の命を受け、街道整備を進めたとされる"],["奥州街道の旅人","塚を数えながら北へ南へ歩いた人々"],["松尾芭蕉","須賀川の俳人・相楽等躬を訪ね、この街道を歩いた"]],"deep":["一里は約3.9km。一里塚は五間（約9m）四方の塚に木を植えるのが基本とされ、榎や松がよく使われた。","«両側がそろって残る» ことが価値の大きなポイント。道の片側だけ、あるいは塚の跡だけのものが多い中、須賀川のように道をはさんで一対残る例は多くない。","芭蕉は『おくのほそ道』の旅で須賀川に七泊ほどしたとされ、宿を貸した相楽等躬との句会で «風流の初めやおくの田植うた» を詠んだ。","一里塚の起点は日本橋。塚の番号がわかれば江戸からの距離がわかるが、須賀川一里塚が何番目にあたるかは、ここでは確かな資料で確かめられていない。","塚の上の木は枯れたり植え替えられたりすることがあり、今の木が江戸時代のままとは限らない。"],"look":["道をはさんで向かい合う二つの塚","塚の上の木と、そのまわりの土盛りの形","塚の間の道幅（旧奥州街道の広さを想像）","須賀川市街の芭蕉ゆかりの地とあわせて巡る"],"q":["一里塚は、だいたい何kmごとにつくられた？","約4km（一里は約3.9km）。旅人は塚を数えて進んだ距離を知りました。"],"koji":[],"myth":"1604年の家康の命令は通説。何番目の塚かは未確認。","img":["一里塚","奥州街道","須賀川宿","おくのほそ道"],"wp":"須賀川一里塚","rel":{"ev":[],"grave":[]},"ph":[["c:2/27/%E9%A0%88%E8%B3%80%E5%B7%9D%E4%B8%80%E9%87%8C%E5%A1%9A%E4%BB%98%E8%BF%91.jpg",3264,2448,"須賀川一里塚"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:2/20/%E9%87%8E%E6%9D%91%E4%B8%80%E9%87%8C%E5%A1%9A%EF%BC%88%E5%9B%BD%E5%8F%B2%E8%B7%A1%EF%BC%89.jpg",3024,4032,"一里塚"]]},{"id":"07_minamiaizu_gun","n":"旧南会津郡役所","yomi":"きゅうみなみあいづぐんやくしょ","cat":"近代","y":1885,"era":["meiji"],"sh":"県指定重要文化財","rank":"B","ad":"南会津郡南会津町田島","st":"会津鉄道会津田島駅から歩いて約10分","la":37.201,"lo":139.772,"hook":"山深い会津の町に、白い洋風の窓が並ぶ。明治の人々が «新しい時代の役所» にかけた思いが形になった。","lead":"旧南会津郡役所は、明治時代の1885年に建てられた郡の役所です。日本の大工が西洋の建物をまねてつくった «擬洋風建築» で、県の重要文化財に指定されています。建物の中は公開され、この地方の歴史を学ぶことができます。","story":["会津田島の町を歩いていると、ほかの建物とは少しちがう、背の高い洋風の建物が目にとまります。縦長の窓、白い壁、正面の玄関。これが明治時代の南会津郡役所です。«どうして山の町に洋風の役所が?»――それは明治という時代そのものが答えです。","明治維新のあと、政府は «文明開化» をかかげ、西洋の技術や制度を急いで取り入れました。役所や学校の建物も、新しい時代の象徴として洋風につくられることが多くなりました。しかし地方には西洋建築を学んだ建築家はほとんどいません。そこで活躍したのが、地元の大工たちです。","大工たちは、写真や絵、横浜や東京の建物を手がかりに、見よう見まねで洋風の建物をつくりました。これを «擬洋風建築» といいます。外から見ると洋風なのに、よく見ると日本の伝統的な技も使われている。旧南会津郡役所にも、そんな «和と洋のまざりあい» を見つけることができます。","南会津は、江戸時代には «南山御蔵入（みなみやまおくらいり）» と呼ばれる幕府の直轄地でした。厳しい年貢に苦しんだ人々が立ち上がった «南山御蔵入騒動» の舞台でもあります。そんな歴史をもつ土地に、明治になって郡の役所が置かれ、新しい地方の政治が始まったのです。","郡役所の制度はやがて廃止され、建物はその後もさまざまな形で使われてきました。今は大切に保存され、中に入って明治の役所の雰囲気を味わうことができます。窓から外をながめると、明治の役人が見た田島の町並みが重なって見えるかもしれません。"],"tl":[["江戸時代","南会津は幕府の直轄地 «南山御蔵入» として治められる"],["1720〜1721年","年貢に苦しむ農民たちが訴え出た «南山御蔵入騒動»"],["1878年","郡区町村編制法で郡役所が置かれるようになる"],["1885年","南会津郡役所の庁舎が完成"],["1926年","郡役所が廃止される"],["昭和","県の重要文化財に指定され、保存・公開される"]],"who":[["地元の大工たち","洋風の庁舎を見よう見まねで建てた職人"],["郡長","郡役所の長として南会津郡を治めた"],["南山御蔵入騒動の農民たち","江戸時代、この地方で年貢の不正を訴えた人々"]],"deep":["«擬洋風建築» は明治前期に全国で建てられた。代表例は長野県の旧開智学校や山形県の旧済生館など。地方の大工の工夫が詰まっている。","郡役所は1878年の郡区町村編制法で置かれ、府県と町村の間で行政を担った。1921年の法律で郡制が廃止され、郡役所は1926年に廃止された。","南山御蔵入騒動では、訴えを起こした農民の代表が処刑された。人々は彼らを «義民» としてたたえ、今も地元で供養が続いている。","会津の南部は冬の雪が深い。洋風建築でありながら、雪国の気候に合わせた工夫がされているかどうかも観察のポイント。","郡役所は当時の «最新の役所»。庁舎の立派さは、地域の人々に «新しい時代が来た» と感じさせる効果もあった。"],"look":["正面の縦長の洋風窓と玄関まわり","和風の技法がまじる細部（屋根・軒・柱など）","内部の展示と、明治の役所の部屋のつくり","田島の町並みと、会津西街道（下野街道）の歴史"],"q":["地方の大工が西洋の建物をまねてつくった明治の建物を何という？","«擬洋風建築»。旧南会津郡役所もその一つです。"],"koji":[],"myth":"建設に関わった大工の名前や設計の手本は確認できていない。","img":["擬洋風建築","南山御蔵入騒動","郡役所","会津田島駅"],"wp":"旧南会津郡役所","rel":{"ev":[],"grave":[]},"ph":[["c:8/88/Former_Kaichi_School03_1024.jpg",1536,2048,"擬洋風建築"],["c:2/2c/Aizutajima_Station.png",2048,1076,"会津田島駅"],["c:b/b5/Aizu-tajima_Gionsai%2C_Nanahokai.JPG",4742,3557,"近く: 田島町 (福島県)"],["c:5/54/Minamiaizu_Police_Station.JPG",3648,2736,"近く: 南会津警察署"],["c:9/99/Tajima_Post_office_002.JPG",1280,600,"近く: 田島郵便局"],["c:c/cd/Okurairi_Koryukan_1.JPG",1280,960,"近く: 御蔵入交流館"]]},{"id":"07_hinoemata","n":"檜枝岐歌舞伎（舞台）","yomi":"ひのえまたかぶき","cat":"伝承","y":1750,"era":["edo","showa"],"sh":"国の重要有形民俗文化財（檜枝岐の舞台）","rank":"B","ad":"南会津郡檜枝岐村居平（鎮守神社境内）","st":"会津鉄道会津高原尾瀬口駅からバスで約1時間10分","la":37.021,"lo":139.382,"hook":"神社の境内に茅葺きの舞台。石段の客席に座れば、山あいの村人が260年以上守ってきた «村の歌舞伎» が始まる。","lead":"檜枝岐歌舞伎は、尾瀬の入口にある檜枝岐村に江戸時代から伝わる農村歌舞伎です。村の人たちが役者になり、鎮守神社の茅葺きの舞台で神さまに奉納します。舞台は国の重要有形民俗文化財になっています。","story":["福島県のいちばん南西、尾瀬のふもとにある檜枝岐村。山に囲まれ、冬は深い雪に閉ざされる村です。この村では、江戸時代から «歌舞伎» が演じられてきました。役者は村の人たち。ふだんは宿や店で働く人が、祭りの日だけ武将やお姫さまに変身するのです。","«どうして山奥の村に歌舞伎が?»――村の人が江戸や伊勢へ旅をしたとき、芝居を見て覚えて帰ったのが始まりだと伝わっています。娯楽の少ない山の暮らしの中で、歌舞伎は村人の大きな楽しみになり、やがて神さまにささげる大切な行事になっていきました。","舞台は鎮守神社の境内にあります。茅葺き屋根の素朴な舞台の前に、斜面を利用した石段の客席が広がり、観客は夜空の下でござを敷いて見物します。拍手とともに «おひねり» が飛ぶのも村芝居ならでは。役者が見得を切ると、山にこだまするような掛け声がかかります。","演じるのは «千葉之家花駒座（ちばのやはなこまざ）»。台本は古くから口伝えや書き写しで受け継がれ、化粧も衣装の準備も村人の手で行います。村の人口は少なく、役者を続けていくのは簡単ではありません。それでも «村の宝を絶やしたくない»――その思いが、何世代にもわたって舞台を支えてきました。","檜枝岐には、平家の落人がかくれ住んだという言い伝えも残ります。都の文化へのあこがれが、歌舞伎を大切にする気持ちにつながったのかもしれません。今も祭りの夜、山あいの舞台に明かりがともると、江戸時代から続く村の時間がよみがえります。"],"tl":[["江戸時代中期","村人が江戸や伊勢で見た芝居を伝えたのが始まりといわれる"],["江戸時代","鎮守神社の祭礼で奉納芝居として演じられるようになる"],["明治時代","現在の舞台の建物が整えられたとされる"],["1976年","«檜枝岐の舞台» が国の重要有形民俗文化財に指定"],["現在","5月・8月の祭礼と、9月の «歌舞伎の夕べ» で上演が続く"]],"who":[["千葉之家花駒座","檜枝岐歌舞伎を演じ継ぐ村人の一座"],["檜枝岐の村人","役者・裏方・観客として芝居を支える"],["鎮守神社の神さま","芝居は神への奉納としてささげられる"]],"deep":["農村歌舞伎（地芝居）は江戸時代に全国の村で盛んになった。幕府はたびたび禁止令を出したが、祭礼の奉納という形で各地に残った。","客席は神社の斜面を利用した石段状で、舞台と観客の距離が近い。屋外で神さまに見せる «奉納» の形を今に伝える。","檜枝岐は «星»«平野»«橘» など同じ姓の家がとても多い村として知られる。芝居の配役も、村の人どうしで世代をこえて受け継がれてきた。","上演は例年、5月12日の愛宕神祭礼、8月18日の鎮守神祭礼、9月の «歌舞伎の夕べ» が知られる（日程は年により確認が必要）。","檜枝岐は «平家の落人の里» として知られ、姓の種類が少ないことなどと結びつけて語られるが、落人伝説は歴史的には確かめられていない。"],"look":["茅葺き屋根の舞台と、その前の石段の客席","舞台を囲む杉木立と鎮守神社の社殿","上演日なら、おひねりが飛ぶ村芝居ならではの熱気","村の歌舞伎伝承館（資料展示）もあわせて見学"],"q":["檜枝岐歌舞伎を演じる村の一座の名前は？","«千葉之家花駒座»。村の人たちが役者も裏方もつとめます。"],"koji":[{"w":"見得を切る","m":"歌舞伎で役者が動きを止め、目立つポーズをとること。転じて、自信たっぷりの態度を見せること"}],"myth":"歌舞伎の伝来の経緯と平家落人伝説は伝承。舞台の建築年代は諸説。","img":["檜枝岐村","農村歌舞伎","尾瀬"],"wp":"檜枝岐歌舞伎","rel":{"ev":[],"grave":[]},"ph":[["c:7/72/Sanjo-taki.jpg",480,640,"檜枝岐村"],["c:b/bf/Mt.Hiuchigatake_11.jpg",3822,2548,"尾瀬"],["c:3/38/Farm_village_Kabuki_stage_Hinoemata-no_Butai.JPG",3264,2448,"近く: 桧枝岐の舞台"],["c:8/8a/Lake_chuzenji_and_kegon_waterfall.jpg",1769,1322,"近く: 日光国立公園"],["c:d/db/Mt._Aizukoma_080713.JPG",2816,2112,"近く: 会津駒ヶ岳"]]},{"id":"07_eryuji","n":"恵隆寺（立木観音）","yomi":"えりゅうじ（たちきかんのん）","cat":"寺社","y":1200,"era":["heian","kamakura"],"sh":"国の重要文化財（観音堂・千手観音立像）","rank":"B","ad":"河沼郡会津坂下町塔寺","st":"JR只見線塔寺駅から歩いて約10分","la":37.574,"lo":139.803,"hook":"大地に根を張ったままの木から彫り出された、と伝わる高さ8mをこえる観音さま。お堂に入ると、その大きさに息をのむ。","lead":"恵隆寺は、会津坂下町にある古いお寺で、«立木観音» の名で親しまれています。本尊の千手観音は、立ったままの木を切らずに彫ったと伝わる大きな仏像です。観音堂と仏像はどちらも国の重要文化財です。","story":["観音堂の扉をくぐると、うす暗い堂内に、見上げるほどの観音さまが立っています。高さは8メートルをこえ、たくさんの手を広げた千手観音。«これが一本の木からできているの?»――そう思わずにはいられない大きさです。","言い伝えでは、昔、弘法大師がこの地を訪れ、大地に根を張った大きな木を切らずに、そのまま観音さまを彫り上げたといいます。だから «立木観音»。根っこが今も地面につながっていると語られることもあります。本当かどうかは確かめられませんが、それほど大地と一体に見える仏さまなのです。","観音堂そのものも古く、中世の建物として国の重要文化財になっています。太い柱と大きな屋根が、巨大な観音さまを包みこむように守っています。何百年もの間、雪の重さや地震にたえてきたお堂です。","会津の人々は、この観音さまに «ころり» と安らかに往生できるよう祈ってきました。恵隆寺は、会津の «ころり三観音» の一つに数えられます。年をとっても元気で、最期は苦しまずに――そんな願いを胸に、今も多くの人が手を合わせに訪れます。","寺のある «塔寺» という地名は、かつてここに大きな塔が建っていたことに由来するともいわれます。只見線の小さな駅から歩いて行ける、会津の祈りの歴史が詰まったお寺です。"],"tl":[["伝・古代","寺の始まりは古く、6世紀にさかのぼるとする寺伝もある"],["伝・平安時代初め","弘法大師が立木に観音を彫ったと伝わる"],["平安時代末〜鎌倉時代","千手観音立像がつくられたと考えられる"],["中世","現在の観音堂が建てられる"],["明治以降","観音堂と千手観音立像が国の重要文化財に"]],"who":[["弘法大師（空海）","立木に観音を彫ったと伝わる僧（伝承）"],["会津の人々","ころり往生や健康を願って参拝してきた"],["歴代の住職","巨大な観音と古いお堂を守ってきた"]],"deep":["千手観音立像は高さ8mをこえる巨像で、平安時代末から鎌倉時代ごろの作と考えられている。日本でも有数の大きさの木造千手観音。","«立木仏» とは、生えている木を切らずに彫ったと伝わる仏像。各地にあるが、実際には根元で切り離して別材を組み合わせている場合も多い。","会津の «ころり三観音» は、恵隆寺（立木観音）・弘安寺（中田観音）・如法寺（鳥追観音）。三つを巡ると安らかな往生がかなうといわれる。","会津は平安時代初め、法相宗の僧・徳一が慧日寺を開くなど、早くから仏教文化が栄えた地。恵隆寺の開基についても徳一と結びつける説がある。","観音堂は正面の柱間が多く、巨像を納めるための広い内部をもつ。中世会津の大型仏堂として貴重。"],"look":["堂内の巨大な千手観音立像（見上げる角度に注目）","中世の観音堂の太い柱と大きな屋根","«ころり三観音» の案内と絵馬","只見線の塔寺駅からの参道と田園風景"],"q":["恵隆寺の本尊が «立木観音» と呼ばれるのはなぜ？","立ったままの木を切らずに彫ったと伝わるから。ただし伝承で、実際の造り方は確かめられていません。"],"koji":[{"w":"ころり往生","m":"長く病に苦しまず、安らかに一生を終えること。会津の三観音に願われてきた"}],"myth":"弘法大師作・立木のままという話は伝承。寺の創建年も寺伝による。","img":["千手観音","会津坂下町","只見線","空海"],"wp":"恵隆寺","rel":{"ev":[],"grave":[]},"ph":[["c:c/ce/%E6%81%B5%E9%9A%86%E5%AF%BA%E8%A6%B3%E9%9F%B3%E5%A0%82_%28Eryuji_Kannondo%29.jpg",2816,2112,"恵隆寺"],["c:a/aa/Sanjusangendo_Thousand-armed_Kannon.JPG",2000,3008,"千手観音"],["c:6/61/Find47_Fukushima-Autumn_leaves_train_%28No._1_Tadami_River_Bridge%2C_Mishima_Town%29-m.jpg",6046,3401,"只見線"],["c:9/98/Kobo_Daishi_%28Taisanji_Matsuyama%29.jpg",260,270,"空海"]]},{"id":"07_kotokuji","n":"興徳寺（蒲生氏郷の墓）","yomi":"こうとくじ（がもううじさとのはか）","cat":"墓所","y":1595,"era":["kamakura","azuchi"],"sh":"","rank":"B","ad":"会津若松市栄町","st":"JR会津若松駅からバスで約10分、«神明通り» 付近から歩いてすぐ","la":37.495,"lo":139.93,"hook":"«黒川» を «若松» に変え、七層の天守を建てた男。40歳で散った蒲生氏郷は、自分がつくった町の真ん中に眠る。","lead":"興徳寺は、会津若松の町なかにある古いお寺です。会津の町の基礎をつくった戦国武将・蒲生氏郷の墓（五輪塔）があります。1590年には豊臣秀吉が «奥州仕置» のためにこの寺に滞在したことでも知られます。","story":["1590年、天下統一を目前にした豊臣秀吉が会津にやって来ました。東北の大名たちの領地を決め直す «奥州仕置» です。秀吉が宿と政務の場にしたのが、この興徳寺でした。そして会津の新しい主に選ばれたのが、近江（滋賀県）出身の若き武将・蒲生氏郷です。","氏郷は信長に才能を見こまれ、信長の娘をめとった人物。秀吉にとっても頼れる武将でした。«なぜ近江の武将を東北に?»――会津は、伊達政宗ら東北の大名ににらみをきかせる大事な場所。秀吉はそこに、信頼できる氏郷を置いたのです。","氏郷は会津に来ると、城下町を大きくつくり変えました。町の名を «黒川» から «若松» に改め、七層の天守を持つ城を築き、近江から商人や職人を呼んで商業を盛んにしました。会津塗や酒づくりが発展したのも、氏郷の政策がきっかけだといわれます。今の会津若松の町の形は、この時代に生まれたのです。","しかし、氏郷の時間は長くありませんでした。1595年、京都の伏見で病のため、40歳の若さで世を去ります。辞世の歌として «限りあれば 吹かねど花は 散るものを 心みじかき 春の山風» が伝わっています。«風が吹かなくても花はいつか散るのに、春の山風はなんと気が短いことか»――早すぎる死を惜しむ思いがにじみます。","氏郷の墓は京都の大徳寺にもありますが、会津の人々は氏郷をしのび、この興徳寺にも墓を建てました。遺髪を納めたとも伝わります。自分がつくった若松の町の真ん中で、氏郷は今も会津を見守っているのです。"],"tl":[["鎌倉〜室町時代","会津の領主・蘆名氏の保護を受けて栄えたと伝わる"],["1590年","豊臣秀吉が興徳寺に滞在し «奥州仕置» を行う。蒲生氏郷が会津の領主に"],["1592年ごろ","氏郷が «黒川» を «若松» と改めたといわれる"],["1593年","七層の天守をもつ鶴ヶ城（黒川城を改修）が完成したとされる"],["1595年","氏郷、伏見で病死。40歳"],["江戸時代以降","会津の人々が氏郷をしのび、墓を守り続ける"]],"who":[["蒲生氏郷","会津の領主。若松の城下町の基礎を築いた"],["豊臣秀吉","奥州仕置のため興徳寺に滞在した天下人"],["織田信長","氏郷の才能を認め、娘を嫁がせた"],["伊達政宗","会津をめぐって氏郷と張り合った東北の雄"]],"deep":["奥州仕置で、秀吉の命令に従わなかった大名は領地を取り上げられた。会津は伊達政宗から取り上げられ、氏郷に与えられた。","氏郷の領地は検地を経て90万石をこえる大きさになったとされ、豊臣政権の中でも有数の大大名だった。","氏郷はキリシタン大名でもあり、洗礼名は «レオン» と伝わる。会津にキリスト教が広まるきっかけの一つともいわれる。","氏郷の死因には病死説のほか、毒殺説もささやかれてきたが、確かな証拠はなく俗説とされる。","墓は京都・大徳寺の黄梅院にもある。興徳寺の五輪塔は会津の人々が建てたもので、遺髪を納めたとする伝えがある。","«若松» の名は、氏郷の故郷・近江日野の «若松の森» にちなむという説がある。"],"look":["蒲生氏郷の墓（五輪塔）","辞世の歌を刻んだ碑","秀吉が滞在した寺としての由来を示す案内","近くの鶴ヶ城へ歩き、氏郷の町づくりを感じる"],"q":["蒲生氏郷が会津の町の名を «黒川» から何に変えた？","«若松»。今の会津若松の名のもとになりました。"],"koji":[{"w":"限りあれば 吹かねど花は 散るものを 心みじかき 春の山風","m":"氏郷の辞世と伝わる歌。命には限りがあるのに、なぜこんなに早く散らせるのかと嘆く"}],"myth":"遺髪を納めたという話、毒殺説、«若松» の由来は伝承・諸説。","img":["蒲生氏郷","奥州仕置","若松城","大徳寺"],"wp":"興徳寺 (会津若松市)","rel":{"ev":[],"grave":[]},"ph":[["c:1/16/Gam%C5%8D_Ujisato_%28Saik%C5%8Dji_Nishiazu%29.jpg",539,779,"蒲生氏郷"],["c:e/e6/%E8%8B%A5%E6%9D%BE%E5%9F%8E%EF%BC%88%E9%B6%B4%E3%83%B6%E5%9F%8E%EF%BC%8920220917-P1003471.jpg",1600,1200,"若松城"],["c:f/f4/090228_Daitoku-ji_Kyoto_Japan03s5.jpg",3690,2460,"大徳寺"]]},{"id":"07_dairinji","n":"大隣寺（二本松少年隊の墓）","yomi":"だいりんじ","cat":"墓所","y":1868,"era":["edo","meiji"],"sh":"","rank":"B","ad":"二本松市成田町","st":"JR東北本線二本松駅から歩いて約20分","la":37.592,"lo":140.432,"hook":"12歳から17歳。大人の戦に出ていった少年たちが、藩主の菩提寺で静かに眠っている。","lead":"大隣寺は、二本松藩主・丹羽家の菩提寺です。境内には、1868年の戊辰戦争で戦った «二本松少年隊» の少年たちや、二本松藩の戦死者の墓があります。命を落とした人々をしのび、今も多くの人がお参りに訪れます。","story":["1868年、新しい政府と旧幕府側の戦い、戊辰戦争が東北にも広がりました。二本松藩は奥羽越列藩同盟に加わり、南から攻めてくる新政府軍と戦うことになります。しかし、藩の兵の多くは白河方面などに出ていて、城を守る大人の兵はわずかしかいませんでした。","そこで出陣したのが、まだ10代前半から半ばの少年たちでした。鉄砲の稽古を受けていた彼らは、若い師範・木村銃太郎に率いられ、城の南の «大壇口（おおだんぐち）» で新政府軍を迎えうちます。«まだ子どもなのに、どうして?»――藩を守りたいという思いと、そうせざるを得ないほど追いつめられた状況がありました。","戦いは激しく、隊長の木村銃太郎も撃たれて命を落としました。少年たちも次々に倒れ、生き残った者も散り散りになりました。そして7月29日（旧暦）、二本松城は落城します。家老たちは城に火を放ち、自ら命を絶ちました。","戦いのあと、亡くなった少年たちや藩士たちの墓が、藩主の菩提寺であるこの大隣寺に建てられました。のちに少年たちは «二本松少年隊» と呼ばれるようになり、その悲しい物語が語り継がれていきます。","境内の墓の前に立つと、刻まれた名前と年齢に胸がしめつけられます。«戦争は子どもの命まで奪う»――大隣寺は、そのことを静かに伝え続けている場所です。毎年、慰霊の行事が行われ、地元の人々が花を手向けています。"],"tl":[["1643年","丹羽光重が白河から二本松へ移り、丹羽家の二本松藩が始まる"],["江戸時代","大隣寺が丹羽家の菩提寺として整えられる"],["1868年5月","二本松藩が奥羽越列藩同盟に加わる"],["1868年7月29日（旧暦）","大壇口の戦い。二本松城落城"],["明治以降","少年隊や戦死者の墓が建てられ、慰霊が続く"],["大正時代","少年隊の元隊士の記録などで «二本松少年隊» の名が広まる"]],"who":[["二本松少年隊","10代前半〜半ばで出陣した少年たち"],["木村銃太郎","少年隊を率いた若い砲術師範。大壇口で戦死"],["丹羽長国","戊辰戦争当時の二本松藩主"],["丹羽光重","二本松藩丹羽家の初代藩主"]],"deep":["少年たちは60人あまりが出陣し、十数人が戦死したとされる。人数は資料によって少しずつ異なる。","«二本松少年隊» という呼び名は戦いの当時のものではなく、明治以降、とくに大正時代に元隊士の記録が出たことで広まったとされる。会津の白虎隊と並べて語られることが多い。","大壇口は二本松城の南の守りの要所。現在、戦いの跡には «二本松少年隊奮戦の地» の碑が建っている。","藩の主力が白河方面などに出ていたため、城の守りは手薄だった。少年や老兵が防衛に加わったのはそのため。","二本松城の落城で、家老の丹羽一学らが自刃したと伝わる。城跡（霞ヶ城公園）にも関連の碑がある。"],"look":["二本松少年隊の墓と、戊辰戦争の戦死者の墓","丹羽家歴代の墓所","大壇口の «少年隊奮戦の地»（車で少し離れた場所）","二本松城跡（霞ヶ城公園）の少年隊の像"],"q":["二本松少年隊が新政府軍を迎えうった城の南の場所は？","«大壇口»。隊長の木村銃太郎もここで戦死しました。"],"koji":[],"myth":"出陣人数・戦死者数は資料により異なる。個々の最期の様子は後年の記録・伝承を含む。","img":["二本松少年隊","二本松城","戊辰戦争","丹羽氏"],"wp":"大隣寺","rel":{"ev":[],"grave":[]},"ph":[["c:8/89/Nihonmatsu_Shonentai_Manifestation_Monument_20100625.jpg",5184,3456,"二本松少年隊"],["c:3/34/Nihonmatsu_Castle_Minowa_Gate_20100625-01.jpg",5184,3456,"二本松城"],["c:4/46/Monument_of_Meijiishin_Fushimi_no_senseki.jpg",3024,3780,"戊辰戦争"]]},{"id":"07_kamaoka","n":"旧亀岡家住宅","yomi":"きゅうかめおかけじゅうたく","cat":"近代","y":1900,"era":["meiji"],"sh":"","rank":"B","ad":"伊達市保原町（保原総合公園内）","st":"阿武隈急行保原駅から歩いて約20分","la":37.815,"lo":140.556,"hook":"蚕が町を豊かにした時代。その富が生んだ、和と洋がまじりあう不思議な屋敷。","lead":"旧亀岡家住宅は、明治時代に伊達地方の実業家・亀岡家が建てた住宅です。和風の家に洋風のデザインを取り入れたつくりで、明治の地方の豊かさとハイカラさを伝えます。今は保原総合公園に移されて公開されています。","story":["明治時代、福島県の伊達地方は «蚕の国» でした。蚕を育て、その繭から生糸をとる養蚕業と、良い蚕の卵（蚕種）を売る蚕種業で、日本有数の産地になっていたのです。生糸は海外へ輸出され、日本の近代化を支える大事な商品でした。","そんな伊達地方で財をなした一族の一つが亀岡家です。亀岡家が建てた住宅は、ふつうの日本の家とは少しちがいました。瓦屋根の和風の建物に、洋風の塔屋や窓、飾りを組み合わせたのです。«どうして洋風にしたの?»――明治の人々にとって、洋風は «新しくてかっこいいもの» の象徴。富と進んだ感覚を示す家だったのです。","建物の中に入ると、和室と洋風の部屋が同じ家の中に並んでいます。細かな彫刻や建具には、腕のいい職人たちの技が光ります。明治の大工たちは、見たこともない西洋の建物を想像しながら、日本の伝統技術で洋風をつくり出していきました。","時代がうつり、養蚕業がおとろえると、豪華な屋敷を維持するのは大変になります。この住宅も、もとの場所から保原総合公園に移されて保存されることになりました。移築によって、多くの人がこの家を見学できるようになったのです。","今、公園の緑の中に立つ屋敷は、ちょっと不思議な存在感を放っています。蚕がもたらした富、明治の人の西洋へのあこがれ、職人の技――小さな町の大きな物語が、この家には詰まっています。"],"tl":[["江戸時代後期","伊達地方で養蚕・蚕種業が盛んになる"],["1859年","横浜開港。生糸が重要な輸出品となる"],["明治時代後期","亀岡家の住宅が建てられる"],["昭和時代","養蚕業がしだいにおとろえる"],["平成時代","保原総合公園に移築・復元され、公開される"]],"who":[["亀岡家","伊達地方の実業家の一族。この住宅を建てた"],["明治の大工・職人たち","和と洋をまぜた建物をつくり上げた"],["伊達地方の養蚕農家","蚕を育て、地域の富を支えた人々"]],"deep":["伊達地方は江戸時代から «蚕種» の一大産地で、«本場» として全国に蚕の卵を送り出した。蚕種は紙に産みつけさせた «蚕種紙» で取引された。","和風の住宅に洋風の塔屋や意匠を加えたつくりは、明治の地方の擬洋風住宅の特徴。純粋な洋館ではなく «和洋折衷» である点がおもしろい。","建物の建築年や大工の名前については、資料によって説明が異なる部分があり、現地の解説で確かめたい。","移築保存は、もとの場所での保存が難しくなった歴史的建物を守る方法の一つ。福島市民家園などでも同じ方法がとられている。","近くの梁川・保原地区には、養蚕や生糸にかかわる歴史的な建物や資料館があり、あわせて巡ると地域の産業史がわかる。","伊達地方の蚕種や生糸は横浜から海外へ輸出され、明治の日本が外貨を得る大きな柱になった。地方の屋敷の豪華さは、世界の市場とつながった産業の豊かさの表れでもある。"],"look":["和風の屋根と洋風の塔屋・窓の組み合わせ","室内の和室と洋室の違い","建具や欄間などの細かな装飾","公園の中での建物のたたずまい","周辺の養蚕農家の建物（二階や屋根に蚕室の工夫が見られる）"],"q":["明治時代、伊達地方を豊かにした産業は何？","養蚕業と蚕種業。蚕の卵や生糸が全国・海外へ送られました。"],"koji":[],"myth":"建築年・設計者・文化財指定の詳細は要確認。","img":["伊達市 (福島県)","養蚕","擬洋風建築"],"wp":"旧亀岡家住宅","rel":{"ev":[],"grave":[]},"ph":[["c:8/86/Kameoka_House_in_Date_Fukushima.jpg",1600,1200,"旧亀岡家住宅"],["c:0/0c/%E9%9C%8A%E5%B1%B1%E3%81%AE%E7%B4%85%E8%91%89.JPG",4608,3456,"伊達市 (福島県)"],["c:0/01/Aoyama-rekishimura4054.jpg",1600,1200,"養蚕"],["c:8/88/Former_Kaichi_School03_1024.jpg",1536,2048,"擬洋風建築"]]},{"id":"07_hiroseza","n":"旧広瀬座（芝居小屋）","yomi":"きゅうひろせざ","cat":"近代","y":1887,"era":["meiji","taisho","heisei"],"sh":"国の重要文化財","rank":"B","ad":"福島市上名倉（福島市民家園内）","st":"JR福島駅からバスで約25分、«民家園» 付近で下車","la":37.731,"lo":140.39,"hook":"回り舞台、花道、すっぽん。明治の町の人たちが夢中になった芝居小屋が、まるごと引っ越してきた。","lead":"旧広瀬座は、明治時代に今の伊達市梁川町に建てられた芝居小屋です。回り舞台や花道など本格的なしかけを備えています。川の工事のためにもとの場所から福島市民家園へ移され、国の重要文化財として公開されています。","story":["テレビも映画もなかった明治時代。町の人たちの一番の楽しみは、芝居でした。旅の一座がやってくると、町じゅうが大さわぎ。梁川の町の人たちは、広瀬川のほとりに本格的な芝居小屋を建てました。それが «広瀬座» です。","小屋の中には、舞台がぐるりと回る «回り舞台»、客席を通って役者が登場する «花道»、花道の途中から役者がせり上がってくる «すっぽん» がありました。«どうやって回すの?»――舞台の下には «奈落» と呼ばれる空間があり、人の力で舞台を回したのです。","梁川は養蚕・生糸の町として栄え、お金と人が集まる場所でした。その豊かさが、町に立派な芝居小屋を生みました。歌舞伎だけでなく、演説会や集会にも使われ、町の人々の «広場» の役割も果たしていたと考えられています。","時代がうつると、映画館やテレビにお客をうばわれ、芝居小屋はしだいに使われなくなりました。そして、広瀬川の改修工事で、もとの場所にはいられなくなります。«このまま壊してしまっていいのか»――そうした声を受けて、建物は福島市民家園に移築されることになりました。","今、民家園の中で、広瀬座は再び芝居や催しの舞台になることがあります。桟敷席に座り、花道を見つめれば、明治の観客のざわめきや拍手が聞こえてくるようです。"],"tl":[["明治20年（1887年）ごろ","梁川町の広瀬川のほとりに建てられたとされる"],["明治〜大正","芝居や興行、集会の場として町の人々に親しまれる"],["昭和","映画やテレビの普及で芝居小屋としての役目がうすれる"],["平成初め","広瀬川の改修で移築が決まり、福島市民家園へ移される"],["平成時代","国の重要文化財に指定"],["現在","民家園で公開され、催しにも使われる"]],"who":[["梁川の町の人々","芝居小屋を建て、支えた観客たち"],["旅回りの一座","各地を回って芝居を見せた役者たち"],["移築にかかわった人々","建物を解体し、民家園に組み立て直した"]],"deep":["«回り舞台» は江戸時代の日本で発達した舞台装置で、世界でも早い例とされる。舞台の下の «奈落» で人が押して回した。","«すっぽん» は花道の七三（舞台から見て約三分、揚幕から約七分）の位置にある小さなせりで、幽霊や妖術使いなど «人間でない役» の登場に使われる。","現存する明治の芝居小屋は全国でも数が少なく、香川の旧金毘羅大芝居（金丸座）や熊本の八千代座などとともに貴重な存在。","移築のきっかけは広瀬川の河川改修とされ、洪水対策の工事が文化財の移転につながった例といえる。","福島市民家園には、江戸〜明治の民家や商家なども移築されており、広瀬座とあわせて昔の暮らしを体感できる。"],"look":["回り舞台と舞台下の奈落（公開時）","花道と «すっぽん» の位置","桟敷席と平土間の客席のつくり","民家園のほかの古民家"],"q":["花道の途中から役者がせり上がって登場する仕掛けを何という？","«すっぽん»。幽霊や妖術使いなどの登場に使われます。"],"koji":[{"w":"奈落の底","m":"もとは舞台の下の空間のこと。転じて、どうにもならないひどい状況のたとえ"}],"myth":"建築年は «明治20年ごろ» とされ、正確な年は資料で要確認。","img":["福島市民家園","芝居小屋","回り舞台","梁川町"],"wp":"旧広瀬座","rel":{"ev":[],"grave":[]},"ph":[["c:0/02/Fukushima_City_Minka-en_entrance.jpg",6240,3120,"福島市民家園"],["c:6/66/%E6%9D%91%E5%9B%BD%E5%BA%A7_%28%E5%B2%90%E9%98%9C%E7%9C%8C%E5%90%84%E5%8B%99%E3%83%B6%E5%8E%9F%E5%B8%82%29--%E5%BB%BB%E3%82%8A%E8%88%9E%E5%8F%B0murakuniza016.jpg",3000,2000,"回り舞台"],["c:a/a0/Yanagawa_Hachiman_Shrine_Date_City_2020.jpg",3840,2160,"梁川町"]]},{"id":"07_shioyasaki","n":"塩屋埼灯台","yomi":"しおやさきとうだい","cat":"近代","y":1899,"era":["meiji","showa","heisei"],"sh":"","rank":"B","ad":"いわき市平薄磯","st":"JRいわき駅からバスで約30分、«灯台入口» 下車、歩いて約10分","la":36.996,"lo":140.98,"hook":"断崖の上の白い灯台は、映画の舞台になり、美空ひばりの歌にもなった。そして大津波の日も、海を見つめていた。","lead":"塩屋埼灯台は、いわき市の海辺の崖の上に立つ白い灯台です。1899年に初めて灯りがともりました。映画『喜びも悲しみも幾年月』や美空ひばりの『みだれ髪』で知られ、中に入って上まで登ることができる «参観灯台» です。","story":["いわきの薄磯の海岸から見上げると、切り立った崖の上に、真っ白な灯台がそびえています。明治時代、東北の太平洋側の海は、船にとって危険な場所でした。«夜の海でも岬の場所がわかるように»――その願いから、1899年、この岬に灯台がともされました。","1938年、福島県の沖で大きな地震が起こり、灯台は大きな被害を受けました。そこで建て直されたのが、今の白い灯台です。以来、灯台守（灯台で働く人）の一家がここに住み、毎晩灯りを守り続けました。","その灯台守の奥さんが書いた手記をもとに、1957年、映画『喜びも悲しみも幾年月』がつくられました。全国の灯台を転々としながら生きる夫婦の物語は大ヒットし、主題歌も広く歌われました。また1987年には、美空ひばりが塩屋埼を舞台にした歌『みだれ髪』を歌い、灯台のふもとには歌碑が建てられています。","2011年3月11日、東日本大震災。大津波が薄磯の町をおそい、多くの方が亡くなりました。灯台も地震で傷つき、しばらく公開が止まりました。しかし修理を終えた灯台は再び灯りをともし、参観も再開されました。灯台は今、ふるさとの海を見守る «祈りの灯» にもなっています。","らせん階段を上って灯台の上に出ると、太平洋が180度以上に広がります。南北にのびる海岸線、白い波。«この光が、今夜もだれかの船を守っている»――そう思うと、灯台の存在がいっそういとおしく感じられます。"],"tl":[["1899年","塩屋埼灯台が初めて点灯"],["1938年","福島県東方沖地震で被害を受ける"],["1940年","現在の灯台に建て直される"],["1957年","映画『喜びも悲しみも幾年月』公開"],["1987年","美空ひばり『みだれ髪』発表。のちにふもとに歌碑"],["2011年","東日本大震災で被害。修理ののち点灯・参観を再開"]],"who":[["灯台守の一家","灯台に住み、毎晩灯りを守った人々"],["田中きよ","塩屋埼の灯台長夫人。その手記が映画のもとになった"],["木下惠介","映画『喜びも悲しみも幾年月』の監督"],["美空ひばり","塩屋埼を舞台にした『みだれ髪』を歌った"]],"deep":["«参観灯台» とは、一般の人が中に入って登れる灯台のこと。全国に十数か所しかなく、塩屋埼はその一つ。","映画『喜びも悲しみも幾年月』は、灯台守夫婦の25年ほどの歩みを描いた作品。主な舞台は全国各地の灯台で、原作の手記を書いたのは塩屋埼の灯台長の妻だった。","『みだれ髪』は作詞・星野哲郎、作曲・船村徹。美空ひばりの晩年の代表曲の一つで、灯台近くに歌碑と遺影碑がある。","灯台は今は無人で、自動で点灯している。灯台守が住み込んでいた時代は、昭和の後半に終わりを迎えた。","薄磯地区は東日本大震災の津波で大きな被害を受けた。灯台の近くには震災の伝承施設もあり、あわせて訪れることで被害と復興を学べる。"],"look":["灯台の上からの太平洋の大パノラマ","ふもとの『みだれ髪』の歌碑","崖の上にそびえる白い灯台の全景（薄磯海岸から）","震災の伝承施設と、再建された薄磯の町並み"],"q":["塩屋埼灯台の灯台長夫人の手記をもとにつくられた映画は？","『喜びも悲しみも幾年月』（1957年、木下惠介監督）。"],"koji":[],"myth":"映画の舞台は全国の灯台で、塩屋埼だけが舞台ではない。","img":["喜びも悲しみも幾年月","美空ひばり","木下惠介","いわき市"],"wp":"塩屋埼灯台","rel":{"ev":[],"grave":[]},"ph":[["c:9/98/Shioya-zaki_lighthouse_01.jpg",1944,2592,"塩屋埼灯台"],["c:2/22/Shioya-zaki_lighthouse_02.jpg",2385,1652],["c:e/ed/Shioya_kitagawa.jpg",1600,1200],["c:0/04/Yorokobi_mo_kanashimi_mo_ikutoshitsuki_1.jpg",326,230,"喜びも悲しみも幾年月"],["c:9/97/Misora-Hibari-4.png",550,715,"美空ひばり"],["c:c/c3/Kinoshita-Keisuke-1.jpg",2342,3540,"木下惠介"],["c:6/68/Iwaki_Montage_2.jpg",1024,1014,"いわき市"]]},{"id":"07_haramachi_musen","n":"原町無線塔跡","yomi":"はらまちむせんとうあと","cat":"近代","y":1921,"era":["taisho","showa"],"sh":"","rank":"B","ad":"南相馬市原町区高見町","st":"JR常磐線原ノ町駅から歩いて約15分","la":37.636,"lo":140.962,"hook":"高さ約200m、コンクリートの巨大な塔が、大正の空に向かって立っていた。海の向こうのアメリカへ、電波を送るために。","lead":"原町無線塔は、1921年に完成した無線電信の送信用の塔です。高さは約200mあり、当時は «東洋一» の高さといわれました。塔は老朽化のため1982年に取りこわされ、今は跡地が公園になって記念の碑や模型が残ります。","story":["大正時代の原町。田んぼと町並みの向こうに、とてつもなく高い塔がそびえていました。鉄筋コンクリートでできた、高さ約200mの無線塔です。今の超高層ビルでいえば、40〜50階建てくらい。«あんな高い塔、何に使うの?»――町の人たちは首をかしげながら見上げたことでしょう。","答えは «太平洋の向こうと話すため» でした。当時、日本とアメリカの間の通信は海底ケーブルが中心で、外国の会社に頼っていました。日本は自分の力で海外と通信するため、強力な無線の送信所をつくることにしたのです。高い塔は、長い電線（アンテナ）を空高く張るための柱でした。","1923年9月1日、関東大震災が起こりました。東京や横浜の通信は大きな被害を受けます。このとき、原町の送信所が、震災の知らせを海外に伝えるための中継に役立ったといわれています。世界は日本の大災害を知り、多くの救援の手がさしのべられました。","その後、通信技術が進歩し、巨大な塔は役目を終えていきます。それでも塔は、原町のシンボルとして何十年も立ち続けました。しかしコンクリートの老朽化が進み、«倒れたら危ない» という声が高まり、1982年、ついに取りこわされることになります。","今、跡地は公園になり、塔を小さくした模型や記念碑が立っています。空を見上げると、そこにかつて200mの塔があったことが信じられないほど。でも、この場所から太平洋の向こうへ電波が飛んでいった――その事実は、原町の人々の誇りとして語り継がれています。"],"tl":[["1910年代","海外との無線通信のため、原町に送信所の建設が始まる"],["1921年","無線塔が完成。磐城無線電信局の送信所として使われる"],["1923年","関東大震災。海外への連絡の中継に役立ったといわれる"],["昭和","通信技術の進歩で送信所としての役目を終える"],["1982年","老朽化のため無線塔を解体"],["現在","跡地が公園となり、模型や記念碑が立つ"]],"who":[["逓信省の技術者たち","海外と直接つながる無線通信をめざした"],["工事にたずさわった人々","巨大なコンクリートの塔を建て上げた"],["原町の人々","塔を町のシンボルとして見上げてきた"]],"deep":["無線塔は鉄筋コンクリート造で、高さは約200m。当時、鉄筋コンクリートの塔としては世界でも最大級とされた。","送信所は «磐城無線電信局» の原町送信所と呼ばれ、受信所は別の場所に置かれた。送信と受信を分けるのは、強い電波が受信の邪魔をしないため。","関東大震災の知らせが海外に伝わった経路については、船の無線や他の局を経由した話もあり、原町の役割の細かな内容には諸説がある。","同じ時代、アメリカとの通信のために愛知県の依佐美送信所などもつくられ、日本の国際無線通信網が整えられていった。","塔の解体後、跡地には10分の1ほどの大きさの模型がつくられ、かつての姿をしのぶことができる。"],"look":["塔を小さく再現した模型","記念碑と説明板","跡地の広さから、塔を支えた基礎の大きさを想像する","南相馬市博物館などの関連展示"],"q":["原町無線塔の高さはおよそ何m？","約200m。完成当時は «東洋一» といわれました。"],"koji":[],"myth":"関東大震災の第一報を伝えたという話は、経路や役割に諸説がある。","img":["関東大震災","南相馬市","依佐美送信所"],"wp":"原町無線塔","rel":{"ev":[],"grave":[]},"ph":[["c:e/e5/HaramachiMemorialRadioTower1.jpg",2736,3648,"原町無線塔"],["c:0/0c/HaramachiMemorialRadioTower4.jpg",3648,2736],["c:b/b9/HaramachiMemorialRadioTower3.jpg",2048,1536],["c:9/95/Haramachi_tower_1975_1.jpg",559,421],["c:3/3a/Kanto-daishinsai.jpg",798,575,"関東大震災"],["c:c/c7/The_Soma_Nomaoi_2005-6.jpg",1280,960,"南相馬市"],["c:6/60/%E4%BE%9D%E4%BD%90%E7%BE%8E%E9%80%81%E4%BF%A1%E6%89%80.jpg",4032,3024,"依佐美送信所"]]},{"id":"07_obori_soma","n":"大堀相馬焼（窯元の里）","yomi":"おおぼりそうまやき","cat":"産業","y":1690,"era":["edo","heisei","reiwa"],"sh":"国の伝統的工芸品","rank":"B","ad":"双葉郡浪江町大堀","st":"JR常磐線浪江駅から車で約15分（避難指示の状況は訪問前に要確認）","la":37.5,"lo":140.93,"hook":"青いひびが走る器に、元気よく駆ける馬。300年続いた窯の里は、ある日とつぜん人の住めない場所になった。","lead":"大堀相馬焼は、浪江町大堀で江戸時代から続く焼き物です。器の表面の «青ひび»、藩のシンボルの «走り駒» の絵、お湯が冷めにくい «二重焼» が特徴です。2011年の原発事故で窯元は町を離れましたが、各地で窯の火を守り続けています。","story":["浪江町の西にある大堀。江戸時代、ここには焼き物をつくる窯がたくさん並んでいました。始まりは元禄時代の1690年ごろ。相馬中村藩の藩士の下男だった «左馬（さま）» という人が、この地で焼き物を始めたと伝わっています。","大堀相馬焼の器をよく見ると、表面に細かなひびが入っています。これは «貫入（かんにゅう）» と呼ばれるもの。焼いたあと冷えるときに、うわぐすりが縮んでできるひびです。«ひびが入っているのに割れないの?»――ひびはうわぐすりだけで、器はしっかりしています。このひびが青く見えることから «青ひび» と呼ばれ、器の美しさになっています。","器には、勢いよく走る馬の絵が描かれています。これは «走り駒»。相馬の殿さまの家には馬を大切にする伝統があり、今も続く «相馬野馬追» にもつながります。走り駒は «右に出る者がいない» という縁起にも通じるといわれ、お祝いの品にも使われてきました。","2011年3月、東日本大震災と原発事故が起きました。大堀の窯元の人々は、ふるさとから避難しなければなりませんでした。窯も、土も、ろくろも置いたまま。«300年続いた焼き物が、ここで終わってしまうのか»――誰もがそう思ったといいます。","それでも窯元たちはあきらめませんでした。避難先の二本松市や県内各地で、新しい窯を築き、大堀相馬焼をつくり続けています。遠く離れても、青ひびと走り駒は受け継がれている。ふるさとへの思いが、器の一つひとつに込められているのです。"],"tl":[["1690年ごろ","左馬が大堀で焼き物を始めたと伝わる"],["江戸時代","相馬中村藩の保護を受け、窯元が増える"],["明治以降","日用の器として東北・関東へ広まる"],["1978年","国の伝統的工芸品に指定"],["2011年","東日本大震災・原発事故で窯元が避難"],["その後","避難先で窯を再興し、生産を続ける"]],"who":[["左馬","大堀相馬焼を始めたと伝わる人物"],["半谷休閑","左馬の主人とされる相馬中村藩士"],["相馬中村藩","焼き物づくりを保護し、産業として育てた"],["大堀の窯元たち","震災後も各地で伝統を守る職人たち"]],"deep":["«青ひび» は、素地とうわぐすりの縮み方の違いで生まれる貫入に、墨などをすりこんで模様を浮かび上がらせたもの。","«二重焼» は器を内側と外側の二重につくる技法で、熱いお湯を入れても持ちやすく、冷めにくい。大堀相馬焼の代表的な特徴。","«走り駒» は狩野派の絵師による馬の絵をもとにしたと伝わり、相馬藩の «繋ぎ駒» の紋とも関係が深い。","江戸時代、大堀には多くの窯元が集まり、東北有数の焼き物の産地だったとされる。","原発事故後、浪江町の避難指示は地区ごとに段階的に解除されてきた。大堀地区を訪れる場合は、最新の状況を確かめる必要がある。","相馬には «相馬駒焼» という別の焼き物もあり、藩の御用窯だった。大堀相馬焼とは別系統とされる。"],"look":["器の表面に走る «青ひび»","手描きの «走り駒» の筆づかい","二重焼の湯のみ（持ったときの感触）","避難先で再興した窯元の工房や販売所"],"q":["大堀相馬焼の器によく描かれる、勢いよく走る馬の絵を何という？","«走り駒»。相馬の馬の文化とつながる縁起のよい絵柄です。"],"koji":[{"w":"右に出る者がいない","m":"その人よりすぐれた人がいないこと。右向きに走る駒の絵柄と結びつけて語られることがある"}],"myth":"左馬・半谷休閑の起源話は伝承。走り駒の絵の由来も諸説。","img":["相馬野馬追","浪江町","貫入"],"wp":"大堀相馬焼","rel":{"ev":[],"grave":[]},"ph":[["c:4/48/Aichi_Prefectural_Ceramic_Museum_%2864%29.jpg",1743,2324,"大堀相馬焼"],["c:f/f2/MET_54930.jpg",4000,3739],["c:7/7e/Double_Gourd-shaped_Sake_Bottle_%28tokkuri%29_LACMA_M.2008.264.46.jpg",1569,2100],["c:0/00/%E5%A4%A7%E5%A0%80%E7%9B%B8%E9%A6%AC%E7%84%BC_%E6%80%A5%E9%A0%88_%281%29.jpg",1130,727],["c:7/78/%E5%A4%A7%E5%A0%80%E7%9B%B8%E9%A6%AC%E7%84%BC_%E6%80%A5%E9%A0%88_%282%29.jpg",823,775],["c:1/15/The_Soma_Nomaoi_2005-5.jpg",960,1280,"相馬野馬追"],["c:4/4f/%E8%8B%95%E9%87%8E%E7%A5%9E%E7%A4%BE%E6%8B%9D%E6%AE%BF%E3%80%81Haiden_of_Kusano-jinja_shrine_-_Panoramio_41312095.jpg",3072,2304,"浪江町"]]},{"id":"07_hongo_yaki","n":"会津本郷焼（本郷の窯場）","yomi":"あいづほんごうやき","cat":"産業","y":1645,"era":["azuchi","edo"],"sh":"国の伝統的工芸品","rank":"B","ad":"大沼郡会津美里町本郷","st":"JR会津若松駅から車で約20分","la":37.46,"lo":139.842,"hook":"城の瓦から始まった焼き物の町。400年以上、窯の火が途絶えなかった東北有数の古い窯場。","lead":"会津本郷焼は、会津美里町本郷でつくられる焼き物です。戦国時代の終わりに鶴ヶ城の瓦を焼いたのが始まりと伝わり、陶器と磁器の両方をつくるめずらしい産地です。国の伝統的工芸品に指定されています。","story":["1590年代、会津の新しい領主になった蒲生氏郷は、城を大改修しました。立派な天守の屋根には、たくさんの瓦が必要です。そこで氏郷は、瓦を焼く職人を呼び寄せ、瓦を焼かせたと伝わります。これが会津本郷焼の始まりといわれています。","江戸時代になり、会津藩主となった保科正之は、焼き物づくりにも力を入れました。尾張の瀬戸（今の愛知県）から陶工を招き、本郷で本格的な陶器づくりが始まったとされます。«瀬戸物» の本場の技が、会津の山里に根づいたのです。","さらに江戸時代の後期、佐藤伊兵衛という人が、白くて硬い «磁器» の技術を学んで持ち帰りました。«陶器（土の焼き物）と磁器（石の焼き物）、両方つくれる産地は多くない»――本郷は、会津藩の保護のもと、東北を代表する焼き物の町になっていきます。","しかし1868年の戊辰戦争で、会津は戦場となり、本郷の窯場も大きな被害を受けました。それでも職人たちは窯を立て直し、焼き物づくりを続けました。昭和には、にしん漬けを作るための «にしん鉢» が海外の博覧会で高い評価を受けたといわれ、会津の暮らしの器が世界に認められました。","今、本郷の町には十数軒の窯元が並び、それぞれ個性のある器をつくっています。夏には «せと市» が開かれ、多くの人でにぎわいます。城の瓦から始まった焼き物の歴史が、今も町の中で生きているのです。"],"tl":[["1590年代","蒲生氏郷が鶴ヶ城の瓦を焼かせたのが始まりと伝わる"],["1645年ごろ","会津藩主・保科正之のもとで瀬戸の陶工が陶器づくりを始めたとされる"],["1800年ごろ","佐藤伊兵衛が磁器の技術を伝える"],["1868年","戊辰戦争で窯場が被害を受ける"],["昭和","にしん鉢が海外の博覧会で評価される"],["1993年","国の伝統的工芸品に指定"]],"who":[["蒲生氏郷","城の瓦を焼かせ、本郷焼の始まりをつくったと伝わる"],["保科正之","会津藩初代藩主。焼き物づくりを保護した"],["水野源左衛門","瀬戸から招かれたと伝わる陶工"],["佐藤伊兵衛","磁器の技術を本郷に伝えた人物"]],"deep":["陶器は粘土を主な原料とし、やわらかく温かみがある。磁器は陶石を原料とし、白く硬く、たたくと高い音がする。本郷は両方を産する。","«にしん鉢» は会津の郷土料理 «にしんの山椒漬け» に使う四角い鉢。宗像窯のにしん鉢が1958年のブリュッセル万国博覧会でグランプリを受けたといわれる。","本郷は良い陶土に恵まれ、城下町・若松に近いことから、藩の窯場として育てられたと考えられる。","会津藩は本郷焼を藩の産業として保護し、磁器の生産は藩の収入にも貢献したとされる。","毎年8月の «会津本郷せと市» は早朝から開かれ、窯元の器を安く買えることで人気。"],"look":["町に点在する窯元の工房とギャラリー","四角い «にしん鉢» と白い磁器の器","会津本郷焼資料館などの展示","8月の «せと市»（開催日は要確認）"],"q":["会津本郷焼は何を焼いたのが始まりと伝わる？","鶴ヶ城の瓦。蒲生氏郷が職人に焼かせたといわれます。"],"koji":[],"myth":"始まりの年、陶工の名、にしん鉢の受賞歴は伝承・資料により差がある。","img":["保科正之","蒲生氏郷","会津美里町"],"wp":"会津本郷焼","rel":{"ev":[],"grave":[]},"ph":[["c:f/f8/Sake_Bottle_%28tokkuri%29_LACMA_M.2008.264.2.jpg",1569,2100,"会津本郷焼"],["c:2/2c/Hoshina_Masayuki2.jpg",414,402,"保科正之"],["c:1/16/Gam%C5%8D_Ujisato_%28Saik%C5%8Dji_Nishiazu%29.jpg",539,779,"蒲生氏郷"],["c:3/36/Isasumi-jinja_roumon.JPG",6016,4000,"会津美里町"]]},{"id":"07_tagokura","n":"田子倉ダム","yomi":"たごくらだむ","cat":"昭和","y":1959,"era":["showa"],"sh":"","rank":"B","ad":"南会津郡只見町田子倉","st":"JR只見線只見駅から車で約15分（冬は道路閉鎖あり）","la":37.32,"lo":139.286,"hook":"戦後の日本に電気を送るため、山あいの村が湖の底に沈んだ。巨大なコンクリートの壁の向こうに、田子倉の集落の記憶が眠る。","lead":"田子倉ダムは、只見川につくられた大きな発電用のダムで、1959年に完成しました。高さは約145mあり、完成当時、日本最大級の水力発電所でした。ダム湖（田子倉湖）の底には、かつての田子倉の集落が沈んでいます。","story":["第二次世界大戦のあと、日本は復興のために大量の電気を必要としていました。工場を動かし、町に明かりをともすため、政府は大きな水力発電所の建設を急ぎます。その舞台に選ばれたのが、雪どけ水が豊富な只見川でした。","ダムをつくる場所には、田子倉という小さな集落がありました。山の恵みと川の魚で暮らす、およそ50戸の村。«ダムができたら、村は湖の底に沈む»――村の人々にとっては、ふるさとを失うということでした。補償の話し合いは長く続き、全国から注目を集めます。","話し合いの末、村人たちはふるさとを離れることになりました。家々は取りこわされ、墓も移されました。移っていった人々の中には、湖を見るたびに «あの辺りが自分の家だった» と思い出す人もいたといいます。","工事は、雪深い山の中で行われました。冬は数メートルの雪に閉ざされ、作業は困難をきわめます。大勢の作業員が働き、事故で命を落とした人もいました。そうした努力の末、1959年、巨大なダムが完成し、たくさんの電気を首都圏などへ送り始めました。","今、ダムの上から見渡す田子倉湖は、周りの山々を映して静かに広がっています。秋の紅葉は見事で、多くの観光客が訪れます。でもその湖の底には、人々の暮らしがあったこと。ダムは、日本の発展と、そのために失われたものの両方を語っています。"],"tl":[["1950年代初め","電源開発株式会社が只見川の開発に取り組む"],["1950年代","田子倉集落の補償交渉が長く続く"],["1950年代後半","集落の人々が移転し、ダム工事が本格化"],["1959年","田子倉ダム完成"],["1971年","只見線が全通し、田子倉付近にも列車が走る"],["現在","日本有数の一般水力発電所として発電を続ける"]],"who":[["田子倉集落の人々","ダムのためにふるさとを離れた"],["電源開発株式会社","ダムと発電所を建設した会社"],["ダム工事の作業員たち","雪深い山で工事に当たった"],["高碕達之助","電源開発の総裁として只見川開発を進めた"]],"deep":["田子倉ダムは重力式コンクリートダム。自分の重さで水圧に耐える形で、高さ約145m。","田子倉発電所は、完成当時の日本で最大級の出力をもつ水力発電所だった。その後の設備更新で出力が増えている。","補償交渉は «田子倉ダム補償問題» として知られ、当時としては高額な補償が話題になった。その後のダム建設の補償のあり方に影響を与えたとされる。","只見川にはこのほか奥只見ダムなど多くのダムがあり、«只見川電源開発» として戦後日本の電力を支えた。","只見線の田子倉駅は利用者が少なく、2013年に廃止された（正確な日付は要確認）。","田子倉湖は日本有数の大きさのダム湖で、周辺は «只見ユネスコエコパーク» にも含まれる。"],"look":["ダムの天端（上部）から見る田子倉湖","巨大なコンクリートの堤体を下から見上げる","ダム近くの展示施設（田子倉ダム資料館など）","秋の紅葉の季節の湖と山々"],"q":["田子倉ダムができて湖の底に沈んだのは何？","田子倉の集落。およそ50戸の村の人々がふるさとを離れました。"],"koji":[],"myth":"集落の戸数や補償額は資料で差がある。田子倉駅廃止の日付は要確認。","img":["田子倉湖","只見川","電源開発","只見線"],"wp":"田子倉ダム","rel":{"ev":[],"grave":[]},"ph":[["c:4/4e/Tagokura-494-r1.JPG",3072,2304,"田子倉ダム"],["c:4/4a/Tagokura_Powerplant.JPG",3072,2304],["c:3/3d/TagokuraDam.JPG",3072,2304],["c:5/5c/Tadami-541-r1.JPG",3072,2304],["c:9/94/Rokujyurigoe.JPG",3072,2304],["c:2/24/Lake_Tagokurako-1.JPG",3072,2304],["c:1/18/Lake_Tagokura-3.JPG",3072,2304],["c:8/82/20081129%E5%8F%AA%E8%A6%8B%E5%B7%9D%E6%BA%90%E6%B5%81%E9%83%A8Tagged.JPG",960,1280]]},{"id":"07_jingamine","n":"陣が峯城跡（平安末の城館）","yomi":"じんがみねじょうあと","cat":"城","y":1150,"era":["heian"],"sh":"国指定史跡","rank":"A","ad":"河沼郡会津坂下町","st":"JR只見線会津坂下駅から車で約10分","la":37.585,"lo":139.84,"hook":"焼け焦げた米、中国から来た白い器。平安時代の終わり、この城館は炎に包まれて消えた。いったい誰が、なぜ?","lead":"陣が峯城跡は、平安時代の終わり、12世紀ごろの城館の跡です。堀に囲まれた館の跡から、焼けた米や中国製の陶磁器などが大量に見つかりました。武士の時代が始まるころの東北の様子を伝える貴重な遺跡として、国の史跡になっています。","story":["会津盆地の西、川が削った崖の上に、深い堀で囲まれた平らな場所があります。ここが陣が峯城跡。«城» といっても、天守のある城ではありません。平安時代の終わり、有力者が住み、守りを固めた «館（やかた）» です。","発掘調査で、人々はおどろきました。建物の跡から、焼けて炭になった米がどっさりと出てきたのです。さらに、中国から運ばれてきた白い磁器や、鏡、武具の一部なども見つかりました。«これは、ただの豪族の家ではない»――都や海外の品を手に入れられる、相当な力を持った人物の館だったと考えられます。","焼けた跡があるということは、この館が火事で燃えたということです。«いったい何があったのか?» 手がかりを求めて研究者は歴史の記録をたどりました。この時代、会津は越後（新潟県）の豪族・城（じょう）氏の勢力下にあったと考えられています。そして城氏は、源平合戦の中で大きな敗北をきっします。","1181年、城氏が信濃の横田河原の戦いで木曽義仲に敗れたあと、奥州の藤原秀衡が会津を手に入れたとする記録があります。陣が峯城は、そのときの争いで焼け落ちたのではないか――そんな説があります。ただし、確かな証拠があるわけではなく、謎はまだ解けていません。","今、城跡は静かな木立と畑の中にあります。堀の跡に立って目を閉じると、平安の終わり、炎に包まれた館と、逃げまどう人々の姿が浮かんでくるようです。武士の世の始まりを物語る、会津の «謎の城» です。"],"tl":[["11世紀末〜12世紀","館が営まれたと考えられる（出土品から推定）"],["12世紀","会津は越後の城氏の勢力下にあったとされる"],["1181年","横田河原の戦いで城氏が木曽義仲に敗れる"],["1181年ごろ","藤原秀衡が会津を押さえたとする記録がある"],["12世紀後半","館が焼失したとみられる"],["平成時代","発掘調査の成果により国史跡に指定"]],"who":[["城長茂（じょうながもち）","越後の豪族・城氏の武将。会津と関わりがあったとされる"],["木曽義仲","横田河原の戦いで城氏を破った源氏の武将"],["藤原秀衡","奥州藤原氏。会津を押さえたと記録される"],["館の主","名前はわからない。大きな力を持った有力者"]],"deep":["焼けた米（炭化米）が大量に出土し、館が火災で焼失したことを示す。米の量から、ここが物資を集める拠点だったと考えられる。","出土した中国製の白磁などは、日本海ルートや奥州藤原氏の流通網を通じて会津にもたらされたと考えられる。平泉の遺跡の出土品と比べる研究もある。","九条兼実の日記『玉葉』には、横田河原の戦いのあと、秀衡が会津を占領したという内容の記事があるとされ、陣が峯城焼失と結びつける説の根拠になっている。","館の主が城氏そのものか、城氏と結んだ会津の有力者かは分かっていない。«陣が峯» という名前も後世の呼び名である。","崖と堀を組み合わせた守りの形は、平安時代末の東北の城館の典型的な姿を知る手がかりとして重要。鎌倉時代以降の城との違いを見る上でも注目される。"],"look":["館を囲む堀の跡と、崖を利用した地形","説明板の出土品写真と復元図","会津坂下町の資料館などの出土品（炭化米・陶磁器）","近くの心清水八幡神社や立木観音（恵隆寺）とあわせた散策"],"q":["陣が峯城跡から大量に見つかった、館が燃えたことを示すものは？","焼けて炭になった米（炭化米）。中国製の陶磁器なども出土しています。"],"koji":[],"myth":"館の主、焼失の原因と年は不明。城氏・秀衡との関係は説の一つ。","img":["城長茂","横田河原の戦い","藤原秀衡","会津坂下町"],"wp":"陣が峯城","rel":{"ev":[],"grave":[]},"ph":[["c:8/8d/Jingaminejo-ato.jpg",774,576,"陣が峯城"],["c:e/e8/Jingaminejo-ato_2.JPG",3264,2448],["c:6/60/WUL-chi05_04229_0019_%E7%BE%A9%E4%BB%B2%E7%B1%8F%E4%B8%8A%E5%90%88%E6%88%A6%E5%9B%B3.pdf",5400,3600,"城長茂"],["c:a/a2/Fujiwara_no_Hidehira.jpg",1438,1306,"藤原秀衡"],["c:c/ce/%E6%81%B5%E9%9A%86%E5%AF%BA%E8%A6%B3%E9%9F%B3%E5%A0%82_%28Eryuji_Kannondo%29.jpg",2816,2112,"会津坂下町"]]},{"id":"07_kawai_tsuginosuke","n":"河井継之助終焉の地（只見町塩沢）","yomi":"かわいつぐのすけしゅうえんのち","cat":"幕末","y":1868,"era":["edo"],"sh":"","rank":"A","ad":"南会津郡只見町塩沢","st":"JR只見線会津塩沢駅から歩いて約10分","la":37.344,"lo":139.364,"hook":"«八十里 腰抜け武士の 越す峠»――傷ついた長岡藩の家老は、担架の上で自分をあざ笑う句を詠み、会津の山里で力尽きた。","lead":"河井継之助は、戊辰戦争で新政府軍と戦った越後長岡藩の家老です。戦いで重い傷を負い、会津へ向かう途中、只見町塩沢で亡くなりました。この地には河井継之助記念館があり、終焉の地としてしのばれています。","story":["1868年、戊辰戦争が越後にもおよびました。長岡藩の家老・河井継之助は、はじめ «どちらにもつかない中立» の道をさぐりました。小千谷で新政府軍の軍監と会談し、戦いを避けたいと願い出ますが、わずかな時間で打ち切られてしまいます。«もはや戦うしかない»――継之助は藩を率いて、奥羽越列藩同盟とともに戦う決断をしました。","継之助は西洋の最新の武器をそろえていました。ガトリング砲と呼ばれる連射のできる機関砲も持っていたといわれます。長岡城は一度落ちますが、継之助は沼地を夜のうちに渡る奇襲で城を取り戻しました。しかし、その戦いの中で左の膝を撃たれ、深い傷を負ってしまいます。","長岡城は再び落ち、継之助は担架に乗せられて会津へ向かうことになりました。越後と会津を結ぶ険しい山道 «八十里越»。担架の上で継之助は «八十里 腰抜け武士の 越す峠» と詠んだと伝わります。自分を «腰抜け» と笑うその句には、くやしさと、どこかさっぱりした覚悟がにじんでいます。","峠を越えて会津の只見に入り、塩沢村の医師の家で手当てを受けますが、傷は悪くなるばかり。死をさとった継之助は、従者に自分の棺を用意させ、火葬のための火を目の前で焚かせたと伝わります。そして8月16日（旧暦）、42歳で息を引き取りました。","その後、遺骨は会津若松をへて長岡に運ばれ、ふるさとに葬られました。塩沢には記念館が建ち、継之助が最期を過ごした部屋の一部が移されています。«武士の時代の終わりを、最後まで自分のやり方で生きた男»――司馬遼太郎の小説『峠』で広く知られるようになった継之助の生き方を、只見の山里は静かに伝えています。"],"tl":[["1827年","長岡藩士の家に生まれる"],["1860年代","藩の改革を進め、家老に昇進。武器の近代化を図る"],["1868年5月","小千谷談判が決裂し、北越戦争が始まる"],["1868年5月","長岡城落城"],["1868年7月","長岡城を奪い返すが、左膝に重傷を負う。まもなく再び落城"],["1868年8月","八十里越を担架で越え、会津の只見へ"],["1868年8月16日（旧暦）","只見町塩沢で死去。42歳"],["1960年代〜70年代","司馬遼太郎『峠』が発表され、広く知られるようになる"]],"who":[["河井継之助","長岡藩の家老。北越戦争を指揮し、塩沢で亡くなった"],["岩村精一郎","小千谷談判で継之助と会談した新政府軍の軍監"],["矢沢宗益","塩沢村の医師。継之助が最期を過ごした家の主"],["司馬遼太郎","継之助を主人公にした小説『峠』の作者"]],"deep":["小千谷談判は、慈眼寺で行われたとされる。継之助は嘆願書を示して戦いの回避を求めたが、軍監の岩村精一郎は受け取らず、会談は短時間で終わったと伝わる。","長岡城の奪還では、城の北東の沼地 «八丁沖» を夜のうちに渡る奇襲をかけた。戊辰戦争で城を奪い返した例として知られる。","長岡藩が持っていたガトリング砲は、当時日本に数門しかなかったとされる。継之助が武器を買いそろえたことは、藩の近代化の象徴として語られる。","八十里越は «実際は八里（約32km）だが、八十里に感じるほど険しい» ことからの名といわれる。越後の吉ヶ平と只見の叶津を結ぶ。","戦争で長岡の町は焼け、多くの人が苦しんだため、継之助を «戦争を起こした人» として恨む声もあった。評価が分かれる人物であることも忘れてはならない。","遺骨は会津若松の寺にいったん葬られたのち、長岡に移されたとされる。墓は長岡市の栄涼寺にある。"],"look":["河井継之助記念館（継之助が最期を過ごした部屋を移した展示）","近くにある継之助の墓碑（遺骨の一部を埋めたとされる）","八十里越の説明と、越後へ続く山並み","只見線の車窓と只見川の風景"],"q":["河井継之助が担架の上で詠んだと伝わる句にある峠の名前は？","«八十里越»。«八十里 腰抜け武士の 越す峠» と詠んだと伝わります。"],"koji":[{"w":"八十里 腰抜け武士の 越す峠","m":"傷ついて担架で峠を越える自分を «腰抜け» と自嘲した句と伝わる"}],"myth":"辞世の句や棺を作らせた話は伝承。ガトリング砲の数・使い方には諸説。","img":["北越戦争","八十里越","峠 (小説)"],"wp":"河井継之助","rel":{"ev":[],"grave":[]},"ph":[["c:8/8a/Kawai_Tugunosuke.jpg",472,659,"河井継之助"],["c:7/7c/Kawai_Tsuginosuke_Memorial_Museum.JPG",3648,2736],["c:6/63/Grave_of_Tuginosuke_Kawai_at_Eiryo-ji_temple_in_Nagaoka.jpg",2304,3072],["c:8/84/Echigo_no_kuni_Uesugi_Kagekatsu_katoku_arasoi_kassen.jpg",2176,1040],["c:1/14/Receipt_of_books_price_-_Kawai_Tsuginosuke.jpg",1258,1776],["c:c/c3/Pine_trees_Kawai_House.jpg",1463,1035],["c:1/1a/Kawai_Sada_and_Kawai_Suga.jpg",934,1401],["c:1/1b/Edward_Schnell.jpg",680,1256]]},{"id":"07_ryozen_jinja","n":"霊山神社（北畠親房・顕家を祀る）","yomi":"りょうぜんじんじゃ","cat":"寺社","y":1337,"era":["kamakura","muromachi","meiji"],"sh":"","rank":"B","ad":"伊達市霊山町大石","st":"JR福島駅からバスで約1時間、«霊山神社前» 下車","la":37.769,"lo":140.664,"hook":"10代で陸奥の大将軍になった若き公家・北畠顕家。奇岩そびえる霊山に城を移し、都をめざして駆け抜けた。","lead":"霊山神社は、南北朝時代に南朝のために戦った北畠親房と、その子・顕家らをまつる神社です。明治時代に創建されました。背後の霊山は、顕家が陸奥の国府を移した «霊山城» があった山で、国の史跡・名勝に指定されています。","story":["1333年、鎌倉幕府がほろび、後醍醐天皇による «建武の新政» が始まりました。天皇は東北を治めるため、わずか16歳ほどの公家の若者・北畠顕家を陸奥守に任じます。父の親房とともに、顕家は義良親王を奉じて多賀城に入りました。«こんな若者に、みちのくがまとめられるのか?»――しかし顕家は、東北の武士たちをみごとにまとめ上げていきます。","やがて足利尊氏が天皇にそむき、世の中は南朝と北朝に分かれて争うようになります。顕家は奥州の軍勢を率いて都へ攻め上り、尊氏を九州へ追い落とすほどの大活躍をしました。遠い東北から大軍で駆けつけたそのスピードは、人々をおどろかせました。","東北にもどった顕家でしたが、多賀城のまわりは足利方の勢力が強くなっていました。そこで1337年、顕家は国府を、けわしい岩山の霊山へ移します。«守りやすい山の上に拠点を»――霊山のそそり立つ岩壁は、天然のとりでになりました。","しかし同じ年、顕家は再び都をめざして出陣します。各地で戦いながら進みましたが、1338年、和泉国の石津（今の大阪府）で討ち死にしました。まだ21歳でした。戦いの直前、顕家は天皇に政治の改めを願う文書を書いたといわれ、その文章は若き武将の誠実さを今に伝えています。","明治時代、南朝に尽くした人々をたたえる動きの中で、霊山のふもとに北畠親房・顕家らをまつる霊山神社がつくられました。境内から霊山を見上げると、20歳あまりで散った若者が、この岩山に託した思いが伝わってくるようです。"],"tl":[["859年","慈覚大師円仁が霊山寺を開いたと伝わる"],["1333年","鎌倉幕府滅亡。北畠顕家が陸奥守となり多賀城へ"],["1336年","顕家が奥州軍を率いて上洛、足利尊氏を破る"],["1337年","顕家、陸奥の国府を霊山へ移す"],["1338年","顕家、和泉国石津で戦死。21歳"],["1347年","霊山城が落城したと伝わる"],["1881年","霊山神社が創建される"]],"who":[["北畠顕家","10代で陸奥守となり、霊山に国府を移した若き公家武将"],["北畠親房","顕家の父。南朝の中心人物で『神皇正統記』の著者"],["義良親王","顕家とともに陸奥へ下った皇子。のちの後村上天皇"],["足利尊氏","後醍醐天皇にそむき、顕家と戦った"]],"deep":["顕家が亡くなる直前に後醍醐天皇に出したとされる文書は «北畠顕家上奏文» と呼ばれ、重い税を改めることや人材の登用などを訴えている。","霊山は玄武岩のけわしい岩峰が連なる山で、国の史跡・名勝に指定されている。山頂近くには霊山城の遺構とされる平場が残る。","霊山神社はのちに別格官幣社に列せられた。南朝の忠臣をまつる神社は、明治以降の国家の歴史観と深くかかわっている。","北畠親房が常陸国の小田城などで書いた『神皇正統記』は、南朝の正しさを説いた歴史書として有名。","顕家の奥州軍の上洛は、ほかの軍に比べて非常に速かったとされ、東北の武士の強さを示す出来事として語られる。"],"look":["社殿と、境内から見上げる霊山の岩峰","北畠顕家の像や記念碑","霊山登山道（国司沢・霊山城跡へ。歩きやすい靴で）","秋の紅葉に染まる霊山の奇岩"],"q":["北畠顕家が陸奥の国府を多賀城から移した山は？","霊山（りょうぜん）。けわしい岩山を天然のとりでにしました。"],"koji":[],"myth":"円仁による開山、霊山城落城の年は伝承・諸説。顕家の陸奥守任命時の年齢は数え方で異なる。","img":["北畠顕家","北畠親房","霊山 (福島県)","霊山城"],"wp":"霊山神社","rel":{"ev":[],"grave":[]},"ph":[["c:c/c4/%E9%9C%8A%E5%B1%B1%E7%A5%9E%E7%A4%BE.jpg",1024,768,"霊山神社"],["c:1/11/Kitabatake_Michishiro.jpg",738,984],["c:8/8a/%E5%8C%97%E7%95%A0%E9%A1%95%E5%AE%B6.png",368,462,"北畠顕家"],["c:d/d4/%E7%99%BB%E5%B1%B1%E5%8F%A3%E3%81%8B%E3%82%89%E3%81%AE%E9%9C%8A%E5%B1%B1%EF%BC%92.jpg",5184,3456,"霊山 (福島県)"],["c:4/4a/Ryozen-Fukushima1.jpg",366,247,"霊山城"]]},{"id":"07_kaiseizan","n":"開成山大神宮（安積開拓の心の拠り所）","yomi":"かいせいざんだいじんぐう","cat":"寺社","y":1876,"era":["meiji"],"sh":"","rank":"B","ad":"郡山市開成","st":"JR郡山駅からバスで約15分、«開成山» 付近で下車","la":37.399,"lo":140.372,"hook":"荒れ野を切りひらく人々の «心のよりどころ» に。伊勢の神さまを分けてもらった、東北のお伊勢さま。","lead":"開成山大神宮は、明治時代の «安積開拓» で荒れ地を開いた人々の心の支えとして創建された神社です。伊勢神宮の神さまの分霊をまつり、«東北のお伊勢さま» と呼ばれています。郡山の発展の原点となった場所です。","story":["明治時代のはじめ、今の郡山市の西には «大槻原» と呼ばれる荒れた原野が広がっていました。水が少なく、木もまばらで、田畑にするのは難しい土地。«この原野を豊かな田んぼに変えられないか»――そう考えたのが、福島県の役人・中條政恒でした。","中條は郡山の商人たちに呼びかけ、開拓のための会社 «開成社» をつくりました。商人たちはお金を出し合い、原野を切りひらいていきます。やがて村ができ、人が住み始めると、人々は «心のよりどころになる神社がほしい» と願いました。そうして建てられたのが、開成山大神宮です。","神社には、伊勢神宮から分けてもらった神さまがまつられました。«どうして伊勢の神さまを?»――伊勢神宮は日本の神社の中心。新しい土地で新しい暮らしを始める人々にとって、国の中心の神さまに見守られることは大きな安心だったのでしょう。","開拓はさらに国の事業となり、明治政府の大久保利通が中心になって進めました。全国から、仕事を失った元武士たちが家族とともに移り住み、荒れ地に向かって鍬をふるいました。そして猪苗代湖の水を引く «安積疏水» が完成し、ようやく原野は田んぼに変わっていったのです。","今、開成山大神宮のまわりは緑豊かな公園になり、郡山は福島県を代表する都市になりました。初詣や七五三には多くの人が訪れます。境内に立つと、原野に夢を描いた人々の汗と祈りが、この町の出発点だったことを感じられます。"],"tl":[["1873年","中條政恒の呼びかけで開成社がつくられ、大槻原の開墾が始まる"],["1874年","開拓の拠点として開成館が建てられる"],["1876年","伊勢神宮の分霊をまつり、開成山大神宮が創建される"],["1876年","明治天皇の東北巡幸で開成館が訪問を受ける"],["1878年","大久保利通のもと、国営の安積開拓・安積疏水事業が決まる"],["1882年","安積疏水が完成し、猪苗代湖の水が流れる"]],"who":[["中條政恒","福島県の役人。安積開拓を最初に進めた"],["阿部茂兵衛","郡山の商人。開成社の中心として開拓に出資した"],["大久保利通","明治政府の内務卿。安積開拓を国の事業にした"],["移住した士族たち","全国から移り住み、原野を耕した"]],"deep":["安積開拓には、久留米・二本松・会津・鳥取など全国の旧藩の士族が移住した。仕事を失った士族を救う «士族授産» の役割もあった。","安積疏水は、猪苗代湖から奥羽山脈をこえて水を引く大工事で、オランダ人技師ファン・ドールンが調査にかかわった。","大久保利通は安積開拓を国の事業とすることを決めたが、1878年に東京で暗殺された。事業はその後も受け継がれた。","近くの開成館は開拓の役所として建てられた擬洋風建築で、現在は開拓の歴史を伝える資料館として公開されている。","安積開拓・安積疏水にかかわる物語は «未来を拓いた一本の水路» として日本遺産に認定されている。"],"look":["社殿と、伊勢神宮にならった神明造りの雰囲気","境内を包む開成山公園の緑","近くの開成館（開拓の歴史の展示）","安積疏水の流れや関連の碑"],"q":["安積開拓で、猪苗代湖から水を引くためにつくられた水路の名前は？","«安積疏水»。1882年に完成し、原野を田んぼに変えました。"],"koji":[],"myth":"創建の経緯や年月の細部は資料で確認したい。","img":["安積疏水","開成館","中條政恒","開成山公園"],"wp":"開成山大神宮","rel":{"ev":[],"grave":[]},"ph":[["c:3/33/%E9%96%8B%E6%88%90%E5%B1%B1%E5%A4%A7%E7%A5%9E%E5%AE%AE.JPG",5184,3456,"開成山大神宮"],["c:c/c1/%E6%A1%9C%E3%81%BE%E3%81%A4%E3%82%8A%EF%BC%88%E9%96%8B%E6%88%90%E5%B1%B1%E5%A4%A7%E7%A5%9E%E5%AE%AE%EF%BC%89.JPG",5184,3456],["c:2/26/Nakajo_Masatsune.jpg",1170,1560,"中條政恒"],["c:5/53/Kaiseizan_Park%2C_koriyama.Cto-75-31_c11b_7.jpg",1800,1096,"開成山公園"]]},{"id":"07_chieko","n":"智恵子の生家（二本松・安達）","yomi":"ちえこのせいか","cat":"近代","y":1886,"era":["meiji","taisho","showa"],"sh":"","rank":"B","ad":"二本松市油井","st":"JR東北本線安達駅から歩いて約20分","la":37.613,"lo":140.42,"hook":"«智恵子は東京に空が無いといふ»。詩人・高村光太郎が愛した妻が、«ほんとの空» を見て育った造り酒屋。","lead":"智恵子の生家は、高村光太郎の詩集『智恵子抄』で知られる高村智恵子（旧姓・長沼）が生まれ育った造り酒屋です。復元された生家と、隣の智恵子記念館が公開されています。二本松の安達太良山の空は、智恵子の «ほんとの空» として有名です。","story":["1886年、二本松の油井村にある造り酒屋・長沼家に、一人の女の子が生まれました。長沼智恵子です。家は大きな酒蔵で、智恵子は裕福な家の長女として育ちました。窓の外には安達太良山がそびえ、その上には澄んだ青空が広がっていました。","智恵子は絵が大好きでした。女学校を卒業すると、東京の日本女子大学校に進み、やがて油絵を学びます。«女性が画家をめざすなんて»――そんな時代に、智恵子は自分の道を進みました。そして東京で、彫刻家で詩人の高村光太郎と出会い、結婚します。","東京での暮らしの中で、智恵子はふるさとの空をなつかしみました。光太郎の詩「あどけない話」には、こんな言葉があります。«智恵子は東京に空が無いといふ»«阿多多羅山の上に毎日出てゐる青い空が智恵子のほんとの空だといふ»。«ほんとの空» とは何だったのか――それは、ふるさとで見た空そのものであり、心のよりどころだったのかもしれません。","しかし、実家の酒屋は家業がかたむき、やがて人手に渡ってしまいます。智恵子は心の病に苦しむようになり、療養生活の中で美しい紙絵（切り絵）をたくさん作りました。1938年、智恵子は52歳で亡くなります。光太郎はその思いを詩にまとめ、1941年に詩集『智恵子抄』を出しました。","今、生家は当時の姿に復元され、酒蔵の様子や智恵子の部屋を見ることができます。隣の記念館には、智恵子の紙絵なども展示されています。外に出て安達太良山の方を見上げてみてください。そこに広がるのが、智恵子が «ほんとの空» と呼んだ空です。"],"tl":[["1886年","長沼智恵子、二本松の造り酒屋に生まれる"],["1903年","日本女子大学校に入学"],["1914年","高村光太郎と結婚"],["1918年ごろ〜","父の死後、実家の家業がかたむき始める"],["1938年","智恵子死去。52歳"],["1941年","高村光太郎の詩集『智恵子抄』刊行"],["平成時代","生家が復元され、智恵子記念館とともに公開"]],"who":[["高村智恵子（長沼智恵子）","この家で生まれ育った画家。『智恵子抄』の智恵子"],["高村光太郎","智恵子の夫。彫刻家・詩人。『智恵子抄』の作者"],["長沼家","智恵子の実家。二本松の造り酒屋"]],"deep":["智恵子は日本女子大学校時代、平塚らいてうらとも縁があり、雑誌『青鞜』の創刊号の表紙絵を描いたことで知られる。","«ほんとの空» の詩「あどけない話」は『智恵子抄』に収められている。「阿多多羅山」は安達太良山のこと。","智恵子の紙絵は、療養中に色紙をはさみで切って作ったもので、千点をこえるといわれる。その色づかいは今も高く評価されている。","生家の酒は «花霞» という銘柄だったと伝わる。","二本松の安達太良山のふもとには、光太郎の詩にちなむ «ほんとの空» の碑や展望スポットがある。","智恵子の病については当時の記録や後の研究でさまざまに語られており、断定的に語るのは避けたい。"],"look":["復元された造り酒屋の生家（酒蔵・帳場・智恵子の部屋）","智恵子記念館の紙絵の展示","生家の裏から見る安達太良山と «ほんとの空»","『智恵子抄』の詩碑"],"q":["「あどけない話」で、智恵子が «ほんとの空» があるといった山は？","阿多多羅山（安達太良山）。二本松から見える山です。"],"koji":[{"w":"ほんとの空","m":"智恵子がふるさとの安達太良山の上の青空を指して言ったことば。ふるさとの象徴として親しまれる"}],"myth":"酒の銘柄や家業の傾いた時期の細部は資料で要確認。","img":["高村光太郎","智恵子抄","安達太良山"],"wp":"高村智恵子","rel":{"ev":[],"grave":[]},"ph":[["c:8/88/Chieko_Takamura.jpg",270,425,"高村智恵子"],["c:a/ac/Chieko.jpg",3264,2448],["c:e/e8/Memorial_Monument_of_Takamura_Chieko.JPG",1536,2048],["c:d/d1/1st_Issue_of_Seito.jpg",952,1356],["c:a/a1/Kusu_by_Chieko_Takamura.jpg",884,640],["c:1/1a/Flowers_%28Hyacinths%29_by_Naganuma_Chieko.jpg",520,668],["c:e/e6/Kotaro_Takamura_by_Shigeru_Tamura.jpg",2660,3707,"高村光太郎"],["c:b/bd/Mount_Adatara_seen_from_the_SE.jpg",4608,2592,"安達太良山"]]},{"id":"07_miharu_takizakura","n":"三春滝桜（樹齢千年超の紅枝垂れ）","yomi":"みはるたきざくら","cat":"伝承","y":1922,"era":["heian","edo","taisho"],"sh":"国指定天然記念物","rank":"B","ad":"田村郡三春町滝","st":"JR磐越東線三春駅から車で約15分（開花期は臨時バスあり）","la":37.411,"lo":140.49,"hook":"薄紅の花が、滝が流れ落ちるように地面まで垂れさがる。1000年以上、春ごとに咲き続けてきたと伝わる日本一の枝垂れ桜。","lead":"三春滝桜は、三春町にある紅枝垂れ桜の巨木です。推定の樹齢は1000年以上といわれ、国の天然記念物に指定されています。山梨の山高神代桜、岐阜の根尾谷淡墨桜とともに «日本三大桜» の一つに数えられます。","story":["春、三春の里の丘の上に、薄紅色の大きな滝が現れます。枝という枝から花がこぼれ落ち、まるで滝が流れているよう。«滝桜» という名前は、この姿から生まれたといわれています。","«この桜は、いつからここにあるの?»――正確な年はわかりません。推定の樹齢は1000年以上。もしそうなら、平安時代から、この場所で花を咲かせてきたことになります。源平合戦も、戦国の世も、戊辰戦争も、この桜は見てきたのかもしれません。","江戸時代、三春は秋田氏が治める城下町でした。滝桜は藩主にも大切にされ、特別な木として守られていたと伝わります。«三春» という町の名前も、梅・桃・桜が一度に咲く春の美しさに由来するという言い伝えがあります。","1922年、滝桜は国の天然記念物に指定されました。その後も、枝を支える支柱を立てたり、土を改良したりと、地元の人々が手をかけて守り続けています。大雪で枝が折れる被害にあったこともありますが、そのたびに人々の手当てで花を咲かせてきました。","2011年の東日本大震災のあとの春も、滝桜は変わらずに花を咲かせました。その姿に励まされた人は少なくありません。1000年の時をこえて咲く花は、人々にとって «また春が来る» という希望そのものなのです。"],"tl":[["伝・平安時代","このころから生えていたと推定される（樹齢1000年以上説）"],["1645年","秋田氏が三春に入り、三春藩が始まる"],["江戸時代","藩主に大切にされたと伝わる"],["1922年","国の天然記念物に指定"],["昭和〜平成","支柱の設置や土壌改良などの保護活動が続く"],["2011年","震災後の春も満開の花を咲かせる"]],"who":[["三春藩主・秋田氏","滝桜を大切にしたと伝わる"],["地元の保存会の人々","支柱や土壌の手入れで桜を守る"],["花見に訪れる人々","春ごとに全国から集まる"],["滝桜を描き、詠んだ人々","歌人や写真家、画家がその姿を作品に残してきた"]],"deep":["品種はエドヒガン系のベニシダレザクラ。枝垂れ桜の中でも特に大きく、樹高は10mをこえる。","周辺の三春町や郡山市には、滝桜の «子孫» とされる枝垂れ桜が多く、«滝桜の娘» と呼ばれるものもある。","«日本三大桜» の三つ（三春滝桜・山高神代桜・根尾谷淡墨桜）は、いずれも大正時代に国の天然記念物に指定された。","樹齢1000年以上という数字は推定で、確かな記録があるわけではない。古い木ほど幹の中が空洞になり、年輪で数えるのが難しい。","開花期には多くの人が訪れるため、観桜料や交通規制がある。夜にはライトアップが行われることもある。","桜の見ごろは例年4月中旬ごろ。年によって前後するため、開花情報を確かめてから訪れたい。滝桜の周りには田畑や里山が広がり、遠くから眺めると、一本の木が風景全体の主役になっていることがよくわかる。"],"look":["滝が流れ落ちるように垂れる枝と花","巨大な幹とそれを支える支柱","少し離れた場所から見る桜と里山の風景","三春の城下町とあわせた散策"],"q":["三春滝桜とともに «日本三大桜» に数えられる山梨県の桜は？","山高神代桜。もう一つは岐阜県の根尾谷淡墨桜です。"],"koji":[],"myth":"樹齢1000年以上は推定。藩主の保護や «三春» の名の由来は伝承。","img":["日本三大桜","三春町","山高神代桜"],"wp":"三春滝桜","rel":{"ev":[],"grave":[]},"ph":[["c:8/8f/Miharu_Miharu-Takizakura_Front_1.jpg",3515,2636,"三春滝桜"],["c:c/cc/Miharu_Takizakura_12.jpg",6000,4000],["c:2/22/H%C5%8Dk%C5%8D-ji%2C_Kitamoto%2C_Saitama.jpg",4912,3264],["c:6/64/Illuminated_Takizakura.jpg",4288,2848],["c:c/c8/ItozakuraOfFukudenTemple.jpg",2832,4240],["c:9/9b/%E4%B8%89%E6%98%A5%E3%81%AE%E6%BB%9D%E6%A1%9C_%E5%AD%90%E5%AD%AB%E6%A8%B9_%E9%A6%99%E5%B7%9D%E7%9C%8C%E5%9C%92%E8%8A%B8%E7%B7%8F%E5%90%88%E3%82%BB%E3%83%B3%E3%82%BF%E3%83%BC.jpg",3000,2000],["c:3/38/Miharu_Takizakura_09.jpg",7389,1500],["c:1/13/Kamaishi_Kanban.jpg",2048,2048]]}];
